	if cached ~= nil then
		return cached
	end
	local loader = __modules[name]
	if not loader then
		error("[Bali] Unknown bundled module: " .. tostring(name), 2)
	end
	if __loading[name] then
		error("[Bali] Circular require detected for module: " .. tostring(name), 2)
	end
	__loading[name] = true
	local result = loader()
	__loading[name] = nil
	if result == nil then
		result = true
	end
	__cache[name] = result
	return result
end

