-- ─── Base64 ──────────────────────────────────────────────────────────────────

local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lookup = {}
for index = 1, #alphabet do
	lookup[string.byte(alphabet, index)] = index - 1
end

local function decodeLua(input)
	input = string.gsub(input, "[^%w%+/=]", "")
	local out = {}
	local chunk = {}
	local length = #input
	local byte = string.byte
	local char = string.char
	local floor = math.floor
	for index = 1, length, 4 do
		local a, b, c, d = byte(input, index, index + 3)
		local va, vb = lookup[a] or 0, lookup[b] or 0
		local vc, vd = lookup[c], lookup[d]
		local n = va * 262144 + vb * 4096 + (vc or 0) * 64 + (vd or 0)
		local b1 = floor(n / 65536) % 256
		local b2 = floor(n / 256) % 256
		local b3 = n % 256
		if c == 61 or vc == nil then
			chunk[#chunk + 1] = char(b1)
		elseif d == 61 or vd == nil then
			chunk[#chunk + 1] = char(b1, b2)
		else
			chunk[#chunk + 1] = char(b1, b2, b3)
		end
		if #chunk >= 2048 then
			out[#out + 1] = table.concat(chunk)
			table.clear(chunk)
		end
	end
	out[#out + 1] = table.concat(chunk)
	return table.concat(out)
end

function Assets.Decode(input)
	local candidates = {}
	local crypt = Util.Global("crypt")
	if type(crypt) == "table" then
		table.insert(candidates, crypt.base64decode)
		table.insert(candidates, crypt.base64_decode)
		if type(crypt.base64) == "table" then
			table.insert(candidates, crypt.base64.decode)
		end
	end
	table.insert(candidates, Util.Global("base64_decode"))
	table.insert(candidates, Util.Global("base64decode"))
	for _, fn in ipairs(candidates) do
		if type(fn) == "function" then
			local ok, result = pcall(fn, input)
			-- PNG signature check guards against decoders that return something unexpected
			if ok and type(result) == "string" and string.sub(result, 2, 4) == "PNG" then
				return result
			end
		end
	end
	return decodeLua(input)
end

-- ─── Loading ─────────────────────────────────────────────────────────────────

local function getAssetFunction()
	return Util.Global("getcustomasset") or Util.Global("getsynasset")
end

local function hasExecutorHttp()
	local synTbl = Util.Global("syn")
	local httpTbl = Util.Global("http")
	local fluxusTbl = Util.Global("fluxus")
	return type(type(synTbl) == "table" and synTbl.request) == "function"
		or type(type(httpTbl) == "table" and httpTbl.request) == "function"
		or type(Util.Global("http_request")) == "function"
		or type(Util.Global("request")) == "function"
		or type(type(fluxusTbl) == "table" and fluxusTbl.request) == "function"
end

local function isValidPngBytes(bytes)
	return type(bytes) == "string" and #bytes > 24 and string.sub(bytes, 1, 8) == "\137PNG\r\n\26\n"
end

local function isValidFontBytes(bytes)
	if type(bytes) ~= "string" or #bytes < 64 then
		return false
	end
	local sig = string.sub(bytes, 1, 4)
	return sig == "\000\001\000\000" or sig == "OTTO" or sig == "true" or sig == "ttcf"
end

local function verify(path, contentId)
	-- Validate local file presence and URI locally without ContentProvider:PreloadAsync (avoids PreloadAsync hooks)
	return type(contentId) == "string"
		and #contentId > 0
		and not string.find(contentId, "^rbxassetid://")
		and Util.FS.IsFile(path)
end

local function jsonStringEscape(str)
	local s = tostring(str or "")
	s = string.gsub(s, "\\", "\\\\")
	s = string.gsub(s, '"', '\\"')
	return '"' .. s .. '"'
end

local function buildFontFamilyJson(familyName, faces)
	local items = {}
	for _, face in ipairs(faces) do
		table.insert(
			items,
			string.format(
				'{"name":%s,"weight":%d,"style":"normal","assetId":%s}',
				jsonStringEscape(face.name),
				face.weight,
				jsonStringEscape(face.assetId)
			)
		)
	end
	return string.format('{"name":%s,"faces":[%s]}', jsonStringEscape(familyName), table.concat(items, ","))
end

function Assets.MaterializeFontFamily(familyName, facesData)
	local getAsset = getAssetFunction()
	if type(getAsset) ~= "function" or not Util.FS.Supported() then
		return nil
	end

	Util.FS.MakeFolder(Assets.FontsFolder)
	local faceEntries = {}
	for _, meta in ipairs(FONT_WEIGHT_META) do
		local weightName = meta.Name
		local ttfPath = string.format("%s/%s_%s_v%s.ttf", Assets.FontsFolder, familyName, weightName, Data.Version)
		local provided = type(facesData) == "table" and facesData[weightName] or nil
		if isValidFontBytes(provided) then
			if not Util.FS.IsFile(ttfPath) then
				Util.FS.Write(ttfPath, provided)
			end
		end
		if Util.FS.IsFile(ttfPath) then
			local okId, ttfAsset = pcall(getAsset, ttfPath)
			if okId and type(ttfAsset) == "string" and ttfAsset ~= "" then
				table.insert(faceEntries, {
					name = weightName,
					weight = meta.Weight,
					assetId = ttfAsset,
				})
			end
		end
	end

	if #faceEntries == 0 then
		return nil
	end

	local jsonPath = string.format("%s/%s_v%s.json", Assets.FontsFolder, familyName, Data.Version)
	local jsonBody = buildFontFamilyJson(familyName, faceEntries)
	Util.FS.Write(jsonPath, jsonBody)

	local okFam, familyAsset = pcall(getAsset, jsonPath)
	if okFam and verify(jsonPath, familyAsset) then
		local okFont, testFont = pcall(function()
			return Font.new(familyAsset, Enum.FontWeight.Regular, Enum.FontStyle.Normal)
		end)
		if okFont and testFont then
			Assets.Fonts[familyName] = familyAsset
			return familyAsset
		end
	end
	return nil
end

local function loadCachedFontsSync()
	local getAsset = getAssetFunction()
	if type(getAsset) ~= "function" or not Util.FS.Supported() then
		return false
	end
	local anyLoaded = false
	for familyName in pairs(FONT_SOURCES) do
		local jsonPath = string.format("%s/%s_v%s.json", Assets.FontsFolder, familyName, Data.Version)
		if Util.FS.IsFile(jsonPath) then
			-- Ensure at least Regular TTF also exists locally
			local regPath = string.format("%s/%s_Regular_v%s.ttf", Assets.FontsFolder, familyName, Data.Version)
			if Util.FS.IsFile(regPath) then
				-- Refresh JSON descriptors in case session custom-asset prefix changed
				local refreshed = Assets.MaterializeFontFamily(familyName, nil)
				if refreshed then
					anyLoaded = true
				end
			end
		end
	end
	return anyLoaded
end

local fontsHydrating = false
function Assets.LoadFontsAsync(priorityList)
	if fontsHydrating or not hasExecutorHttp() then
		return
	end
	local getAsset = getAssetFunction()
	if type(getAsset) ~= "function" or not Util.FS.Supported() then
		return
	end

	fontsHydrating = true
	Util.Spawn(function()
		pcall(function()
			Util.FS.MakeFolder(Assets.FontsFolder)
			local order = priorityList or { "Builder", "Gotham", "Mono", "Montserrat", "Ubuntu", "Nunito" }
			for _, familyName in ipairs(order) do
				if not Assets.Fonts[familyName] and FONT_SOURCES[familyName] then
					local facesData = {}
					local downloadedAny = false
					local weightUrls = FONT_SOURCES[familyName]
					for _, meta in ipairs(FONT_WEIGHT_META) do
						local weightName = meta.Name
						local ttfPath = string.format("%s/%s_%s_v%s.ttf", Assets.FontsFolder, familyName, weightName, Data.Version)
						if Util.FS.IsFile(ttfPath) then
							downloadedAny = true
						else
							local candidates = weightUrls[weightName]
							if type(candidates) == "table" then
								for _, url in ipairs(candidates) do
									local body = Util.HttpGet(url, false, true)
									if isValidFontBytes(body) then
										Util.FS.Write(ttfPath, body)
										facesData[weightName] = body
										downloadedAny = true
										break
									end
								end
							end
						end
					end
					if downloadedAny then
						local famAsset = Assets.MaterializeFontFamily(familyName, facesData)
						if famAsset and type(Assets.OnFontsUpdated) == "function" then
							pcall(Assets.OnFontsUpdated, familyName, famAsset)
						end
					end
				end
			end
			Assets.FontsLoaded = true
		end)
		fontsHydrating = false
	end)
end

function Assets.LoadFonts(syncOnly)
	loadCachedFontsSync()
	if not syncOnly then
		Assets.LoadFontsAsync()
	end
	return Assets.Fonts
end

function Assets.GetFontFamily(name)
	return Assets.Fonts[name]
end

function Assets.Load()
	if Assets.Loaded then
		return Assets.Available
	end
	Assets.Loaded = true

	local getAsset = getAssetFunction()
	if type(getAsset) ~= "function" or not Util.FS.Supported() then
		return false
	end

	local atlasPath = string.format("%s/%s_v%s.png", Assets.Folder, "Atlas", Data.Version)
	local ok = pcall(function()
		Util.FS.MakeFolder(Assets.Folder)
		local sources = {
			Atlas = Data.Atlas.Data,
			Glow = Data.Glow,
			Shadow = Data.Shadow,
			Noise = Data.Noise,
			Glass = Data.Glass,
			Banner = Data.Banner,
			Logo = Data.Logo,
		}
		for name, payload in pairs(sources) do
			local path = string.format("%s/%s_v%s.png", Assets.Folder, name, Data.Version)
			if not Util.FS.IsFile(path) then
				local raw = Assets.Decode(payload)
				if isValidPngBytes(raw) then
					Util.FS.Write(path, raw)
				end
			end
			if Util.FS.IsFile(path) then
				local id = getAsset(path)
				if type(id) == "string" and id ~= "" then
					Assets.Images[name] = id
				end
			end
		end
	end)

	if ok and Assets.Images.Atlas and verify(atlasPath, Assets.Images.Atlas) then
		Assets.Available = true
	else
		Assets.Images = {}
		Assets.Available = false
	end

	-- Synchronously mount cached on-device fonts and hydrate any missing fonts via proxy CDN
	loadCachedFontsSync()
	Assets.LoadFontsAsync()

	return Assets.Available
end

function Assets.Get(name)
	return Assets.Images[name]
end

-- Shadow descriptor { Image, Slice, Inset } (inset = transparent margin around the shape)
function Assets.Shadow()
	if Assets.Images.Shadow then
		return { Image = Assets.Images.Shadow, Slice = Rect.new(64, 64, 96, 96), Inset = 40 }
	end
	return Assets.Fallback.Shadow
end

Assets.Data = Data

return Assets
end

__modules["Core/Create"] = function()
--[[
	Bali UI · Core/Create
	Declarative instance factory with theme bindings and layout shorthands.

	New("Frame", {
		Size = ..., Parent = ...,
		Theme = { BackgroundColor3 = "Card" },   -- live theme binding
		Font = "Medium",                         -- text: binds FontFace to the active family
		Corner = 10,                             -- UICorner radius (or UDim)
		Padding = 12 | { top, right, bottom, left },
		Stroke = { Theme = { Color = "Stroke" }, Transparency = 0.9, Thickness = 1 },
		Children = { ... },
	})
]]

local Theme = require("Core/Theme")

local Create = {}

local TEXT_CLASSES = { TextLabel = true, TextButton = true, TextBox = true }
local IMAGE_CLASSES = { ImageLabel = true, ImageButton = true }
local GUI_CLASSES = {
	Frame = true,
	ScrollingFrame = true,
	CanvasGroup = true,
	TextLabel = true,
	TextButton = true,
	TextBox = true,
	ImageLabel = true,
	ImageButton = true,
	ViewportFrame = true,
}

local SPECIAL = { Theme = true, Font = true, Corner = true, Padding = true, Stroke = true, Children = true, Parent = true }

local function applyDefaults(instance, className)
	if GUI_CLASSES[className] then
		instance.BorderSizePixel = 0
	end
	if TEXT_CLASSES[className] then
		instance.BackgroundTransparency = 1
		instance.Text = ""
		instance.TextSize = 13
		instance.TextXAlignment = Enum.TextXAlignment.Left
		instance.TextColor3 = Theme.Current.Text
		instance.FontFace = Theme.Font("Regular")
		if className == "TextButton" then
			instance.AutoButtonColor = false
		elseif className == "TextBox" then
			instance.ClearTextOnFocus = false
		end
	elseif IMAGE_CLASSES[className] then
		instance.BackgroundTransparency = 1
		if className == "ImageButton" then
			instance.AutoButtonColor = false
		end
	end
end

function Create.Corner(parent, radius)
	local corner = Instance.new("UICorner")
	corner.CornerRadius = typeof(radius) == "UDim" and radius or UDim.new(0, radius or 8)
	corner.Parent = parent
	return corner
end

function Create.Padding(parent, padding)
	local object = Instance.new("UIPadding")
	local top, right, bottom, left
	if type(padding) == "number" then
		top, right, bottom, left = padding, padding, padding, padding
	else
		top = padding[1] or 0
		right = padding[2] or top
		bottom = padding[3] or top
		left = padding[4] or right
	end
	object.PaddingTop = UDim.new(0, top)
	object.PaddingRight = UDim.new(0, right)
	object.PaddingBottom = UDim.new(0, bottom)
	object.PaddingLeft = UDim.new(0, left)
	object.Parent = parent
	return object
end

function Create.Stroke(parent, options)
	options = options or {}
	local stroke = Instance.new("UIStroke")
	stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	stroke.Thickness = options.Thickness or 1
	stroke.Transparency = options.Transparency or Theme.Current.StrokeTransparency
	stroke.Color = options.Color or Theme.Current.Stroke
	if options.Theme then
		Theme.Bind(stroke, options.Theme)
	end
	stroke.Parent = parent
	return stroke
end

-- Glass edge: a stroke whose top edge catches light and fades towards the bottom
function Create.GlassStroke(parent, strength)
	local stroke = Create.Stroke(parent, {
		Theme = {
			Color = "Stroke",
			Transparency = function(theme)
				return math.max(theme.StrokeTransparency - (strength or 0.04), 0)
			end,
		},
	})
	local gradient = Instance.new("UIGradient")
	gradient.Rotation = 90
	gradient.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(0.5, 0.45),
		NumberSequenceKeypoint.new(1, 0.7),
	})
	gradient.Parent = stroke
	return stroke
end

function Create.List(parent, options)
	options = options or {}
	local layout = Instance.new("UIListLayout")
	layout.SortOrder = Enum.SortOrder.LayoutOrder
	layout.FillDirection = options.Direction or Enum.FillDirection.Vertical
	layout.Padding = UDim.new(0, options.Gap or 0)
	layout.HorizontalAlignment = options.HAlign or Enum.HorizontalAlignment.Left
	layout.VerticalAlignment = options.VAlign or Enum.VerticalAlignment.Top
	if options.Wraps then
		layout.Wraps = true
	end
	layout.Parent = parent
	return layout
end

function Create.New(className, props)
	local instance = Instance.new(className)
	applyDefaults(instance, className)
	props = props or {}

	for key, value in pairs(props) do
		if not SPECIAL[key] then
			instance[key] = value
		end
	end

	-- Ensure colored TextButtons default to opaque unless caller overrides transparency
	if className == "TextButton" and props.BackgroundTransparency == nil and (not props.Theme or props.Theme.BackgroundTransparency == nil) then
		if props.BackgroundColor3 ~= nil or (props.Theme and props.Theme.BackgroundColor3 ~= nil) then
			instance.BackgroundTransparency = 0
		end
	end

	if props.Font then
		Theme.Bind(instance, { FontFace = "@" .. props.Font })
	end
	if props.Theme then
		Theme.Bind(instance, props.Theme)
	end
	if props.Corner then
		Create.Corner(instance, props.Corner)
	end
	if props.Padding then
		Create.Padding(instance, props.Padding)
	end
	if props.Stroke then
		Create.Stroke(instance, props.Stroke)
	end
	if props.Children then
		for _, child in ipairs(props.Children) do
			child.Parent = instance
		end
	end
	if props.Parent then
		instance.Parent = props.Parent
	end
	return instance
end

-- Text shorthand: { Class = "TextLabel", Color = "SubText", Font = "Medium", ... }
function Create.Text(props)
	local className = props.Class or "TextLabel"
	props.Class = nil
	props.Theme = props.Theme or {}
	if props.Theme.TextColor3 == nil then
		props.Theme.TextColor3 = props.Color or "Text"
	end
	props.Color = nil
	props.Font = props.Font or "Regular"
	return Create.New(className, props)
end

return Create
end

__modules["Core/Icons"] = function()
--[[
	Bali UI · Core/Icons
	Icon resolution: embedded Lucide atlas names, Roblox asset ids, or glyph fallbacks.
]]

local Assets = require("Core/Assets")
local Theme = require("Core/Theme")
local Create = require("Core/Create")

local Icons = {
	StealthMode = true,
	AllowRemoteAssets = false,
}

local glyphs = {
	check = "✓",
	x = "×",
	plus = "+",
	minus = "-",
	["chevron-right"] = "›",
	["chevron-left"] = "‹",
	["chevron-down"] = "›",
	["chevron-up"] = "›",
	search = "⌕",
	info = "i",
	["circle-check"] = "✓",
	["circle-x"] = "×",
	["triangle-alert"] = "!",
	["circle-alert"] = "!",
	["circle-help"] = "?",
	ellipsis = "•••",
	circle = "●",
	["bali-logo"] = "PH",
	bali = "PH",
}
local glyphRotation = { ["chevron-down"] = 90, ["chevron-up"] = -90 }

local function isLocalAsset(text)
	return string.find(text, "^rbxasset://") ~= nil
end

local function isRemoteRobloxAsset(text)
	return string.find(text, "^rbxassetid://") ~= nil
		or string.find(text, "^rbxthumb://") ~= nil
		or string.find(text, "^%d+$") ~= nil
end

local function isAssetString(text)
	return isLocalAsset(text)
		or isRemoteRobloxAsset(text)
		or string.find(text, "^https?://") ~= nil
end

-- Returns a descriptor table or nil when no icon was requested
function Icons.Resolve(icon)
	if icon == nil or icon == "" or icon == false then
		return nil
	end
	if type(icon) == "number" then
		if Icons.StealthMode and not Icons.AllowRemoteAssets then
			return {
				Kind = "Glyph",
				Text = glyphs.circle,
				Rotation = 0,
			}
		end
		return { Kind = "Asset", Image = "rbxassetid://" .. icon }
	end
	icon = tostring(icon)
	if isAssetString(icon) then
		if isRemoteRobloxAsset(icon) and Icons.StealthMode and not Icons.AllowRemoteAssets then
			return {
				Kind = "Glyph",
				Text = glyphs.circle,
				Rotation = 0,
			}
		end
		if string.find(icon, "^%d+$") then
			icon = "rbxassetid://" .. icon
		end
		return { Kind = "Asset", Image = icon }
	end
	local key = string.lower(icon)
	if (key == "bali-logo" or key == "bali") and Assets.Available and Assets.Images.Logo then
		return { Kind = "Asset", Image = Assets.Images.Logo }
	end
	local cell = Assets.Data.Icons[key]
	if cell and Assets.Available and Assets.Images.Atlas then
		local size = Assets.Data.Atlas.Cell
		return {
			Kind = "Atlas",
			Image = Assets.Images.Atlas,
			Offset = Vector2.new(cell[1], cell[2]),
			Size = Vector2.new(size, size),
		}
	end
	return {
		Kind = "Glyph",
		Text = glyphs[key] or string.upper(string.sub(icon, 1, 1)),
		Rotation = glyphRotation[key] or 0,
	}
end

function Icons.Exists(name)
	return type(name) == "string" and Assets.Data.Icons[string.lower(name)] ~= nil
end

function Icons.List()
	local names = {}
	for name in pairs(Assets.Data.Icons) do
		table.insert(names, name)
	end
	table.sort(names)
	return names
end

local function colorProperty(instance)
	if instance:IsA("TextLabel") then
		return "TextColor3"
	elseif instance:IsA("Frame") then
		return "BackgroundColor3"
	end
	return "ImageColor3"
end

-- Icons.Create(icon, { Size, Position, AnchorPoint, Color = "SubText" | Color3, Transparency, ZIndex, Parent, Name })
function Icons.Create(icon, props)
	props = props or {}
	local iconKey = type(icon) == "string" and string.lower(icon) or nil
	local descriptor = Icons.Resolve(icon)
	if not descriptor then
		return nil
	end

	local size = props.Size or UDim2.fromOffset(16, 16)
	local instance
	local barChildren = {}
	if iconKey == "minus" or iconKey == "plus" then
		-- Crisp 2px vector bars avoid blurry/faint 1px atlas scaling on compact action buttons
		instance = Create.New("Frame", {
			Name = props.Name or "Icon",
			Size = size,
			BackgroundTransparency = 1,
		})
		local barW = math.max(10, math.floor((size.X.Offset or 14) * 0.76 + 0.5))
		local hBar = Create.New("Frame", {
			Name = "MinusBar",
			Size = UDim2.fromOffset(barW, 2),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			BackgroundTransparency = props.Transparency or 0,
			Corner = 99,
			Parent = instance,
		})
		table.insert(barChildren, hBar)
		if iconKey == "plus" then
			local vBar = Create.New("Frame", {
				Name = "PlusVBar",
				Size = UDim2.fromOffset(2, barW),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				BackgroundTransparency = props.Transparency or 0,
				Corner = 99,
				Parent = instance,
			})
			table.insert(barChildren, vBar)
		end
	elseif descriptor.Kind == "Glyph" then
		instance = Create.New("TextLabel", {
			Name = props.Name or "Icon",
			Size = size,
			Text = descriptor.Text,
			TextXAlignment = Enum.TextXAlignment.Center,
			TextYAlignment = Enum.TextYAlignment.Center,
			TextScaled = true,
			Rotation = descriptor.Rotation,
			TextTransparency = props.Transparency or 0,
			Font = "Bold",
		})
	else
		instance = Create.New("ImageLabel", {
			Name = props.Name or "Icon",
			Size = size,
			Image = descriptor.Image,
			ScaleType = Enum.ScaleType.Fit,
			ImageTransparency = props.Transparency or 0,
		})
		if descriptor.Kind == "Atlas" then
			instance.ImageRectOffset = descriptor.Offset
			instance.ImageRectSize = descriptor.Size
		end
	end

	if props.Position then
		instance.Position = props.Position
	end
	if props.AnchorPoint then
		instance.AnchorPoint = props.AnchorPoint
	end
	if props.ZIndex then
		instance.ZIndex = props.ZIndex
		for _, bar in ipairs(barChildren) do
			bar.ZIndex = props.ZIndex
		end
	end
	if props.LayoutOrder then
		instance.LayoutOrder = props.LayoutOrder
	end
	if props.Visible ~= nil then
		instance.Visible = props.Visible == true
	end

	local color = props.Color or "Text"
	if #barChildren > 0 then
		for _, bar in ipairs(barChildren) do
			if typeof(color) == "Color3" then
				bar.BackgroundColor3 = color
			else
				Theme.Bind(bar, { BackgroundColor3 = color })
			end
		end
	else
		if typeof(color) == "Color3" then
			instance[colorProperty(instance)] = color
		else
			Theme.Bind(instance, { [colorProperty(instance)] = color })
		end
	end

	if props.Parent then
		instance.Parent = props.Parent
	end
	return instance
end

-- Swaps the icon of an existing icon instance (keeps size/colour)
function Icons.Set(instance, icon)
	if not instance then
		return
	end
	local descriptor = Icons.Resolve(icon)
	if instance:IsA("TextLabel") then
		instance.Text = descriptor and (descriptor.Text or string.upper(string.sub(tostring(icon), 1, 1))) or ""
		instance.Rotation = descriptor and descriptor.Rotation or 0
		return
	end
	if not descriptor or descriptor.Kind == "Glyph" then
		instance.Image = ""
		return
	end
	instance.Image = descriptor.Image
	if descriptor.Kind == "Atlas" then
		instance.ImageRectOffset = descriptor.Offset
		instance.ImageRectSize = descriptor.Size
	else
		instance.ImageRectOffset = Vector2.zero
		instance.ImageRectSize = Vector2.zero
	end
end

-- Rebinds the colour of an icon to another theme key (or a Color3)
function Icons.SetColor(instance, color, animate)
	if not instance then
		return
	end
	if instance:IsA("Frame") then
		for _, child in ipairs(instance:GetChildren()) do
			if child:IsA("Frame") then
				if typeof(color) == "Color3" then
					Theme.Unbind(child, "BackgroundColor3")
					child.BackgroundColor3 = color
				else
					Theme.Bind(child, { BackgroundColor3 = color })
				end
			end
		end
		return
	end
	local property = colorProperty(instance)
	if typeof(color) == "Color3" then
		Theme.Unbind(instance, property)
		instance[property] = color
		return
	end
	Theme.Bind(instance, { [property] = color })
end

function Icons.ColorProperty(instance)
	return colorProperty(instance)
end

function Icons.TransparencyTarget(instance)
	if not instance then
		return nil
	end
	return instance:FindFirstChild("MinusBar") or instance
end

function Icons.TransparencyProperty(instance)
	local target = Icons.TransparencyTarget(instance) or instance
	if target:IsA("TextLabel") then
		return "TextTransparency"
	elseif target:IsA("Frame") then
		return "BackgroundTransparency"
	end
	return "ImageTransparency"
end

function Icons.SetTransparency(instance, alpha)
	if not instance then
		return
	end
	if instance:IsA("Frame") then
		for _, child in ipairs(instance:GetChildren()) do
			if child:IsA("Frame") then
				child.BackgroundTransparency = alpha
			end
		end
		return
	end
	local target = Icons.TransparencyTarget(instance)
	if not target then
		return
	end
	target[Icons.TransparencyProperty(target)] = alpha
end

return Icons
end

__modules["Core/Maid"] = function()
--[[
	Bali UI · Core/Maid
	Tracks connections, instances, callbacks and objects for deterministic cleanup.
]]

local Maid = {}
Maid.__index = Maid

function Maid.new()
	return setmetatable({ _items = {} }, Maid)
end

function Maid:Give(item)
	if item ~= nil then
		table.insert(self._items, item)
	end
	return item
end

local function cleanup(item)
	local kind = typeof(item)
	if kind == "RBXScriptConnection" then
		item:Disconnect()
	elseif kind == "Instance" then
		item:Destroy()
	elseif kind == "function" then
		item()
	elseif kind == "thread" then
		pcall(task.cancel, item)
	elseif kind == "table" then
		if type(item.Destroy) == "function" then
			item:Destroy()
		elseif type(item.Disconnect) == "function" then
			item.Disconnect()
		end
	end
end

function Maid:Clean()
	local items = self._items
	self._items = {}
	for index = #items, 1, -1 do
		local ok, err = pcall(cleanup, items[index])
		if not ok then
			warn("[Bali] Cleanup error: " .. tostring(err))
		end
	end
end

Maid.Destroy = Maid.Clean

return Maid
end

__modules["Core/Services"] = function()
--[[
	Bali UI · Core/Services
	Lazy, cached service access. Uses cloneref when the executor provides it.
]]

local cloneref = (typeof(cloneref) == "function" and cloneref) or function(object)
	return object
end

local cache = {}

local Services = setmetatable({}, {
	__index = function(self, name)
		local service = cache[name]
		if service == nil then
			service = cloneref(game:GetService(name))
			cache[name] = service
		end
		return service
	end,
})

return Services
end

__modules["Core/Signal"] = function()
--[[
	Bali UI · Core/Signal
	Lightweight synchronous signal with safe handler execution.
]]

local Signal = {}
Signal.__index = Signal

function Signal.new()
	return setmetatable({ _handlers = {} }, Signal)
end

function Signal:Connect(fn)
	local handler = { Fn = fn, Connected = true }
	table.insert(self._handlers, handler)

	local connection = { Connected = true }
	function connection.Disconnect()
		if not handler.Connected then
			return
		end
		handler.Connected = false
		connection.Connected = false
		local index = table.find(self._handlers, handler)
		if index then
			table.remove(self._handlers, index)
		end
	end
	return connection
end

function Signal:Once(fn)
	local connection
	connection = self:Connect(function(...)
		connection.Disconnect()
		fn(...)
	end)
	return connection
end

function Signal:Fire(...)
	-- copy so handlers can disconnect while firing
	local handlers = table.clone(self._handlers)
	for _, handler in ipairs(handlers) do
		if handler.Connected then
			local ok, err = pcall(handler.Fn, ...)
			if not ok then
				warn("[Bali] Signal handler error: " .. tostring(err))
			end
		end
	end
end

function Signal:Destroy()
	for _, handler in ipairs(self._handlers) do
		handler.Connected = false
	end
	table.clear(self._handlers)
end

return Signal
end

__modules["Core/Theme"] = function()
--[[
	Bali UI · Core/Theme
	Theme presets, live re-theming through property bindings, accent overrides and typography.

	Binding values:
	  "Key"        -> Theme.Current[Key]
	  "@Weight"    -> Font face of the active family with that weight (Regular/Medium/SemiBold/Bold)
	  function(t)  -> computed from the active theme table
]]

local Assets = require("Core/Assets")
local Tween = require("Core/Tween")
local Signal = require("Core/Signal")

local Theme = {}

local rgb = Color3.fromRGB

Theme.BuiltInFonts = {
	Gotham = "rbxasset://fonts/families/GothamSSm.json",
