Theme.Order = { "Graphite", "Midnight", "Ocean", "Aurora", "Sunset", "Emerald", "Light" }

Theme.Name = "Graphite"
Theme.Current = table.clone(Theme.Presets.Graphite)
Theme.AccentOverride = nil
Theme.Overrides = {}
Theme.Changed = Signal.new()

local bindings = {} -- [Instance] = { [property] = key }
local destroyHooks = {}

function Theme.GetFontAsset(family)
	local key = family or Theme.FontFamily
	if Theme.OnDeviceFonts and Assets.GetFontFamily then
		local onDevice = Assets.GetFontFamily(key)
		if type(onDevice) == "string" and onDevice ~= "" then
			return onDevice
		end
	end
	return Theme.BuiltInFonts[key] or Theme.Fonts[key] or Theme.BuiltInFonts.Gotham
end

function Theme.SyncOnDeviceFonts()
	for key in pairs(Theme.BuiltInFonts) do
		Theme.Fonts[key] = Theme.GetFontAsset(key)
	end
end

function Theme.Font(weight)
	local family = Theme.GetFontAsset(Theme.FontFamily)
	local enumWeight = Enum.FontWeight[weight or "Regular"] or Enum.FontWeight.Regular
	local ok, f = pcall(Font.new, family, enumWeight, Enum.FontStyle.Normal)
	if ok and f then
		return f
	end
	local fbFamily = Theme.BuiltInFonts[Theme.FontFamily] or Theme.BuiltInFonts.Gotham
	local okFb, fFb = pcall(Font.new, fbFamily, enumWeight, Enum.FontStyle.Normal)
	if okFb and fFb then
		return fFb
	end
	return Font.fromEnum(Enum.Font.Gotham)
end

function Theme.Mono(weight)
	local enumWeight = Enum.FontWeight[weight or "Regular"] or Enum.FontWeight.Regular
	local ok, f = pcall(Font.new, Theme.GetFontAsset("Mono"), enumWeight, Enum.FontStyle.Normal)
	if ok and f then
		return f
	end
	local okFb, fFb = pcall(Font.new, Theme.BuiltInFonts.Mono, enumWeight, Enum.FontStyle.Normal)
	if okFb and fFb then
		return fFb
	end
	return Font.fromEnum(Enum.Font.Code)
end

function Theme.Resolve(key)
	if type(key) == "function" then
		return key(Theme.Current)
	elseif type(key) == "string" then
		if string.sub(key, 1, 1) == "@" then
			return Theme.Font(string.sub(key, 2))
		end
		return Theme.Current[key]
	end
	return key
end

function Theme.Get(key)
	return Theme.Current[key]
end

-- Accent gradient used across the library
function Theme.AccentSequence(theme)
	theme = theme or Theme.Current
	return ColorSequence.new(theme.Accent, theme.Accent2)
end

local function apply(instance, map, animate)
	local tweenProps
	for property, key in pairs(map) do
		local value = Theme.Resolve(key)
		if value ~= nil then
			if animate and typeof(value) == "Color3" then
				tweenProps = tweenProps or {}
				tweenProps[property] = value
			else
				instance[property] = value
			end
		end
	end
	if tweenProps then
		Tween.Play(instance, tweenProps, Tween.Smooth, Enum.EasingStyle.Quad)
	end
end

-- Theme.Bind(instance, { BackgroundColor3 = "Card", TextColor3 = "Text", FontFace = "@Medium" })
function Theme.Bind(instance, map)
	local existing = bindings[instance]
	if existing then
		for property, key in pairs(map) do
			existing[property] = key
		end
	else
		bindings[instance] = table.clone(map)
		local ok, connection = pcall(function()
			return instance.Destroying:Connect(function()
				Theme.Unbind(instance)
			end)
		end)
		if ok then
			destroyHooks[instance] = connection
		end
	end
	local ok, err = pcall(apply, instance, map, false)
	if not ok then
		warn("[Bali] Theme bind failed: " .. tostring(err))
	end
	return instance
end

function Theme.Unbind(instance, property)
	if property then
		local map = bindings[instance]
		if map then
			map[property] = nil
		end
		return
	end
	bindings[instance] = nil
	local hook = destroyHooks[instance]
	if hook then
		destroyHooks[instance] = nil
		pcall(function()
			hook:Disconnect()
		end)
	end
end

local function refresh(animate)
	for instance, map in pairs(bindings) do
		local ok = pcall(apply, instance, map, animate)
		if not ok then
			bindings[instance] = nil
		end
	end
	Theme.Changed:Fire(Theme.Current)
end

function Theme.Set(name, animate)
	local source = Theme.Presets[name]
	if not source then
		warn("[Bali] Unknown theme: " .. tostring(name))
		return false
	end
	Theme.Name = name
	Theme.Current = table.clone(source)
	for key, value in pairs(Theme.Overrides) do
		Theme.Current[key] = value
	end
	if Theme.AccentOverride then
		Theme.Current.Accent = Theme.AccentOverride
		Theme.Current.Accent2 = Theme.AccentOverride:Lerp(source.Accent2, 0.45)
		Theme.Current.AccentHover = computeAccentHover(Theme.Current)
	end
	refresh(animate ~= false)
	return true
end

-- Registers (or replaces) a theme. Missing keys inherit from the dark base palette.
function Theme.Add(name, overrides)
	Theme.Presets[name] = preset(overrides or {})
	if not table.find(Theme.Order, name) then
		table.insert(Theme.Order, name)
	end
	return Theme.Presets[name]
end

function Theme.SetAccent(color, animate)
	Theme.AccentOverride = color
	local source = Theme.Presets[Theme.Name] or Base
	if color then
		Theme.Current.Accent = color
		Theme.Current.Accent2 = color:Lerp(source.Accent2, 0.45)
		Theme.Current.AccentHover = computeAccentHover(Theme.Current)
	else
		Theme.Current.Accent = source.Accent
		Theme.Current.Accent2 = source.Accent2
		Theme.Current.AccentHover = source.AccentHover or computeAccentHover(Theme.Current)
	end
	refresh(animate ~= false)
end

-- Live overrides of keys that survive theme switches (e.g. window transparency slider).
-- Pass nil to drop the override and restore the preset value.
function Theme.SetValue(key, value, animate)
	Theme.Overrides[key] = value
	if value == nil then
		local source = Theme.Presets[Theme.Name] or Base
		value = source[key]
	end
	Theme.Current[key] = value
	refresh(animate ~= false)
end

function Theme.SetFont(family)
	if not Theme.BuiltInFonts[family] and not Theme.Fonts[family] then
		return false
	end
	Theme.FontFamily = family
	Theme.SyncOnDeviceFonts()
	refresh(false)
	return true
end

function Theme.SetOnDeviceFonts(enabled)
	Theme.OnDeviceFonts = enabled == true
	Theme.SyncOnDeviceFonts()
	refresh(false)
	if Theme.OnDeviceFonts and Assets.LoadFontsAsync then
		Assets.LoadFontsAsync({ Theme.FontFamily, "Builder", "Gotham", "Mono" })
	end
	return Theme.OnDeviceFonts
end

Assets.OnFontsUpdated = function(familyName)
	Theme.SyncOnDeviceFonts()
	if Theme.OnDeviceFonts and (familyName == Theme.FontFamily or familyName == "Mono") then
		refresh(false)
	end
end

return Theme
end

__modules["Core/Transition"] = function()
--[[
	Bali UI · Core/Transition
	Reusable micro-interactions and mount/unmount animations respecting Tween.Speed and Tween.Reduced.
	Uses crisp layout-safe fades and slides without UIScale bitmap text blurring.
]]

local Services = require("Core/Services")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Util = require("Core/Util")

local Transition = {}
local activeFadeEntries = setmetatable({}, { __mode = "k" })

local function bumpAnimId(frame)
	local nextId = (frame:GetAttribute("_BaliAnimId") or 0) + 1
	frame:SetAttribute("_BaliAnimId", nextId)
	return nextId
end

function Transition.IsOverlayBlocking(guiObj)
	if not guiObj or typeof(guiObj) ~= "Instance" then
		return false
	end
	local cur = guiObj
	local screenGui = nil
	local inPopup = false
	local inDialog = false
	local inCmdPalette = false
	while cur do
		local name = cur.Name
		if name == "BaliDialogLayer" then
			inDialog = true
			screenGui = cur.Parent
		elseif name == "BaliCommandPaletteBackdrop" then
			inCmdPalette = true
		elseif name == "BaliPopupLayer" then
			inPopup = true
			screenGui = cur.Parent
		elseif (name == "BaliMainLayer" or name == "BaliHUDLayer") and not screenGui then
			screenGui = cur.Parent
		end
		if cur:IsA("ScreenGui") then
			screenGui = cur
			break
		end
		cur = cur.Parent
	end
	if not screenGui then
		return false
	end
	local dialogLayer = screenGui:FindFirstChild("BaliDialogLayer")
	if dialogLayer and dialogLayer.Visible ~= false then
		local dialogBackdrop = dialogLayer:FindFirstChild("DialogBackdrop")
		if dialogBackdrop and dialogBackdrop.Visible ~= false and dialogBackdrop.Active ~= false and not dialogBackdrop:GetAttribute("_BaliClosing") then
			return not inDialog
		end
	end
	local popupLayer = screenGui:FindFirstChild("BaliPopupLayer")
	if popupLayer and popupLayer.Visible ~= false then
		local cmdBackdrop = popupLayer:FindFirstChild("BaliCommandPaletteBackdrop")
		if cmdBackdrop and cmdBackdrop.Visible and cmdBackdrop.Active ~= false and not cmdBackdrop:GetAttribute("_BaliClosing") then
			return (not inCmdPalette) and (not inDialog)
		end
		local popupBackdrop = popupLayer:FindFirstChild("PopupBackdrop")
		if popupBackdrop and popupBackdrop.Visible and popupBackdrop.Active ~= false then
			return (not inPopup) and (not inDialog)
		end
	end
	return false
end

local function collectFadeEntries(root)
	if root:IsA("CanvasGroup") then
		local saved = root:GetAttribute("_BaliRestGroupTrans")
		if saved == nil or (not root:GetAttribute("_BaliUnmounted") and not root:GetAttribute("_BaliFadingIn")) then
			saved = root.GroupTransparency
			if saved >= 0.995 and root:GetAttribute("_BaliRestGroupTrans") ~= nil then
				saved = root:GetAttribute("_BaliRestGroupTrans")
			end
			root:SetAttribute("_BaliRestGroupTrans", saved)
		end
		if saved < 0.995 then
			return { { Inst = root, Prop = "GroupTransparency", Target = saved, IsContent = false } }
		end
		return {}
	end

	local isFading = root:GetAttribute("_BaliFading") == true
		or root:GetAttribute("_BaliUnmounted") == true
		or root:GetAttribute("_BaliFadingIn") == true
	local refresh = not isFading
	local entries = {}

	local cascadeAttrMap = {
		BackgroundTransparency = "_BaliCascadeBg",
		TextTransparency = "_BaliCascadeTxt",
		ImageTransparency = "_BaliCascadeImg",
		Transparency = "_BaliCascadeStroke",
	}

	local function hasCascadingAncestor(inst)
		local cur = inst
		while cur and cur ~= game do
			if cur:GetAttribute("_BaliCascading") == true then
				return true
			end
			if cur == root then
				break
			end
			cur = cur.Parent
		end
		return false
	end

	local function isForegroundContent(inst, prop)
		if prop == "TextTransparency" then
			return true
		end
		if prop == "ImageTransparency" then
			local n = inst.Name
			return inst ~= root
				and n ~= "Shadow"
				and n ~= "Glow"
				and n ~= "GlowTop"
				and n ~= "GlowBottom"
				and n ~= "GlowLeft"
				and n ~= "GlowRight"
				and n ~= "Noise"
				and n ~= "GlassSheen"
				and n ~= "Picture"
				and n ~= "WindowShadow"
				and n ~= "GlowTopLeft"
				and n ~= "GlowBottomRight"
		end
		return false
	end

	local function record(inst, prop, attrName)
		local val
		local cascadeAttr = cascadeAttrMap[prop]
		if refresh then
			if cascadeAttr and hasCascadingAncestor(inst) then
				local cascadeVal = inst:GetAttribute(cascadeAttr)
				if cascadeVal ~= nil then
					val = cascadeVal
				else
					val = inst[prop]
				end
			else
				val = inst[prop]
			end
			inst:SetAttribute(attrName, val)
		else
			val = inst:GetAttribute(attrName)
			if val == nil then
				if cascadeAttr and hasCascadingAncestor(inst) then
					val = inst:GetAttribute(cascadeAttr)
				end
				if val == nil then
					val = inst[prop]
				end
				inst:SetAttribute(attrName, val)
			end
		end
		if val < 0.995 then
			table.insert(entries, {
				Inst = inst,
				Prop = prop,
				Target = val,
				IsContent = isForegroundContent(inst, prop),
			})
		end
	end

	local function scan(inst)
		if inst:IsA("GuiObject") then
			record(inst, "BackgroundTransparency", "_BaliRestBg")
		end
		if inst:IsA("ScrollingFrame") then
			record(inst, "ScrollBarImageTransparency", "_BaliRestBar")
		end
		if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
			record(inst, "TextTransparency", "_BaliRestTxt")
		elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
			record(inst, "ImageTransparency", "_BaliRestImg")
		elseif inst:IsA("UIStroke") then
			record(inst, "Transparency", "_BaliRestStr")
		end
	end

	local function walkVisibleDescendants(parentNode)
		for _, child in ipairs(parentNode:GetChildren()) do
			if child.Name ~= "_BaliRippleWash" then
				if child:IsA("GuiObject") and not child.Visible then
					continue
				end
				scan(child)
				walkVisibleDescendants(child)
			end
		end
	end

	scan(root)
	walkVisibleDescendants(root)

	local prevEntries = activeFadeEntries[root]
	if prevEntries then
		local activeSet = {}
		for _, entry in ipairs(entries) do
			local propsMap = activeSet[entry.Inst]
			if not propsMap then
				propsMap = {}
				activeSet[entry.Inst] = propsMap
			end
			propsMap[entry.Prop] = true
		end
		for _, prev in ipairs(prevEntries) do
			local inst = prev.Inst
			local propsMap = inst and activeSet[inst]
			if inst and inst.Parent and not (propsMap and propsMap[prev.Prop]) then
				if prev.Target < 0.995 then
					inst[prev.Prop] = prev.Target
					if not Tween.Reduced then
						Tween.Play(inst, { [prev.Prop] = prev.Target }, Tween.Instant)
					end
				end
			end
		end
	end

	return entries
end

local function invalidateCascadeTree(root)
	if not root then
		return
	end
	if root:IsA("ScrollingFrame") or root:GetAttribute("_BaliCascadeSeq") ~= nil then
		Transition.RestoreCascade(root)
	end
	for _, desc in ipairs(root:GetDescendants()) do
		if desc:IsA("ScrollingFrame") or desc:GetAttribute("_BaliCascadeSeq") ~= nil then
			Transition.RestoreCascade(desc)
		end
	end
end

local function isAncestorHidden(inst, stopAt)
	local cur = inst
	while cur and cur ~= game do
		if cur:IsA("GuiObject") then
			if not cur.Visible or cur:GetAttribute("_BaliUnmounted") == true then
				return true
			end
		elseif cur:IsA("LayerCollector") then
			if not cur.Enabled then
				return true
			end
			break
		end
		if stopAt and cur == stopAt then
			break
		end
		cur = cur.Parent
	end
	return false
end

local function hasLayoutSiblingController(frame)
	local parent = frame and frame.Parent
	if not parent then
		return false
	end
	return parent:FindFirstChildOfClass("UIListLayout") ~= nil
		or parent:FindFirstChildOfClass("UIGridLayout") ~= nil
end

function Transition.Mount(frame, _scaleFrom, opts)
	if not frame then
		return nil
	end

	local noPos = type(opts) == "table" and opts.NoPositionTween == true
	local dur = (type(opts) == "table" and tonumber(opts.Duration)) or 0.28
	local animId = bumpAnimId(frame)
	invalidateCascadeTree(frame)
	local entries = collectFadeEntries(frame)
	activeFadeEntries[frame] = entries
	local controlled = noPos or hasLayoutSiblingController(frame)

	local targetPos = frame:GetAttribute("_BaliMountTargetPos")
	if typeof(targetPos) ~= "UDim2" then
		targetPos = frame.Position
		if not noPos then
			frame:SetAttribute("_BaliMountTargetPos", targetPos)
		end
	end

	frame:SetAttribute("_BaliFading", true)
	frame:SetAttribute("_BaliUnmounted", false)
	frame:SetAttribute("_BaliFadingIn", true)
	frame.Visible = true

	if Tween.Reduced then
		if not controlled then
			frame.Position = targetPos
		end
		for _, entry in ipairs(entries) do
			if entry.Inst and entry.Inst.Parent then
				entry.Inst[entry.Prop] = entry.Target
			end
		end
		frame:SetAttribute("_BaliFading", nil)
		frame:SetAttribute("_BaliFadingIn", false)
		frame:SetAttribute("_BaliMountTargetPos", nil)
		activeFadeEntries[frame] = nil
		return nil
	end

	local mainTween = nil
	if not controlled then
		frame.Position = UDim2.new(
			targetPos.X.Scale,
			targetPos.X.Offset,
			targetPos.Y.Scale,
			targetPos.Y.Offset + 8
		)
		mainTween = Tween.Play(frame, { Position = targetPos }, dur, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end

	local bgDur = math.min(dur, math.max(dur * 0.85, 0.06))
	for _, entry in ipairs(entries) do
		local inst = entry.Inst
		if inst and inst.Parent then
			inst[entry.Prop] = math.max(entry.Target, entry.IsContent and 0.94 or 0.88)
			local t = Tween.Play(
				inst,
				{ [entry.Prop] = entry.Target },
				entry.IsContent and dur or bgDur,
				Enum.EasingStyle.Quint,
				Enum.EasingDirection.Out
			)
			if entry.IsContent or not mainTween then
				mainTween = t
			end
		end
	end

	if mainTween then
		Tween.Then(mainTween, function()
			if frame.Parent and frame:GetAttribute("_BaliAnimId") == animId then
				frame:SetAttribute("_BaliFading", nil)
				frame:SetAttribute("_BaliFadingIn", false)
				frame:SetAttribute("_BaliMountTargetPos", nil)
				activeFadeEntries[frame] = nil
			end
		end)
	else
		frame:SetAttribute("_BaliFading", nil)
		frame:SetAttribute("_BaliFadingIn", false)
		frame:SetAttribute("_BaliMountTargetPos", nil)
		activeFadeEntries[frame] = nil
	end

	return mainTween
end

function Transition.Unmount(frame, _scaleTo, onDone, opts)
	if not frame then
		if onDone then
			Util.SafeCall(onDone)
		end
		return nil
	end

	local noPos = type(opts) == "table" and opts.NoPositionTween == true
	local dur = (type(opts) == "table" and tonumber(opts.Duration)) or 0.28
	local animId = bumpAnimId(frame)
	invalidateCascadeTree(frame)
	local entries = collectFadeEntries(frame)
	activeFadeEntries[frame] = entries
	local controlled = noPos or hasLayoutSiblingController(frame)

	local targetPos = frame:GetAttribute("_BaliMountTargetPos")
	if typeof(targetPos) ~= "UDim2" then
		targetPos = frame.Position
		if not noPos then
			frame:SetAttribute("_BaliMountTargetPos", targetPos)
		end
	end

	frame:SetAttribute("_BaliFading", true)
	frame:SetAttribute("_BaliFadingIn", false)
	frame:SetAttribute("_BaliUnmounted", true)

	local function finishUnmount()
		if frame:GetAttribute("_BaliAnimId") ~= animId then
			return
		end
		if not onDone and frame.Parent then
			frame.Visible = false
		end
		if frame.Parent and not controlled then
			frame.Position = targetPos
		end
		frame:SetAttribute("_BaliMountTargetPos", nil)
		if onDone then
			Util.SafeCall(onDone)
		end
		if frame.Parent then
			frame:SetAttribute("_BaliFading", nil)
			frame:SetAttribute("_BaliUnmounted", false)
			-- Restore resting transparencies only after hiding/onDone so text never flashes back
			if not frame.Visible then
				for _, entry in ipairs(entries) do
					if entry.Inst and entry.Inst.Parent then
						entry.Inst[entry.Prop] = entry.Target
						if not Tween.Reduced then
							Tween.Play(entry.Inst, { [entry.Prop] = entry.Target }, Tween.Instant)
						end
					end
				end
				activeFadeEntries[frame] = nil
			end
		end
	end

	if Tween.Reduced then
		finishUnmount()
		return nil
	end

	local mainTween = nil
	if not controlled then
		mainTween = Tween.Play(frame, {
			Position = UDim2.new(
				targetPos.X.Scale,
				targetPos.X.Offset,
				targetPos.Y.Scale,
				targetPos.Y.Offset + 6
			),
		}, dur, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end

	local contentDur = math.min(dur, math.max(dur * 0.82, 0.06))
	for _, entry in ipairs(entries) do
		local inst = entry.Inst
		if inst and inst.Parent then
			local entryDur = entry.IsContent and contentDur or dur
			local t = Tween.Play(inst, { [entry.Prop] = 1 }, entryDur, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			if not entry.IsContent then
				mainTween = t
			elseif not mainTween then
				mainTween = t
			end
		end
	end

	if mainTween then
		Tween.Then(mainTween, finishUnmount)
	else
		finishUnmount()
	end

	return mainTween
end

function Transition.Ripple(btn, _inputOrPos, colorKey)
	if not btn or Tween.Reduced then
		return nil
	end

	local absSize = btn.AbsoluteSize
	if absSize.X <= 0 or absSize.Y <= 0 then
		return nil
	end

	local hasLayoutController = btn:FindFirstChildOfClass("UIListLayout") ~= nil
		or btn:FindFirstChildOfClass("UIGridLayout") ~= nil
		or btn.AutomaticSize ~= Enum.AutomaticSize.None

	local resolved = Theme.Resolve(colorKey or "Stroke")
	local color = typeof(resolved) == "Color3" and resolved or Theme.Current.Text

	if hasLayoutController then
		-- Never inject a Scale(1,1) child inside layout-driven / AutomaticSize buttons (breaks size measurement).
		local strokeObj = btn:FindFirstChildOfClass("UIStroke")
		if strokeObj and strokeObj.Parent then
			local restTrans = btn:GetAttribute("_BaliRippleRestStrokeTrans")
			if restTrans == nil then
				restTrans = strokeObj.Transparency
				btn:SetAttribute("_BaliRippleRestStrokeTrans", restTrans)
			end
			local restColor = btn:GetAttribute("_BaliRippleRestStrokeColor")
			if typeof(restColor) ~= "Color3" then
				restColor = strokeObj.Color
				btn:SetAttribute("_BaliRippleRestStrokeColor", restColor)
			end
			strokeObj.Color = color
			strokeObj.Transparency = math.min(restTrans, 0.28)
			local tw = Tween.Play(strokeObj, { Color = restColor, Transparency = restTrans }, Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			Tween.Then(tw, function()
				if btn.Parent then
					btn:SetAttribute("_BaliRippleRestStrokeTrans", nil)
					btn:SetAttribute("_BaliRippleRestStrokeColor", nil)
				end
			end)
			return tw
		end
		local restBg = btn:GetAttribute("_BaliRippleRestBgTrans")
		if restBg == nil then
			restBg = btn.BackgroundTransparency
			btn:SetAttribute("_BaliRippleRestBgTrans", restBg)
		end
		if restBg < 0.95 then
			btn.BackgroundTransparency = math.max(0, restBg - 0.14)
			local tw = Tween.Play(btn, { BackgroundTransparency = restBg }, Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			Tween.Then(tw, function()
				if btn.Parent then
					btn:SetAttribute("_BaliRippleRestBgTrans", nil)
				end
			end)
			return tw
		end
		return nil
	end

	local existing = btn:FindFirstChild("_BaliRippleWash")
	if existing then
		existing:Destroy()
	end

	local wash = Instance.new("Frame")
	wash.Name = "_BaliRippleWash"
	wash.Position = UDim2.fromScale(0, 0)
	wash.Size = UDim2.fromScale(1, 1)
	wash.BackgroundColor3 = color
	wash.BackgroundTransparency = 0.84
	wash.BorderSizePixel = 0
	wash.ZIndex = btn.ZIndex + 1

	local sourceCorner = btn:FindFirstChildOfClass("UICorner")
	if sourceCorner then
		local corner = Instance.new("UICorner")
		corner.CornerRadius = sourceCorner.CornerRadius
		corner.Parent = wash
	end

	local grad = Instance.new("UIGradient")
	grad.Color = ColorSequence.new(color)
	grad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0.25),
		NumberSequenceKeypoint.new(0.5, 0),
		NumberSequenceKeypoint.new(1, 0.35),
	})
	grad.Offset = Vector2.new(-0.35, 0)
	grad.Parent = wash

	wash.Parent = btn

	Tween.Play(grad, { Offset = Vector2.new(0.35, 0) }, Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	local tween = Tween.Play(
		wash,
		{ BackgroundTransparency = 1 },
		Tween.Normal,
		Enum.EasingStyle.Quint,
		Enum.EasingDirection.Out
	)

	Tween.Then(tween, function()
		if wash.Parent then
			wash:Destroy()
		end
	end)

	return tween
end

function Transition.Hover(hit, surface, normalKey, hoverKey, strokeObj)
	if not hit then
		return function() end
	end
	surface = surface or hit

	local hovered = false
	local cleaned = false
	local baseStrokeTrans = strokeObj and strokeObj.Transparency or nil

	local function resolveColor(key)
		local resolved = Theme.Resolve(key)
		return typeof(resolved) == "Color3" and resolved or nil
	end

	local function resolveBaseStrokeTrans()
		if not strokeObj then
			return nil
		end
		if baseStrokeTrans ~= nil then
			return baseStrokeTrans
		end
		return strokeObj.Transparency
	end

	local function applyHoverState(isHover, animate)
		local targetColor = resolveColor(isHover and hoverKey or normalKey)
		if targetColor then
			if animate then
				Tween.Play(surface, { BackgroundColor3 = targetColor }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			else
				surface.BackgroundColor3 = targetColor
			end
		end

		if strokeObj and strokeObj.Parent then
			local restTrans = resolveBaseStrokeTrans()
			if restTrans ~= nil then
				local targetTrans = isHover and math.max(restTrans - 0.08, 0) or restTrans
				if animate then
					Tween.Play(strokeObj, { Transparency = targetTrans }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
				else
					strokeObj.Transparency = targetTrans
				end
			end
		end
	end

	-- Bind resting color so theme switches keep the surface synchronized
	if type(normalKey) == "string" or type(normalKey) == "function" then
		Theme.Bind(surface, { BackgroundColor3 = normalKey })
	else
		applyHoverState(false, false)
	end

	local connections = {}

	table.insert(connections, hit.MouseEnter:Connect(function()
		if cleaned or Util.IsTouchDevice() or Transition.IsOverlayBlocking(hit) then
			return
		end
		if strokeObj and baseStrokeTrans == nil then
			baseStrokeTrans = strokeObj.Transparency
		end
		hovered = true
		applyHoverState(true, true)
	end))

	table.insert(connections, hit.MouseLeave:Connect(function()
		if cleaned then
			return
		end
		hovered = false
		applyHoverState(false, true)
	end))

	table.insert(connections, Theme.Changed:Connect(function()
		if cleaned then
			return
		end
		if strokeObj and strokeObj.Parent and not hovered then
			baseStrokeTrans = strokeObj.Transparency
		end
		if hovered then
			applyHoverState(true, false)
		end
	end))

	local function cleanup()
		if cleaned then
			return
		end
		cleaned = true
		for _, conn in ipairs(connections) do
			pcall(function()
				if typeof(conn) == "RBXScriptConnection" then
					conn:Disconnect()
				elseif type(conn) == "table" and type(conn.Disconnect) == "function" then
					conn.Disconnect()
				end
			end)
		end
		table.clear(connections)
	end

	table.insert(connections, hit.Destroying:Connect(cleanup))

	return cleanup
end

function Transition.SlideFade(frame, offsetY, offsetX)
	if not frame then
		return nil
	end

	local animId = bumpAnimId(frame)
	invalidateCascadeTree(frame)
	local yOffset = offsetY ~= nil and offsetY or 6
	local xOffset = offsetX or 0
	local entries = collectFadeEntries(frame)
	frame:SetAttribute("_BaliUnmounted", false)
	frame:SetAttribute("_BaliFadingIn", true)
	frame.Visible = true

	local targetPos = frame:GetAttribute("_BaliSlideTargetPos")
	if typeof(targetPos) ~= "UDim2" then
		targetPos = frame.Position
		frame:SetAttribute("_BaliSlideTargetPos", targetPos)
	end

	local parentLayout = hasLayoutSiblingController(frame)
	if Tween.Reduced then
		if not parentLayout then
			frame.Position = targetPos
		end
		for _, entry in ipairs(entries) do
			if entry.Inst and entry.Inst.Parent then
				entry.Inst[entry.Prop] = entry.Target
			end
		end
		frame:SetAttribute("_BaliFadingIn", false)
		frame:SetAttribute("_BaliSlideTargetPos", nil)
		return nil
	end

	local mainTween
	if not parentLayout then
		frame.Position = UDim2.new(
			targetPos.X.Scale,
			targetPos.X.Offset + xOffset,
			targetPos.Y.Scale,
			targetPos.Y.Offset + yOffset
		)
		mainTween = Tween.Play(frame, { Position = targetPos }, Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end

	for _, entry in ipairs(entries) do
		local inst = entry.Inst
		if inst and inst.Parent then
			inst[entry.Prop] = math.min(1, math.max(entry.Target + 0.12, 0.92))
			local fadeTween = Tween.Play(inst, { [entry.Prop] = entry.Target }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			if not mainTween then
				mainTween = fadeTween
			end
		end
	end

	if mainTween then
		Tween.Then(mainTween, function()
			if frame.Parent and frame:GetAttribute("_BaliAnimId") == animId then
				frame:SetAttribute("_BaliFadingIn", false)
				frame:SetAttribute("_BaliSlideTargetPos", nil)
			end
		end)
	else
		frame:SetAttribute("_BaliFadingIn", false)
		frame:SetAttribute("_BaliSlideTargetPos", nil)
	end

	return mainTween
end

function Transition.Pulse(inst, prop, fromVal, toVal, period)
	if not inst or not prop then
		return function() end
	end

	if Tween.Reduced then
		pcall(function()
			inst[prop] = toVal
		end)
		return function() end
	end

	pcall(function()
		inst[prop] = fromVal
	end)

	local halfPeriod = math.max(((period or 1.2) * 0.5) * Tween.Speed, 0.05)
	local info = TweenInfo.new(halfPeriod, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)
	local tween = Services.TweenService:Create(inst, info, { [prop] = toVal })
	tween:Play()

	local stopped = false
	local destroyConn

	local function stop()
		if stopped then
			return
		end
		stopped = true
		if destroyConn then
			destroyConn:Disconnect()
			destroyConn = nil
		end
		pcall(function()
			tween:Cancel()
		end)
		pcall(function()
			if inst.Parent then
				inst[prop] = fromVal
			end
		end)
	end

	local ok, conn = pcall(function()
		return inst.Destroying:Connect(stop)
	end)
	if ok then
		destroyConn = conn
	end

	return stop
end

-- Rayfield-inspired sequential staggered reveal inside ScrollingFrames / containers.
-- Never uses UIScale or mutates UIListLayout sibling sizes, keeping fonts razor sharp.
local function collectCascadeTargets(container, out, limit)
	for _, child in ipairs(container:GetChildren()) do
		if #out >= limit then
			return
		end
		if child:IsA("GuiObject") and child.Visible then
			local name = child.Name
			if name ~= "_BaliRippleWash" then
				if child:IsA("Frame") and (name == "ColumnRow" or name == "LeftColumn" or name == "RightColumn") then
					collectCascadeTargets(child, out, limit)
				else
					table.insert(out, child)
				end
			end
		end
	end
end

local function snapshotVisualProps(root)
	local isFading = root:GetAttribute("_BaliCascading") == true or root:GetAttribute("_BaliFading") == true
	local refresh = not isFading
	local entries = {}
	local function addInst(inst)
		if inst:IsA("GuiObject") then
			if refresh or inst:GetAttribute("_BaliCascadeBg") == nil then
				local val = isFading and inst:GetAttribute("_BaliRestBg") or inst.BackgroundTransparency
				if val == nil then
					val = inst.BackgroundTransparency
				end
				inst:SetAttribute("_BaliRestBg", val)
				inst:SetAttribute("_BaliCascadeBg", val)
			end
			table.insert(entries, { Inst = inst, Prop = "BackgroundTransparency", Target = inst:GetAttribute("_BaliCascadeBg"), IsContent = false })
		end
		if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
			if refresh or inst:GetAttribute("_BaliCascadeTxt") == nil then
				local val = isFading and inst:GetAttribute("_BaliRestTxt") or inst.TextTransparency
				if val == nil then
					val = inst.TextTransparency
				end
				inst:SetAttribute("_BaliRestTxt", val)
				inst:SetAttribute("_BaliCascadeTxt", val)
			end
			table.insert(entries, { Inst = inst, Prop = "TextTransparency", Target = inst:GetAttribute("_BaliCascadeTxt"), IsContent = true })
		elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
			if refresh or inst:GetAttribute("_BaliCascadeImg") == nil then
				local val = isFading and inst:GetAttribute("_BaliRestImg") or inst.ImageTransparency
				if val == nil then
					val = inst.ImageTransparency
				end
				inst:SetAttribute("_BaliRestImg", val)
				inst:SetAttribute("_BaliCascadeImg", val)
			end
			local n = inst.Name
			local isForeground = (n ~= "Shadow" and n ~= "WindowShadow" and n ~= "Glow" and n ~= "GlowTop" and n ~= "GlowBottom" and n ~= "GlowLeft" and n ~= "GlowRight" and n ~= "GlowTopLeft" and n ~= "GlowBottomRight" and n ~= "Noise" and n ~= "GlassSheen" and n ~= "Picture")
			table.insert(entries, { Inst = inst, Prop = "ImageTransparency", Target = inst:GetAttribute("_BaliCascadeImg"), IsContent = isForeground })
		elseif inst:IsA("UIStroke") then
			if refresh or inst:GetAttribute("_BaliCascadeStroke") == nil then
				local val = isFading and inst:GetAttribute("_BaliRestStr") or inst.Transparency
				if val == nil then
					val = inst.Transparency
				end
				inst:SetAttribute("_BaliRestStr", val)
				inst:SetAttribute("_BaliCascadeStroke", val)
			end
			table.insert(entries, { Inst = inst, Prop = "Transparency", Target = inst:GetAttribute("_BaliCascadeStroke"), IsContent = false })
		end
	end

	addInst(root)
	for _, desc in ipairs(root:GetDescendants()) do
		if desc.Name ~= "_BaliRippleWash" then
			addInst(desc)
		end
	end
	return entries
end

function Transition.Cascade(container, stepDelay, maxItems, slideOffsetX)
	if not container then
		return nil
	end

	local seq = (container:GetAttribute("_BaliCascadeSeq") or 0) + 1
	container:SetAttribute("_BaliCascadeSeq", seq)

	if Tween.Reduced then
		container:SetAttribute("_BaliCascadeActive", nil)
		return nil
	end
	container:SetAttribute("_BaliCascadeActive", true)

	if slideOffsetX and slideOffsetX ~= 0 and not hasLayoutSiblingController(container) then
		local restPos = container:GetAttribute("_BaliSlideTargetPos")
		if typeof(restPos) ~= "UDim2" then
			restPos = container.Position
			container:SetAttribute("_BaliSlideTargetPos", restPos)
		end
		container.Position = UDim2.new(
			restPos.X.Scale,
			restPos.X.Offset + slideOffsetX,
			restPos.Y.Scale,
			restPos.Y.Offset
		)
		local slideTw = Tween.Play(container, { Position = restPos }, Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		if slideTw then
			Tween.Then(slideTw, function()
				if container.Parent and container:GetAttribute("_BaliCascadeSeq") == seq then
					container:SetAttribute("_BaliSlideTargetPos", nil)
				end
			end)
		end
	end

	local targets = {}
	collectCascadeTargets(container, targets, maxItems or 14)
	if #targets == 0 then
		container:SetAttribute("_BaliCascadeActive", nil)
		return nil
	end

	local step = stepDelay or 0.02
	for index, card in ipairs(targets) do
		local props = snapshotVisualProps(card)
		card:SetAttribute("_BaliCascading", true)
		for _, entry in ipairs(props) do
			if entry.Target < 1 then
				entry.Inst[entry.Prop] = math.max(entry.Target, entry.IsContent and 0.92 or 0.85)
			end
		end

		local delaySec = math.min((index - 1) * step, 0.22)
		local function reveal()
			if container:GetAttribute("_BaliCascadeSeq") ~= seq then
				if not container.Parent or isAncestorHidden(card) then
					card:SetAttribute("_BaliCascading", nil)
					for _, entry in ipairs(props) do
						if entry.Inst.Parent and entry.Target < 1 then
							entry.Inst[entry.Prop] = entry.Target
						end
					end
				end
				return
			end
			if not container.Parent or isAncestorHidden(card) then
				card:SetAttribute("_BaliCascading", nil)
				for _, entry in ipairs(props) do
					if entry.Inst.Parent and entry.Target < 1 then
						entry.Inst[entry.Prop] = entry.Target
					end
				end
				if index == #targets then
					container:SetAttribute("_BaliCascadeActive", nil)
				end
				return
			end
			local lastRevealTween = nil
			for _, entry in ipairs(props) do
				if entry.Inst.Parent and entry.Target < 1 then
					local t = Tween.Play(
						entry.Inst,
						{ [entry.Prop] = entry.Target },
						entry.IsContent and Tween.Normal or Tween.Fast,
						Enum.EasingStyle.Quint,
						Enum.EasingDirection.Out
					)
					if t then
						lastRevealTween = t
					end
				end
			end
			if lastRevealTween then
				Tween.Then(lastRevealTween, function()
					if card.Parent and container:GetAttribute("_BaliCascadeSeq") == seq then
						card:SetAttribute("_BaliCascading", nil)
						if index == #targets then
							container:SetAttribute("_BaliCascadeActive", nil)
						end
					end
				end)
			else
				card:SetAttribute("_BaliCascading", nil)
				if index == #targets then
					container:SetAttribute("_BaliCascadeActive", nil)
				end
			end
		end

		if delaySec <= 0 then
			reveal()
		else
			task.delay(delaySec, reveal)
		end
	end

	return seq
end

function Transition.RestoreCascade(container)
	if not container then
		return
	end
	container:SetAttribute("_BaliCascadeSeq", (container:GetAttribute("_BaliCascadeSeq") or 0) + 1)
	container:SetAttribute("_BaliCascadeActive", nil)
	local restPos = container:GetAttribute("_BaliSlideTargetPos")
	if typeof(restPos) == "UDim2" then
		container.Position = restPos
		container:SetAttribute("_BaliSlideTargetPos", nil)
	end
	local function restoreInst(inst, inCascadingSubtree)
		local cascadingHere = inCascadingSubtree or (inst:GetAttribute("_BaliCascading") == true)
		if inst:IsA("GuiObject") and inst:GetAttribute("_BaliCascading") ~= nil then
			inst:SetAttribute("_BaliCascading", nil)
		end
		if not cascadingHere then
			return false
		end
		local restoreProps = nil
		if inst:IsA("GuiObject") then
			local bg = inst:GetAttribute("_BaliCascadeBg")
			if bg ~= nil then
				inst.BackgroundTransparency = bg
				restoreProps = restoreProps or {}
				restoreProps.BackgroundTransparency = bg
				local restBg = inst:GetAttribute("_BaliRestBg")
				if restBg == nil or restBg > bg + 0.01 then
					inst:SetAttribute("_BaliRestBg", bg)
				end
			end
		end
		if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
			local txt = inst:GetAttribute("_BaliCascadeTxt")
			if txt ~= nil then
				inst.TextTransparency = txt
				restoreProps = restoreProps or {}
				restoreProps.TextTransparency = txt
				local restTxt = inst:GetAttribute("_BaliRestTxt")
				if restTxt == nil or restTxt > txt + 0.01 then
					inst:SetAttribute("_BaliRestTxt", txt)
				end
			end
		elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
			local img = inst:GetAttribute("_BaliCascadeImg")
			if img ~= nil then
				inst.ImageTransparency = img
				restoreProps = restoreProps or {}
				restoreProps.ImageTransparency = img
				local restImg = inst:GetAttribute("_BaliRestImg")
				if restImg == nil or restImg > img + 0.01 then
					inst:SetAttribute("_BaliRestImg", img)
				end
			end
		elseif inst:IsA("UIStroke") then
			local str = inst:GetAttribute("_BaliCascadeStroke")
			if str ~= nil then
				inst.Transparency = str
				restoreProps = restoreProps or {}
				restoreProps.Transparency = str
				local restStr = inst:GetAttribute("_BaliRestStr")
				if restStr == nil or restStr > str + 0.01 then
					inst:SetAttribute("_BaliRestStr", str)
				end
			end
		end
		if restoreProps and next(restoreProps) ~= nil and not Tween.Reduced then
			Tween.Play(inst, restoreProps, Tween.Instant)
		end
		return true
	end
	local function walkRestore(node, inCascadingSubtree)
		local active = restoreInst(node, inCascadingSubtree)
		for _, child in ipairs(node:GetChildren()) do
			if child.Name ~= "_BaliRippleWash" then
				walkRestore(child, active)
			end
		end
	end
	walkRestore(container, container:GetAttribute("_BaliCascading") == true)
end

return Transition
end

__modules["Core/Tween"] = function()
--[[
	Bali UI · Core/Tween
	Centralised tweening with cached TweenInfo, global speed and Reduce Motion support.
]]

local Services = require("Core/Services")

local Tween = {
	Speed = 1, -- global multiplier (Settings -> Animation Speed)
	Reduced = false, -- Reduce Motion: near-instant transitions

	-- Durations (snappy 120Hz Apple-style deceleration timings)
	Instant = 0.07,
	Fast = 0.14,
	Normal = 0.22,
	Smooth = 0.32,
	Slow = 0.45,
}

local infoCache = {}

local function getInfo(duration, style, direction, delayTime)
	local key = string.format("%.3f|%s|%s|%.3f", duration, style.Name, direction.Name, delayTime or 0)
	local info = infoCache[key]
	if not info then
		info = TweenInfo.new(duration, style, direction, 0, false, delayTime or 0)
		infoCache[key] = info
	end
	return info
end

local function scale(duration)
	if Tween.Reduced then
		return 0.01
	end
	return math.max((duration or Tween.Normal) * Tween.Speed, 0.01)
end

-- Tween.Play(instance, { Prop = value }, duration?, style?, direction?, delay?)
function Tween.Play(instance, properties, duration, style, direction, delayTime)
	local tween = Services.TweenService:Create(
		instance,
		getInfo(scale(duration), style or Enum.EasingStyle.Quint, direction or Enum.EasingDirection.Out, delayTime),
		properties
	)
	tween:Play()
	return tween
end

-- Crisp Apple-style fluid deceleration used for knobs, popovers, pills and panels (no overshoot)
function Tween.Spring(instance, properties, duration)
	return Tween.Play(instance, properties, duration or Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
end

function Tween.Linear(instance, properties, duration)
	-- linear tweens are used for timers; they ignore Reduce Motion so timing stays correct
	local tween = Services.TweenService:Create(
		instance,
		getInfo(math.max(duration, 0.01), Enum.EasingStyle.Linear, Enum.EasingDirection.Out),
		properties
	)
	tween:Play()
	return tween
end

-- Runs `callback` when the tween completes (or immediately for nil)
function Tween.Then(tween, callback)
	if not tween then
		callback()
		return
	end
	local connection
	connection = tween.Completed:Connect(function(state)
		connection:Disconnect()
		if state == Enum.PlaybackState.Completed then
			callback()
		end
	end)
end

-- Animates a number from -> to, calling onStep(value) each frame. Returns a cancel function.
function Tween.Number(from, to, duration, onStep, onDone)
	local holder = Instance.new("NumberValue")
	holder.Value = from
	local connection = holder:GetPropertyChangedSignal("Value"):Connect(function()
		onStep(holder.Value)
	end)
	local tween = Tween.Play(holder, { Value = to }, duration or Tween.Slow, Enum.EasingStyle.Quint)
	local finished = false
	local function finish()
		if finished then
			return
		end
		finished = true
		connection:Disconnect()
		holder:Destroy()
	end
	tween.Completed:Connect(function(state)
		if state == Enum.PlaybackState.Completed then
			onStep(to)
			if onDone then
				onDone()
			end
		end
		finish()
	end)
	return function()
		tween:Cancel()
		finish()
	end
end

return Tween
end

__modules["Core/Util"] = function()
--[[
	Bali UI · Core/Util
	Pure helpers: math, formatting, colors, safe calls, key names, executor shims.
]]

local Services = require("Core/Services")

local Util = {}

-- ─── Math ────────────────────────────────────────────────────────────────────

function Util.Clamp(value, min, max)
	if value < min then
		return min
	elseif value > max then
		return max
	end
	return value
end

function Util.Lerp(a, b, t)
	return a + (b - a) * t
end

-- Number of decimals implied by a step (0.25 -> 2, 1 -> 0, 0.1 -> 1)
function Util.Decimals(step)
	if not step or step >= 1 or step <= 0 then
		return 0
	end
	local text = string.format("%.6f", step):gsub("0+$", "")
	local dot = text:find("%.")
	return dot and (#text - dot) or 0
end

-- Snap a value to a step relative to min, then clamp
function Util.Snap(value, min, max, step)
	step = (step and step > 0) and step or 1
	local snapped = min + math.floor((value - min) / step + 0.5) * step
	local decimals = Util.Decimals(step)
	local factor = 10 ^ decimals
	snapped = math.floor(snapped * factor + 0.5) / factor
	return Util.Clamp(snapped, math.min(min, max), math.max(min, max))
end

function Util.FormatNumber(value, decimals)
	decimals = decimals or 0
	local text = string.format("%." .. decimals .. "f", value)
	local sign, int, frac = text:match("^([%-]?)(%d+)(%.?%d*)$")
	if not int then
		return text
	end
	int = int:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
	return sign .. int .. frac
end

-- ─── Tables ──────────────────────────────────────────────────────────────────

function Util.Merge(defaults, overrides)
	local result = {}
	for key, value in pairs(defaults) do
		result[key] = value
	end
	if type(overrides) == "table" then
		for key, value in pairs(overrides) do
			result[key] = value
		end
	end
	return result
end

-- Accepts a string shorthand ("Title") or an options table
function Util.Options(options, defaults, shorthandKey)
	if type(options) ~= "table" then
		options = { [shorthandKey or "Title"] = options }
	end
	return Util.Merge(defaults or {}, options)
end

function Util.Find(list, value)
	for index, item in ipairs(list) do
		if item == value then
			return index
		end
	end
	return nil
end

function Util.Copy(list)
	local result = {}
	for index, item in ipairs(list) do
		result[index] = item
	end
	return result
end

function Util.Count(dictionary)
	local count = 0
	for _ in pairs(dictionary) do
		count += 1
	end
	return count
end

-- ─── Strings ─────────────────────────────────────────────────────────────────

function Util.Trim(text)
	return (tostring(text):gsub("^%s+", ""):gsub("%s+$", ""))
end

function Util.RandomString(length)
	local chars = {}
	for index = 1, length or 12 do
		chars[index] = string.char(math.random(97, 122))
	end
	return table.concat(chars)
end

function Util.Matches(haystack, query)
	if not query or query == "" then
		return true
	end
	if not haystack then
		return false
	end
	return string.find(string.lower(tostring(haystack)), string.lower(query), 1, true) ~= nil
end

-- ─── Colors ──────────────────────────────────────────────────────────────────

function Util.ToHex(color)
	return string.format(
		"%02X%02X%02X",
		math.floor(color.R * 255 + 0.5),
		math.floor(color.G * 255 + 0.5),
		math.floor(color.B * 255 + 0.5)
	)
end

function Util.FromHex(hex)
	hex = tostring(hex or ""):gsub("#", ""):gsub("%s", "")
	if #hex == 3 then
		hex = hex:sub(1, 1):rep(2) .. hex:sub(2, 2):rep(2) .. hex:sub(3, 3):rep(2)
	end
	if #hex ~= 6 or hex:find("[^%x]") then
		return nil
	end
	return Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16))
end

function Util.LerpColor(a, b, t)
	return Color3.new(Util.Lerp(a.R, b.R, t), Util.Lerp(a.G, b.G, t), Util.Lerp(a.B, b.B, t))
end

function Util.Luminance(color)
	return 0.2126 * color.R + 0.7152 * color.G + 0.0722 * color.B
end

-- ─── Safe execution ──────────────────────────────────────────────────────────

Util.ErrorHandler = nil -- set by the library to surface callback errors as toasts

function Util.SafeCall(fn, ...)
	if type(fn) ~= "function" then
		return false
	end
	local ok, result = pcall(fn, ...)
	if not ok then
		warn("[Bali] Callback error: " .. tostring(result))
		if Util.ErrorHandler then
			pcall(Util.ErrorHandler, result)
		end
	end
	return ok, result
end

-- Fire a user callback without letting it yield or break UI code
function Util.Spawn(fn, ...)
	if type(fn) ~= "function" then
		return
	end
	task.spawn(Util.SafeCall, fn, ...)
end

-- ─── Input helpers ───────────────────────────────────────────────────────────

-- Mouse position in AbsolutePosition space (GUI inset removed)
function Util.MousePosition()
	local UserInputService = Services.UserInputService
	local location = UserInputService:GetMouseLocation()
	local inset = Services.GuiService:GetGuiInset()
	return Vector2.new(location.X - inset.X, location.Y - inset.Y)
end

function Util.IsPointer(input)
	local inputType = input.UserInputType
	return inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch
end

function Util.IsMove(input)
	local inputType = input.UserInputType
	return inputType == Enum.UserInputType.MouseMovement or inputType == Enum.UserInputType.Touch
end

function Util.IsTouchDevice()
	local UserInputService = Services.UserInputService
	return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
end

local keyAliases = {
	LeftShift = "LShift",
	RightShift = "RShift",
	LeftControl = "LCtrl",
	RightControl = "RCtrl",
	LeftAlt = "LAlt",
	RightAlt = "RAlt",
	LeftSuper = "LCmd",
	RightSuper = "RCmd",
	Return = "Enter",
	Backspace = "Back",
	CapsLock = "Caps",
	PageUp = "PgUp",
	PageDown = "PgDn",
	Insert = "Ins",
	Delete = "Del",
	Escape = "Esc",
	One = "1",
	Two = "2",
	Three = "3",
	Four = "4",
	Five = "5",
	Six = "6",
	Seven = "7",
	Eight = "8",
	Nine = "9",
	Zero = "0",
	MouseButton1 = "MB1",
	MouseButton2 = "MB2",
	MouseButton3 = "MB3",
	Minus = "-",
	Equals = "=",
	LeftBracket = "[",
	RightBracket = "]",
	Semicolon = ";",
	Quote = "'",
	Comma = ",",
	Period = ".",
	Slash = "/",
	BackSlash = "\\",
	Backquote = "`",
}

-- Converts an Enum.KeyCode / Enum.UserInputType (or its name) into a short label
function Util.KeyName(key)
	if key == nil then
		return "None"
	end
	local name = typeof(key) == "EnumItem" and key.Name or tostring(key)
	return keyAliases[name] or name
end

-- Resolves a string/EnumItem into an EnumItem (KeyCode or mouse UserInputType)
function Util.ResolveKey(key)
	if key == nil or key == "None" or key == "" then
		return nil
	end
	if typeof(key) == "EnumItem" then
		return key
	end
	local name = tostring(key)
	if name == "MB1" or name == "MouseButton1" then
		return Enum.UserInputType.MouseButton1
	elseif name == "MB2" or name == "MouseButton2" then
		return Enum.UserInputType.MouseButton2
	elseif name == "MB3" or name == "MouseButton3" then
		return Enum.UserInputType.MouseButton3
	end
	for alias, real in pairs(keyAliases) do
		if real == name then
			name = alias
			break
		end
	end
	local ok, item = pcall(function()
		return Enum.KeyCode[name]
	end)
	return ok and item or nil
end

-- ─── Executor shims ──────────────────────────────────────────────────────────

local env = (typeof(getgenv) == "function" and getgenv()) or _G
local _fenv = typeof(getfenv) == "function" and getfenv(1) or nil
Util.Env = env

function Util.Global(name)
	local value = env[name]
	if value == nil then
		value = rawget(_G, name)
	end
	if value == nil and type(_fenv) == "table" then
		value = _fenv[name]
	end
	return value
end

function Util.SetClipboard(text)
	local fn = Util.Global("setclipboard") or Util.Global("toclipboard") or Util.Global("set_clipboard")
	if type(fn) == "function" then
		return (pcall(fn, tostring(text)))
	end
	return false
end

function Util.ExecutorName()
	local name = "Roblox Studio"
	pcall(function()
		local fn = Util.Global("identifyexecutor") or Util.Global("getexecutorname")
		if type(fn) == "function" then
			local res = fn()
			if res and tostring(res) ~= "" then
				name = tostring(res)
			end
		end
	end)
	return name
end

function Util.ExtractInviteCode(raw)
	local s = Util.Trim(tostring(raw or ""))
	s = s:gsub("%?.*$", ""):gsub("/+$", "")
	return s:match("([^/]+)$") or s
end

function Util.HttpGet(url, acceptJson, noGameFallback)
	local headers = { ["User-Agent"] = "Mozilla/5.0" }
	if acceptJson ~= false then
		headers["Accept"] = "application/json"
	end
	local synTbl = Util.Global("syn")
	local httpTbl = Util.Global("http")
	local fluxusTbl = Util.Global("fluxus")
	local req = (type(synTbl) == "table" and synTbl.request)
		or (type(httpTbl) == "table" and httpTbl.request)
		or Util.Global("http_request")
		or Util.Global("request")
		or (type(fluxusTbl) == "table" and fluxusTbl.request)

	if type(req) == "function" then
		local ok, res = pcall(req, { Url = url, Method = "GET", Headers = headers })
		if ok and type(res) == "table" then
			local code = tonumber(res.StatusCode or res.status_code)
			if code and code >= 400 and code < 500 then
				return nil, code
			end
			if type(res.Body) == "string" and #res.Body > 0 then
				if (res.Success == nil or res.Success == true) and (not code or (code >= 200 and code < 300)) then
					return res.Body, code or 200
				end
			end
		end
	end

	if noGameFallback then
		return nil, 0
	end

	local ok, body = pcall(function()
		return game:HttpGet(url)
	end)
	if ok and type(body) == "string" and #body > 0 then
		return body, 200
	end
	return nil, 0
end

function Util.CloneRef(instance)
	if instance == nil then
		return nil
	end
	local cloneFn = Util.Global("cloneref")
	if type(cloneFn) == "function" then
		local ok, cloned = pcall(cloneFn, instance)
		if ok and cloned ~= nil then
			return cloned
		end
	end
	return instance
end

function Util.ProtectGui(gui)
	if gui == nil then
		return false
	end
	local synTbl = Util.Global("syn")
	local protectFn = (type(synTbl) == "table" and synTbl.protect_gui)
		or Util.Global("protect_gui")
		or Util.Global("protectgui")
	if type(protectFn) == "function" then
		local ok = pcall(protectFn, gui)
		return ok
	end
	return false
end

function Util.ConstantTimeEquals(a, b)
	if type(a) ~= "string" or type(b) ~= "string" then
		return false
	end
	local lenA, lenB = #a, #b
	local diff = bit32.bxor(lenA, lenB)
	local maxLen = math.max(lenA, lenB)
	local byte = string.byte
	for i = 1, maxLen do
		local ca = i <= lenA and byte(a, i) or 0
		local cb = i <= lenB and byte(b, i) or 0
		diff = bit32.bor(diff, bit32.bxor(ca, cb))
	end
	return diff == 0
end

-- Deterministic 256-bit keyed digest (8 independent 32-bit avalanche lanes -> 64 hex chars)
function Util.HashKey(input, salt)
	local text = tostring(salt or "BaliKeySalt_v1") .. "\0" .. tostring(input or "")
	local lanes = {
		0x811c9dc5, 0x9e3779b9, 0x85ebca6b, 0xc2b2ae35,
		0x27d4eb2f, 0x165667b1, 0x5bd1e995, 0x6c62272e,
	}
	local bxor = bit32.bxor
	local lrot = bit32.lrotate
	local rshift = bit32.rshift
	local band = bit32.band
	local byte = string.byte

	for i = 1, #text do
		local b = byte(text, i)
		for lane = 1, 8 do
			local h = bxor(lanes[lane], b + i * (lane * 17))
			h = band(h * 0x01000193, 0xFFFFFFFF)
			h = bxor(lrot(h, (lane * 5 + i) % 31 + 1), rshift(h, (lane % 7) + 3))
			lanes[lane] = band(h + lanes[((lane % 8) + 1)], 0xFFFFFFFF)
		end
	end

	-- Cross-lane finalization rounds
	for round = 1, 4 do
		for lane = 1, 8 do
			local prev = lanes[((lane + 6) % 8) + 1]
			local h = bxor(lanes[lane], rshift(prev, 13))
			h = bxor(lrot(h, 7 + round), prev)
			h = band(h * 0x85ebca6b, 0xFFFFFFFF)
			lanes[lane] = bxor(h, rshift(h, 16))
		end
	end

	local out = table.create(8)
	for lane = 1, 8 do
		out[lane] = string.format("%08x", lanes[lane])
	end
	return table.concat(out)
end

function Util.SanitizeKeyInput(text, maxLen)
	local s = tostring(text or "")
	s = string.gsub(s, "%c", "")
	s = Util.Trim(s)
	local cap = tonumber(maxLen) or 128
	if #s > cap then
		s = string.sub(s, 1, cap)
	end
	return s
end

local _corePcall = pcall
local _coreRawequal = rawequal
local _coreTostring = tostring
local _coreByte = string.byte
local _coreBxor = bit32.bxor
local _coreClock = os.clock

local _corePrims = { _corePcall, _coreRawequal, _coreTostring, _coreByte, _coreBxor, _coreClock }
local _baselineMeta = {}
do
	local isLuaFn = Util.Global("islclosure")
	local isCFn = Util.Global("iscclosure")
	for idx, fn in ipairs(_corePrims) do
		local meta = {}
		if type(isLuaFn) == "function" then
			local ok, res = _corePcall(isLuaFn, fn)
			if ok then
				meta.isL = res
			end
		end
		if type(isCFn) == "function" then
			local ok, res = _corePcall(isCFn, fn)
			if ok then
				meta.isC = res
			end
		end
		if type(debug) == "table" and type(debug.info) == "function" then
			local ok, src = _corePcall(debug.info, fn, "s")
			if ok then
				meta.src = src
			end
		end
		_baselineMeta[idx] = meta
	end
end

function Util.VerifyIntegrity()
	if not _coreRawequal(pcall, _corePcall)
		or not _coreRawequal(rawequal, _coreRawequal)
		or not _coreRawequal(tostring, _coreTostring)
		or not _coreRawequal(string.byte, _coreByte)
		or not _coreRawequal(bit32.bxor, _coreBxor)
		or not _coreRawequal(os.clock, _coreClock)
	then
		return false, "Runtime primitive mismatch detected"
	end

	if _coreBxor(0x5A, 0xA5) ~= 0xFF or _coreByte("A") ~= 65 or _coreTostring(42) ~= "42" then
		return false, "Runtime primitive behavior check failed"
	end

	local isLuaFn = Util.Global("islclosure")
	local isCFn = Util.Global("iscclosure")
	for idx, fn in ipairs(_corePrims) do
		local base = _baselineMeta[idx] or {}
		if base.isL ~= nil and type(isLuaFn) == "function" then
			local ok, hooked = _corePcall(isLuaFn, fn)
			if ok and hooked ~= base.isL then
				return false, "Hooked core primitive detected"
			end
		end
		if base.isC ~= nil and type(isCFn) == "function" then
			local ok, native = _corePcall(isCFn, fn)
			if ok and native ~= base.isC then
				return false, "Non-baseline core primitive detected"
			end
		end
		if base.src ~= nil and type(debug) == "table" and type(debug.info) == "function" then
			local ok, src = _corePcall(debug.info, fn, "s")
			if ok and src ~= base.src then
				return false, "Tampered primitive source detected"
			end
		end
	end
	return true
end

Util.FS = {
	Supported = function()
		return type(Util.Global("writefile")) == "function" and type(Util.Global("readfile")) == "function"
	end,
	Write = function(path, contents)
		local fn = Util.Global("writefile")
		return fn and (pcall(fn, path, contents)) or false
	end,
	Read = function(path)
		local fn = Util.Global("readfile")
		if not fn then
			return nil
		end
		local ok, result = pcall(fn, path)
		return ok and result or nil
	end,
	IsFile = function(path)
		local fn = Util.Global("isfile")
		if not fn then
			return false
		end
		local ok, result = pcall(fn, path)
		return ok and result == true
	end,
	IsFolder = function(path)
		local fn = Util.Global("isfolder")
		if not fn then
			return false
		end
		local ok, result = pcall(fn, path)
		return ok and result == true
	end,
	MakeFolder = function(path)
		local make = Util.Global("makefolder")
		if not make then
			return false
		end
		-- create each segment so nested paths work on every executor
		local current = ""
		for segment in string.gmatch(path, "[^/\\]+") do
			current = current == "" and segment or (current .. "/" .. segment)
			if not Util.FS.IsFolder(current) then
				pcall(make, current)
			end
		end
		return true
	end,
	List = function(path)
		local fn = Util.Global("listfiles")
		if not fn then
			return {}
		end
		local ok, result = pcall(fn, path)
		return (ok and type(result) == "table") and result or {}
	end,
	Delete = function(path)
		local fn = Util.Global("delfile")
		return fn and (pcall(fn, path)) or false
	end,
}

return Util
end

__modules["Systems/Blur"] = function()
--[[
	Bali UI · Systems/Blur
	Safely manages a dedicated Lighting BlurEffect synchronized with UI open state.
]]

local Services = require("Core/Services")
local Tween = require("Core/Tween")
local Util = require("Core/Util")

local Blur = {}

local enabled = true
local intensity = 8
local isOpen = false
local blurEffect = nil
local activeTween = nil
local tweenToken = 0

local function getLighting()
	local ok, lighting = pcall(function()
		return Services.Lighting
	end)
	return ok and lighting or nil
end

local function ensureEffect()
	if blurEffect and blurEffect.Parent then
		return blurEffect
	end
	local lighting = getLighting()
	if not lighting then
		return nil
	end
	for _, legacyName in ipairs({ "LuminaBlur", "BaliBlur" }) do
		local legacy = lighting:FindFirstChild(legacyName)
		if legacy and legacy:IsA("BlurEffect") then
			pcall(function()
				legacy:Destroy()
			end)
		end
	end
	local envBlur = Util.Global("_BaliBlurEffect")
	if typeof(envBlur) == "Instance" and envBlur:IsA("BlurEffect") and envBlur.Parent == lighting then
		blurEffect = envBlur
		return blurEffect
	end
	local created
	pcall(function()
		created = Instance.new("BlurEffect")
		created.Name = Util.RandomString(10)
		created.Size = 0
		created.Enabled = false
		created.Parent = lighting
	end)
	blurEffect = created
	if created and type(Util.Env) == "table" then
		Util.Env._BaliBlurEffect = created
	end
	return blurEffect
end

local function sync()
	tweenToken += 1
	local myToken = tweenToken

	if activeTween then
		pcall(function()
			activeTween:Cancel()
		end)
		activeTween = nil
	end

	local shouldShow = enabled and isOpen and intensity > 0
	if shouldShow then
		local effect = ensureEffect()
		if not effect then
			return
		end
		effect.Enabled = true
		if Tween.Reduced then
			effect.Size = intensity
		else
			activeTween = Tween.Play(effect, { Size = intensity }, Tween.Normal, Enum.EasingStyle.Quad)
		end
	else
		if not blurEffect or not blurEffect.Parent then
			return
		end
		local effect = blurEffect
		if Tween.Reduced then
			effect.Size = 0
			effect.Enabled = false
		else
			local tween = Tween.Play(effect, { Size = 0 }, Tween.Fast, Enum.EasingStyle.Quad)
			activeTween = tween
			Tween.Then(tween, function()
				if tweenToken == myToken and effect.Parent then
					effect.Enabled = false
				end
			end)
		end
	end
end

function Blur.SetEnabled(state)
	enabled = state == true
	sync()
end

function Blur.SetIntensity(value)
	intensity = Util.Clamp(tonumber(value) or 0, 0, 56)
	sync()
end

function Blur.SetOpen(state)
	isOpen = state == true
	sync()
end

function Blur.IsEnabled()
	return enabled
end

function Blur.GetIntensity()
	return intensity
end

function Blur.Destroy()
	tweenToken += 1
	if activeTween then
		pcall(function()
			activeTween:Cancel()
		end)
		activeTween = nil
	end
	if blurEffect then
		if type(Util.Env) == "table" and Util.Env._BaliBlurEffect == blurEffect then
			Util.Env._BaliBlurEffect = nil
		end
		pcall(function()
			blurEffect:Destroy()
		end)
		blurEffect = nil
	end
end

return Blur
end

__modules["Systems/CommandPalette"] = function()
--[[
	Bali UI · Systems/CommandPalette
	Apple Spotlight / Raycast style glass modal with live fuzzy search across tabs,
	elements, and themes, full keyboard navigation, and click/touch execution.
]]

local Services = require("Core/Services")
local Maid = require("Core/Maid")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Util = require("Core/Util")

local CommandPalette = {}

local MAX_RESULTS = 40
local ROW_HEIGHT = 44
local ROW_GAP = 4
local MAX_LIST_HEIGHT = 290

local rootMaid = Maid.new()
local openMaid = Maid.new()
local layer = nil
local windowRef = nil

local backdrop = nil
local shadow = nil
local modal = nil
local searchBox = nil
local resultsScroll = nil
local emptyLabel = nil
local footerHint = nil

local isOpen = false
local results = {} -- current filtered items
local rowViews = {} -- UI rows matching `results`
local selectedIndex = 0
local queryToken = 0

local TYPE_ICONS = {
	Tab = "layers",
	Theme = "palette",
	Button = "pointer",
	ButtonGroup = "pointer",
	Toggle = "toggle",
	Checkbox = "list-checks",
	Slider = "sliders",
	RangeSlider = "sliders",
	Stepper = "sliders",
	Input = "type",
	Dropdown = "list",
	Segmented = "sliders",
	Keybind = "key",
	ColorPicker = "droplet",
	Accordion = "folder",
	StatCard = "chart-line",
	Chart = "chart-line",
	ProgressBar = "gauge",
	Table = "grid",
	CardGrid = "grid",
}

local function getViewportSize()
	if layer and layer.AbsoluteSize.X > 0 and layer.AbsoluteSize.Y > 0 then
		return layer.AbsoluteSize
	end
	local cam = Services.Workspace.CurrentCamera
	return cam and cam.ViewportSize or Vector2.new(1280, 720)
end

local function fuzzyScore(query, text)
	if not query or query == "" then
		return 1
	end
	if not text or text == "" then
		return nil
	end

	local q = string.lower(query)
	local t = string.lower(tostring(text))

	if t == q then
		return 1000
	end
	if string.sub(t, 1, #q) == q then
		return 850 - #t
	end

	local foundPos = string.find(t, q, 1, true)
	if foundPos then
		return 650 - foundPos * 2
	end

	-- Subsequence fuzzy match
	local qi = 1
	local qLen = #q
	local score = 200
	local lastMatch = 0
	for ti = 1, #t do
		if string.byte(t, ti) == string.byte(q, qi) then
			if lastMatch > 0 then
				if ti == lastMatch + 1 then
					score += 18
				else
					score -= math.min(ti - lastMatch, 12)
				end
			end
			if ti == 1 or string.sub(t, ti - 1, ti - 1) == " " then
				score += 14
			end
			lastMatch = ti
			qi += 1
			if qi > qLen then
				return math.max(score, 10)
			end
		end
	end

	return nil
end

local function syncShadow()
	if not shadow or not modal then
		return
	end
	if not modal.Visible then
		shadow.Visible = false
		return
	end
	local shadowInfo = Assets.Shadow()
	local inset = shadowInfo.Inset or 24
	local absPos = modal.AbsolutePosition
	local absSize = modal.AbsoluteSize
	local parentPos = (backdrop and backdrop:IsA("GuiBase2d")) and backdrop.AbsolutePosition or Vector2.zero

	shadow.Visible = true
	shadow.Position = UDim2.fromOffset(absPos.X - parentPos.X - inset, absPos.Y - parentPos.Y - inset)
	shadow.Size = UDim2.fromOffset(absSize.X + inset * 2, absSize.Y + inset * 2)
end

local function scrollElementIntoView(tab, element)
	if not tab or not element or not element.Frame then
		return
	end
	task.defer(function()
		pcall(function()
			local page = tab.Page or tab._page or tab.Container
			if not page or not page:IsA("ScrollingFrame") then
				return
			end
			local frame = element.Frame
			if not frame or not frame.Parent then
				return
			end
			local relY = frame.AbsolutePosition.Y - page.AbsolutePosition.Y + page.CanvasPosition.Y
			local targetY = math.max(0, relY - page.AbsoluteSize.Y * 0.35)
			Tween.Play(page, { CanvasPosition = Vector2.new(page.CanvasPosition.X, targetY) }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		end)
	end)
end

local function executeItem(item)
	if not item then
		return
	end

	CommandPalette.Close()

	if item.Kind == "Theme" then
		Theme.Set(item.ThemeName, true)
		return
	end

	if item.Kind == "Tab" then
		if windowRef and type(windowRef.SelectTab) == "function" and item.Tab then
			pcall(windowRef.SelectTab, windowRef, item.Tab)
		elseif item.Tab and type(item.Tab.Select) == "function" then
			pcall(item.Tab.Select, item.Tab)
		end
		return
	end

	if item.Kind == "Element" then
		if windowRef and type(windowRef.SelectTab) == "function" and item.Tab then
			pcall(windowRef.SelectTab, windowRef, item.Tab)
		elseif item.Tab and type(item.Tab.Select) == "function" then
			pcall(item.Tab.Select, item.Tab)
		end
		if item.SubTab and type(item.SubTab.Select) == "function" then
			pcall(item.SubTab.Select, item.SubTab)
		end

		local el = item.Element
		if el then
			scrollElementIntoView(item.Tab, el)
			if item.ElemType == "Button" and type(el.Fire) == "function" then
				Util.Spawn(el.Fire, el)
			elseif (item.ElemType == "Toggle" or item.ElemType == "Checkbox") then
				if type(el.Toggle) == "function" then
					Util.Spawn(el.Toggle, el)
				elseif type(el.Set) == "function" and type(el.Get) == "function" then
					local ok, cur = pcall(el.Get, el)
					if ok then
						Util.Spawn(el.Set, el, not cur)
					end
				end
			end
			if type(el.Flash) == "function" then
				pcall(el.Flash, el)
			end
		end
	end
end

local function collectMatches(query)
	local candidates = {}

	-- Tabs
	if windowRef and type(windowRef.Tabs) == "table" then
		for _, tab in ipairs(windowRef.Tabs) do
			local title = tab.Title or "Tab"
			local score = fuzzyScore(query, title)
			if tab.Category and tab.Category ~= "" then
				local catScore = fuzzyScore(query, tab.Category .. " " .. title)
				if catScore and (not score or catScore > score) then
					score = catScore - 20
				end
			end
			if score then
				table.insert(candidates, {
					Score = score + (query == "" and 20 or 15),
					Kind = "Tab",
					Title = title,
					Subtitle = tab.Category and (tostring(tab.Category) .. "  •  Tab") or "Navigation Tab",
					Badge = "Jump",
					Icon = tab.Icon or "layers",
					Tab = tab,
				})
			end
		end
	end

	-- Registered Elements
	if windowRef and type(windowRef._elements) == "table" then
		for _, entry in ipairs(windowRef._elements) do
			if type(entry) == "table" and entry.Title and entry.Title ~= "" then
				local tabTitle = entry.Tab and entry.Tab.Title or ""
				local secTitle = entry.Section and entry.Section.Title or ""
				local subTitle = entry.SubTab and entry.SubTab.Title or ""
				local breadcrumb = ""
				if tabTitle ~= "" and secTitle ~= "" then
					breadcrumb = tabTitle .. (subTitle ~= "" and (" › " .. subTitle) or "") .. " › " .. secTitle
				elseif tabTitle ~= "" then
					breadcrumb = tabTitle
				elseif secTitle ~= "" then
					breadcrumb = secTitle
				end

				local best = fuzzyScore(query, entry.Title)
				if entry.Desc and entry.Desc ~= "" then
					local dScore = fuzzyScore(query, entry.Desc)
					if dScore and (not best or dScore - 30 > best) then
						best = dScore - 30
					end
				end
				if breadcrumb ~= "" then
					local bScore = fuzzyScore(query, breadcrumb .. " " .. entry.Title)
					if bScore and (not best or bScore - 40 > best) then
						best = bScore - 40
					end
				end

				if best then
					local elemType = tostring(entry.Type or "Control")
					local badgeMap = {
						Button = "Run",
						ColorPicker = "Color Picker",
						RangeSlider = "Range Slider",
						ProgressBar = "Progress",
						ButtonRow = "Buttons",
						CardGrid = "Cards",
						StatCard = "Stat",
					}
					local badge = badgeMap[elemType] or elemType
					if (elemType == "Toggle" or elemType == "Checkbox") and entry.Element and type(entry.Element.Get) == "function" then
						local ok, val = pcall(entry.Element.Get, entry.Element)
						if ok then
							badge = val and "ON" or "OFF"
						end
					end

					table.insert(candidates, {
						Score = best,
						Kind = "Element",
						ElemType = elemType,
						Title = tostring(entry.Title),
						Subtitle = breadcrumb ~= "" and breadcrumb or elemType,
						Badge = badge,
						Icon = TYPE_ICONS[elemType] or "chevron-right",
						Tab = entry.Tab,
						SubTab = entry.SubTab,
						Element = entry.Element,
					})
				end
			end
		end
	end

	-- Themes
	for _, themeName in ipairs(Theme.Order) do
		local score = fuzzyScore(query, themeName)
		local prefixed = fuzzyScore(query, "Theme " .. themeName)
		if prefixed and (not score or prefixed - 15 > score) then
			score = prefixed - 15
		end
		if score then
			table.insert(candidates, {
				Score = score - (query == "" and 10 or 0),
				Kind = "Theme",
				ThemeName = themeName,
				Title = "Theme: " .. themeName,
				Subtitle = Theme.Name == themeName and "Active Theme Preset" or "Switch Theme Preset",
				Badge = Theme.Name == themeName and "Active" or "Apply",
				Icon = "palette",
			})
		end
	end

	table.sort(candidates, function(a, b)
		if a.Score ~= b.Score then
			return a.Score > b.Score
		end
		return a.Title < b.Title
	end)

	if #candidates > MAX_RESULTS then
		local trimmed = {}
		for idx = 1, MAX_RESULTS do
			trimmed[idx] = candidates[idx]
		end
		return trimmed
	end
	return candidates
end

local function updateSelectionVisuals(ensureVisible)
	for idx, view in ipairs(rowViews) do
		local selected = idx == selectedIndex
		if selected then
			Theme.Bind(view.Button, { BackgroundColor3 = "TileHover" })
			view.Button.BackgroundTransparency = 0.08
			if view.Stroke then
				Theme.Bind(view.Stroke, { Color = "Accent" })
				view.Stroke.Transparency = 0.55
			end
			Theme.Bind(view.Title, { TextColor3 = "Text" })
		else
			Theme.Bind(view.Button, { BackgroundColor3 = "Tile" })
			view.Button.BackgroundTransparency = 0.65
			if view.Stroke then
				Theme.Bind(view.Stroke, { Color = "Stroke" })
				view.Stroke.Transparency = 0.9
			end
			Theme.Bind(view.Title, { TextColor3 = "Text" })
		end
	end

	if ensureVisible and selectedIndex >= 1 and selectedIndex <= #results and resultsScroll then
		local step = ROW_HEIGHT + ROW_GAP
		local itemTop = (selectedIndex - 1) * step
		local itemBottom = itemTop + ROW_HEIGHT
		local viewHeight = resultsScroll.AbsoluteSize.Y
		local canvasY = resultsScroll.CanvasPosition.Y
		if itemTop < canvasY then
			resultsScroll.CanvasPosition = Vector2.new(0, itemTop)
		elseif itemBottom > canvasY + viewHeight and viewHeight > 0 then
			resultsScroll.CanvasPosition = Vector2.new(0, itemBottom - viewHeight)
		end
	end
end

local function rebuildResults(query)
	if not resultsScroll then
		return
	end
	queryToken += 1

	for _, view in ipairs(rowViews) do
		if view.Button and view.Button.Parent then
			view.Button:Destroy()
		end
	end
	table.clear(rowViews)

	results = collectMatches(query)
	local count = #results
	emptyLabel.Visible = count == 0

	local vp = getViewportSize()
	local maxH = math.min(MAX_LIST_HEIGHT, math.max(120, vp.Y * 0.44))
	local contentH = count > 0 and (count * ROW_HEIGHT + (count - 1) * ROW_GAP + 12) or 84
	resultsScroll.Size = UDim2.new(1, 0, 0, math.min(maxH, contentH))
	resultsScroll.CanvasPosition = Vector2.zero

	for idx, item in ipairs(results) do
		local row = Create.New("TextButton", {
			Name = "Result_" .. tostring(idx),
			Parent = resultsScroll,
			Size = UDim2.new(1, 0, 0, ROW_HEIGHT),
			Corner = 9,
			Padding = { 6, 10, 6, 10 },
			Text = "",
			BackgroundTransparency = 0.65,
			Theme = { BackgroundColor3 = "Tile" },
			LayoutOrder = idx,
			ZIndex = 312,
		})

		local rowStroke = Create.Stroke(row, {
			Theme = { Color = "Stroke" },
			Transparency = 0.9,
			Thickness = 1,
		})

		local iconBox = Create.New("Frame", {
			Name = "IconBox",
			Parent = row,
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 2, 0.5, 0),
			Size = UDim2.fromOffset(26, 26),
			Corner = 7,
			BackgroundTransparency = 0.25,
			Theme = { BackgroundColor3 = "Field" },
			ZIndex = 313,
		})
		Icons.Create(item.Icon, {
			Size = UDim2.fromOffset(14, 14),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Color = item.Kind == "Theme" and "Accent" or "SubText",
			ZIndex = 314,
			Parent = iconBox,
		})

		local textBox = Create.New("Frame", {
			Name = "TextGroup",
			Parent = row,
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 38, 0.5, 0),
			Size = UDim2.new(1, -106, 1, 0),
			BackgroundTransparency = 1,
			ZIndex = 313,
		})

		local titleLabel = Create.Text({
			Name = "Title",
			Parent = textBox,
			Position = UDim2.fromOffset(0, 1),
			Size = UDim2.new(1, 0, 0, 16),
			Text = item.Title,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Font = "Medium",
			TextSize = 13,
			Color = "Text",
			ZIndex = 314,
		})

		Create.Text({
			Name = "Subtitle",
			Parent = textBox,
			Position = UDim2.fromOffset(0, 17),
			Size = UDim2.new(1, 0, 0, 14),
			Text = item.Subtitle,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Font = "Regular",
			TextSize = 11,
			Color = "SubText",
			ZIndex = 314,
		})

		local badge = Create.New("Frame", {
			Name = "Badge",
			Parent = row,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.fromScale(1, 0.5),
			Size = UDim2.fromOffset(0, 20),
			AutomaticSize = Enum.AutomaticSize.X,
			Corner = 6,
			Padding = { 0, 8, 0, 8 },
			BackgroundTransparency = 0.25,
			Theme = { BackgroundColor3 = "Field" },
			ZIndex = 313,
		})
		Create.GlassStroke(badge, 0.02)
		Create.Text({
			Name = "Label",
			Parent = badge,
			Size = UDim2.fromOffset(0, 20),
			AutomaticSize = Enum.AutomaticSize.X,
			TextXAlignment = Enum.TextXAlignment.Center,
			Text = item.Badge,
			Font = "SemiBold",
			TextSize = 10,
			Color = item.Badge == "ON" and "Accent" or "SubText",
			ZIndex = 314,
		})

		row.MouseEnter:Connect(function()
			if Util.IsTouchDevice() then
				return
			end
			selectedIndex = idx
			updateSelectionVisuals(false)
		end)

		row.Activated:Connect(function(input)
			Transition.Ripple(row, input)
			executeItem(item)
		end)

		rowViews[idx] = {
			Button = row,
			Stroke = rowStroke,
			Title = titleLabel,
		}
	end

	selectedIndex = count > 0 and 1 or 0
	updateSelectionVisuals(false)
	syncShadow()
end

local function updateModalWidth()
	if not modal then
		return
	end
	local vp = getViewportSize()
	local wrapper = windowRef and windowRef.MainWrapper
	if wrapper and wrapper.Parent and (not windowRef.IsVisible or windowRef:IsVisible()) and wrapper.AbsoluteSize.X > 0 and wrapper.AbsoluteSize.Y > 0 then
		local wPos = wrapper.AbsolutePosition
		local wSize = wrapper.AbsoluteSize
		local width = math.max(260, math.min(540, math.floor(wSize.X * 0.88), vp.X - 32))
		local modalH = modal.AbsoluteSize.Y > 0 and modal.AbsoluteSize.Y or 260
		local cx = Util.Clamp(wPos.X + wSize.X * 0.5, width * 0.5 + 12, math.max(width * 0.5 + 12, vp.X - width * 0.5 - 12))
		local topY = wPos.Y + Util.Clamp(math.floor(wSize.Y * 0.16), 24, 96)
		topY = Util.Clamp(topY, 12, math.max(12, vp.Y - modalH - 12))
		modal.Size = UDim2.fromOffset(width, 0)
		modal.Position = UDim2.fromOffset(math.floor(cx), math.floor(topY))
	else
		local width = math.max(260, math.min(540, vp.X - 32))
		local topRatio = vp.Y < 500 and 0.08 or 0.16
		modal.Size = UDim2.fromOffset(width, 0)
		modal.Position = UDim2.new(0.5, 0, topRatio, 0)
	end
	syncShadow()
end

local function ensureBuilt()
	if backdrop and backdrop.Parent then
		return true
	end
	if not layer or not layer.Parent then
		return false
	end

	backdrop = Create.New("TextButton", {
		Name = "BaliCommandPaletteBackdrop",
		Parent = layer,
		Visible = false,
		Active = true,
		Size = UDim2.fromScale(1, 1),
		Text = "",
		AutoButtonColor = false,
		BackgroundTransparency = 1,
		Theme = { BackgroundColor3 = "Overlay" },
		ZIndex = 300,
	})

	local shadowInfo = Assets.Shadow()
	shadow = Create.New("ImageLabel", {
		Name = "Shadow",
		Parent = backdrop,
		Visible = false,
		Image = shadowInfo.Image,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = shadowInfo.Slice,
		Theme = { ImageColor3 = "Shadow", ImageTransparency = "ShadowTransparency" },
		ZIndex = 301,
	})

	modal = Create.New("Frame", {
		Name = "Modal",
		Parent = backdrop,
		Visible = false,
		Active = true,
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.16, 0),
		Size = UDim2.fromOffset(520, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Corner = 14,
		ClipsDescendants = true,
		BackgroundTransparency = 0,
		Theme = {
			BackgroundColor3 = "Card",
		},
		ZIndex = 305,
	})
	Create.GlassStroke(modal, 0.12)

	local inputSink = Create.New("TextButton", {
		Name = "InputSink",
		Parent = modal,
		Size = UDim2.new(1, 0, 0, 0),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		Active = true,
		ZIndex = 305,
	})

	local glowId = Assets.Get("Glow")
	if glowId then
		Create.New("ImageLabel", {
			Name = "Glow",
			Parent = modal,
			Size = UDim2.fromOffset(320, 180),
			Position = UDim2.fromOffset(-80, -70),
			Corner = 14,
			Image = glowId,
			ScaleType = Enum.ScaleType.Stretch,
			Theme = {
				ImageColor3 = "Accent",
				ImageTransparency = function(t)
					return math.min(t.GlowTransparency + 0.05, 0.94)
				end,
			},
			ZIndex = 305,
		})
	end

	local body = Create.New("Frame", {
		Name = "Body",
		Parent = modal,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ZIndex = 308,
	})
	rootMaid:Give(body:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		inputSink.Size = UDim2.new(1, 0, 0, math.max(48, body.AbsoluteSize.Y))
	end))
	Create.List(body, { Direction = Enum.FillDirection.Vertical, Gap = 0 })

	local searchBar = Create.New("Frame", {
