		Theme = {
			TextColor3 = "Text",
			PlaceholderColor3 = "Muted",
		},
		ZIndex = 310,
	})

	local escChip = Create.Text({
		Class = "TextButton",
		Name = "EscChip",
		Parent = searchBar,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.fromOffset(38, 22),
		Corner = 6,
		BackgroundTransparency = 0.2,
		TextXAlignment = Enum.TextXAlignment.Center,
		Text = "Esc",
		Font = "SemiBold",
		TextSize = 10,
		Color = "SubText",
		Theme = { BackgroundColor3 = "Field", TextColor3 = "SubText" },
		ZIndex = 310,
	})
	Create.GlassStroke(escChip, 0.02)

	Create.New("Frame", {
		Name = "TopDivider",
		Parent = body,
		Size = UDim2.new(1, 0, 0, 1),
		LayoutOrder = 2,
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		ZIndex = 309,
	})

	local listWrap = Create.New("Frame", {
		Name = "ListWrap",
		Parent = body,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
