		TextSize = 11,
		Color = "SubText",
		ZIndex = 310,
	})

	rootMaid:Give(backdrop.Activated:Connect(function(input)
		-- Close only when clicking backdrop outside modal
		local pos = typeof(input) == "InputObject" and Vector2.new(input.Position.X, input.Position.Y) or Util.MousePosition()
		local mPos = modal.AbsolutePosition
		local mSize = modal.AbsoluteSize
		local inside = pos.X >= mPos.X and pos.X <= mPos.X + mSize.X and pos.Y >= mPos.Y and pos.Y <= mPos.Y + mSize.Y
		if not inside then
			CommandPalette.Close()
		end
	end))

	rootMaid:Give(escChip.Activated:Connect(function(input)
		Transition.Ripple(escChip, input)
		CommandPalette.Close()
	end))

	rootMaid:Give(searchBox:GetPropertyChangedSignal("Text"):Connect(function()
		if isOpen then
			rebuildResults(searchBox.Text)
		end
	end))

	rootMaid:Give(searchBox.FocusLost:Connect(function(enterPressed)
		if isOpen and enterPressed and selectedIndex >= 1 and results[selectedIndex] then
			executeItem(results[selectedIndex])
		end
	end))

	rootMaid:Give(modal:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncShadow))
	rootMaid:Give(layer:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateModalWidth))

	updateModalWidth()
	return true
end

function CommandPalette.Init(popupLayer, window)
	if layer ~= popupLayer then
		rootMaid:Clean()
		openMaid:Clean()
		if backdrop then
			backdrop:Destroy()
			backdrop = nil
		end
		layer = popupLayer
	end
	windowRef = window
	isOpen = false
	ensureBuilt()
	return CommandPalette
end

function CommandPalette.Open()
	if isOpen then
		return
	end
	if not ensureBuilt() or not searchBox then
		return
	end

	isOpen = true
	openMaid:Clean()
	updateModalWidth()

	backdrop.Active = true
	backdrop:SetAttribute("_BaliClosing", nil)
	backdrop.Visible = true
	backdrop.BackgroundTransparency = 1
	Tween.Play(backdrop, { BackgroundTransparency = 0.22 }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

	searchBox.Text = ""
	rebuildResults("")
	updateModalWidth()
	Transition.Mount(modal, 0.95)
	syncShadow()
	if shadow then
		shadow.ImageTransparency = 1
		Tween.Play(shadow, { ImageTransparency = Theme.Current.ShadowTransparency }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end

	openMaid:Give(Services.UserInputService.InputBegan:Connect(function(input)
		if not isOpen then
			return
		end
		if input.UserInputType ~= Enum.UserInputType.Keyboard then
			return
		end
		local code = input.KeyCode
		if code == Enum.KeyCode.Escape then
			CommandPalette.Close()
		elseif code == Enum.KeyCode.Down then
			if #results > 0 then
				selectedIndex = (selectedIndex % #results) + 1
				updateSelectionVisuals(true)
			end
		elseif code == Enum.KeyCode.Up then
			if #results > 0 then
				selectedIndex = ((selectedIndex - 2) % #results) + 1
				updateSelectionVisuals(true)
			end
		elseif (code == Enum.KeyCode.Return or code == Enum.KeyCode.KeypadEnter) then
			if Services.UserInputService:GetFocusedTextBox() ~= searchBox then
				if selectedIndex >= 1 and results[selectedIndex] then
					executeItem(results[selectedIndex])
				end
			end
		end
	end))

	task.defer(function()
		if isOpen and searchBox and searchBox.Parent then
			pcall(function()
				searchBox:CaptureFocus()
			end)
		end
	end)
end

function CommandPalette.Close()
	if not isOpen then
		return
	end
	isOpen = false
	openMaid:Clean()

	if searchBox then
		pcall(function()
			searchBox:ReleaseFocus()
		end)
	end
	if shadow then
		Tween.Play(shadow, { ImageTransparency = 1 }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end
	if backdrop then
		backdrop.Active = false
		backdrop:SetAttribute("_BaliClosing", true)
		Tween.Play(backdrop, { BackgroundTransparency = 1 }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end
	if modal then
		Transition.Unmount(modal, 0.95, function()
			if not isOpen then
				if shadow and shadow.Parent then
					shadow.Visible = false
				end
				if backdrop and backdrop.Parent then
					backdrop.Visible = false
				end
				if modal and modal.Parent then
					modal.Visible = false
				end
			end
		end)
	elseif backdrop then
		if shadow and shadow.Parent then
			shadow.Visible = false
		end
		backdrop.Visible = false
	end
end

function CommandPalette.Toggle()
	if isOpen then
		CommandPalette.Close()
	else
		CommandPalette.Open()
	end
end

function CommandPalette.IsOpen()
	return isOpen
end

function CommandPalette.Destroy()
	isOpen = false
	openMaid:Clean()
	rootMaid:Clean()
	table.clear(results)
	table.clear(rowViews)
	if backdrop then
		backdrop:Destroy()
		backdrop = nil
	end
	shadow = nil
	modal = nil
	searchBox = nil
	resultsScroll = nil
	emptyLabel = nil
	footerHint = nil
	layer = nil
	windowRef = nil
end

return CommandPalette
end

__modules["Systems/Config"] = function()
--[[
	Bali UI · Systems/Config
	JSON profile manager with HttpService + pure-Lua JSON fallback, Color3 hex+alpha
	and Enum serialization, autoload support, and optional Theme/Accent/Font/Blur/Watermark sync.
]]

local Services = require("Core/Services")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Tween = require("Core/Tween")
local Blur = require("Systems/Blur")
local Watermark = require("Systems/Watermark")
local KeybindList = require("Systems/KeybindList")

local Config = {}

local DEFAULT_FOLDER = "Bali/Configs"
local AUTOLOAD_FILE = "_autoload.txt"
local AUTOSAVE_FILE = "_autosave.json"
local AUTOSAVE_STATE_FILE = "_autosave_enabled.txt"

local folder = DEFAULT_FOLDER
local registryRef = nil
local extrasRef = nil
local memoryStore = {}
local memoryAutoLoad = nil
local memoryAutoSave = nil
local lastAutoSaveFlags = nil
local lastAutoSaveUnnamed = nil
local hasLoadedAutoSave = false
local autoSaveEnabled = true
local isLoading = false
local autoSaveToken = 0

-- ─── Pure-Lua JSON Encoder & Decoder ─────────────────────────────────────────

local encodeEscape = {
	['"'] = '\\"',
	["\\"] = "\\\\",
	["\b"] = "\\b",
	["\f"] = "\\f",
	["\n"] = "\\n",
	["\r"] = "\\r",
	["\t"] = "\\t",
}

local function encodeString(str)
	local escaped = string.gsub(str, '[%z\1-\31"\\]', function(ch)
		return encodeEscape[ch] or string.format("\\u%04x", string.byte(ch))
	end)
	return '"' .. escaped .. '"'
end

local function isArrayTable(tbl)
	local count = 0
	local maxIndex = 0
	for k in pairs(tbl) do
		if type(k) ~= "number" or k < 1 or k % 1 ~= 0 then
			return false, 0
		end
		count += 1
		if k > maxIndex then
			maxIndex = k
		end
	end
	if count == 0 then
		return false, 0
	end
	return count == maxIndex, maxIndex
end

local function luaJsonEncode(val, seen)
	local kind = type(val)
	if val == nil then
		return "null"
	elseif kind == "boolean" then
		return val and "true" or "false"
	elseif kind == "number" then
		if val ~= val or val == math.huge or val == -math.huge then
			return "null"
		end
		return string.format("%.14g", val)
	elseif kind == "string" then
		return encodeString(val)
	elseif kind == "table" then
		seen = seen or {}
		if seen[val] then
			error("Circular reference in JSON encode")
		end
		seen[val] = true

		local isArr, len = isArrayTable(val)
		local out = {}
		if isArr then
			for idx = 1, len do
				out[idx] = luaJsonEncode(val[idx], seen)
			end
			seen[val] = nil
			return "[" .. table.concat(out, ",") .. "]"
		else
			local keys = {}
			for k in pairs(val) do
				if type(k) == "string" or type(k) == "number" then
					table.insert(keys, k)
				end
			end
			table.sort(keys, function(a, b)
				return tostring(a) < tostring(b)
			end)
			for _, k in ipairs(keys) do
				table.insert(out, encodeString(tostring(k)) .. ":" .. luaJsonEncode(val[k], seen))
			end
			seen[val] = nil
			return "{" .. table.concat(out, ",") .. "}"
		end
	end
	return "null"
end

local function codepointToUtf8(cp)
	if cp <= 0x7F then
		return string.char(cp)
	elseif cp <= 0x7FF then
		return string.char(
			0xC0 + math.floor(cp / 64),
			0x80 + (cp % 64)
		)
	elseif cp <= 0xFFFF then
		return string.char(
			0xE0 + math.floor(cp / 4096),
			0x80 + (math.floor(cp / 64) % 64),
			0x80 + (cp % 64)
		)
	elseif cp <= 0x10FFFF then
		return string.char(
			0xF0 + math.floor(cp / 262144),
			0x80 + (math.floor(cp / 4096) % 64),
			0x80 + (math.floor(cp / 64) % 64),
			0x80 + (cp % 64)
		)
	end
	return "?"
end

local function luaJsonDecode(str)
	if type(str) ~= "string" then
		error("Expected JSON string")
	end
	local len = #str
	local pos = 1

	local function skipWs()
		local _, nextPos = string.find(str, "^[ \t\r\n]+", pos)
		if nextPos then
			pos = nextPos + 1
		end
	end

	local parseValue

	local function parseString()
		pos += 1 -- skip opening quote
		local buf = {}
		while pos <= len do
			local byte = string.byte(str, pos)
			if byte == 34 then -- '"'
				pos += 1
				return table.concat(buf)
			elseif byte == 92 then -- '\'
				pos += 1
				local esc = string.sub(str, pos, pos)
				if esc == '"' or esc == "\\" or esc == "/" then
					table.insert(buf, esc)
					pos += 1
				elseif esc == "b" then
					table.insert(buf, "\b")
					pos += 1
				elseif esc == "f" then
					table.insert(buf, "\f")
					pos += 1
				elseif esc == "n" then
					table.insert(buf, "\n")
					pos += 1
				elseif esc == "r" then
					table.insert(buf, "\r")
					pos += 1
				elseif esc == "t" then
					table.insert(buf, "\t")
					pos += 1
				elseif esc == "u" then
					local hex = string.sub(str, pos + 1, pos + 4)
					if #hex < 4 or not string.match(hex, "^%x%x%x%x$") then
						error("Invalid unicode escape at position " .. pos)
					end
					local code = tonumber(hex, 16)
					pos += 5
					-- Handle UTF-16 surrogate pairs
					if code >= 0xD800 and code <= 0xDBFF and string.sub(str, pos, pos + 1) == "\\u" then
						local lowHex = string.sub(str, pos + 2, pos + 5)
						local low = string.match(lowHex, "^%x%x%x%x$") and tonumber(lowHex, 16)
						if low and low >= 0xDC00 and low <= 0xDFFF then
							code = 0x10000 + (code - 0xD800) * 1024 + (low - 0xDC00)
							pos += 6
						end
					end
					table.insert(buf, codepointToUtf8(code))
				else
					error("Invalid escape sequence at position " .. pos)
				end
			else
				local nextSpecial = string.find(str, '["\\]', pos)
				if not nextSpecial then
					error("Unterminated string")
				end
				table.insert(buf, string.sub(str, pos, nextSpecial - 1))
				pos = nextSpecial
			end
		end
		error("Unterminated string")
	end

	local function parseNumber()
		local numStr = string.match(str, "^-?%d+%.?%d*[eE]?[+-]?%d*", pos)
		if not numStr or numStr == "" then
			error("Invalid number at position " .. pos)
		end
		local num = tonumber(numStr)
		if num == nil then
			error("Invalid number '" .. numStr .. "' at position " .. pos)
		end
		pos += #numStr
		return num
	end

	local function parseArray()
		pos += 1 -- skip '['
		local arr = {}
		skipWs()
		if string.sub(str, pos, pos) == "]" then
			pos += 1
			return arr
		end
		while pos <= len do
			table.insert(arr, parseValue())
			skipWs()
			local ch = string.sub(str, pos, pos)
			if ch == "]" then
				pos += 1
				return arr
			elseif ch ~= "," then
				error("Expected ',' or ']' in array at position " .. pos)
			end
			pos += 1
		end
		error("Unterminated array")
	end

	local function parseObject()
		pos += 1 -- skip '{'
		local obj = {}
		skipWs()
		if string.sub(str, pos, pos) == "}" then
			pos += 1
			return obj
		end
		while pos <= len do
			skipWs()
			if string.sub(str, pos, pos) ~= '"' then
				error("Expected string key at position " .. pos)
			end
			local key = parseString()
			skipWs()
			if string.sub(str, pos, pos) ~= ":" then
				error("Expected ':' after key at position " .. pos)
			end
			pos += 1
			obj[key] = parseValue()
			skipWs()
			local ch = string.sub(str, pos, pos)
			if ch == "}" then
				pos += 1
				return obj
			elseif ch ~= "," then
				error("Expected ',' or '}' in object at position " .. pos)
			end
			pos += 1
		end
		error("Unterminated object")
	end

	parseValue = function()
		skipWs()
		local ch = string.sub(str, pos, pos)
		if ch == '"' then
			return parseString()
		elseif ch == "{" then
			return parseObject()
		elseif ch == "[" then
			return parseArray()
		elseif ch == "t" and string.sub(str, pos, pos + 3) == "true" then
			pos += 4
			return true
		elseif ch == "f" and string.sub(str, pos, pos + 4) == "false" then
			pos += 5
			return false
		elseif ch == "n" and string.sub(str, pos, pos + 3) == "null" then
			pos += 4
			return nil
		elseif ch == "-" or (ch >= "0" and ch <= "9") then
			return parseNumber()
		end
		error("Unexpected token at position " .. pos)
	end

	local result = parseValue()
	skipWs()
	if pos <= len then
		error("Trailing characters at position " .. pos)
	end
	return result
end

function Config.JsonEncode(tbl)
	local ok, encoded = pcall(function()
		return Services.HttpService:JSONEncode(tbl)
	end)
	if ok and type(encoded) == "string" then
		return encoded
	end
	return luaJsonEncode(tbl)
end

function Config.JsonDecode(str)
	if type(str) ~= "string" or str == "" then
		return nil
	end
	local ok, decoded = pcall(function()
		return Services.HttpService:JSONDecode(str)
	end)
	if ok then
		return decoded
	end
	local fallbackOk, fallbackRes = pcall(luaJsonDecode, str)
	if fallbackOk then
		return fallbackRes
	end
	return nil
end

-- ─── Type Serialization ──────────────────────────────────────────────────────

local function serializeValue(value, extraAlpha)
	local rbxType = typeof(value)
	if rbxType == "Color3" then
		return {
			__type = "Color3",
			Hex = "#" .. Util.ToHex(value),
			Alpha = tonumber(extraAlpha) or 0,
		}
	elseif rbxType == "EnumItem" then
		return tostring(value)
	end

	local luaType = type(value)
	if luaType == "table" then
		local out = {}
		for k, v in pairs(value) do
			if type(k) == "string" or type(k) == "number" then
				local serialized = serializeValue(v)
				if serialized ~= nil then
					out[k] = serialized
				end
			end
		end
		return out
	elseif luaType == "string" or luaType == "number" or luaType == "boolean" then
		return value
	end
	return nil
end

local function resolveEnumString(str)
	local enumType, itemName = string.match(str, "^Enum%.([^%.]+)%.([^%.]+)$")
	if not enumType or not itemName then
		return nil
	end
	local ok, item = pcall(function()
		return Enum[enumType][itemName]
	end)
	return ok and item or nil
end

local function deserializeValue(value)
	local luaType = type(value)
	if luaType == "string" then
		if string.sub(value, 1, 5) == "Enum." then
			local resolved = resolveEnumString(value)
			if resolved then
				return resolved
			end
		end
		return value
	elseif luaType == "table" then
		if value.__type == "Color3" or (type(value.Hex) == "string" and value.Alpha ~= nil) then
			local color = Util.FromHex(value.Hex)
			return color or Color3.new(1, 1, 1), tonumber(value.Alpha) or 0
		end
		local out = {}
		for k, v in pairs(value) do
			local decoded = deserializeValue(v)
			out[k] = decoded
		end
		return out
	end
	return value
end

-- ─── Payload Building & Restoration ──────────────────────────────────────────

local function sanitizeName(name)
	if name == nil then
		return nil
	end
	local clean = Util.Trim(tostring(name))
	clean = string.gsub(clean, "%.json$", "")
	clean = string.gsub(clean, '[<>:"/\\|%?%*%.]+', "_")
	clean = Util.Trim(clean)
	if clean == "" or string.sub(clean, 1, 1) == "_" then
		return nil
	end
	return clean
end

local function ensureFolder()
	if Util.FS.Supported() then
		Util.FS.MakeFolder(folder)
	end
end

local function configPath(safeName)
	return folder .. "/" .. safeName .. ".json"
end

local function autoLoadPath()
	return folder .. "/" .. AUTOLOAD_FILE
end

local function autoSavePath()
	return folder .. "/" .. AUTOSAVE_FILE
end

local function autoSaveStatePath()
	return folder .. "/" .. AUTOSAVE_STATE_FILE
end

local function collectPreferences()
	if not extrasRef then
		return nil
	end

	local prefs = {
		Theme = Theme.Name,
		Accent = Theme.AccentOverride and serializeValue(Theme.AccentOverride, 0) or false,
		Font = Theme.FontFamily,
		BackgroundTransparency = Theme.Overrides.BackgroundTransparency,
		AnimationSpeed = Tween.Speed,
		ReduceMotion = Tween.Reduced,
		BlurEnabled = Blur.IsEnabled(),
		BlurIntensity = Blur.GetIntensity(),
		WatermarkVisible = Watermark.IsVisible(),
		KeybindListVisible = KeybindList.IsVisible(),
	}

	if type(extrasRef) == "table" and type(extrasRef.Save) == "function" then
		local ok, custom = Util.SafeCall(extrasRef.Save)
		if ok and type(custom) == "table" then
			prefs.Custom = serializeValue(custom)
		end
	end

	return prefs
end

local function applyPreferences(prefs)
	if not extrasRef or type(prefs) ~= "table" then
		return
	end

	if type(prefs.Theme) == "string" and Theme.Presets[prefs.Theme] then
		Theme.Set(prefs.Theme, true)
	end

	if prefs.Accent == false then
		Theme.SetAccent(nil, true)
	elseif prefs.Accent ~= nil then
		local accentColor = deserializeValue(prefs.Accent)
		if typeof(accentColor) == "Color3" then
			Theme.SetAccent(accentColor, true)
		end
	end

	if type(prefs.Font) == "string" and Theme.Fonts[prefs.Font] then
		Theme.SetFont(prefs.Font)
	end

	if prefs.BackgroundTransparency ~= nil then
		Theme.SetValue("BackgroundTransparency", tonumber(prefs.BackgroundTransparency), true)
	end

	if type(prefs.AnimationSpeed) == "number" then
		Tween.Speed = Util.Clamp(prefs.AnimationSpeed, 0.1, 3)
	end
	if type(prefs.ReduceMotion) == "boolean" then
		Tween.Reduced = prefs.ReduceMotion
	end

	if type(prefs.BlurEnabled) == "boolean" then
		Blur.SetEnabled(prefs.BlurEnabled)
	end
	if type(prefs.BlurIntensity) == "number" then
		Blur.SetIntensity(prefs.BlurIntensity)
	end

	if type(prefs.WatermarkVisible) == "boolean" then
		Watermark.SetVisible(prefs.WatermarkVisible)
	end
	if type(prefs.KeybindListVisible) == "boolean" then
		KeybindList.SetVisible(prefs.KeybindListVisible)
	end

	if type(extrasRef) == "table" then
		if type(extrasRef.Load) == "function" and type(prefs.Custom) == "table" then
			Util.SafeCall(extrasRef.Load, deserializeValue(prefs.Custom))
		end
		if type(extrasRef.OnLoad) == "function" then
			Util.SafeCall(extrasRef.OnLoad, prefs)
		end
	end
end

local function serializeMap(sourceMap)
	local out = {}
	if type(sourceMap) ~= "table" then
		return out
	end

	for key, element in pairs(sourceMap) do
		if type(element) == "table" and not element.IgnoreConfig then
			local opts = element.Options
			if not (type(opts) == "table" and opts.IgnoreConfig) then
				if element.Type == "Toggle" and type(element.Get) == "function" then
					local ok, val = pcall(element.Get, element)
					if ok then
						local hasInlineKey = type(element.GetKeybind) == "function" and element._hasKeybind == true
						if hasInlineKey then
							local kbOk, k = pcall(element.GetKeybind, element)
							out[key] = {
								__type = "ToggleState",
								Value = val == true,
								Key = (kbOk and k ~= nil) and tostring(k) or "None",
							}
						elseif val ~= nil then
							out[key] = serializeValue(val)
						end
					end
				elseif element.Type == "ColorPicker" and type(element.Get) == "function" then
					local ok, color, alpha = pcall(element.Get, element)
					if ok and typeof(color) == "Color3" then
						out[key] = serializeValue(color, alpha or 0)
					end
				elseif element.Type == "Keybind" and type(element.Get) == "function" then
					local ok, k, mode = pcall(element.Get, element)
					if ok then
						out[key] = {
							__type = "Keybind",
							Key = k ~= nil and tostring(k) or "None",
							Mode = mode or "Toggle",
						}
					end
				elseif type(element.Get) == "function" then
					local ok, val, extra = pcall(element.Get, element)
					if ok then
						if typeof(val) == "Color3" then
							out[key] = serializeValue(val, extra or 0)
						elseif typeof(val) == "EnumItem" or (extra ~= nil and (extra == "Toggle" or extra == "Hold" or extra == "Always")) then
							out[key] = {
								__type = "Keybind",
								Key = val ~= nil and tostring(val) or "None",
								Mode = extra or "Toggle",
							}
						elseif val ~= nil then
							out[key] = serializeValue(val)
						end
					end
				elseif element.Value ~= nil then
					out[key] = serializeValue(element.Value)
				end
			end
		end
	end

	return out
end

local function applyMap(targetMap, rawMap)
	if type(targetMap) ~= "table" or type(rawMap) ~= "table" then
		return
	end

	for flag, raw in pairs(rawMap) do
		local element = targetMap[flag]
		if type(element) == "table" and not element.IgnoreConfig then
			local opts = element.Options
			if not (type(opts) == "table" and opts.IgnoreConfig) and type(element.Set) == "function" then
				if type(raw) == "table" and raw.__type == "ToggleState" then
					local value = raw.Value == true
					pcall(element.Set, element, value)
					if type(element.SetKeybind) == "function" then
						local key = nil
						if raw.Key ~= nil and raw.Key ~= "None" and raw.Key ~= "" then
							key = deserializeValue(raw.Key)
							if typeof(key) ~= "EnumItem" then
								key = Util.ResolveKey(raw.Key)
							end
						end
						pcall(element.SetKeybind, element, key)
					end
				elseif type(raw) == "table" and raw.__type == "Keybind" then
					local key = nil
					if raw.Key ~= nil and raw.Key ~= "None" and raw.Key ~= "" then
						key = deserializeValue(raw.Key)
						if typeof(key) ~= "EnumItem" then
							key = Util.ResolveKey(raw.Key)
						end
					end
					pcall(element.Set, element, key, raw.Mode)
				elseif type(raw) == "table" and (raw.__type == "Color3" or type(raw.Hex) == "string") then
					local color, alpha = deserializeValue(raw)
					if typeof(color) == "Color3" then
						pcall(element.Set, element, color, alpha)
					end
				else
					local value = deserializeValue(raw)
					pcall(element.Set, element, value)
				end
			end
		end
	end
end

local function collectFlags()
	return serializeMap(registryRef)
end

local function applyFlags(flags)
	applyMap(registryRef, flags)
end

-- ─── Public API ──────────────────────────────────────────────────────────────

function Config.IsLoading()
	return isLoading
end

function Config.Init(folderName, registry, extras)
	folder = (type(folderName) == "string" and Util.Trim(folderName) ~= "") and Util.Trim(folderName) or DEFAULT_FOLDER
	registryRef = registry
	extrasRef = extras
	ensureFolder()
	if Util.FS.Supported() and Util.FS.IsFile(autoSaveStatePath()) then
		local rawState = string.lower(Util.Trim(Util.FS.Read(autoSaveStatePath()) or ""))
		if rawState == "false" or rawState == "0" then
			autoSaveEnabled = false
		else
			autoSaveEnabled = true
		end
	end
	return Config
end

function Config.Export(includeUnnamed)
	local payload = {
		Version = 1,
		Flags = collectFlags(),
	}
	if includeUnnamed and type(extrasRef) == "table" and type(extrasRef.UnnamedRegistry) == "table" then
		payload.Unnamed = serializeMap(extrasRef.UnnamedRegistry)
	end
	local prefs = collectPreferences()
	if prefs then
		payload.Preferences = prefs
	end
	return Config.JsonEncode(payload)
end

function Config.Import(jsonStr)
	local decoded = Config.JsonDecode(jsonStr)
	if type(decoded) ~= "table" then
		return false, "Invalid JSON config payload"
	end

	local prevLoading = isLoading
	isLoading = true
	local ok, err = pcall(function()
		if type(decoded.Flags) == "table" then
			applyFlags(decoded.Flags)
			if type(decoded.Unnamed) == "table" and type(extrasRef) == "table" and type(extrasRef.UnnamedRegistry) == "table" then
				applyMap(extrasRef.UnnamedRegistry, decoded.Unnamed)
			end
			if type(decoded.Preferences) == "table" then
				applyPreferences(decoded.Preferences)
			end
		else
			-- Support flat { Flag = Value } payloads
			applyFlags(decoded)
		end
	end)
	isLoading = prevLoading

	if not ok then
		return false, tostring(err)
	end
	return true
end

function Config.Save(name)
	local safeName = sanitizeName(name)
	if not safeName then
		return false, "Invalid config name"
	end

	local json = Config.Export(true)
	memoryStore[safeName] = json

	if Util.FS.Supported() then
		ensureFolder()
		local ok = Util.FS.Write(configPath(safeName), json)
		if not ok then
			return false, "Failed to write config file"
		end
	end

	return true
end

function Config.Load(name)
	local safeName = sanitizeName(name)
	if not safeName then
		return false, "Invalid config name"
	end

	local raw = nil
	if Util.FS.Supported() and Util.FS.IsFile(configPath(safeName)) then
		raw = Util.FS.Read(configPath(safeName))
	end
	if not raw then
		raw = memoryStore[safeName]
	end
	if not raw then
		return false, "Config not found"
	end

	return Config.Import(raw)
end

function Config.Delete(name)
	local safeName = sanitizeName(name)
	if not safeName then
		return false, "Invalid config name"
	end

	memoryStore[safeName] = nil
	if memoryAutoLoad == safeName then
		memoryAutoLoad = nil
	end

	if Util.FS.Supported() then
		local path = configPath(safeName)
		if Util.FS.IsFile(path) then
			Util.FS.Delete(path)
		end
		if Config.GetAutoLoad() == safeName then
			Config.SetAutoLoad(nil)
		end
	end

	return true
end

function Config.List()
	local seen = {}
	local names = {}

	if Util.FS.Supported() then
		ensureFolder()
		for _, fullPath in ipairs(Util.FS.List(folder)) do
			local base = string.match(tostring(fullPath), "([^/\\]+)%.json$")
			if base and string.sub(base, 1, 1) ~= "_" and not seen[base] then
				seen[base] = true
				table.insert(names, base)
			end
		end
	end

	for name in pairs(memoryStore) do
		if not seen[name] then
			seen[name] = true
			table.insert(names, name)
		end
	end

	table.sort(names)
	return names
end

function Config.SetAutoLoad(name)
	if name == nil or name == "" or name == "None" then
		memoryAutoLoad = nil
		if Util.FS.Supported() and Util.FS.IsFile(autoLoadPath()) then
			Util.FS.Delete(autoLoadPath())
		end
		return true
	end

	local safeName = sanitizeName(name)
	if not safeName then
		return false, "Invalid config name"
	end

	memoryAutoLoad = safeName
	if Util.FS.Supported() then
		ensureFolder()
		Util.FS.Write(autoLoadPath(), safeName)
	end
	return true
end

function Config.GetAutoLoad()
	if Util.FS.Supported() and Util.FS.IsFile(autoLoadPath()) then
		local raw = Util.FS.Read(autoLoadPath())
		local safe = sanitizeName(raw)
		if safe then
			return safe
		end
	end
	return memoryAutoLoad
end

function Config.LoadAuto()
	local autoName = Config.GetAutoLoad()
	if not autoName then
		return false, "No autoload config set"
	end
	return Config.Load(autoName)
end

function Config.GetAutoSave()
	return autoSaveEnabled
end

function Config.SaveAutoSaveNow()
	if isLoading or not autoSaveEnabled or not registryRef then
		return false
	end
	local json = Config.Export(true)
	memoryAutoSave = json
	if Util.FS.Supported() then
		ensureFolder()
		return Util.FS.Write(autoSavePath(), json)
	end
	return true
end

function Config.SetAutoSave(enabled)
	autoSaveEnabled = enabled == true
	if Util.FS.Supported() then
		ensureFolder()
		Util.FS.Write(autoSaveStatePath(), autoSaveEnabled and "true" or "false")
	end
	if autoSaveEnabled and not isLoading and registryRef then
		Config.SaveAutoSaveNow()
	end
	return true
end

function Config.TriggerAutoSave()
	if not autoSaveEnabled or isLoading or not registryRef then
		return
	end
	autoSaveToken += 1
	local myToken = autoSaveToken
	task.delay(0.35, function()
		if autoSaveToken == myToken and autoSaveEnabled and not isLoading then
			Config.SaveAutoSaveNow()
		end
	end)
end

function Config.LoadAutoSave()
	if not autoSaveEnabled then
		return false, "Auto-save is disabled"
	end
	local raw = nil
	if Util.FS.Supported() and Util.FS.IsFile(autoSavePath()) then
		raw = Util.FS.Read(autoSavePath())
	end
	if not raw then
		raw = memoryAutoSave
	end
	if not raw or raw == "" then
		return false, "No auto-save snapshot found"
	end
	local decoded = Config.JsonDecode(raw)
	if type(decoded) == "table" then
		lastAutoSaveFlags = type(decoded.Flags) == "table" and decoded.Flags or decoded
		lastAutoSaveUnnamed = type(decoded.Unnamed) == "table" and decoded.Unnamed or nil
		hasLoadedAutoSave = true
	end
	return Config.Import(raw)
end

function Config.HasLoadedAutoSave()
	return hasLoadedAutoSave == true and autoSaveEnabled == true
end

function Config.TryApplyCachedAutoSave(key, element, isFlag)
	if not autoSaveEnabled or not hasLoadedAutoSave or type(element) ~= "table" then
		return false
	end
	local source = isFlag and lastAutoSaveFlags or lastAutoSaveUnnamed
	if type(source) ~= "table" or source[key] == nil then
		return false
	end
	local prevLoading = isLoading
	isLoading = true
	pcall(applyMap, { [key] = element }, { [key] = source[key] })
	isLoading = prevLoading
	return true
end

return Config
end

__modules["Systems/Input"] = function()
--[[
	Bali UI · Systems/Input
	Centralised input dispatcher: keybinds (Toggle/Hold/Always), key capture,
	viewport-clamped dragging, and smooth resizing for mouse and touch.
]]

local Services = require("Core/Services")
local Maid = require("Core/Maid")
local Util = require("Core/Util")

local Input = {
	Capturing = false,
}

local initialized = false
local rootMaid = Maid.new()
local keybinds = {} -- [id] = entry
local captureConn = nil
local captureCallback = nil
local captureToken = 0

local function getViewportBounds(instance)
	if instance then
		local layer = instance:FindFirstAncestorWhichIsA("LayerCollector")
		if layer and layer.AbsoluteSize.X > 0 and layer.AbsoluteSize.Y > 0 then
			return layer.AbsolutePosition, layer.AbsoluteSize
		end
	end
	local camera = Services.Workspace.CurrentCamera
	local rawSize = camera and camera.ViewportSize or Vector2.new(1920, 1080)
	local ok, inset = pcall(function()
		return Services.GuiService:GetGuiInset()
	end)
	if ok and inset then
		return Vector2.new(inset.X, inset.Y), Vector2.new(rawSize.X - inset.X, rawSize.Y - inset.Y)
	end
	return Vector2.zero, rawSize
end

local function matchesKey(key, input)
	if typeof(key) ~= "EnumItem" then
		return false
	end
	if key.EnumType == Enum.KeyCode then
		return input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode == key
	elseif key.EnumType == Enum.UserInputType then
		return input.UserInputType == key
	end
	return false
end

local function normalizeMode(mode)
	if mode == "Hold" or mode == "Always" or mode == "Toggle" then
		return mode
	end
	return "Toggle"
end

function Input.Init()
	if initialized then
		return Input
	end
	initialized = true

	local UIS = Services.UserInputService

	rootMaid:Give(UIS.InputBegan:Connect(function(input, gameProcessedEvent)
		if Input.Capturing or gameProcessedEvent or UIS:GetFocusedTextBox() ~= nil then
			return
		end

		for _, entry in pairs(keybinds) do
			if entry.Key and matchesKey(entry.Key, input) then
				if entry.Mode == "Toggle" then
					entry.Active = not entry.Active
					Util.Spawn(entry.Callback, entry.Active)
				elseif entry.Mode == "Hold" then
					if not entry.Active then
						entry.Active = true
						Util.Spawn(entry.Callback, true)
					end
				end
			end
		end
	end))

	rootMaid:Give(UIS.InputEnded:Connect(function(input)
		for _, entry in pairs(keybinds) do
			if entry.Mode == "Hold" and entry.Active and entry.Key and matchesKey(entry.Key, input) then
				entry.Active = false
				Util.Spawn(entry.Callback, false)
			end
		end
	end))

	return Input
end

function Input.RegisterKeybind(id, key, callback, mode)
	Input.Init()

	local bindId = id or Util.RandomString(8)
	if keybinds[bindId] then
		keybinds[bindId].Destroy()
	end

	local resolvedMode = normalizeMode(mode)
	local resolvedKey = Util.ResolveKey(key)

	local entry = {
		Id = bindId,
		Key = resolvedKey,
		Mode = resolvedMode,
		Active = resolvedMode == "Always",
		Callback = callback,
	}

	function entry.SetKey(arg1, arg2)
		local newKey = (arg1 == entry) and arg2 or arg1
		entry.Key = Util.ResolveKey(newKey)
		if entry.Key == nil and entry.Mode == "Hold" and entry.Active then
			entry.Active = false
			Util.Spawn(entry.Callback, false)
		end
	end

	function entry.SetMode(arg1, arg2)
		local newMode = (arg1 == entry) and arg2 or arg1
		local targetMode = normalizeMode(newMode)
		if entry.Mode == targetMode then
			return
		end
		entry.Mode = targetMode
		if targetMode == "Always" then
			if not entry.Active then
				entry.Active = true
				Util.Spawn(entry.Callback, true)
			end
		elseif targetMode == "Hold" and entry.Active then
			entry.Active = false
			Util.Spawn(entry.Callback, false)
		end
	end

	function entry.SetActive(arg1, arg2, arg3)
		local active, silent
		if arg1 == entry then
			active, silent = arg2, arg3
		else
			active, silent = arg1, arg2
		end
		local state = active == true
		if entry.Mode == "Always" then
			state = true
		end
		if entry.Active == state then
			return
		end
		entry.Active = state
		if not silent then
			Util.Spawn(entry.Callback, state)
		end
	end

	function entry.Destroy()
		if keybinds[bindId] == entry then
			keybinds[bindId] = nil
		end
	end

	keybinds[bindId] = entry
	return entry
end

function Input.CancelCapture()
	captureToken += 1
	local pending = captureCallback
	captureCallback = nil

	if captureConn then
		captureConn:Disconnect()
		captureConn = nil
	end
	Input.Capturing = false

	if pending then
		Util.Spawn(pending, nil, true)
	end
end

function Input.CaptureKey(onComplete, opts)
	Input.Init()
	if Input.Capturing then
		Input.CancelCapture()
	end

	opts = opts or {}
	local allowMouse = opts.AllowMouse ~= false
	captureToken += 1
	local myToken = captureToken
	local armed = false

	Input.Capturing = true
	captureCallback = onComplete

	local function finish(result, cancelled)
		if captureToken ~= myToken then
			return
		end
		captureToken += 1
		local cb = captureCallback
		captureCallback = nil
		if captureConn then
			captureConn:Disconnect()
			captureConn = nil
		end
		Input.Capturing = false
		if cb then
			Util.Spawn(cb, result, cancelled)
		end
	end

	-- Defer one frame so the click that opened key capture is not captured
	task.defer(function()
		if captureToken ~= myToken or not Input.Capturing then
			return
		end
		armed = true
	end)

	captureConn = Services.UserInputService.InputBegan:Connect(function(input)
		if not armed or captureToken ~= myToken then
			return
		end

		if input.UserInputType == Enum.UserInputType.Keyboard then
			if input.KeyCode == Enum.KeyCode.Unknown then
				return
			end
			if input.KeyCode == Enum.KeyCode.Escape then
				finish(nil, true)
			elseif input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete then
				finish(nil, false)
			else
				finish(input.KeyCode, false)
			end
		elseif allowMouse and (
			input.UserInputType == Enum.UserInputType.MouseButton2
			or input.UserInputType == Enum.UserInputType.MouseButton3
		) then
			finish(input.UserInputType, false)
		end
	end)
end

function Input.BindDrag(handle, target, opts)
	Input.Init()
	target = target or handle
	opts = opts or {}

	local shouldClamp = opts.Clamp ~= false
	local padding = opts.Padding ~= nil and opts.Padding or 8
	local threshold = opts.Threshold or 0
	local dragMaid = Maid.new()

	local dragging = false
	local movedPastThreshold = false
	local activeInput = nil
	local startPointer = Vector2.zero
	local startAbsPos = Vector2.zero

	local function isEnabled()
		if type(opts.Enabled) == "function" then
			return opts.Enabled() ~= false
		elseif opts.Enabled ~= nil then
			return opts.Enabled ~= false
		end
		return true
	end

	local function isMatchingMove(input)
		if not activeInput then
			return false
		end
		if activeInput.UserInputType == Enum.UserInputType.Touch then
			return input == activeInput
		end
		return input.UserInputType == Enum.UserInputType.MouseMovement
	end

	local function isMatchingEnd(input)
		if not activeInput then
			return false
		end
		if activeInput.UserInputType == Enum.UserInputType.Touch then
			return input == activeInput
		end
		return input.UserInputType == Enum.UserInputType.MouseButton1
	end

	local function stopDrag()
		if not dragging then
			return
		end
		dragging = false
		activeInput = nil
		if opts.OnEnd then
			Util.SafeCall(opts.OnEnd, movedPastThreshold)
		end
	end

	local function updatePosition(input)
		if not dragging or not target or not target.Parent then
			stopDrag()
			return
		end

		local current = Vector2.new(input.Position.X, input.Position.Y)
		local delta = current - startPointer
		if not movedPastThreshold then
			if delta.Magnitude < threshold then
				return
			end
			movedPastThreshold = true
			if opts.OnStart then
				Util.SafeCall(opts.OnStart)
			end
		end

		local desiredTopLeft = startAbsPos + delta
		local size = target.AbsoluteSize
		if shouldClamp then
			local vpOrigin, vpSize = getViewportBounds(target)
			local minX = vpOrigin.X + padding
			local minY = vpOrigin.Y + padding
			local maxX = math.max(minX, vpOrigin.X + vpSize.X - size.X - padding)
			local maxY = math.max(minY, vpOrigin.Y + vpSize.Y - size.Y - padding)
			desiredTopLeft = Vector2.new(
				Util.Clamp(desiredTopLeft.X, minX, maxX),
				Util.Clamp(desiredTopLeft.Y, minY, maxY)
			)
		end

		local parent = target.Parent
		local parentPos = (parent and parent:IsA("GuiBase2d")) and parent.AbsolutePosition or Vector2.zero
		local localTopLeft = desiredTopLeft - parentPos
		local anchorPos = localTopLeft + size * target.AnchorPoint
		target.Position = UDim2.fromOffset(math.round(anchorPos.X), math.round(anchorPos.Y))

		if opts.OnDrag then
			Util.SafeCall(opts.OnDrag, target.Position)
		end
	end

	dragMaid:Give(handle.InputBegan:Connect(function(input)
		if not isEnabled() or not Util.IsPointer(input) then
			return
		end
		dragging = true
		movedPastThreshold = threshold <= 0
		activeInput = input
		startPointer = Vector2.new(input.Position.X, input.Position.Y)
		startAbsPos = target.AbsolutePosition
		if movedPastThreshold and opts.OnStart then
			Util.SafeCall(opts.OnStart)
		end
	end))

	dragMaid:Give(Services.UserInputService.InputChanged:Connect(function(input)
		if dragging and isMatchingMove(input) then
			updatePosition(input)
		end
	end))

	dragMaid:Give(Services.UserInputService.InputEnded:Connect(function(input)
		if dragging and isMatchingEnd(input) then
			stopDrag()
		end
	end))

	dragMaid:Give(handle.Destroying:Connect(function()
		dragMaid:Clean()
	end))

	return {
		IsDragging = function()
			return dragging
		end,
		WasMoved = function()
			return movedPastThreshold
		end,
		Destroy = function()
			stopDrag()
			dragMaid:Clean()
		end,
	}
end

function Input.BindResize(grip, target, minSize, maxSize, onResize)
	Input.Init()
	target = target or grip
	minSize = minSize or Vector2.new(460, 360)

	local resizeMaid = Maid.new()
	local resizing = false
	local activeInput = nil
	local startPointer = Vector2.zero
	local startSize = Vector2.zero
	local startAbsPos = Vector2.zero

	local function isMatchingMove(input)
		if not activeInput then
			return false
		end
		if activeInput.UserInputType == Enum.UserInputType.Touch then
			return input == activeInput
		end
		return input.UserInputType == Enum.UserInputType.MouseMovement
	end

	local function isMatchingEnd(input)
		if not activeInput then
			return false
		end
		if activeInput.UserInputType == Enum.UserInputType.Touch then
			return input == activeInput
		end
		return input.UserInputType == Enum.UserInputType.MouseButton1
	end

	local function stopResize()
		if not resizing then
			return
		end
		resizing = false
		activeInput = nil
	end

	local function updateSize(input)
		if not resizing or not target or not target.Parent then
			stopResize()
			return
		end

		local delta = Vector2.new(input.Position.X, input.Position.Y) - startPointer
		local vpOrigin, vpSize = getViewportBounds(target)
		local vpCapX = math.max(minSize.X, (vpOrigin.X + vpSize.X) - startAbsPos.X - 8)
		local vpCapY = math.max(minSize.Y, (vpOrigin.Y + vpSize.Y) - startAbsPos.Y - 8)

		local limitX = maxSize and math.min(maxSize.X, vpCapX) or vpCapX
		local limitY = maxSize and math.min(maxSize.Y, vpCapY) or vpCapY
		limitX = math.max(minSize.X, limitX)
		limitY = math.max(minSize.Y, limitY)

		local newW = math.round(Util.Clamp(startSize.X + delta.X, minSize.X, limitX))
		local newH = math.round(Util.Clamp(startSize.Y + delta.Y, minSize.Y, limitY))
		local newSize = Vector2.new(newW, newH)

		target.Size = UDim2.fromOffset(newW, newH)

		-- Keep top-left corner fixed regardless of AnchorPoint
		if target.AnchorPoint ~= Vector2.zero then
			local parent = target.Parent
			local parentPos = (parent and parent:IsA("GuiBase2d")) and parent.AbsolutePosition or Vector2.zero
			local localTopLeft = startAbsPos - parentPos
			local anchorPos = localTopLeft + newSize * target.AnchorPoint
			target.Position = UDim2.fromOffset(math.round(anchorPos.X), math.round(anchorPos.Y))
		end

		if onResize then
			Util.SafeCall(onResize, newSize)
		end
	end

	resizeMaid:Give(grip.InputBegan:Connect(function(input)
		if not Util.IsPointer(input) then
			return
		end
		resizing = true
		activeInput = input
		startPointer = Vector2.new(input.Position.X, input.Position.Y)
		startSize = target.AbsoluteSize
		startAbsPos = target.AbsolutePosition
	end))

	resizeMaid:Give(Services.UserInputService.InputChanged:Connect(function(input)
		if resizing and isMatchingMove(input) then
			updateSize(input)
		end
	end))

	resizeMaid:Give(Services.UserInputService.InputEnded:Connect(function(input)
		if resizing and isMatchingEnd(input) then
			stopResize()
		end
	end))

	resizeMaid:Give(grip.Destroying:Connect(function()
		resizeMaid:Clean()
	end))

	return {
		IsResizing = function()
			return resizing
		end,
		Destroy = function()
			stopResize()
			resizeMaid:Clean()
		end,
	}
end

function Input.Destroy()
	Input.CancelCapture()
	for _, entry in pairs(keybinds) do
		if type(entry.Destroy) == "function" then
			entry.Destroy()
		end
	end
	table.clear(keybinds)
	rootMaid:Clean()
	initialized = false
end

return Input
end

__modules["Systems/KeybindList"] = function()
--[[
	Bali UI · Systems/KeybindList
	Draggable obsidian glass HUD displaying active or all registered keybinds
	with AutomaticSize.Y rows and zero text overlap.
]]

local Maid = require("Core/Maid")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Util = require("Core/Util")
local Input = require("Systems/Input")

local KeybindList = {}

local PANEL_WIDTH = 228

local rootMaid = Maid.new()
local layer = nil
local panel = nil
local modeChip = nil
local rowsContainer = nil
local emptyLabel = nil
local dragHandle = nil

local visible = false
local mode = "ActiveOnly" -- "ActiveOnly" | "All"
local entries = {} -- [id] = { Order, Title, KeyName, Mode, Active, Row? }
local orderCounter = 0

local function normalizeMode(value)
	return value == "All" and "All" or "ActiveOnly"
end

local function isRowVisible(entry)
	if mode == "All" then
		return true
	end
	return entry.Active == true
end

local function applyRowState(entry)
	local row = entry.Row
	if not row then
		return
	end

	local show = isRowVisible(entry)
	row.Frame.Visible = show

	row.Title.Text = tostring(entry.Title or "Keybind")
	local keyLabel = entry.KeyName and tostring(entry.KeyName) or "None"
	row.KeyLabel.Text = keyLabel ~= "" and keyLabel or "None"

	local shortMode = entry.Mode == "Hold" and "H" or (entry.Mode == "Always" and "A" or "T")
	row.ModeLabel.Text = shortMode

	if entry.Active then
		Theme.Bind(row.Dot, { BackgroundColor3 = "Accent" })
		Theme.Bind(row.Title, { TextColor3 = "Text" })
		Theme.Bind(row.KeyChip, { BackgroundColor3 = "TileHover" })
		Theme.Bind(row.KeyLabel, { TextColor3 = "Text" })
		Tween.Play(row.Frame, { BackgroundTransparency = 0.25 }, Tween.Fast)
	else
		Theme.Bind(row.Dot, { BackgroundColor3 = "Muted" })
		Theme.Bind(row.Title, { TextColor3 = "SubText" })
		Theme.Bind(row.KeyChip, { BackgroundColor3 = "Field" })
		Theme.Bind(row.KeyLabel, { TextColor3 = "Muted" })
		Tween.Play(row.Frame, { BackgroundTransparency = 1 }, Tween.Fast)
	end
end

local function refreshEmptyState()
	if not emptyLabel then
		return
	end
	local visibleCount = 0
	for _, entry in pairs(entries) do
		if isRowVisible(entry) then
			visibleCount += 1
		end
	end
	emptyLabel.Visible = visibleCount == 0
	emptyLabel.Text = mode == "ActiveOnly" and "No active keybinds" or "No keybinds registered"
end

local function buildRow(id, entry)
	if not rowsContainer or not rowsContainer.Parent then
		return
	end
	if entry.Row and entry.Row.Frame then
		entry.Row.Frame:Destroy()
	end

	local rowFrame = Create.New("Frame", {
		Name = "Keybind_" .. tostring(id),
		Parent = rowsContainer,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Corner = 7,
		Padding = { 5, 6, 5, 6 },
		BackgroundTransparency = 1,
		Theme = { BackgroundColor3 = "Tile" },
		LayoutOrder = entry.Order,
		ZIndex = 342,
	})

	local dot = Create.New("Frame", {
		Name = "Indicator",
		Parent = rowFrame,
		Position = UDim2.fromOffset(2, 6),
		Size = UDim2.fromOffset(6, 6),
		Corner = UDim.new(1, 0),
		Theme = { BackgroundColor3 = "Accent" },
		ZIndex = 343,
	})

	local title = Create.Text({
		Name = "Title",
		Parent = rowFrame,
		Position = UDim2.fromOffset(14, 0),
		Size = UDim2.new(1, -92, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		Font = "Medium",
		TextSize = 12,
		Color = "Text",
		ZIndex = 343,
	})

	local rightGroup = Create.New("Frame", {
		Name = "Right",
		Parent = rowFrame,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.fromOffset(0, 20),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		ZIndex = 343,
	})
	Create.List(rightGroup, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 4,
	})
	local function syncTitleWidth()
		local rw = rightGroup.AbsoluteSize.X
		local reserve = math.max(76, rw + 20)
		title.Size = UDim2.new(1, -reserve, 0, 0)
	end
	rightGroup:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncTitleWidth)
	task.defer(syncTitleWidth)

	local modeChipRow = Create.New("Frame", {
		Name = "ModeBadge",
		Parent = rightGroup,
		Size = UDim2.fromOffset(18, 18),
		Corner = 5,
		BackgroundTransparency = 0.4,
		Theme = { BackgroundColor3 = "Field" },
		LayoutOrder = 1,
		ZIndex = 344,
	})
	local modeLabel = Create.Text({
		Name = "Label",
		Parent = modeChipRow,
		Size = UDim2.fromScale(1, 1),
		TextXAlignment = Enum.TextXAlignment.Center,
		Font = "SemiBold",
		TextSize = 10,
		Color = "Muted",
		ZIndex = 345,
	})

	local keyChip = Create.New("Frame", {
		Name = "KeyChip",
		Parent = rightGroup,
		Size = UDim2.fromOffset(0, 18),
		AutomaticSize = Enum.AutomaticSize.X,
		Corner = 5,
		Padding = { 0, 6, 0, 6 },
		Theme = { BackgroundColor3 = "Field" },
		LayoutOrder = 2,
		ZIndex = 344,
	})
	Create.GlassStroke(keyChip, 0.02)

	local keyLabel = Create.Text({
		Name = "Label",
		Parent = keyChip,
		Size = UDim2.fromOffset(0, 18),
		AutomaticSize = Enum.AutomaticSize.X,
		TextXAlignment = Enum.TextXAlignment.Center,
		Font = "SemiBold",
		TextSize = 10,
		Color = "Text",
		ZIndex = 345,
	})

	entry.Row = {
		Frame = rowFrame,
		Dot = dot,
		Title = title,
		ModeLabel = modeLabel,
		KeyChip = keyChip,
		KeyLabel = keyLabel,
	}

	applyRowState(entry)
end

local function ensureBuilt()
	if panel and panel.Parent then
		return true
	end
	if not layer or not layer.Parent then
		return false
	end

	panel = Create.New("Frame", {
		Name = "BaliKeybindList",
		Parent = layer,
		Visible = visible,
		Active = true,
		Position = UDim2.fromOffset(16, 112),
		Size = UDim2.fromOffset(PANEL_WIDTH, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Corner = 12,
		ClipsDescendants = true,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.min(t.CardTransparency, 0.08)
			end,
		},
		ZIndex = 340,
	})
	Create.GlassStroke(panel, 0.06)

	local glowId = Assets.Get("Glow")
	if glowId then
		Create.New("ImageLabel", {
			Name = "Glow",
			Parent = panel,
			Size = UDim2.fromOffset(130, 48),
			Position = UDim2.fromOffset(8, 4),
			Corner = 12,
			Image = glowId,
			ScaleType = Enum.ScaleType.Stretch,
			Theme = {
				ImageColor3 = "Accent",
				ImageTransparency = function(t)
					return math.min(t.GlowTransparency + 0.08, 0.95)
				end,
			},
			ZIndex = 340,
		})
	end

	local wrapper = Create.New("Frame", {
		Name = "Wrapper",
		Parent = panel,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ZIndex = 341,
	})
	Create.List(wrapper, { Direction = Enum.FillDirection.Vertical, Gap = 0 })

	local header = Create.New("Frame", {
		Name = "Header",
		Parent = wrapper,
		Size = UDim2.new(1, 0, 0, 34),
		BackgroundTransparency = 1,
		Padding = { 0, 10, 0, 12 },
		LayoutOrder = 1,
		ZIndex = 342,
	})

	Icons.Create("keyboard", {
		Size = UDim2.fromOffset(14, 14),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Color = "Accent",
		ZIndex = 343,
		Parent = header,
	})

	Create.Text({
		Name = "Title",
		Parent = header,
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 22, 0.5, 0),
		Size = UDim2.new(1, -86, 0, 18),
		Text = "Keybinds",
		Font = "SemiBold",
		TextSize = 12,
		Color = "Text",
		ZIndex = 343,
	})

	modeChip = Create.Text({
		Class = "TextButton",
		Name = "ModeChip",
		Parent = header,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.fromOffset(48, 20),
		Corner = 6,
		BackgroundTransparency = 0.15,
		TextXAlignment = Enum.TextXAlignment.Center,
		Text = mode == "ActiveOnly" and "Active" or "All",
		Font = "SemiBold",
		TextSize = 10,
		Color = "SubText",
		Theme = { BackgroundColor3 = "Tile", TextColor3 = "SubText" },
		ZIndex = 343,
	})
	Create.GlassStroke(modeChip, 0.02)
	rootMaid:Give(modeChip.Activated:Connect(function(input)
		Transition.Ripple(modeChip, input)
		KeybindList.SetMode(mode == "ActiveOnly" and "All" or "ActiveOnly")
	end))

	Create.New("Frame", {
		Name = "Divider",
		Parent = wrapper,
		Size = UDim2.new(1, 0, 0, 1),
		LayoutOrder = 2,
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		ZIndex = 342,
	})

	rowsContainer = Create.New("Frame", {
		Name = "Rows",
		Parent = wrapper,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 6, 8, 8, 8 },
		LayoutOrder = 3,
		ZIndex = 342,
	})
	Create.List(rowsContainer, { Direction = Enum.FillDirection.Vertical, Gap = 4 })

	emptyLabel = Create.Text({
		Name = "Empty",
		Parent = rowsContainer,
		Size = UDim2.new(1, 0, 0, 24),
		TextXAlignment = Enum.TextXAlignment.Center,
		Text = "No active keybinds",
		Font = "Regular",
		TextSize = 11,
		Color = "SubText",
		TextTransparency = 0.25,
		LayoutOrder = 999999,
		ZIndex = 343,
	})

	dragHandle = Input.BindDrag(header, panel, { Clamp = true, Padding = 8 })
	rootMaid:Give(dragHandle)

	for id, entry in pairs(entries) do
		buildRow(id, entry)
	end
	refreshEmptyState()

	return true
end

function KeybindList.Init(targetLayer)
	if layer == targetLayer and panel and panel.Parent then
		return KeybindList
	end
	rootMaid:Clean()
	for _, entry in pairs(entries) do
		entry.Row = nil
	end
	if panel then
		panel:Destroy()
		panel = nil
	end
	layer = targetLayer
	ensureBuilt()
	return KeybindList
end

function KeybindList.SetVisible(state)
	local targetState = state == true
	visible = targetState
	if not ensureBuilt() then
		return
	end

	if targetState then
		Transition.Mount(panel, 0.94)
	else
		Transition.Unmount(panel, 0.94, function()
			if not visible and panel and panel.Parent then
				panel.Visible = false
			end
		end)
	end
end

function KeybindList.IsVisible()
	return visible
end

function KeybindList.SetMode(newMode)
	mode = normalizeMode(newMode)
	if modeChip then
		modeChip.Text = mode == "ActiveOnly" and "Active" or "All"
	end
	for _, entry in pairs(entries) do
		applyRowState(entry)
	end
	refreshEmptyState()
end

function KeybindList.Register(id, meta)
	if id == nil then
		return
	end
	meta = type(meta) == "table" and meta or {}

	local existing = entries[id]
	if existing then
		KeybindList.Update(id, meta)
		return
	end

	orderCounter += 1
	local entry = {
		Order = orderCounter,
		Title = meta.Title or tostring(id),
		KeyName = meta.KeyName or "None",
		Mode = meta.Mode or "Toggle",
		Active = meta.Active == true,
		Row = nil,
	}
	entries[id] = entry
	if rowsContainer and rowsContainer.Parent then
		buildRow(id, entry)
		refreshEmptyState()
	end
end

function KeybindList.Update(id, meta)
	if id == nil or type(meta) ~= "table" then
		return
	end
	local entry = entries[id]
	if not entry then
		KeybindList.Register(id, meta)
		return
	end

	if meta.Title ~= nil then
		entry.Title = meta.Title
	end
	if meta.KeyName ~= nil then
		entry.KeyName = meta.KeyName
	end
	if meta.Mode ~= nil then
		entry.Mode = meta.Mode
	end
	if meta.Active ~= nil then
		entry.Active = meta.Active == true
	end

	applyRowState(entry)
	refreshEmptyState()
end

function KeybindList.Unregister(id)
	local entry = entries[id]
	if not entry then
		return
	end
	if entry.Row and entry.Row.Frame then
		entry.Row.Frame:Destroy()
	end
	entries[id] = nil
	refreshEmptyState()
end

function KeybindList.Destroy()
	visible = false
	rootMaid:Clean()
	for _, entry in pairs(entries) do
		if entry.Row and entry.Row.Frame then
			entry.Row.Frame:Destroy()
		end
		entry.Row = nil
	end
	table.clear(entries)
	if panel then
		panel:Destroy()
		panel = nil
	end
	modeChip = nil
	rowsContainer = nil
	emptyLabel = nil
	dragHandle = nil
	layer = nil
end

return KeybindList
end

__modules["Systems/Notification"] = function()
--[[
	Bali UI · Systems/Notification
	Apple-inspired obsidian glass toast stack with radial glow, AutomaticSize.Y wrapping,
	hover-to-pause linear progress bar, action pills, and unread history tracking.
]]

local Services = require("Core/Services")
local Signal = require("Core/Signal")
local Maid = require("Core/Maid")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Util = require("Core/Util")

local MAX_VISIBLE = 5
local MAX_HISTORY = 50
local DEFAULT_DURATION = 4.5
local TOAST_MAX_WIDTH = 296
local TOAST_MIN_HEIGHT = 76

local Notification = {
	History = {},
	UnreadCount = 0,
	Changed = Signal.new(),
}

local rootMaid = Maid.new()
local layer = nil
local container = nil
local listLayout = nil
local currentPosition = "BottomRight"
local activeToasts = {}
local idCounter = 0

local TYPE_STYLE = {
	Info = { ColorKey = "Info", Icon = "info" },
	Success = { ColorKey = "Success", Icon = "circle-check" },
	Warning = { ColorKey = "Warning", Icon = "triangle-alert" },
	Error = { ColorKey = "Error", Icon = "circle-x" },
	Accent = { ColorKey = "Accent", Icon = "sparkles" },
}

local function getTypeMeta(kind)
	return TYPE_STYLE[kind] or TYPE_STYLE.Info
end

local function getViewportWidth()
	if layer and layer.AbsoluteSize.X > 0 then
		return layer.AbsoluteSize.X
	end
	local cam = Services.Workspace.CurrentCamera
	return cam and cam.ViewportSize.X or 1280
end

local function computeWidth()
	return math.max(220, math.min(TOAST_MAX_WIDTH, getViewportWidth() - 24))
end

local function applyPositionLayout()
	if not container or not listLayout then
		return
	end

	local pos = currentPosition
	local width = computeWidth()
	local isTop = pos == "TopRight" or pos == "TopLeft"
	local isLeft = pos == "BottomLeft" or pos == "TopLeft"

	container.Size = UDim2.new(0, width, 1, -32)
	if isTop and isLeft then
		container.AnchorPoint = Vector2.new(0, 0)
		container.Position = UDim2.fromOffset(16, 16)
	elseif isTop then
		container.AnchorPoint = Vector2.new(1, 0)
		container.Position = UDim2.new(1, -16, 0, 16)
	elseif isLeft then
		container.AnchorPoint = Vector2.new(0, 1)
		container.Position = UDim2.new(0, 16, 1, -16)
	else
		container.AnchorPoint = Vector2.new(1, 1)
		container.Position = UDim2.new(1, -16, 1, -16)
	end

	listLayout.VerticalAlignment = isTop and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Bottom
	listLayout.HorizontalAlignment = isLeft and Enum.HorizontalAlignment.Left or Enum.HorizontalAlignment.Right
end

local function ensureContainer()
	if container and container.Parent then
		return true
	end
	if not layer or not layer.Parent then
		return false
	end

	container = Create.New("Frame", {
		Name = "BaliNotificationStack",
		Parent = layer,
		BackgroundTransparency = 1,
		ZIndex = 400,
	})

	listLayout = Create.List(container, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 8,
	})

	applyPositionLayout()

	rootMaid:Give(layer:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		applyPositionLayout()
	end))

	return true
end

function Notification.Init(targetLayer)
	if layer == targetLayer and container and container.Parent then
		return Notification
	end

	-- Migrate existing active toast container seamlessly to the new host layer
	if container and container.Parent and targetLayer and targetLayer.Parent then
		rootMaid:Clean()
		layer = targetLayer
		container.Parent = targetLayer
		applyPositionLayout()
		rootMaid:Give(layer:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			applyPositionLayout()
		end))
		return Notification
	end

	for index = #activeToasts, 1, -1 do
		local toast = activeToasts[index]
		if toast and toast.Dismiss then
			toast.Dismiss(true)
		end
	end
	table.clear(activeToasts)

	if container then
		container:Destroy()
		container = nil
		listLayout = nil
	end
	rootMaid:Clean()

	layer = targetLayer
	ensureContainer()
	return Notification
end

function Notification.SetPosition(position)
	if position ~= "BottomRight" and position ~= "TopRight" and position ~= "BottomLeft" and position ~= "TopLeft" then
		return
	end
	currentPosition = position
	applyPositionLayout()
end

function Notification.MarkAllRead()
	local changed = Notification.UnreadCount > 0
	for _, item in ipairs(Notification.History) do
		if not item.Read then
			item.Read = true
			changed = true
		end
	end
	Notification.UnreadCount = 0
	if changed then
		Notification.Changed:Fire()
	end
end

function Notification.ClearHistory()
	table.clear(Notification.History)
	Notification.UnreadCount = 0
	Notification.Changed:Fire()
end

function Notification.SetDefaultDuration(seconds)
	local num = tonumber(seconds)
	if num ~= nil then
		DEFAULT_DURATION = Util.Clamp(num, 1, 30)
	end
	return DEFAULT_DURATION
end

function Notification.GetDefaultDuration()
	return DEFAULT_DURATION
end

function Notification.Notify(opts)
	opts = Util.Options(opts, {
		Title = "Notification",
		Duration = DEFAULT_DURATION,
		Type = "Info",
	}, "Content")

	idCounter += 1
	local noteId = idCounter
	local noteType = TYPE_STYLE[opts.Type] and opts.Type or "Info"
	local titleText = tostring(opts.Title or "Notification")
	local bodyText = opts.Content or opts.Description or ""
	bodyText = bodyText ~= nil and tostring(bodyText) or ""

	local historyEntry = {
		Id = noteId,
		Title = titleText,
		Content = bodyText,
		Type = noteType,
		Icon = opts.Icon,
		Timestamp = os.time(),
		TimeText = os.date("%H:%M"),
		Read = false,
	}
	table.insert(Notification.History, 1, historyEntry)
	if #Notification.History > MAX_HISTORY then
		table.remove(Notification.History, #Notification.History)
	end
	Notification.UnreadCount += 1
	Notification.Changed:Fire()

	if not ensureContainer() then
		local noop = {}
		function noop.Dismiss() end
		function noop.Update() end
		return noop
	end

	-- Evict oldest visible toast when stack hits MAX_VISIBLE
	while #activeToasts >= MAX_VISIBLE do
		local oldest = activeToasts[1]
		if oldest then
			oldest.Dismiss(true)
		else
			table.remove(activeToasts, 1)
		end
	end

	local toastMaid = Maid.new()
	local dismissed = false
	local typeMeta = getTypeMeta(noteType)
	local dismiss

	local wrapper = Create.New("Frame", {
		Name = "Toast_" .. tostring(noteId),
		Parent = container,
		Size = UDim2.new(1, 0, 0, TOAST_MIN_HEIGHT + 2),
		AutomaticSize = Enum.AutomaticSize.None,
		ClipsDescendants = false,
		BackgroundTransparency = 1,
		LayoutOrder = noteId,
		ZIndex = 401,
	})

	local cardShell = Create.New("Frame", {
		Name = "CardShell",
		Parent = wrapper,
		Size = UDim2.new(1, 0, 0, TOAST_MIN_HEIGHT + 2),
		AutomaticSize = Enum.AutomaticSize.None,
		ClipsDescendants = false,
		BackgroundTransparency = 1,
		ZIndex = 401,
	})

	local shadowDesc = Assets.Shadow()
	local shadowInset = shadowDesc.Inset or 24
	Create.New("ImageLabel", {
		Name = "Shadow",
		Parent = cardShell,
		Image = shadowDesc.Image,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = shadowDesc.Slice,
		Position = UDim2.fromOffset(-shadowInset, -shadowInset + 4),
		Size = UDim2.new(1, shadowInset * 2, 1, shadowInset * 2),
		BackgroundTransparency = 1,
		Theme = {
			ImageColor3 = "Shadow",
			ImageTransparency = "ShadowTransparency",
		},
		ZIndex = 401,
	})

	local card = Create.New("Frame", {
		Name = "Card",
		Parent = cardShell,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Corner = 14,
		ClipsDescendants = true,
		BackgroundTransparency = 0.08,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.clamp((t.CardTransparency or 0.06) + 0.04, 0.06, 0.14)
			end,
		},
		ZIndex = 402,
	})
	local cardMinConst = Instance.new("UISizeConstraint")
	cardMinConst.MinSize = Vector2.new(0, TOAST_MIN_HEIGHT)
	cardMinConst.Parent = card
	Create.GlassStroke(card, 0.12)

	local glassSheen = Create.New("Frame", {
		Name = "GlassSheen",
		Parent = card,
		Size = UDim2.fromScale(1, 1),
		Corner = 14,
		BackgroundColor3 = Color3.new(1, 1, 1),
		BackgroundTransparency = 0.94,
		ZIndex = 402,
	})
	local sheenGrad = Instance.new("UIGradient")
	sheenGrad.Rotation = 125
	sheenGrad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(0.45, 0.65),
		NumberSequenceKeypoint.new(1, 1),
	})
	sheenGrad.Parent = glassSheen

	local noiseId = Assets.Get("Noise")
	if noiseId then
		Create.New("ImageLabel", {
			Name = "Noise",
			Parent = card,
			Size = UDim2.fromScale(1, 1),
			Corner = 14,
			Image = noiseId,
			ScaleType = Enum.ScaleType.Tile,
			TileSize = UDim2.fromOffset(128, 128),
			ImageTransparency = 0.965,
			ZIndex = 402,
		})
	end

	local glowId = Assets.Get("Glow")
	local glowImg = nil
	if glowId then
		glowImg = Create.New("ImageLabel", {
			Name = "Glow",
			Parent = card,
			Size = UDim2.new(0, 185, 1, 0),
			Position = UDim2.fromOffset(-14, 0),
			Corner = 14,
			Image = glowId,
			ScaleType = Enum.ScaleType.Stretch,
			Theme = {
				ImageColor3 = typeMeta.ColorKey,
				ImageTransparency = function(t)
					return math.min((t.GlowTransparency or 0.82) + 0.02, 0.91)
				end,
			},
			ZIndex = 402,
		})
	end

	local accentBar = Create.New("Frame", {
		Name = "AccentBar",
		Parent = card,
		Size = UDim2.new(1, -28, 0, 1),
		Position = UDim2.new(0, 14, 0, 0),
		BackgroundTransparency = 0.18,
		Corner = UDim.new(1, 0),
		Theme = { BackgroundColor3 = typeMeta.ColorKey },
		ZIndex = 405,
	})
	local barGrad = Instance.new("UIGradient")
	barGrad.Rotation = 0
	barGrad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(0.12, 0.25),
		NumberSequenceKeypoint.new(0.3, 0),
		NumberSequenceKeypoint.new(0.7, 0.35),
		NumberSequenceKeypoint.new(1, 1),
	})
	barGrad.Parent = accentBar

	local body = Create.New("Frame", {
		Name = "Body",
		Parent = card,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 14, 14, 16, 14 },
		ZIndex = 404,
	})
	local bodyPad = body:FindFirstChildOfClass("UIPadding")

	local iconBadge = Create.New("Frame", {
		Name = "IconBadge",
		Parent = body,
		Size = UDim2.fromOffset(40, 40),
		Position = UDim2.fromOffset(0, 2),
		Corner = 11,
		BackgroundTransparency = 0.83,
		Theme = { BackgroundColor3 = typeMeta.ColorKey },
		ZIndex = 406,
	})
	local iconBadgeGrad = Instance.new("UIGradient")
	iconBadgeGrad.Rotation = 90
	iconBadgeGrad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(1, 0.35),
	})
	iconBadgeGrad.Parent = iconBadge

	local iconStroke = Create.Stroke(iconBadge, {
		Theme = { Color = typeMeta.ColorKey },
		Transparency = 0.45,
		Thickness = 1,
	})
	local iconStrokeGrad = Instance.new("UIGradient")
	iconStrokeGrad.Rotation = 90
	iconStrokeGrad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(0.6, 0.45),
		NumberSequenceKeypoint.new(1, 0.8),
	})
	iconStrokeGrad.Parent = iconStroke

	local iconObj = Icons.Create(opts.Icon or typeMeta.Icon, {
		Size = UDim2.fromOffset(20, 20),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = typeMeta.ColorKey,
		ZIndex = 407,
		Parent = iconBadge,
	})

	local contentCol = Create.New("Frame", {
		Name = "ContentCol",
		Parent = body,
		Position = UDim2.fromOffset(52, 0),
		Size = UDim2.new(1, -52, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ZIndex = 405,
	})
	Create.List(contentCol, { Direction = Enum.FillDirection.Vertical, Gap = 5 })

	local header = Create.New("Frame", {
		Name = "Header",
		Parent = contentCol,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		ZIndex = 405,
	})

	local titleLabel = Create.Text({
		Name = "Title",
		Parent = header,
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.new(1, -30, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = titleText,
		TextWrapped = true,
		Font = "Bold",
		TextSize = 15,
		LineHeight = 1.12,
		Color = "Text",
		ZIndex = 406,
	})

	local closeBtn = Create.New("TextButton", {
		Name = "Close",
		Parent = header,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 2, 0, -1),
		Size = UDim2.fromOffset(24, 24),
		Corner = 7,
		BackgroundTransparency = 0.78,
		Theme = { BackgroundColor3 = "Tile" },
		Text = "",
		ZIndex = 406,
	})
	Create.GlassStroke(closeBtn, 0.02)
	local closeIcon = Icons.Create("x", {
		Size = UDim2.fromOffset(13, 13),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = "Muted",
		ZIndex = 407,
		Parent = closeBtn,
	})

	toastMaid:Give(closeBtn.MouseEnter:Connect(function()
		if Util.IsTouchDevice() then
			return
		end
		Tween.Play(closeBtn, { BackgroundTransparency = 0.25, BackgroundColor3 = Theme.Current.TileHover }, Tween.Fast)
		Icons.SetColor(closeIcon, "Text")
	end))
	toastMaid:Give(closeBtn.MouseLeave:Connect(function()
		Tween.Play(closeBtn, { BackgroundTransparency = 0.78, BackgroundColor3 = Theme.Current.Tile }, Tween.Fast)
		Icons.SetColor(closeIcon, "Muted")
	end))

	local descLabel = Create.Text({
		Name = "Description",
		Parent = contentCol,
		Size = UDim2.new(1, -4, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = bodyText,
		TextWrapped = true,
		Font = "Medium",
		TextSize = 13,
		LineHeight = 1.18,
		TextTransparency = 0.05,
		Color = "SubText",
		Visible = bodyText ~= "",
		LayoutOrder = 2,
		ZIndex = 405,
	})

	local actionsRow = nil
	if type(opts.Actions) == "table" and #opts.Actions > 0 then
		if bodyPad then
			bodyPad.PaddingBottom = UDim.new(0, 20)
		end
		actionsRow = Create.New("Frame", {
			Name = "Actions",
			Parent = contentCol,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			Padding = { 3, 0, 0, 0 },
			LayoutOrder = 3,
			ZIndex = 405,
		})
		Create.List(actionsRow, {
			Direction = Enum.FillDirection.Horizontal,
			Gap = 6,
			Wraps = true,
		})

		for idx, action in ipairs(opts.Actions) do
			if type(action) == "table" then
				local isPrimary = action.Primary == true
				local btn = Create.New("TextButton", {
					Name = "Action_" .. tostring(idx),
					Parent = actionsRow,
					Size = UDim2.fromOffset(0, 28),
					AutomaticSize = Enum.AutomaticSize.X,
					Corner = 8,
					Padding = { 0, 12, 0, 12 },
					LayoutOrder = idx,
					Text = tostring(action.Title or "Action"),
					TextXAlignment = Enum.TextXAlignment.Center,
					Font = "SemiBold",
					TextSize = 12,
					Theme = isPrimary and {
						BackgroundColor3 = "Accent",
						TextColor3 = "AccentText",
					} or {
						BackgroundColor3 = "Tile",
						TextColor3 = "Text",
					},
					ZIndex = 406,
				})
				if not isPrimary then
					local actionStroke = Create.GlassStroke(btn, 0.02)
					toastMaid:Give(Transition.Hover(btn, btn, "Tile", "TileHover", actionStroke))
				end
				toastMaid:Give(btn.Activated:Connect(function(input)
					Transition.Ripple(btn, input, isPrimary and "AccentText" or "Stroke")
					if action.Callback then
						Util.Spawn(action.Callback)
					end
					if action.Dismiss ~= false and dismiss then
						dismiss(false)
					end
				end))
			end
		end
	end

	local progressTrack = Create.New("Frame", {
		Name = "ProgressTrack",
		Parent = card,
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -4),
		Size = UDim2.new(1, -28, 0, 2),
		Corner = UDim.new(1, 0),
		ClipsDescendants = false,
		BackgroundTransparency = 0.76,
		Theme = { BackgroundColor3 = "Stroke" },
		ZIndex = 405,
	})

	local progressFill = Create.New("Frame", {
		Name = "Fill",
		Parent = progressTrack,
		Size = UDim2.fromScale(1, 1),
		Corner = UDim.new(1, 0),
		BackgroundTransparency = 0.05,
		Theme = { BackgroundColor3 = typeMeta.ColorKey },
		ZIndex = 406,
	})
	local fillGrad = Instance.new("UIGradient")
	fillGrad.Rotation = 0
	fillGrad.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0.38),
		NumberSequenceKeypoint.new(0.65, 0.08),
		NumberSequenceKeypoint.new(1, 0),
	})
	fillGrad.Parent = progressFill

	local tipGlow = Create.New("Frame", {
		Name = "TipGlow",
		Parent = progressFill,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.fromOffset(10, 4),
		Corner = UDim.new(1, 0),
		BackgroundTransparency = 0.35,
		Theme = { BackgroundColor3 = typeMeta.ColorKey },
		ZIndex = 407,
	})

	local function syncShellHeight()
		if dismissed then
			return
		end
		local h = math.max(TOAST_MIN_HEIGHT, math.ceil(card.AbsoluteSize.Y))
		if math.abs(wrapper.Size.Y.Offset - h) > 0.5 then
			wrapper.Size = UDim2.new(1, 0, 0, h)
		end
		if math.abs(cardShell.Size.Y.Offset - h) > 0.5 then
			cardShell.Size = UDim2.new(1, 0, 0, h)
		end
	end
	toastMaid:Give(card:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncShellHeight))
	syncShellHeight()

	-- Timer & hover-to-pause state
	local totalDuration = tonumber(opts.Duration)
	if totalDuration == nil then
		totalDuration = opts.Duration == false and 0 or DEFAULT_DURATION
	end
	local remaining = totalDuration
	local isPaused = false
	local runStart = 0
	local progressTween = nil
	local timerToken = 0

	local toast = {}

	local function stopProgressTween()
		timerToken += 1
		if progressTween then
			pcall(function()
				progressTween:Cancel()
			end)
			progressTween = nil
		end
	end

	dismiss = function(immediate)
		if dismissed then
			return
		end
		dismissed = true
		stopProgressTween()

		local index = table.find(activeToasts, toast)
		if index then
			table.remove(activeToasts, index)
		end

		if not historyEntry.Read then
			historyEntry.Read = true
			Notification.UnreadCount = math.max(0, Notification.UnreadCount - 1)
			Notification.Changed:Fire()
		end

		local function finalize()
			toastMaid:Clean()
			if wrapper and wrapper.Parent then
				wrapper:Destroy()
			end
		end

		if immediate or Tween.Reduced then
			finalize()
		else
			local isTop = currentPosition == "TopRight" or currentPosition == "TopLeft"
			local isLeft = currentPosition == "BottomLeft" or currentPosition == "TopLeft"
			local slideOutX = isLeft and -24 or 24
			local slideOutY = isTop and -10 or 10
			if wrapper and wrapper.Parent then
				local h = math.max(wrapper.AbsoluteSize.Y, card.AbsoluteSize.Y)
				wrapper.ClipsDescendants = true
				wrapper.AutomaticSize = Enum.AutomaticSize.None
				wrapper.Size = UDim2.new(1, 0, 0, h)
				Tween.Play(wrapper, { Size = UDim2.new(1, 0, 0, 0) }, Tween.Fast, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			end
			Tween.Play(cardShell, { Position = UDim2.fromOffset(slideOutX, slideOutY) }, Tween.Fast, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			Transition.Unmount(cardShell, 1, finalize, { NoPositionTween = true })
		end
	end

	local function startTimer(durationSec)
		stopProgressTween()
		if dismissed or durationSec <= 0 or durationSec == math.huge then
			progressTrack.Visible = false
			return
		end

		progressTrack.Visible = true
		totalDuration = durationSec
		remaining = durationSec
		progressFill.Size = UDim2.fromScale(1, 1)

		if isPaused then
			return
		end

		timerToken += 1
		local myToken = timerToken
		runStart = os.clock()
		progressTween = Tween.Linear(progressFill, { Size = UDim2.fromScale(0, 1) }, remaining)
		Tween.Then(progressTween, function()
			if not dismissed and timerToken == myToken then
				dismiss(false)
			end
		end)
	end

	local function pauseTimer()
		if dismissed or isPaused or remaining <= 0 or totalDuration <= 0 or totalDuration == math.huge then
			return
		end
		isPaused = true
		local elapsed = os.clock() - runStart
		remaining = math.max(0.05, remaining - elapsed)
		stopProgressTween()
		local ratio = Util.Clamp(remaining / totalDuration, 0, 1)
		progressFill.Size = UDim2.fromScale(ratio, 1)
	end

	local function resumeTimer()
		if dismissed or not isPaused or remaining <= 0 or totalDuration <= 0 or totalDuration == math.huge then
			return
		end
		isPaused = false
		timerToken += 1
		local myToken = timerToken
		runStart = os.clock()
		progressTween = Tween.Linear(progressFill, { Size = UDim2.fromScale(0, 1) }, remaining)
		Tween.Then(progressTween, function()
			if not dismissed and timerToken == myToken then
				dismiss(false)
			end
		end)
	end

	function toast.Dismiss(arg1, arg2)
		local immediate = (arg1 == toast) and (arg2 == true) or (arg1 == true)
		dismiss(immediate)
	end

	function toast.Update(arg1, arg2)
		if dismissed then
			return
		end
		local newOpts = (arg1 == toast) and arg2 or arg1
		if type(newOpts) ~= "table" then
			return
		end

		if newOpts.Title ~= nil then
			titleText = tostring(newOpts.Title)
			titleLabel.Text = titleText
			historyEntry.Title = titleText
		end
		if newOpts.Content ~= nil or newOpts.Description ~= nil then
			bodyText = tostring(newOpts.Content or newOpts.Description or "")
			descLabel.Text = bodyText
			descLabel.Visible = bodyText ~= ""
			historyEntry.Content = bodyText
		end
		if newOpts.Type ~= nil and TYPE_STYLE[newOpts.Type] then
			noteType = newOpts.Type
			typeMeta = getTypeMeta(noteType)
			historyEntry.Type = noteType
			-- Accent styling updated via iconBadge/icon/progressBar below
			Theme.Bind(iconBadge, { BackgroundColor3 = typeMeta.ColorKey })
			Theme.Bind(iconStroke, { Color = typeMeta.ColorKey })
			Theme.Bind(accentBar, { BackgroundColor3 = typeMeta.ColorKey })
			Theme.Bind(progressFill, { BackgroundColor3 = typeMeta.ColorKey })
			Theme.Bind(tipGlow, { BackgroundColor3 = typeMeta.ColorKey })
			Icons.SetColor(iconObj, typeMeta.ColorKey)
			if glowImg then
				Theme.Bind(glowImg, { ImageColor3 = typeMeta.ColorKey })
			end
			if newOpts.Icon == nil then
				Icons.Set(iconObj, typeMeta.Icon)
			end
		end
		if newOpts.Icon ~= nil then
			Icons.Set(iconObj, newOpts.Icon)
			historyEntry.Icon = newOpts.Icon
		end
		if newOpts.Duration ~= nil then
			local newDur = newOpts.Duration == false and 0 or (tonumber(newOpts.Duration) or DEFAULT_DURATION)
			startTimer(newDur)
		end

		syncShellHeight()
		Notification.Changed:Fire()
	end

	toastMaid:Give(closeBtn.Activated:Connect(function(input)
		Transition.Ripple(closeBtn, input)
		dismiss(false)
	end))

	toastMaid:Give(card.MouseEnter:Connect(function()
		if not Util.IsTouchDevice() then
			pauseTimer()
		end
	end))
	toastMaid:Give(card.MouseLeave:Connect(function()
		resumeTimer()
	end))

	toastMaid:Give(wrapper.Destroying:Connect(function()
		if not dismissed then
			dismissed = true
			stopProgressTween()
			local idx = table.find(activeToasts, toast)
			if idx then
				table.remove(activeToasts, idx)
			end
			toastMaid:Clean()
		end
	end))

	table.insert(activeToasts, toast)
	local isTop = currentPosition == "TopRight" or currentPosition == "TopLeft"
	local isLeft = currentPosition == "BottomLeft" or currentPosition == "TopLeft"
	local slideInY = isTop and -18 or 18
	local slideInX = isLeft and -28 or 28
	Transition.SlideFade(cardShell, slideInY, slideInX)
	startTimer(totalDuration)

	return toast
end

function Notification.Destroy()
	for index = #activeToasts, 1, -1 do
		local toast = activeToasts[index]
		if toast and toast.Dismiss then
			toast.Dismiss(true)
		end
	end
	table.clear(activeToasts)
	rootMaid:Clean()
	if container then
		container:Destroy()
		container = nil
		listLayout = nil
	end
	layer = nil
	Notification.ClearHistory()
end

return Notification
end

__modules["Systems/Tooltip"] = function()
--[[
	Bali UI · Systems/Tooltip
	Delayed obsidian glass tooltips with AutomaticSize.Y wrapping, smart viewport clamping,
	and cursor-avoidance positioning.
]]

local Services = require("Core/Services")
local Maid = require("Core/Maid")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Tween = require("Core/Tween")
local Transition = require("Core/Transition")
local Util = require("Core/Util")

local Tooltip = {}

local DEFAULT_DELAY = 0.12
local MAX_WIDTH = 260
local MIN_WIDTH = 44
local EDGE_PAD = 8

local rootMaid = Maid.new()
local layer = nil
local card = nil
local shadow = nil
local label = nil
local visible = false
local activeOwner = nil
local activeAnchor = nil
local activeSide = nil
local openCursorX = nil
local currentWidth = 120
local currentHeight = 28
local pendingThread = nil
local boundCleanups = {} -- [GuiObject] = cleanupFn

local function getViewportBounds()
	if layer and layer.AbsoluteSize.X > 0 and layer.AbsoluteSize.Y > 0 then
		return layer.AbsolutePosition, layer.AbsoluteSize
	end
	local camera = Services.Workspace.CurrentCamera
	local raw = camera and camera.ViewportSize or Vector2.new(1920, 1080)
	local ok, inset = pcall(function()
		return Services.GuiService:GetGuiInset()
	end)
	if ok and inset then
		return Vector2.new(inset.X, inset.Y), Vector2.new(raw.X - inset.X, raw.Y - inset.Y)
	end
	return Vector2.zero, raw
end

local function getCursorPosition()
	-- GuiObject.AbsolutePosition is reported in GuiInset-subtracted coordinates even under IgnoreGuiInset = true
	return Util.MousePosition()
end

local function cancelPending()
	if pendingThread then
		pcall(task.cancel, pendingThread)
		pendingThread = nil
	end
end

local function syncShadow()
	if not shadow or not card then
		return
	end
	if not card.Visible then
		shadow.Visible = false
		return
	end
	local shadowInfo = Assets.Shadow()
	local inset = shadowInfo.Inset or 24
	local size = card.AbsoluteSize
	local w = (card.Size.X.Offset > 0 and card.Size.X.Offset) or (size.X > 0 and size.X) or currentWidth
	local h = (size.Y > 0 and size.Y) or currentHeight
	local pos = card.Position
	shadow.Visible = true
	shadow.Position = UDim2.new(pos.X.Scale, pos.X.Offset - inset, pos.Y.Scale, pos.Y.Offset - inset)
	shadow.Size = UDim2.fromOffset(w + inset * 2, h + inset * 2)
end

local function measureSize(text)
	local font = Theme.Font("Medium")
	local ok, bounds = pcall(function()
		local params = Instance.new("GetTextBoundsParams")
		params.Text = text
		params.Font = font
		params.Size = 12
		params.Width = MAX_WIDTH - 20
		return Services.TextService:GetTextBoundsAsync(params)
	end)
	if ok and bounds then
		return Util.Clamp(math.ceil(bounds.X) + 22, MIN_WIDTH, MAX_WIDTH), math.max(math.ceil(bounds.Y) + 14, 28)
	end
	return Util.Clamp(#text * 7 + 22, MIN_WIDTH, MAX_WIDTH), 28
end

local function placeNearCursor(w, h)
	local origin, vp = getViewportBounds()
	local cursor = getCursorPosition()
	local offset = 10
	local minX = origin.X + EDGE_PAD
	local minY = origin.Y + EDGE_PAD
	local maxX = math.max(minX, origin.X + vp.X - w - EDGE_PAD)
	local maxY = math.max(minY, origin.Y + vp.Y - h - EDGE_PAD)

	local x = cursor.X + offset
	local y = cursor.Y + 12

	if x + w + EDGE_PAD > origin.X + vp.X then
		x = cursor.X - w - offset
	end
	if y + h + EDGE_PAD > origin.Y + vp.Y then
		y = cursor.Y - h - offset
	end

	x = Util.Clamp(x, minX, maxX)
	y = Util.Clamp(y, minY, maxY)

	-- Guarantee cursor does not overlap the clamped tooltip box
	local cursorPad = 10
	local overlapsX = cursor.X >= (x - 4) and cursor.X <= (x + w + 4)
	local overlapsY = cursor.Y >= (y - 4) and cursor.Y <= (y + h + 4)
	if overlapsX and overlapsY then
		local aboveY = cursor.Y - h - cursorPad
		local belowY = cursor.Y + cursorPad + 8
		if aboveY >= minY then
			y = aboveY
		elseif belowY + h + EDGE_PAD <= origin.Y + vp.Y then
			y = belowY
		else
			local leftX = cursor.X - w - cursorPad
			local rightX = cursor.X + cursorPad
			if leftX >= minX then
				x = leftX
			elseif rightX + w + EDGE_PAD <= origin.X + vp.X then
				x = rightX
			end
		end
	end

	return math.round(x), math.round(y)
end

local function placeNearAnchor(anchorGui, w, h, preferredSide)
	local origin, vp = getViewportBounds()
	local absPos = anchorGui.AbsolutePosition
	local absSize = anchorGui.AbsoluteSize
	local gap = 8
	local minX = origin.X + EDGE_PAD
	local minY = origin.Y + EDGE_PAD
	local maxX = math.max(minX, origin.X + vp.X - w - EDGE_PAD)
	local maxY = math.max(minY, origin.Y + vp.Y - h - EDGE_PAD)

	local x, y
	if preferredSide == "Right" then
		x = absPos.X + absSize.X + 10
		y = absPos.Y + (absSize.Y - h) * 0.5
		if x + w + EDGE_PAD > origin.X + vp.X then
			x = absPos.X - w - 10
		end
	elseif preferredSide == "Left" then
		x = absPos.X - w - 10
		y = absPos.Y + (absSize.Y - h) * 0.5
		if x < minX then
			x = absPos.X + absSize.X + 10
		end
	else
		if absSize.X > 260 and openCursorX ~= nil then
			x = Util.Clamp(openCursorX - w * 0.5, absPos.X, math.max(absPos.X, absPos.X + absSize.X - w))
		else
			x = absPos.X + (absSize.X - w) * 0.5
		end
		if preferredSide == "Top" then
			y = absPos.Y - h - gap
			if y < minY then
				y = absPos.Y + absSize.Y + gap
			end
		else
			y = absPos.Y + absSize.Y + gap
			if y + h + EDGE_PAD > origin.Y + vp.Y then
				local aboveY = absPos.Y - h - gap
				if aboveY >= minY then
					y = aboveY
				end
			end
		end
	end

	x = Util.Clamp(x, minX, maxX)
	y = Util.Clamp(y, minY, maxY)

	return math.round(x), math.round(y)
end

local function updatePosition(anchorGui, preferredSide)
	if not card then
		return
	end
	local size = card.AbsoluteSize
	local w = (card.Size.X.Offset > 0 and card.Size.X.Offset) or currentWidth
	local h = (card.Visible and size.Y > 0 and size.Y) or currentHeight

	local x, y
	if anchorGui and typeof(anchorGui) == "Instance" and anchorGui:IsA("GuiObject") and anchorGui.Parent then
		x, y = placeNearAnchor(anchorGui, w, h, preferredSide)
	else
		x, y = placeNearCursor(w, h)
	end

	local parentPos = (layer and layer:IsA("GuiBase2d")) and layer.AbsolutePosition or Vector2.zero
	card.Position = UDim2.fromOffset(x - parentPos.X, y - parentPos.Y)
	syncShadow()
end

local function ensureBuilt()
	if card and card.Parent then
		return true
	end
	if not layer or not layer.Parent then
		return false
	end

	local shadowInfo = Assets.Shadow()
	shadow = Create.New("ImageLabel", {
		Name = "BaliTooltipShadow",
		Parent = layer,
		Visible = false,
		Active = false,
		Image = shadowInfo.Image,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = shadowInfo.Slice,
		ImageTransparency = Theme.Current.ShadowTransparency,
		Theme = { ImageColor3 = "Shadow", ImageTransparency = "ShadowTransparency" },
		ZIndex = 499,
	})

	card = Create.New("Frame", {
		Name = "BaliTooltip",
		Parent = layer,
		Visible = false,
		Active = false,
		Size = UDim2.fromOffset(120, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Corner = 8,
		Padding = { 7, 10, 7, 10 },
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.min(t.CardTransparency, 0.06)
			end,
		},
		ZIndex = 500,
	})
	Create.GlassStroke(card, 0.05)

	label = Create.Text({
		Name = "Text",
		Parent = card,
		Active = false,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		Font = "Medium",
		TextSize = 12,
		Color = "Text",
		ZIndex = 501,
	})

	rootMaid:Give(card:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		if visible then
			updatePosition(activeAnchor, activeSide)
		end
	end))

	return true
end

function Tooltip.Init(popupLayer)
	if layer == popupLayer and card and card.Parent then
		return Tooltip
	end
	if card then
		card:Destroy()
		card = nil
	end
	if shadow then
		shadow:Destroy()
		shadow = nil
	end
	layer = popupLayer
	visible = false
	ensureBuilt()
	return Tooltip
end

function Tooltip.Show(text, anchorGui, side)
	if text == nil or text == "" then
		Tooltip.Hide()
		return
	end
	if not ensureBuilt() then
		return
	end

	local str = tostring(text)
	local width, height = measureSize(str)
	currentWidth = width
	currentHeight = height
	card.Size = UDim2.fromOffset(width, 0)
	label.Text = str
	label:SetAttribute("_BaliRestTxt", 0)

	local wasVisible = visible
	visible = true
	activeAnchor = (anchorGui and typeof(anchorGui) == "Instance" and anchorGui:IsA("GuiObject")) and anchorGui or nil
	activeSide = side
	if activeAnchor and not activeOwner then
		activeOwner = activeAnchor
	end

	updatePosition(activeAnchor, activeSide)
	if not wasVisible then
		if not card:GetAttribute("_BaliFading") then
			label.TextTransparency = 0
		end
		if shadow then
			shadow.Visible = true
			shadow.ImageTransparency = 1
			Tween.Play(shadow, { ImageTransparency = Theme.Current.ShadowTransparency }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		end
		Transition.Mount(card, 0.96, { NoPositionTween = true, Duration = 0.14 })
	else
		card.Visible = true
		label.TextTransparency = 0
		if not Tween.Reduced then
			Tween.Play(label, { TextTransparency = 0 }, Tween.Fast)
		end
		syncShadow()
	end
end

function Tooltip.Hide()
	cancelPending()
	activeOwner = nil
	activeAnchor = nil
	activeSide = nil
	openCursorX = nil
	if not visible or not card then
		visible = false
		if shadow then
			shadow.Visible = false
		end
		return
	end
	visible = false
	if shadow then
		Tween.Play(shadow, { ImageTransparency = 1 }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end
	Transition.Unmount(card, 0.96, function()
		if not visible then
			if card and card.Parent then
				card.Visible = false
			end
			if shadow and shadow.Parent then
				shadow.Visible = false
			end
		end
	end, { NoPositionTween = true, Duration = 0.12 })
end

function Tooltip.Bind(guiObj, textOrFn, opts)
	if not guiObj then
		return function() end
	end

	if boundCleanups[guiObj] then
		boundCleanups[guiObj]()
	end

	opts = opts or {}
	local delayTime = opts.Delay ~= nil and opts.Delay or DEFAULT_DELAY
	local anchorMode = opts.Anchor or "Element"
	local preferredSide = opts.Side or "Auto"
	local bindMaid = Maid.new()
	local hovering = false
	local cleaned = false

	local function resolveText()
		if type(textOrFn) == "function" then
			local ok, result = Util.SafeCall(textOrFn)
			return ok and result or nil
		end
		return textOrFn
	end

	local function showForObject()
		if cleaned or not hovering or not guiObj.Parent or Transition.IsOverlayBlocking(guiObj) then
			return
		end
		local content = resolveText()
		if content == nil or content == "" then
			return
		end
		activeOwner = guiObj
		openCursorX = getCursorPosition().X
		local anchor = anchorMode == "Element" and guiObj or nil
		Tooltip.Show(content, anchor, anchor and preferredSide or nil)
	end

	bindMaid:Give(guiObj.MouseEnter:Connect(function()
		if cleaned or Util.IsTouchDevice() or Transition.IsOverlayBlocking(guiObj) then
			return
		end
		hovering = true
		cancelPending()
		pendingThread = task.delay(delayTime, function()
			pendingThread = nil
			showForObject()
		end)
	end))

	if anchorMode == "Cursor" then
		bindMaid:Give(guiObj.MouseMoved:Connect(function()
			if cleaned or not hovering then
				return
			end
			if visible and activeOwner == guiObj and not activeAnchor then
				updatePosition(nil, nil)
			end
		end))
	end

	local function cancelHover()
		hovering = false
		cancelPending()
		if activeOwner == guiObj then
			Tooltip.Hide()
		end
	end

	bindMaid:Give(guiObj.MouseLeave:Connect(cancelHover))

	bindMaid:Give(guiObj.InputBegan:Connect(function(input)
		if Util.IsPointer(input) then
			if Util.IsTouchDevice() and anchorMode == "Element" then
				hovering = true
				cancelPending()
				pendingThread = task.delay(delayTime, function()
					pendingThread = nil
					showForObject()
				end)
			else
				cancelHover()
			end
		end
	end))

	if Util.IsTouchDevice() then
		bindMaid:Give(guiObj.InputEnded:Connect(function(input)
			if Util.IsPointer(input) then
				cancelHover()
			end
		end))
	end

	bindMaid:Give(guiObj.AncestryChanged:Connect(function(_, newParent)
		if not newParent then
			cancelHover()
		end
	end))

	local function cleanup()
		if cleaned then
			return
		end
		cleaned = true
		cancelHover()
		if boundCleanups[guiObj] == cleanup then
			boundCleanups[guiObj] = nil
		end
		bindMaid:Clean()
	end

	bindMaid:Give(guiObj.Destroying:Connect(cleanup))
	boundCleanups[guiObj] = cleanup
	rootMaid:Give(cleanup)

	return cleanup
end

function Tooltip.Destroy()
	cancelPending()
	for _, fn in pairs(boundCleanups) do
		pcall(fn)
	end
	table.clear(boundCleanups)
	rootMaid:Clean()
	if card then
		card:Destroy()
		card = nil
	end
	if shadow then
		shadow:Destroy()
		shadow = nil
	end
	layer = nil
	label = nil
	activeOwner = nil
	activeAnchor = nil
	activeSide = nil
	openCursorX = nil
	visible = false
end

return Tooltip
end

__modules["Systems/Watermark"] = function()
--[[
	Bali UI · Systems/Watermark
	Draggable Dynamic-Island style obsidian glass HUD pill with live pulse status dot,
	viewport clamping, and optional live FPS/Ping/Time/Players telemetry.
]]

local Services = require("Core/Services")
local Maid = require("Core/Maid")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Transition = require("Core/Transition")
local Util = require("Core/Util")
local Input = require("Systems/Input")

local Watermark = {}

local rootMaid = Maid.new()
local layer = nil
local pill = nil
local dot = nil
local dotHalo = nil
local titleLabel = nil
local divider = nil
local statsLabel = nil
local stopPulseFn = nil
local dragHandle = nil
local renderConn = nil

local visible = false
local titleText = "Bali"
local customText = nil
local statsConfig = {
	FPS = true,
	Ping = true,
	Time = true,
	Players = false,
	Custom = nil,
}

local fpsSamples = 0
local fpsElapsed = 0
local currentFps = 60
local lastRefresh = 0

local function readPingMs()
	local ok, value = pcall(function()
		local net = Services.Stats and Services.Stats.Network
		local item = net and net.ServerStatsItem and net.ServerStatsItem["Data Ping"]
		return item and item:GetValue() or 0
	end)
	return (ok and type(value) == "number") and math.max(0, math.round(value)) or 0
end

local function readPlayerCount()
	local ok, text = pcall(function()
		local players = Services.Players
		return tostring(#players:GetPlayers()) .. "/" .. tostring(players.MaxPlayers)
	end)
	return ok and text or "1/1"
end

local function formatStats()
	local parts = {}
	if customText ~= nil and customText ~= "" then
		table.insert(parts, tostring(customText))
	end

	local cfg = statsConfig

	if cfg.FPS == true then
		table.insert(parts, tostring(math.max(0, math.round(currentFps))) .. " FPS")
	elseif type(cfg.FPS) == "number" then
		table.insert(parts, tostring(math.round(cfg.FPS)) .. " FPS")
	elseif type(cfg.FPS) == "string" and cfg.FPS ~= "" then
		table.insert(parts, cfg.FPS)
	end

	if cfg.Ping == true then
		table.insert(parts, tostring(readPingMs()) .. " ms")
	elseif type(cfg.Ping) == "number" then
		table.insert(parts, tostring(math.round(cfg.Ping)) .. " ms")
	elseif type(cfg.Ping) == "string" and cfg.Ping ~= "" then
		table.insert(parts, cfg.Ping)
	end

	if cfg.Time == true then
		table.insert(parts, tostring(os.date("%H:%M:%S")))
	elseif type(cfg.Time) == "string" and cfg.Time ~= "" then
		table.insert(parts, cfg.Time)
	end

	if cfg.Players == true then
		table.insert(parts, readPlayerCount() .. " Players")
	elseif type(cfg.Players) == "string" or type(cfg.Players) == "number" then
		table.insert(parts, tostring(cfg.Players))
	end

	if type(cfg.Custom) == "string" and cfg.Custom ~= "" then
		table.insert(parts, cfg.Custom)
	end

	return table.concat(parts, "  •  ")
end

local function refreshLabels()
	if not pill then
		return
	end
	titleLabel.Text = titleText
	local text = formatStats()
	statsLabel.Text = text
	local hasStats = text ~= ""
	statsLabel.Visible = hasStats
	divider.Visible = hasStats and titleText ~= ""
	titleLabel.Visible = titleText ~= ""
end

local function stopLiveEffects()
	if stopPulseFn then
		stopPulseFn()
		stopPulseFn = nil
	end
	if renderConn then
		renderConn:Disconnect()
		renderConn = nil
	end
end

local function startLiveEffects()
	stopLiveEffects()
	if not pill or not visible then
		return
	end

	if dotHalo then
		stopPulseFn = Transition.Pulse(dotHalo, "BackgroundTransparency", 0.5, 0.92, 1.6)
	end

	fpsSamples = 0
	fpsElapsed = 0
	lastRefresh = os.clock()

	renderConn = Services.RunService.RenderStepped:Connect(function(dt)
		if not visible or not pill or not pill.Parent then
			stopLiveEffects()
			return
		end
		fpsSamples += 1
		fpsElapsed += dt
		local now = os.clock()
		if now - lastRefresh >= 0.5 then
			if fpsElapsed > 0 then
				currentFps = fpsSamples / fpsElapsed
			end
			fpsSamples = 0
			fpsElapsed = 0
			lastRefresh = now
			refreshLabels()
		end
	end)
end

local function ensureBuilt()
	if pill and pill.Parent then
		return true
	end
	if not layer or not layer.Parent then
		return false
	end

	pill = Create.New("Frame", {
		Name = "BaliWatermark",
		Parent = layer,
		Visible = visible,
		Active = true,
		Position = UDim2.fromOffset(16, 68),
		Size = UDim2.fromOffset(0, 34),
		AutomaticSize = Enum.AutomaticSize.X,
		Corner = UDim.new(1, 0),
		ClipsDescendants = true,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.min(t.CardTransparency, 0.08)
			end,
		},
		ZIndex = 350,
	})
	Create.GlassStroke(pill, 0.06)

	local glowId = Assets.Get("Glow")
	if glowId then
		Create.New("ImageLabel", {
			Name = "Glow",
			Parent = pill,
			Size = UDim2.fromOffset(100, 34),
			Position = UDim2.fromOffset(-20, 0),
			Corner = UDim.new(1, 0),
			Image = glowId,
			ScaleType = Enum.ScaleType.Stretch,
			Theme = {
				ImageColor3 = "Accent",
				ImageTransparency = function(t)
					return math.min(t.GlowTransparency + 0.06, 0.94)
				end,
			},
			ZIndex = 350,
		})
	end

	local content = Create.New("Frame", {
		Name = "Content",
		Parent = pill,
		Size = UDim2.fromOffset(0, 34),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Padding = { 0, 14, 0, 12 },
		ZIndex = 352,
	})
	Create.List(content, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 8,
	})

	local dotHolder = Create.New("Frame", {
		Name = "PulseHolder",
		Parent = content,
		Size = UDim2.fromOffset(12, 12),
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		ZIndex = 353,
	})

	dotHalo = Create.New("Frame", {
		Name = "Halo",
		Parent = dotHolder,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(12, 12),
		Corner = UDim.new(1, 0),
		BackgroundTransparency = 0.6,
		Theme = { BackgroundColor3 = "Accent" },
		ZIndex = 353,
	})

	dot = Create.New("Frame", {
		Name = "Dot",
		Parent = dotHolder,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(6, 6),
		Corner = UDim.new(1, 0),
		Theme = { BackgroundColor3 = "Accent" },
		ZIndex = 354,
	})

	titleLabel = Create.Text({
		Name = "Title",
		Parent = content,
		Size = UDim2.fromOffset(0, 18),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = titleText,
		Font = "SemiBold",
		TextSize = 12,
		Color = "Text",
		LayoutOrder = 2,
		ZIndex = 353,
	})

	divider = Create.New("Frame", {
		Name = "Divider",
		Parent = content,
		Size = UDim2.fromOffset(1, 13),
		LayoutOrder = 3,
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		ZIndex = 353,
	})

	statsLabel = Create.Text({
		Name = "Stats",
		Parent = content,
		Size = UDim2.fromOffset(0, 18),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = "",
		Font = "Medium",
		TextSize = 12,
		Color = "SubText",
		LayoutOrder = 4,
		ZIndex = 353,
	})

	dragHandle = Input.BindDrag(pill, pill, { Clamp = true, Padding = 8 })
	rootMaid:Give(dragHandle)
	refreshLabels()

	if visible then
		startLiveEffects()
	end

	return true
end

function Watermark.Init(targetLayer)
	if layer == targetLayer and pill and pill.Parent then
		return Watermark
	end
	stopLiveEffects()
	rootMaid:Clean()
	if pill then
		pill:Destroy()
		pill = nil
	end
	layer = targetLayer
	ensureBuilt()
	return Watermark
end

function Watermark.SetVisible(state)
	local targetState = state == true
	visible = targetState
	if not ensureBuilt() then
		return
	end

	if targetState then
		refreshLabels()
		Transition.Mount(pill, 0.92)
		startLiveEffects()
	else
		stopLiveEffects()
		Transition.Unmount(pill, 0.92, function()
			if not visible and pill and pill.Parent then
				pill.Visible = false
			end
		end)
	end
end

function Watermark.IsVisible()
	return visible
end

function Watermark.SetTitle(text)
	titleText = text ~= nil and tostring(text) or ""
	refreshLabels()
end

function Watermark.SetText(text)
	customText = text ~= nil and tostring(text) or nil
	refreshLabels()
end

function Watermark.SetStats(stats)
	if type(stats) == "table" then
		customText = nil
		for key, value in pairs(stats) do
			statsConfig[key] = value
		end
	end
	refreshLabels()
end

function Watermark.Destroy()
	visible = false
	stopLiveEffects()
	rootMaid:Clean()
	if pill then
		pill:Destroy()
		pill = nil
	end
	dot = nil
	dotHalo = nil
	titleLabel = nil
	divider = nil
	statsLabel = nil
	dragHandle = nil
	layer = nil
end

return Watermark
end

__modules["Elements/Accordion"] = function()
--[[
	Bali UI · Elements/Accordion
	Collapsible glass sub-container inside a Section with smooth expand/collapse animation
	and full Container attachment so all library elements can be nested cleanly.
]]

local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Tween = require("Core/Tween")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")
local Tooltip = require("Systems/Tooltip")

local Accordion = {}
Accordion.__index = Accordion

local function unwrapCard(cardParent, opts)
	local cardObj = Base.Card(cardParent, opts)
	if typeof(cardObj) == "Instance" then
		return cardObj, cardObj:FindFirstChildOfClass("UIStroke"), nil
	end
	return cardObj.Frame, cardObj.Stroke, cardObj
end

local function isDisabledOrLocked(self)
	return self.Disabled == true or self.Locked == true or self._disabled == true or self._locked == true
end

function Accordion.new(parent, opts, ctx)
	opts = Util.Options(opts, {
		Title = "Accordion",
		Description = nil,
		Icon = nil,
		Expanded = nil,
		Default = false,
		Callback = nil,
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("Accordion", parent, opts, ctx)
	local cardParent = (typeof(self.Frame) == "Instance") and self.Frame or parent
	local cardFrame, cardStroke, cardUI = unwrapCard(cardParent, opts)

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = cardFrame
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
	end

	cardFrame.ClipsDescendants = true
	Create.List(cardFrame, { Gap = 0 })

	local initialExpanded = false
	if opts.Expanded ~= nil then
		initialExpanded = opts.Expanded == true
	elseif opts.Opened ~= nil then
		initialExpanded = opts.Opened == true
	elseif opts.Default ~= nil then
		initialExpanded = opts.Default == true
	end

	local expanded = initialExpanded
	local animGen = 0

	self.Expanded = expanded
	self.Value = expanded
	self.Stroke = cardStroke

	-- Header row
	local headerBtn = Create.New("TextButton", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Text = "",
		Corner = 10,
		Padding = { 10, 12, 10, 12 },
		Theme = {
			BackgroundColor3 = "Tile",
			BackgroundTransparency = "TileTransparency",
		},
		Parent = cardFrame,
	})
	Transition.Hover(headerBtn, headerBtn, "Tile", "TileHover", cardStroke)

	local iconOffset = 0
	if opts.Icon then
		iconOffset = 24
		Icons.Create(opts.Icon, {
			Name = "Icon",
			Size = UDim2.fromOffset(16, 16),
			Position = UDim2.new(0, 0, 0.5, 0),
			AnchorPoint = Vector2.new(0, 0.5),
			Color = "Accent",
			Parent = headerBtn,
		})
	end

	local textCol = Create.New("Frame", {
		Name = "TextCol",
		Size = UDim2.new(1, -(iconOffset + 24), 0, 0),
		Position = UDim2.fromOffset(iconOffset, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = headerBtn,
	})
	Create.List(textCol, { Gap = 2 })

	local titleLabel = Create.Text({
		Name = "Title",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = tostring(opts.Title or "Accordion"),
		TextSize = 13,
		Font = "SemiBold",
		TextWrapped = true,
		Color = "Text",
		LayoutOrder = 1,
		Parent = textCol,
	})

	local descText = opts.Description and tostring(opts.Description) or ""
	local descLabel = Create.Text({
		Name = "Description",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = descText,
		TextSize = 11,
		TextWrapped = true,
		Color = "SubText",
		Visible = descText ~= "",
		LayoutOrder = 2,
		Parent = textCol,
	})

	local chevron = Icons.Create("chevron-down", {
		Name = "Chevron",
		Size = UDim2.fromOffset(15, 15),
		Position = UDim2.new(1, 0, 0.5, 0),
		AnchorPoint = Vector2.new(1, 0.5),
		Color = "SubText",
		Parent = headerBtn,
	})
	local chevronBaseRot = chevron and chevron.Rotation or 0
	if chevron and expanded then
		chevron.Rotation = chevronBaseRot + 180
	end

	local divider = Create.New("Frame", {
		Name = "Divider",
		Size = UDim2.new(1, 0, 0, 1),
		LayoutOrder = 2,
		Visible = expanded,
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		Parent = cardFrame,
	})

	local bodyClip = Create.New("Frame", {
		Name = "BodyClip",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = expanded and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
		ClipsDescendants = not expanded,
		BackgroundTransparency = 1,
		Visible = expanded,
		LayoutOrder = 3,
		Parent = cardFrame,
	})

	local bodyInner = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 8, 12, 10, 12 },
		Parent = bodyClip,
	})
	local innerLayout = Create.List(bodyInner, { Gap = 8 })

	self.Content = bodyInner
	self.Body = bodyInner
	self.TitleLabel = titleLabel
	self.DescLabel = descLabel

	if self.BindUI then
		self:BindUI({
			Frame = cardFrame,
			Stroke = cardStroke,
			TitleLabel = titleLabel,
			DescLabel = descLabel,
			LockOverlay = cardUI and cardUI.LockOverlay or nil,
			SetDisabled = cardUI and cardUI.SetDisabled or nil,
			Lock = cardUI and cardUI.Lock or nil,
			Unlock = cardUI and cardUI.Unlock or nil,
			Flash = cardUI and cardUI.Flash or nil,
		})
	end

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, headerBtn, opts.Tooltip)
	end

	if ctx.AttachContainer then
		ctx.AttachContainer(self, bodyInner, ctx.Tab, ctx.Section)
	end

	local function animateState(targetExpanded)
		animGen += 1
		local myGen = animGen

		if chevron then
			Tween.Play(chevron, { Rotation = targetExpanded and (chevronBaseRot + 180) or chevronBaseRot }, Tween.Fast)
		end

		if targetExpanded then
			divider.Visible = true
			bodyClip.ClipsDescendants = true
			bodyClip.Visible = true
			bodyClip.AutomaticSize = Enum.AutomaticSize.None
			bodyClip.Size = UDim2.new(1, 0, 0, 0)

			local function runExpandTween()
				if animGen ~= myGen or not expanded then
					return
				end
				local targetH = math.max(18, innerLayout.AbsoluteContentSize.Y + 18)
				local tw = Tween.Play(bodyClip, { Size = UDim2.new(1, 0, 0, targetH) }, Tween.Normal)
				Tween.Then(tw, function()
					if animGen == myGen and expanded then
						bodyClip.AutomaticSize = Enum.AutomaticSize.Y
						bodyClip.Size = UDim2.new(1, 0, 0, 0)
						bodyClip.ClipsDescendants = false
					end
				end)
			end

			if innerLayout.AbsoluteContentSize.Y > 0 then
				runExpandTween()
			else
				task.defer(runExpandTween)
			end
		else
			divider.Visible = false
			bodyClip.ClipsDescendants = true
			local startH = bodyClip.AbsoluteSize.Y
			if startH <= 0 then
				startH = innerLayout.AbsoluteContentSize.Y + 18
			end
			bodyClip.AutomaticSize = Enum.AutomaticSize.None
			bodyClip.Size = UDim2.new(1, 0, 0, startH)

			local tw = Tween.Play(bodyClip, { Size = UDim2.new(1, 0, 0, 0) }, Tween.Fast)
			Tween.Then(tw, function()
				if animGen == myGen and not expanded then
					bodyClip.Visible = false
				end
			end)
		end
	end

	function self:SetExpanded(state, silent)
		local nextState = state == true
		if expanded == nextState then
			return
		end
		expanded = nextState
		self.Expanded = expanded
		self.Value = expanded
		animateState(expanded)

		if not silent then
			if opts.Callback then
				Util.Spawn(opts.Callback, expanded)
			end
			self.Changed:Fire(expanded)
		end
	end

	function self:Set(state, silent)
		self:SetExpanded(state, silent)
	end

	function self:Get()
		return expanded
	end

	function self:IsExpanded()
		return expanded
	end

	function self:Expand(silent)
		self:SetExpanded(true, silent)
	end

	function self:Collapse(silent)
		self:SetExpanded(false, silent)
	end

	function self:Toggle(silent)
		self:SetExpanded(not expanded, silent)
	end

	headerBtn.Activated:Connect(function()
		if isDisabledOrLocked(self) then
			return
		end
		Transition.Ripple(headerBtn, nil, "Accent")
		self:Toggle(false)
	end)

	local baseSetTitle = self.SetTitle
	function self:SetTitle(text)
		titleLabel.Text = tostring(text or "")
		if baseSetTitle then
			pcall(baseSetTitle, self, text)
		end
	end

	local baseSetDesc = self.SetDesc
	function self:SetDesc(text)
		local str = text and tostring(text) or ""
		descLabel.Text = str
		descLabel.Visible = str ~= ""
		if baseSetDesc then
			pcall(baseSetDesc, self, text)
		end
	end

	self.Maid:Give(function()
		animGen += 1
	end)

	return self
end

return Accordion
end

__modules["Elements/Analytics"] = function()
--[[
	Bali UI · Elements/Analytics
	Data visualization & dashboard elements inspired by SEDA, MEXC, and TradingView:
	StatCard, Chart (Line/Area & Bar with hover crosshair), ProgressBar, Table, CardGrid.
]]

local Services = require("Core/Services")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Tween = require("Core/Tween")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")
local Tooltip = require("Systems/Tooltip")

local Analytics = {}

-- ─── Shared Helpers ──────────────────────────────────────────────────────────

local function unwrapCard(cardParent, opts)
	local cardObj = Base.Card(cardParent, opts)
	if typeof(cardObj) == "Instance" then
		return cardObj, cardObj:FindFirstChildOfClass("UIStroke"), nil
	end
	return cardObj.Frame, cardObj.Stroke, cardObj
end

local function resolveColorSpec(spec, fallback)
	if typeof(spec) == "Color3" then
		return spec
	elseif type(spec) == "string" and Theme.Current[spec] ~= nil then
		return spec
	end
	return fallback or "Accent"
end

local function bindColorProp(inst, prop, colorSpec)
	if typeof(colorSpec) == "Color3" then
		Theme.Unbind(inst, prop)
		inst[prop] = colorSpec
	else
		Theme.Bind(inst, { [prop] = colorSpec })
	end
end

local function resolveAlign(align)
	if typeof(align) == "EnumItem" then
		return align
	elseif type(align) == "string" then
		local lower = string.lower(align)
		if lower == "right" then
			return Enum.TextXAlignment.Right
		elseif lower == "center" then
			return Enum.TextXAlignment.Center
		end
	end
	return Enum.TextXAlignment.Left
end

local function formatNumericValue(value, prefix, suffix, decimals)
	if type(value) ~= "number" then
		return tostring(value or "")
	end
	local dec = decimals
	if dec == nil then
		dec = (math.floor(value) == value) and 0 or 2
	end
	return (prefix or "") .. Util.FormatNumber(value, dec) .. (suffix or "")
end

local function computeMinMax(points)
	local minV, maxV = math.huge, -math.huge
	for _, v in ipairs(points) do
		local n = tonumber(v)
		if n then
			if n < minV then
				minV = n
			end
			if n > maxV then
				maxV = n
			end
		end
	end
	if minV == math.huge then
		return 0, 1
	end
	if math.abs(maxV - minV) < 1e-6 then
		return minV - 1, maxV + 1
	end
	return minV, maxV
end

local function renderLineSegments(container, points, colorSpec, thickness, padY)
	for _, child in ipairs(container:GetChildren()) do
		if child:IsA("GuiObject") then
			child:Destroy()
		end
	end
	local count = type(points) == "table" and #points or 0
	if count < 2 then
		return
	end
	local w = container.AbsoluteSize.X
	local h = container.AbsoluteSize.Y
	if w <= 2 or h <= 2 then
		return
	end

	local minV, maxV = computeMinMax(points)
	local span = maxV - minV
	local insetY = padY or 3
	local usableH = math.max(1, h - insetY * 2)

	local coords = table.create(count)
	for i = 1, count do
		local n = tonumber(points[i]) or minV
		local nx = (i - 1) / (count - 1)
		local ny = 1 - ((n - minV) / span)
		coords[i] = Vector2.new(nx * w, insetY + ny * usableH)
	end

	for i = 1, count - 1 do
		local p1, p2 = coords[i], coords[i + 1]
		local dx, dy = p2.X - p1.X, p2.Y - p1.Y
		local len = math.sqrt(dx * dx + dy * dy)
		local seg = Create.New("Frame", {
			Name = "Seg_" .. i,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset((p1.X + p2.X) * 0.5, (p1.Y + p2.Y) * 0.5),
			Size = UDim2.fromOffset(len + 1.5, thickness or 2),
			Rotation = math.deg(math.atan2(dy, dx)),
			Corner = 999,
			ZIndex = container.ZIndex + 1,
			Parent = container,
		})
		bindColorProp(seg, "BackgroundColor3", colorSpec)
	end
end

-- ─── 1. StatCard ─────────────────────────────────────────────────────────────

local StatCard = {}
StatCard.__index = StatCard

function StatCard.new(parent, opts, ctx)
	opts = Util.Options(opts, {
		Title = "Metric",
		Value = 0,
		Prefix = "",
		Suffix = "",
		Decimals = nil,
		Delta = nil,
		Icon = "activity",
		Color = "Accent",
		Points = nil,
		Glow = true,
		Animate = true,
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("StatCard", parent, opts, ctx)
	local cardParent = (typeof(self.Frame) == "Instance") and self.Frame or parent
	local cardFrame, cardStroke, cardUI = unwrapCard(cardParent, opts)

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = cardFrame
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
	end

	cardFrame.ClipsDescendants = true

	local colorSpec = resolveColorSpec(opts.Color, "Accent")
	local currentRaw = opts.Value
	local currentPoints = type(opts.Points) == "table" and Util.Copy(opts.Points) or {}
	local cancelRoll = nil

	self.Value = currentRaw
	self.Stroke = cardStroke

	-- Subtle top-left radial Glow tint (clipped cleanly to card corner)
	local glowImg = Assets.Get("Glow")
	if opts.Glow ~= false and glowImg then
		local glow = Create.New("ImageLabel", {
			Name = "Glow",
			Size = UDim2.fromOffset(160, 84),
			Position = UDim2.fromOffset(-44, -38),
			Corner = opts.Corner or 10,
			Image = glowImg,
			ScaleType = Enum.ScaleType.Stretch,
			ZIndex = 1,
			Theme = { ImageTransparency = "GlowTransparency" },
			Parent = cardFrame,
		})
		bindColorProp(glow, "ImageColor3", colorSpec)
	end

	local content = Create.New("Frame", {
		Name = "Content",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = 12,
		ZIndex = 2,
		Parent = cardFrame,
	})
	Create.List(content, { Gap = 10 })

	-- Top Row: IconBadge + Title (left) | Delta Pill (right)
	local topRow = Create.New("Frame", {
		Name = "TopRow",
		Size = UDim2.new(1, 0, 0, 30),
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		ZIndex = 2,
		Parent = content,
	})

	local badgeObj = Base.IconBadge(topRow, opts.Icon or "activity", type(colorSpec) == "string" and colorSpec or "Accent")
	local badgeFrame = (typeof(badgeObj) == "Instance") and badgeObj or badgeObj.Frame
	if badgeFrame then
		badgeFrame.Position = UDim2.new(0, 0, 0.5, 0)
		badgeFrame.AnchorPoint = Vector2.new(0, 0.5)
		badgeFrame.ZIndex = 3
	end

	local deltaPill = Create.New("Frame", {
		Name = "DeltaPill",
		Size = UDim2.fromOffset(0, 22),
		AutomaticSize = Enum.AutomaticSize.X,
		Position = UDim2.new(1, 0, 0.5, 0),
		AnchorPoint = Vector2.new(1, 0.5),
		Corner = 999,
		Padding = { 0, 8, 0, 7 },
		Visible = false,
		ZIndex = 3,
		Theme = {
			BackgroundColor3 = "Success",
			BackgroundTransparency = function() return 0.85 end,
		},
		Parent = topRow,
	})
	Create.List(deltaPill, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 4,
		VAlign = Enum.VerticalAlignment.Center,
	})
	local deltaStroke = Create.Stroke(deltaPill, {
		Theme = { Color = "Success", Transparency = function() return 0.65 end },
	})
	local deltaIcon = Icons.Create("trending-up", {
		Size = UDim2.fromOffset(13, 13),
		Color = "Success",
		LayoutOrder = 1,
		ZIndex = 4,
		Parent = deltaPill,
	})
	local deltaText = Create.Text({
		Size = UDim2.fromOffset(0, 22),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = "",
		TextSize = 11,
		Font = "SemiBold",
		Color = "Success",
		LayoutOrder = 2,
		ZIndex = 4,
		Parent = deltaPill,
	})

	local titleLabel = Create.Text({
		Name = "Title",
		Size = UDim2.new(1, -110, 1, 0),
		Position = UDim2.fromOffset(38, 0),
		Text = tostring(opts.Title or "Metric"),
		TextSize = 12,
		Font = "Medium",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Color = "SubText",
		ZIndex = 3,
		Parent = topRow,
	})

	self.TitleLabel = titleLabel

	-- Bottom Row: Large Value (left) + Inline Sparkline (right)
	local bottomRow = Create.New("Frame", {
		Name = "BottomRow",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		ZIndex = 2,
		Parent = content,
	})

	local sparkContainer = Create.New("Frame", {
		Name = "Sparkline",
		Size = UDim2.fromOffset(82, 28),
		Position = UDim2.new(1, 0, 0.5, 0),
		AnchorPoint = Vector2.new(1, 0.5),
		BackgroundTransparency = 1,
		Visible = #currentPoints >= 2,
		ZIndex = 3,
		Parent = bottomRow,
	})

	local valueLabel = Create.Text({
		Name = "Value",
		Size = UDim2.new(1, #currentPoints >= 2 and -90 or 0, 0, 28),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = formatNumericValue(currentRaw, opts.Prefix, opts.Suffix, opts.Decimals),
		TextSize = 22,
		Font = "Bold",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Color = "Text",
		ZIndex = 3,
		Parent = bottomRow,
	})

	if self.BindUI then
		self:BindUI({
			Frame = cardFrame,
			Stroke = cardStroke,
			TitleLabel = titleLabel,
			LockOverlay = cardUI and cardUI.LockOverlay or nil,
			SetDisabled = cardUI and cardUI.SetDisabled or nil,
			Lock = cardUI and cardUI.Lock or nil,
			Unlock = cardUI and cardUI.Unlock or nil,
			Flash = cardUI and cardUI.Flash or nil,
		})
	end

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, cardFrame, opts.Tooltip)
	end

	local function updateDelta(delta)
		if delta == nil or delta == "" then
			deltaPill.Visible = false
			return
		end
		deltaPill.Visible = true
		local num = tonumber(delta)
		local isNeg = false
		local formatted
		if num then
			isNeg = num < 0
			local sign = num > 0 and "+" or ""
			local dec = (math.floor(num) == num) and 0 or 1
			formatted = string.format("%s%." .. dec .. "f%%", sign, num)
		else
			formatted = tostring(delta)
			isNeg = string.sub(formatted, 1, 1) == "-"
		end
		local key = isNeg and "Error" or "Success"
		Theme.Bind(deltaPill, {
			BackgroundColor3 = key,
			BackgroundTransparency = function() return 0.85 end,
		})
		Theme.Bind(deltaStroke, {
			Color = key,
			Transparency = function() return 0.65 end,
		})
		Theme.Bind(deltaText, { TextColor3 = key })
		deltaText.Text = formatted
		if deltaIcon then
			Icons.Set(deltaIcon, isNeg and "trending-down" or "trending-up")
			Icons.SetColor(deltaIcon, key)
		end
	end

	local function redrawSpark()
		local hasSpark = #currentPoints >= 2
		sparkContainer.Visible = hasSpark
		valueLabel.Size = UDim2.new(1, hasSpark and -90 or 0, 0, 28)
		if hasSpark then
			renderLineSegments(sparkContainer, currentPoints, colorSpec, 2, 3)
		end
	end

	self.Maid:Give(sparkContainer:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		if #currentPoints >= 2 then
			renderLineSegments(sparkContainer, currentPoints, colorSpec, 2, 3)
		end
	end))

	function self:SetValue(v, delta)
		if cancelRoll then
			cancelRoll()
			cancelRoll = nil
		end
		local prevNum = tonumber(currentRaw)
		local nextNum = tonumber(v)
		currentRaw = v
		self.Value = v

		if opts.Animate ~= false and prevNum and nextNum and prevNum ~= nextNum then
			cancelRoll = Tween.Number(prevNum, nextNum, Tween.Normal, function(stepVal)
				valueLabel.Text = formatNumericValue(stepVal, opts.Prefix, opts.Suffix, opts.Decimals)
			end, function()
				cancelRoll = nil
			end)
		else
			valueLabel.Text = formatNumericValue(v, opts.Prefix, opts.Suffix, opts.Decimals)
		end

		if delta ~= nil then
			updateDelta(delta)
		end
	end

	function self:SetPoints(pts)
		currentPoints = type(pts) == "table" and Util.Copy(pts) or {}
		redrawSpark()
	end

	function self:Get()
		return currentRaw
	end

	local baseSetTitle = self.SetTitle
	function self:SetTitle(text)
		titleLabel.Text = tostring(text or "")
		if baseSetTitle then
			pcall(baseSetTitle, self, text)
		end
	end

	self.Maid:Give(function()
		if cancelRoll then
			cancelRoll()
			cancelRoll = nil
		end
	end)

	updateDelta(opts.Delta)
	task.defer(redrawSpark)
	return self
end

-- ─── 2. Chart ────────────────────────────────────────────────────────────────

local Chart = {}
Chart.__index = Chart

function Chart.new(parent, opts, ctx)
	opts = Util.Options(opts, {
		Title = "Chart",
		Subtitle = nil,
		Value = nil,
		Mode = "Line",
		Points = {},
		Labels = {},
		Height = 110,
		Color = "Accent",
		ShowGrid = true,
		Prefix = "",
		Suffix = "",
		Decimals = nil,
		MaxPoints = nil,
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("Chart", parent, opts, ctx)
	local cardParent = (typeof(self.Frame) == "Instance") and self.Frame or parent
	local cardFrame, cardStroke, cardUI = unwrapCard(cardParent, opts)

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = cardFrame
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
	end

	local mode = (type(opts.Mode) == "string" and string.lower(opts.Mode) == "bar") and "Bar" or "Line"
	local colorSpec = resolveColorSpec(opts.Color, "Accent")
	local chartHeight = math.max(56, tonumber(opts.Height) or 110)
	local showGrid = opts.ShowGrid ~= false
	local points = type(opts.Points) == "table" and Util.Copy(opts.Points) or {}
	local labels = type(opts.Labels) == "table" and Util.Copy(opts.Labels) or {}
	local maxPoints = opts.MaxPoints or math.max(#points, 24)
	local staticHeadline = opts.Value

	self.Value = points
	self.Stroke = cardStroke

	local content = Create.New("Frame", {
		Name = "Content",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = 12,
		Parent = cardFrame,
	})
	Create.List(content, { Gap = 8 })

	-- Header row
	local header = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = content,
	})

	local headerLeft = Create.New("Frame", {
		Size = UDim2.new(1, -104, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = header,
	})
	Create.List(headerLeft, { Gap = 2 })

	local titleLabel = Create.Text({
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = tostring(opts.Title or "Chart"),
		TextSize = 13,
		Font = "SemiBold",
		TextWrapped = true,
		Color = "Text",
		LayoutOrder = 1,
		Parent = headerLeft,
	})

	local subtitleLabel
	if opts.Subtitle and opts.Subtitle ~= "" then
		subtitleLabel = Create.Text({
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = tostring(opts.Subtitle),
			TextSize = 11,
			TextWrapped = true,
			Color = "SubText",
			LayoutOrder = 2,
			Parent = headerLeft,
		})
	end

	local headerRight = Create.New("Frame", {
		Size = UDim2.fromOffset(100, 32),
		Position = UDim2.new(1, 0, 0, 0),
		AnchorPoint = Vector2.new(1, 0),
		BackgroundTransparency = 1,
		Parent = header,
	})
	Create.List(headerRight, { Gap = 1, HAlign = Enum.HorizontalAlignment.Right })

	local readoutLabel = Create.Text({
		Size = UDim2.new(1, 0, 0, 18),
		Text = "",
		TextSize = 14,
		Font = "Bold",
		TextXAlignment = Enum.TextXAlignment.Right,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Color = "Text",
		LayoutOrder = 1,
		Parent = headerRight,
	})

	local hoverTagLabel = Create.Text({
		Size = UDim2.new(1, 0, 0, 13),
		Text = "Latest",
		TextSize = 10,
		Font = "Medium",
		TextXAlignment = Enum.TextXAlignment.Right,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Color = "SubText",
		TextTransparency = 0.25,
		Visible = true,
		LayoutOrder = 2,
		Parent = headerRight,
	})

	-- Main plot area
	local plotArea = Create.New("Frame", {
		Name = "PlotArea",
		Size = UDim2.new(1, 0, 0, chartHeight),
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		Parent = content,
	})

	local yAxis = Create.New("Frame", {
		Name = "YAxis",
		Size = UDim2.new(0, 38, 1, 0),
		BackgroundTransparency = 1,
		Parent = plotArea,
	})

	local function makeYLabel(yScale, yAnchor)
		return Create.Text({
			Size = UDim2.new(1, 0, 0, 14),
			Position = UDim2.fromScale(0, yScale),
			AnchorPoint = Vector2.new(0, yAnchor),
			Text = "",
			TextSize = 10,
			TextXAlignment = Enum.TextXAlignment.Right,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Color = "Muted",
			Parent = yAxis,
		})
	end

	local yMaxLabel = makeYLabel(0, 0)
	local yMidLabel = makeYLabel(0.5, 0.5)
	local yMinLabel = makeYLabel(1, 1)

	local plotCanvas = Create.New("Frame", {
		Name = "PlotCanvas",
		Size = UDim2.new(1, -46, 1, -6),
		Position = UDim2.fromOffset(44, 3),
		BackgroundTransparency = 1,
		Parent = plotArea,
	})

	local gridLayer = Create.New("Frame", {
		Name = "GridLayer",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 1,
		Parent = plotCanvas,
	})
	if showGrid then
		for _, yScale in ipairs({ 0, 0.5, 1 }) do
			Create.New("Frame", {
				Size = UDim2.new(1, 0, 0, 1),
				Position = UDim2.fromScale(0, yScale),
				AnchorPoint = Vector2.new(0, yScale == 1 and 1 or (yScale == 0.5 and 0.5 or 0)),
				ZIndex = 1,
				Theme = {
					BackgroundColor3 = "Divider",
					BackgroundTransparency = "DividerTransparency",
				},
				Parent = gridLayer,
			})
		end
	end

	local geomLayer = Create.New("Frame", {
		Name = "Geometry",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = plotCanvas,
	})

	local crosshair = Create.New("Frame", {
		Name = "Crosshair",
		Size = UDim2.new(0, 1, 1, 0),
		Visible = false,
		ZIndex = 5,
		Theme = {
			BackgroundColor3 = "Stroke",
			BackgroundTransparency = function() return 0.55 end,
		},
		Parent = plotCanvas,
	})

	local dotHalo = Create.New("Frame", {
		Name = "HoverHalo",
		Size = UDim2.fromOffset(14, 14),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Corner = 999,
		Visible = false,
		ZIndex = 6,
		BackgroundTransparency = 0.72,
		Parent = plotCanvas,
	})
	bindColorProp(dotHalo, "BackgroundColor3", colorSpec)

	local dotCenter = Create.New("Frame", {
		Name = "HoverDot",
		Size = UDim2.fromOffset(7, 7),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Corner = 999,
		ZIndex = 7,
		Theme = { BackgroundColor3 = "Knob" },
		Parent = dotHalo,
	})
	local dotStroke = Create.Stroke(dotCenter, { Thickness = 2, Transparency = 0 })
	bindColorProp(dotStroke, "Color", colorSpec)

	local hitOverlay = Create.New("Frame", {
		Name = "HitOverlay",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 8,
		Parent = plotCanvas,
	})

	local xAxisWrap = Create.New("Frame", {
		Name = "XAxisWrap",
		Size = UDim2.new(1, 0, 0, 14),
		BackgroundTransparency = 1,
		Visible = #labels > 0,
		LayoutOrder = 3,
		Parent = content,
	})

	local xAxisRow = Create.New("Frame", {
		Name = "XAxis",
		Size = UDim2.new(1, -46, 1, 0),
		Position = UDim2.fromOffset(44, 0),
		BackgroundTransparency = 1,
		Visible = #labels > 0,
		Parent = xAxisWrap,
	})

	if self.BindUI then
		self:BindUI({
			Frame = cardFrame,
			Stroke = cardStroke,
			TitleLabel = titleLabel,
			DescLabel = subtitleLabel,
			LockOverlay = cardUI and cardUI.LockOverlay or nil,
			SetDisabled = cardUI and cardUI.SetDisabled or nil,
			Lock = cardUI and cardUI.Lock or nil,
			Unlock = cardUI and cardUI.Unlock or nil,
			Flash = cardUI and cardUI.Flash or nil,
		})
	end

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, cardFrame, opts.Tooltip)
	end

	local plottedCoords = {}
	local barFrames = {}
	local hoveredIndex = nil

	local function refreshDefaultReadout()
		if hoveredIndex ~= nil then
			return
		end
		if staticHeadline ~= nil then
			readoutLabel.Text = type(staticHeadline) == "number"
				and formatNumericValue(staticHeadline, opts.Prefix, opts.Suffix, opts.Decimals)
				or tostring(staticHeadline)
		elseif #points > 0 then
			readoutLabel.Text = formatNumericValue(tonumber(points[#points]) or points[#points], opts.Prefix, opts.Suffix, opts.Decimals)
		else
			readoutLabel.Text = "—"
		end
		hoverTagLabel.Visible = true
		hoverTagLabel.TextTransparency = 0.25
		if #labels > 0 then
			hoverTagLabel.Text = tostring(labels[#labels])
		elseif staticHeadline ~= nil then
			hoverTagLabel.Text = "Current"
		else
			hoverTagLabel.Text = "Latest"
		end
	end

	local function rebuildXLabels()
		for _, child in ipairs(xAxisRow:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		if #labels == 0 then
			xAxisWrap.Visible = false
			xAxisRow.Visible = false
			return
		end
		xAxisWrap.Visible = true
		xAxisRow.Visible = true
		local canvasW = plotCanvas.AbsoluteSize.X
		local maxByWidth = canvasW > 40 and math.max(2, math.floor(canvasW / 54) + 1) or 6
		local maxShown = math.min(6, maxByWidth)
		local step = math.max(1, math.ceil(#labels / math.max(1, maxShown - 1)))
		local minEndGap = math.max(step, math.ceil(#labels * 0.18))
		local lastPlacedScale = -1
		local labelWidth = 48
		local minNormDist = canvasW > 0 and ((labelWidth + 6) / canvasW) or 0.2
		for i = 1, #labels do
			local scaleX = #labels == 1 and 0.5 or (i - 1) / (#labels - 1)
			local isEnd = (i == 1 or i == #labels)
			local isCadence = ((i - 1) % step == 0 and (i - 1) >= minEndGap and (#labels - i) >= minEndGap)
			if isEnd or (isCadence and (scaleX - lastPlacedScale) >= minNormDist and (1 - scaleX) >= minNormDist) then
				local align = Enum.TextXAlignment.Center
				local anchorX = 0.5
				if i == 1 and #labels > 1 then
					align = Enum.TextXAlignment.Left
					anchorX = 0
				elseif i == #labels and #labels > 1 then
					align = Enum.TextXAlignment.Right
					anchorX = 1
				end
				Create.Text({
					Size = UDim2.fromOffset(labelWidth, 14),
					Position = UDim2.fromScale(scaleX, 0),
					AnchorPoint = Vector2.new(anchorX, 0),
					Text = tostring(labels[i]),
					TextSize = 10,
					TextXAlignment = align,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Color = "Muted",
					Parent = xAxisRow,
				})
				lastPlacedScale = scaleX
			end
		end
	end

	local function redrawChart()
		for _, child in ipairs(geomLayer:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		table.clear(plottedCoords)
		table.clear(barFrames)

		local count = #points
		if count == 0 then
			yMaxLabel.Text = ""
			yMidLabel.Text = ""
			yMinLabel.Text = ""
			refreshDefaultReadout()
			return
		end

		local minV, maxV = computeMinMax(points)
		local span = maxV - minV
		local midV = (minV + maxV) * 0.5

		yMaxLabel.Text = formatNumericValue(maxV, opts.Prefix, "", opts.Decimals)
		yMidLabel.Text = formatNumericValue(midV, opts.Prefix, "", opts.Decimals)
		yMinLabel.Text = formatNumericValue(minV, opts.Prefix, "", opts.Decimals)

		local w = plotCanvas.AbsoluteSize.X
		local h = plotCanvas.AbsoluteSize.Y
		if w <= 4 or h <= 4 then
			refreshDefaultReadout()
			return
		end

		if mode == "Bar" then
			local gap = count > 24 and 2 or 4
			local barW = math.max(2, (w - (count - 1) * gap) / count)
			for i = 1, count do
				local val = tonumber(points[i]) or minV
				local norm = Util.Clamp((val - minV) / span, 0, 1)
				local barH = math.max(4, norm * (h - 4))
				local xLeft = (i - 1) * (barW + gap)
				local yTop = h - barH

				local bar = Create.New("Frame", {
					Name = "Bar_" .. i,
					Size = UDim2.fromOffset(barW, barH),
					Position = UDim2.fromOffset(xLeft, yTop),
					Corner = math.min(8, math.max(4, math.floor(barW * 0.45))),
					ZIndex = 2,
					Parent = geomLayer,
				})
				bindColorProp(bar, "BackgroundColor3", colorSpec)

				local grad = Instance.new("UIGradient")
				grad.Rotation = 90
				grad.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.08),
					NumberSequenceKeypoint.new(1, 0.58),
				})
				grad.Parent = bar

				plottedCoords[i] = Vector2.new(xLeft + barW * 0.5, yTop)
				barFrames[i] = bar
			end
		else
			if count == 1 then
				local py = h * 0.5
				plottedCoords[1] = Vector2.new(w * 0.5, py)
			else
				local padTop = 4
				local usableH = math.max(1, h - padTop * 2)
				for i = 1, count do
					local val = tonumber(points[i]) or minV
					local norm = Util.Clamp((val - minV) / span, 0, 1)
					local px = ((i - 1) / (count - 1)) * w
					local py = padTop + (1 - norm) * usableH
					plottedCoords[i] = Vector2.new(px, py)
				end

				-- Smooth area gradient strips beneath the piecewise line
				local stripCount = math.min(44, math.max(count * 2, 24))
				local stripW = (w / stripCount) + 1
				for s = 0, stripCount - 1 do
					local sampleX = ((s + 0.5) / stripCount) * w
					local t = (sampleX / w) * (count - 1) + 1
					local idx0 = Util.Clamp(math.floor(t), 1, count - 1)
					local frac = t - idx0
					local yVal = Util.Lerp(plottedCoords[idx0].Y, plottedCoords[idx0 + 1].Y, frac)
					local stripH = math.max(1, h - yVal)

					local strip = Create.New("Frame", {
						Name = "Area_" .. s,
						Position = UDim2.fromOffset(s * (w / stripCount), yVal),
						Size = UDim2.fromOffset(stripW, stripH),
						ZIndex = 2,
						Parent = geomLayer,
					})
					bindColorProp(strip, "BackgroundColor3", colorSpec)

					local areaGrad = Instance.new("UIGradient")
					areaGrad.Rotation = 90
					areaGrad.Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 0.72),
						NumberSequenceKeypoint.new(1, 0.99),
					})
					areaGrad.Parent = strip
				end

				-- Crisp rotated line segments + vertex dots
				for i = 1, count - 1 do
					local p1, p2 = plottedCoords[i], plottedCoords[i + 1]
					local dx, dy = p2.X - p1.X, p2.Y - p1.Y
					local len = math.sqrt(dx * dx + dy * dy)
					local seg = Create.New("Frame", {
						Name = "Line_" .. i,
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.fromOffset((p1.X + p2.X) * 0.5, (p1.Y + p2.Y) * 0.5),
						Size = UDim2.fromOffset(len + 1.5, 2),
						Rotation = math.deg(math.atan2(dy, dx)),
						Corner = 999,
						ZIndex = 3,
						Parent = geomLayer,
					})
					bindColorProp(seg, "BackgroundColor3", colorSpec)
				end

				for i = 1, count do
					local p = plottedCoords[i]
					local vertex = Create.New("Frame", {
						Name = "Pt_" .. i,
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.fromOffset(p.X, p.Y),
						Size = UDim2.fromOffset(4, 4),
						Corner = 999,
						ZIndex = 4,
						Parent = geomLayer,
					})
					bindColorProp(vertex, "BackgroundColor3", colorSpec)
				end
			end
		end

		refreshDefaultReadout()
	end

	local function updateHoverAt(pos)
		local count = #points
		if count == 0 or #plottedCoords == 0 then
			return
		end
		local cPos, cSize = plotCanvas.AbsolutePosition, plotCanvas.AbsoluteSize
		if cSize.X <= 0 then
			return
		end
		local relX = Util.Clamp((pos.X - cPos.X) / cSize.X, 0, 1)
		local idx
		if mode == "Bar" then
			idx = Util.Clamp(math.floor(relX * count) + 1, 1, count)
		else
			idx = count == 1 and 1 or Util.Clamp(math.floor(relX * (count - 1) + 0.5) + 1, 1, count)
		end

		hoveredIndex = idx
		local coord = plottedCoords[idx]
		if coord then
			crosshair.Visible = true
			crosshair.Position = UDim2.fromOffset(coord.X, 0)
			dotHalo.Visible = true
			dotHalo.Position = UDim2.fromOffset(coord.X, coord.Y)
		end

		local val = tonumber(points[idx]) or points[idx]
		readoutLabel.Text = formatNumericValue(val, opts.Prefix, opts.Suffix, opts.Decimals)
		hoverTagLabel.TextTransparency = 0
		local lbl = labels[idx]
		if lbl and lbl ~= "" then
			hoverTagLabel.Text = tostring(lbl)
			hoverTagLabel.Visible = true
		else
			hoverTagLabel.Text = "#" .. idx
			hoverTagLabel.Visible = true
		end
	end

	local function clearHover()
		hoveredIndex = nil
		crosshair.Visible = false
		dotHalo.Visible = false
		refreshDefaultReadout()
	end

	self.Maid:Give(hitOverlay.MouseMoved:Connect(function()
		if Transition.IsOverlayBlocking(hitOverlay) then
			clearHover()
			return
		end
		updateHoverAt(Util.MousePosition())
	end))
	self.Maid:Give(hitOverlay.MouseLeave:Connect(clearHover))
	self.Maid:Give(hitOverlay.InputBegan:Connect(function(input)
		if Transition.IsOverlayBlocking(hitOverlay) then
			return
		end
		if Util.IsPointer(input) then
			updateHoverAt(Util.MousePosition())
		end
	end))
	self.Maid:Give(hitOverlay.InputChanged:Connect(function(input)
		if Transition.IsOverlayBlocking(hitOverlay) then
			clearHover()
			return
		end
		if Util.IsMove(input) then
			updateHoverAt(Util.MousePosition())
		end
	end))

	self.Maid:Give(plotCanvas:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		rebuildXLabels()
		redrawChart()
	end))

	function self:SetPoints(pts, newLabels)
		points = type(pts) == "table" and Util.Copy(pts) or {}
		if newLabels ~= nil then
			labels = type(newLabels) == "table" and Util.Copy(newLabels) or {}
			rebuildXLabels()
		end
		self.Value = points
		redrawChart()
	end

	function self:Push(val, label)
		table.insert(points, val)
		if label ~= nil then
			table.insert(labels, label)
		end
		if type(maxPoints) == "number" and maxPoints > 0 then
			while #points > maxPoints do
				table.remove(points, 1)
				if #labels > 0 then
					table.remove(labels, 1)
				end
			end
		end
		self.Value = points
		if label ~= nil then
			rebuildXLabels()
		end
		redrawChart()
	end

	function self:Get()
		return Util.Copy(points)
	end

	local baseSetTitle = self.SetTitle
	function self:SetTitle(text)
		titleLabel.Text = tostring(text or "")
		if baseSetTitle then
			pcall(baseSetTitle, self, text)
		end
	end

	rebuildXLabels()
	task.defer(redrawChart)
	return self
end

-- ─── 3. ProgressBar ──────────────────────────────────────────────────────────

local ProgressBar = {}
ProgressBar.__index = ProgressBar

function ProgressBar.new(parent, opts, ctx)
	opts = Util.Options(opts, {
		Title = "Progress",
		Value = 0,
		Max = 100,
		Suffix = "%",
		Badge = nil,
		SecondaryLabel = nil,
		Gradient = true,
		Height = 8,
		Color = "Accent",
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("ProgressBar", parent, opts, ctx)
	local cardParent = (typeof(self.Frame) == "Instance") and self.Frame or parent
	local cardFrame, cardStroke, cardUI = unwrapCard(cardParent, opts)

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = cardFrame
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
	end

	local currentVal = tonumber(opts.Value) or 0
	local currentMax = math.max(1e-6, tonumber(opts.Max) or 100)
	local useGradient = opts.Gradient ~= false
	local colorSpec = resolveColorSpec(opts.Color, "Accent")
	local barHeight = math.max(4, tonumber(opts.Height) or 8)

	self.Value = currentVal
	self.Stroke = cardStroke

	local content = Create.New("Frame", {
		Name = "Content",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = 12,
		Parent = cardFrame,
	})
	Create.List(content, { Gap = 8 })

	local topRow = Create.New("Frame", {
		Name = "TopRow",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = content,
	})

	local rightRow = Create.New("Frame", {
		Name = "Right",
		Size = UDim2.fromOffset(0, 22),
		AutomaticSize = Enum.AutomaticSize.X,
		Position = UDim2.new(1, 0, 0.5, 0),
		AnchorPoint = Vector2.new(1, 0.5),
		BackgroundTransparency = 1,
		Parent = topRow,
	})
	Create.List(rightRow, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 6,
		HAlign = Enum.HorizontalAlignment.Right,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local valueText = Create.Text({
		Name = "ValueText",
		Size = UDim2.fromOffset(0, 20),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = "",
		TextSize = 12,
		Font = "SemiBold",
		Color = "SubText",
		LayoutOrder = 1,
		Parent = rightRow,
	})

	local badgeObj
	local badgeFrame
	local badgeLabel
	if opts.Badge and opts.Badge ~= "" then
		badgeObj = Base.Badge(rightRow, tostring(opts.Badge), "Accent")
		if typeof(badgeObj) == "Instance" then
			badgeFrame = badgeObj
			badgeLabel = badgeObj:IsA("TextLabel") and badgeObj or badgeObj:FindFirstChildOfClass("TextLabel")
		else
			badgeFrame = badgeObj.Frame
			badgeLabel = badgeObj.Label
		end
		if badgeFrame then
			badgeFrame.LayoutOrder = 2
		end
	end

	local titleLabel = Create.Text({
		Name = "Title",
		Size = UDim2.new(1, -148, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Text = tostring(opts.Title or "Progress"),
		TextSize = 13,
		Font = "Medium",
		TextWrapped = true,
		Color = "Text",
		Parent = topRow,
	})

	local track = Create.New("Frame", {
		Name = "Track",
		Size = UDim2.new(1, 0, 0, barHeight),
		Corner = UDim.new(1, 0),
		ClipsDescendants = true,
		LayoutOrder = 2,
		Theme = { BackgroundColor3 = "Field" },
		Parent = content,
	})
	Create.Stroke(track, { Theme = { Color = "Stroke", Transparency = "StrokeTransparency" } })

	local ratio = Util.Clamp(currentVal / currentMax, 0, 1)
	local fill = Create.New("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(ratio, 1),
		Corner = UDim.new(1, 0),
		Parent = track,
	})

	if useGradient then
		fill.BackgroundColor3 = Color3.new(1, 1, 1)
		local grad = Instance.new("UIGradient")
		grad.Color = Theme.AccentSequence()
		grad.Parent = fill
		local conn = Theme.Changed:Connect(function(t)
			grad.Color = Theme.AccentSequence(t)
		end)
		self.Maid:Give(conn)
	else
		bindColorProp(fill, "BackgroundColor3", colorSpec)
	end

	local secondaryLabel
	if opts.SecondaryLabel and opts.SecondaryLabel ~= "" then
		secondaryLabel = Create.Text({
			Name = "Secondary",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Text = tostring(opts.SecondaryLabel),
			TextSize = 11,
			TextWrapped = true,
			Color = "Muted",
			LayoutOrder = 3,
			Parent = content,
		})
	end
	self.DescLabel = secondaryLabel
	self.SecondaryLabel = secondaryLabel

	if self.BindUI then
		self:BindUI({
			Frame = cardFrame,
			Stroke = cardStroke,
			TitleLabel = titleLabel,
			DescLabel = secondaryLabel,
			LockOverlay = cardUI and cardUI.LockOverlay or nil,
			SetDisabled = cardUI and cardUI.SetDisabled or nil,
			Lock = cardUI and cardUI.Lock or nil,
			Unlock = cardUI and cardUI.Unlock or nil,
			Flash = cardUI and cardUI.Flash or nil,
		})
	end

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, cardFrame, opts.Tooltip)
	end

	local function refreshText()
		local displayNum
		if opts.Suffix == "%" and currentMax ~= 100 then
			displayNum = Util.Clamp((currentVal / currentMax) * 100, 0, 100)
		else
			displayNum = currentVal
		end
		valueText.Text = formatNumericValue(displayNum, "", opts.Suffix or "%")
	end

	function self:Set(val, maxVal, badgeText, silent)
		if maxVal ~= nil then
			currentMax = math.max(1e-6, tonumber(maxVal) or currentMax)
		end
		currentVal = Util.Clamp(tonumber(val) or 0, 0, currentMax)
		self.Value = currentVal

		local targetRatio = Util.Clamp(currentVal / currentMax, 0, 1)
		Tween.Play(fill, { Size = UDim2.fromScale(targetRatio, 1) }, Tween.Normal)
		refreshText()

		if badgeText ~= nil and badgeObj then
			if type(badgeObj) == "table" and badgeObj.SetText then
				pcall(badgeObj.SetText, badgeObj, tostring(badgeText))
			end
			if badgeLabel then
				badgeLabel.Text = tostring(badgeText)
			end
		end

		if not silent then
			self.Changed:Fire(currentVal, currentMax)
		end
	end

	function self:Get()
		return currentVal
	end

	local baseSetTitle = self.SetTitle
	function self:SetTitle(text)
		titleLabel.Text = tostring(text or "")
		if baseSetTitle then
			pcall(baseSetTitle, self, text)
		end
	end

	refreshText()
	return self
end

-- ─── 4. Table ────────────────────────────────────────────────────────────────

local Table = {}
Table.__index = Table

function Table.new(parent, opts, ctx)
	opts = Util.Options(opts, {
		Title = nil,
		Columns = {},
		Rows = {},
		Selectable = false,
		MaxHeight = 240,
		Searchable = false,
		OnRowClick = nil,
		Action = nil,
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("Table", parent, opts, ctx)
	local cardParent = (typeof(self.Frame) == "Instance") and self.Frame or parent
	local cardFrame, cardStroke, cardUI = unwrapCard(cardParent, opts)

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = cardFrame
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
	end

	local columns = type(opts.Columns) == "table" and opts.Columns or {}
	local rowsData = type(opts.Rows) == "table" and opts.Rows or {}
	local selectable = opts.Selectable == true
	local searchable = opts.Searchable == true
	local maxHeight = math.max(80, tonumber(opts.MaxHeight) or 240)
	local actionDef = type(opts.Action) == "table" and opts.Action or nil
	local selectedSet = {} -- [rowTable] = true
	local searchQuery = ""

	self.Value = rowsData
	self.Stroke = cardStroke

	local content = Create.New("Frame", {
		Name = "Content",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = 12,
		Parent = cardFrame,
	})
	Create.List(content, { Gap = 8 })

	local titleLabel
	local searchInput
	if (opts.Title and opts.Title ~= "") or searchable then
		local topHeader = Create.New("Frame", {
			Name = "Header",
			Size = UDim2.new(1, 0, 0, 28),
			BackgroundTransparency = 1,
			LayoutOrder = 1,
			Parent = content,
		})

		titleLabel = Create.Text({
			Name = "Title",
			Size = UDim2.new(1, searchable and -154 or 0, 1, 0),
			Text = tostring(opts.Title or ""),
			TextSize = 13,
			Font = "SemiBold",
			TextTruncate = Enum.TextTruncate.AtEnd,
			Color = "Text",
			Parent = topHeader,
		})

		if searchable then
			local searchWrap = Create.New("Frame", {
				Name = "SearchWrap",
				Size = UDim2.fromOffset(146, 26),
				Position = UDim2.new(1, 0, 0.5, 0),
				AnchorPoint = Vector2.new(1, 0.5),
				Corner = 7,
				Padding = { 0, 8, 0, 8 },
				Theme = { BackgroundColor3 = "Field" },
				Parent = topHeader,
			})
			local searchStroke = Create.Stroke(searchWrap, {
				Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
			})
			Icons.Create("search", {
				Size = UDim2.fromOffset(14, 14),
				Position = UDim2.new(0, 0, 0.5, 0),
				AnchorPoint = Vector2.new(0, 0.5),
				Color = "Muted",
				Parent = searchWrap,
			})
			searchInput = Create.Text({
				Class = "TextBox",
				Size = UDim2.new(1, -18, 1, 0),
				Position = UDim2.fromOffset(18, 0),
				Text = "",
				PlaceholderText = "Filter...",
				TextSize = 11,
				Theme = {
					TextColor3 = "Text",
					PlaceholderColor3 = "Muted",
				},
				Parent = searchWrap,
			})
			searchInput.Focused:Connect(function()
				Theme.Bind(searchStroke, { Color = "Accent", Transparency = function() return 0.35 end })
			end)
			searchInput.FocusLost:Connect(function()
				Theme.Bind(searchStroke, { Color = "Stroke", Transparency = "StrokeTransparency" })
			end)
		end
	end

	-- Exact shared column geometry calculator
	local checkReserve = selectable and 28 or 0
	local actionReserve = actionDef and 78 or 0
	local colGap = 6

	local fixedPx = 0
	local fixedScale = 0
	local autoCount = 0
	for _, col in ipairs(columns) do
		if type(col.Width) == "number" then
			if col.Width > 0 and col.Width <= 1 then
				fixedScale += col.Width
			else
				fixedPx += col.Width
			end
		elseif typeof(col.Width) == "UDim" then
			fixedScale += col.Width.Scale
			fixedPx += col.Width.Offset
		else
			autoCount += 1
		end
	end
	local totalGap = math.max(0, #columns - 1) * colGap

	local function colUDim(col)
		if type(col.Width) == "number" then
			if col.Width > 0 and col.Width <= 1 then
				return UDim.new(col.Width, -math.ceil(totalGap * col.Width + 0.5))
			end
			return UDim.new(0, col.Width)
		elseif typeof(col.Width) == "UDim" then
			return col.Width
		end
		local s = math.max(0.05, (1 - fixedScale) / math.max(1, autoCount))
		local o = -math.ceil((fixedPx + totalGap) / math.max(1, autoCount))
		return UDim.new(s, o)
	end

	-- Column Header Bar
	local colHeader = Create.New("Frame", {
		Name = "ColumnsHeader",
		Size = UDim2.new(1, 0, 0, 28),
		LayoutOrder = 2,
		Corner = 7,
		Padding = { 0, 8, 0, 8 },
		Theme = {
			BackgroundColor3 = "Tile",
			BackgroundTransparency = "TileTransparency",
		},
		Parent = content,
	})

	local headerColsWrap = Create.New("Frame", {
		Size = UDim2.new(1, -(checkReserve + actionReserve), 1, 0),
		Position = UDim2.fromOffset(checkReserve, 0),
		BackgroundTransparency = 1,
		Parent = colHeader,
	})
	Create.List(headerColsWrap, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = colGap,
		VAlign = Enum.VerticalAlignment.Center,
	})

	for idx, col in ipairs(columns) do
		local w = colUDim(col)
		Create.Text({
			Name = "ColH_" .. idx,
			Size = UDim2.new(w.Scale, w.Offset, 1, 0),
			LayoutOrder = idx,
			Text = tostring(col.Title or col.Key or ""),
			TextSize = 11,
			Font = "SemiBold",
			TextXAlignment = resolveAlign(col.Align),
			TextTruncate = Enum.TextTruncate.AtEnd,
			Color = "SubText",
			Parent = headerColsWrap,
		})
	end

	local scroll = Create.New("ScrollingFrame", {
		Name = "RowsScroll",
		Size = UDim2.new(1, 0, 0, 40),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(0, 0, 0, 0),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 3,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		LayoutOrder = 3,
		Theme = { ScrollBarImageColor3 = "Muted" },
		Parent = content,
	})
	Create.Padding(scroll, { 3, 6, 3, 3 })
	local scrollLayout = Create.List(scroll, { Gap = 4 })

	local emptyLabel = Create.Text({
		Name = "Empty",
		Size = UDim2.new(1, 0, 0, 34),
		Text = "No matching rows",
		TextSize = 12,
		TextXAlignment = Enum.TextXAlignment.Center,
		Color = "Muted",
		Visible = false,
		Parent = scroll,
	})

	if self.BindUI then
		self:BindUI({
			Frame = cardFrame,
			Stroke = cardStroke,
			TitleLabel = titleLabel,
			LockOverlay = cardUI and cardUI.LockOverlay or nil,
			SetDisabled = cardUI and cardUI.SetDisabled or nil,
			Lock = cardUI and cardUI.Lock or nil,
			Unlock = cardUI and cardUI.Unlock or nil,
			Flash = cardUI and cardUI.Flash or nil,
		})
	end

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, cardFrame, opts.Tooltip)
	end

	local rowObjects = {}

	local function syncScrollHeight()
		local contentY = scrollLayout.AbsoluteContentSize.Y
		if contentY > 0 then
			scroll.Size = UDim2.new(1, 0, 0, math.min(contentY, maxHeight))
		else
			local visibleCount = 0
			for _, obj in ipairs(rowObjects) do
				if obj.Button.Visible then
					visibleCount += 1
				end
			end
			local est = visibleCount == 0 and 34 or (visibleCount * 36 + math.max(0, visibleCount - 1) * 4)
			scroll.Size = UDim2.new(1, 0, 0, math.min(est, maxHeight))
		end
	end

	scrollLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncScrollHeight)

	local function rowMatchesQuery(row)
		if searchQuery == "" then
			return true
		end
		for _, col in ipairs(columns) do
			local raw = row[col.Key]
			local txt = type(raw) == "table" and (raw.Text or raw.Value or "") or raw
			if txt ~= nil and Util.Matches(tostring(txt), searchQuery) then
				return true
			end
		end
		return false
	end

	local function applyFilter()
		local any = false
		for _, obj in ipairs(rowObjects) do
			local ok = rowMatchesQuery(obj.Row)
			obj.Button.Visible = ok
			if ok then
				any = true
			end
		end
		emptyLabel.Visible = not any
		task.defer(syncScrollHeight)
	end

	local function updateRowCheck(obj)
		local active = selectedSet[obj.Row] == true
		if obj.CheckBox then
			Theme.Bind(obj.CheckBox, {
				BackgroundColor3 = active and "Accent" or "Field",
			})
			Theme.Bind(obj.CheckStroke, {
				Color = active and "Accent" or "Stroke",
				Transparency = active and function() return 1 end or function() return 0.38 end,
			})
			if obj.CheckIcon then
				obj.CheckIcon.Visible = active
			end
		end
		Theme.Bind(obj.Button, {
			BackgroundColor3 = active and "Accent" or "TileHover",
			BackgroundTransparency = active and function() return 0.88 end or function() return obj.Hovered and 0.48 or 1 end,
		})
	end

	local function rebuildRows()
		for _, obj in ipairs(rowObjects) do
			obj.Button:Destroy()
		end
		table.clear(rowObjects)

		for rowIdx, row in ipairs(rowsData) do
			local rowBtn = Create.New("TextButton", {
				Name = "Row_" .. rowIdx,
				Size = UDim2.new(1, 0, 0, 36),
				LayoutOrder = rowIdx,
				Corner = 7,
				Padding = { 0, 4, 0, 8 },
				BackgroundTransparency = 1,
				Theme = { BackgroundColor3 = "TileHover" },
				Parent = scroll,
			})

			local checkBox, checkStroke, checkIcon
			if selectable then
				checkBox = Create.New("Frame", {
					Name = "Checkbox",
					Size = UDim2.fromOffset(18, 18),
					Position = UDim2.new(0, 0, 0.5, 0),
					AnchorPoint = Vector2.new(0, 0.5),
					Corner = 5,
					Theme = { BackgroundColor3 = "Field" },
					Parent = rowBtn,
				})
				checkStroke = Create.Stroke(checkBox, {
					Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
					Thickness = 1.25,
				})
				checkIcon = Icons.Create("check", {
					Size = UDim2.fromOffset(13, 13),
					Position = UDim2.fromScale(0.5, 0.5),
					AnchorPoint = Vector2.new(0.5, 0.5),
					Color = "AccentText",
					Parent = checkBox,
				})
				checkIcon.Visible = false
			end

			local cellsWrap = Create.New("Frame", {
				Size = UDim2.new(1, -(checkReserve + actionReserve), 1, 0),
				Position = UDim2.fromOffset(checkReserve, 0),
				BackgroundTransparency = 1,
				Parent = rowBtn,
			})
			Create.List(cellsWrap, {
				Direction = Enum.FillDirection.Horizontal,
				Gap = colGap,
				VAlign = Enum.VerticalAlignment.Center,
			})

			for colIdx, col in ipairs(columns) do
				local w = colUDim(col)
				local cellFrame = Create.New("Frame", {
					Name = "Cell_" .. colIdx,
					Size = UDim2.new(w.Scale, w.Offset, 1, 0),
					LayoutOrder = colIdx,
					BackgroundTransparency = 1,
					Parent = cellsWrap,
				})

				local raw = row[col.Key]
				local cellText, cellColor, cellIcon, isBadge
				if type(raw) == "table" then
					cellText = tostring(raw.Text ~= nil and raw.Text or (raw.Value or ""))
					cellColor = raw.Color
					cellIcon = raw.Icon
					isBadge = raw.Badge == true
				else
					cellText = raw ~= nil and tostring(raw) or ""
				end
				if not cellIcon and colIdx == 1 then
					cellIcon = row.Icon
				end
				if not cellColor and col.Color then
					if type(col.Color) == "function" then
						cellColor = col.Color(raw, row)
					else
						cellColor = col.Color
					end
				end

				local resolvedColor = cellColor and resolveColorSpec(cellColor, "Text") or "Text"
				local align = resolveAlign(col.Align)

				if isBadge then
					local pill = Create.New("Frame", {
						Size = UDim2.fromOffset(0, 22),
						AutomaticSize = Enum.AutomaticSize.X,
						Position = UDim2.new(
							align == Enum.TextXAlignment.Right and 1 or (align == Enum.TextXAlignment.Center and 0.5 or 0),
							0,
							0.5,
							0
						),
						AnchorPoint = Vector2.new(
							align == Enum.TextXAlignment.Right and 1 or (align == Enum.TextXAlignment.Center and 0.5 or 0),
							0.5
						),
						Corner = 999,
						Padding = { 0, 8, 0, 8 },
						Theme = { BackgroundTransparency = function() return 0.85 end },
						Parent = cellFrame,
					})
					bindColorProp(pill, "BackgroundColor3", resolvedColor)
					local pillLbl = Create.Text({
						Size = UDim2.fromOffset(0, 22),
						AutomaticSize = Enum.AutomaticSize.X,
						Text = cellText,
						TextSize = 11,
						Font = "SemiBold",
						TextTruncate = Enum.TextTruncate.AtEnd,
						Parent = pill,
					})
					bindColorProp(pillLbl, "TextColor3", resolvedColor)
				else
					local iconOffset = 0
					if cellIcon then
						iconOffset = 20
						Icons.Create(cellIcon, {
							Size = UDim2.fromOffset(14, 14),
							Position = UDim2.new(0, 0, 0.5, 0),
							AnchorPoint = Vector2.new(0, 0.5),
							Color = resolvedColor == "Text" and "SubText" or resolvedColor,
							Parent = cellFrame,
						})
					end
					local cellLbl = Create.Text({
						Size = UDim2.new(1, -iconOffset, 1, 0),
						Position = UDim2.fromOffset(iconOffset, 0),
						Text = cellText,
						TextSize = 12,
						Font = colIdx == 1 and "Medium" or "Regular",
						TextXAlignment = align,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Parent = cellFrame,
					})
					bindColorProp(cellLbl, "TextColor3", resolvedColor)
				end
			end

			if actionDef then
				local actBtn = Create.New("TextButton", {
					Name = "ActionBtn",
					Size = UDim2.fromOffset(72, 24),
					Position = UDim2.new(1, 0, 0.5, 0),
					AnchorPoint = Vector2.new(1, 0.5),
					Text = "",
					AutoButtonColor = false,
					BackgroundTransparency = 0,
					Corner = 6,
					Padding = { 0, 6, 0, 6 },
					Theme = { BackgroundColor3 = "Field" },
					Parent = rowBtn,
				})
				local actStroke = Create.Stroke(actBtn, {
					Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
				})
				Transition.Hover(actBtn, actBtn, "Field", "FieldHover", actStroke)
				local actInner = Create.New("Frame", {
					Size = UDim2.fromScale(1, 1),
					BackgroundTransparency = 1,
					Parent = actBtn,
				})
				Create.List(actInner, {
					Direction = Enum.FillDirection.Horizontal,
					Gap = 4,
					HAlign = Enum.HorizontalAlignment.Center,
					VAlign = Enum.VerticalAlignment.Center,
				})
				if actionDef.Icon then
					Icons.Create(actionDef.Icon, {
						Size = UDim2.fromOffset(13, 13),
						Color = "Accent",
						LayoutOrder = 1,
						Parent = actInner,
					})
				end
				if actionDef.Title and actionDef.Title ~= "" then
					Create.Text({
						Size = UDim2.fromOffset(0, 24),
						AutomaticSize = Enum.AutomaticSize.X,
						Text = tostring(actionDef.Title),
						TextSize = 11,
						Font = "SemiBold",
						TextXAlignment = Enum.TextXAlignment.Center,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Color = "Accent",
						LayoutOrder = 2,
						Parent = actInner,
					})
				end
				actBtn.Activated:Connect(function()
					Transition.Ripple(actBtn, nil, "Accent")
					if actionDef.Callback then
						Util.Spawn(actionDef.Callback, row, rowIdx)
					end
				end)
			end

			local obj = {
				Row = row,
				Index = rowIdx,
				Button = rowBtn,
				CheckBox = checkBox,
				CheckStroke = checkStroke,
				CheckIcon = checkIcon,
				Hovered = false,
			}

			rowBtn.MouseEnter:Connect(function()
				obj.Hovered = true
				updateRowCheck(obj)
			end)
			rowBtn.MouseLeave:Connect(function()
				obj.Hovered = false
				updateRowCheck(obj)
			end)
			rowBtn.Activated:Connect(function()
				if selectable then
					selectedSet[row] = not selectedSet[row] or nil
					updateRowCheck(obj)
					self.Changed:Fire(self:GetSelected())
				end
				if opts.OnRowClick then
					Util.Spawn(opts.OnRowClick, row, rowIdx)
				end
			end)

			updateRowCheck(obj)
			table.insert(rowObjects, obj)
		end

		applyFilter()
	end

	if searchInput then
		searchInput:GetPropertyChangedSignal("Text"):Connect(function()
			searchQuery = Util.Trim(searchInput.Text)
			applyFilter()
		end)
	end

	function self:SetRows(newRows)
		rowsData = type(newRows) == "table" and newRows or {}
		self.Value = rowsData
		table.clear(selectedSet)
		rebuildRows()
	end

	function self:GetSelected()
		local rows, indices = {}, {}
		for _, obj in ipairs(rowObjects) do
			if selectedSet[obj.Row] then
				table.insert(rows, obj.Row)
				table.insert(indices, obj.Index)
			end
		end
		return rows, indices
	end

	local baseSetTitle = self.SetTitle
	function self:SetTitle(text)
		if titleLabel then
			titleLabel.Text = tostring(text or "")
		end
		if baseSetTitle then
			pcall(baseSetTitle, self, text)
		end
	end

	rebuildRows()
	return self
end

-- ─── 5. CardGrid ─────────────────────────────────────────────────────────────

local CardGrid = {}
CardGrid.__index = CardGrid

function CardGrid.new(parent, opts, ctx)
	opts = Util.Options(opts, {
		Cards = {},
		Default = nil,
		Callback = nil,
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("CardGrid", parent, opts, ctx)

	local container = Create.New("Frame", {
		Name = "CardGrid",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = parent,
	})

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = container
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
		container.Parent = self.Frame
	end

	if self.BindUI then
		self:BindUI({ Frame = container })
	end

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, container, opts.Tooltip)
	end

	local gridLayout = Instance.new("UIGridLayout")
	gridLayout.SortOrder = Enum.SortOrder.LayoutOrder
	gridLayout.CellPadding = UDim2.fromOffset(8, 8)
	gridLayout.Parent = container

	local cards = type(opts.Cards) == "table" and Util.Copy(opts.Cards) or {}
	local activeId = opts.Default
	if activeId == nil and opts.Default ~= false then
		for _, c in ipairs(cards) do
			if c.Active then
				activeId = c.Id
				break
			end
		end
		if activeId == nil and cards[1] then
			activeId = cards[1].Id
		end
	elseif activeId == false then
		activeId = nil
	end
	self.Value = activeId

	local cardEntries = {} -- [id] = { CardData, Button, Stroke, Gradient, TitleLabel, IconObj, MetricRows }

	local function getCardHeight()
		local maxMetrics = 0
		for _, c in ipairs(cards) do
			local count = type(c.Metrics) == "table" and #c.Metrics or 0
			if count > maxMetrics then
				maxMetrics = count
			end
		end
		return math.max(76, 44 + maxMetrics * 20 + 12)
	end

	local function updateGridCellSize()
		local count = math.max(1, #cards)
		local width = container.AbsoluteSize.X
		local cols
		if count == 1 then
			cols = 1
		elseif width <= 0 or width >= 520 then
			cols = math.min(count, 4)
		elseif width >= 220 then
			cols = math.min(count, 2)
		else
			cols = 1
		end
		local gapTotal = (cols - 1) * 8
		local offsetAdjust = -math.ceil(gapTotal / cols)
		gridLayout.CellSize = UDim2.new(1 / cols, offsetAdjust, 0, getCardHeight())
	end

	local function styleCardEntry(entry, isActive)
		if isActive then
			entry.Button.BackgroundColor3 = Color3.new(1, 1, 1)
			Theme.Unbind(entry.Button, "BackgroundColor3")
			Theme.Unbind(entry.Button, "BackgroundTransparency")
			entry.Button.BackgroundTransparency = 0.14
			entry.Button:SetAttribute("_BaliRestBg", 0.14)
			entry.Button:SetAttribute("_BaliCascadeBg", 0.14)
			entry.Gradient.Enabled = true
			entry.Gradient.Color = Theme.AccentSequence()
			Theme.Bind(entry.Stroke, {
				Color = "Accent",
				Transparency = function() return 0.22 end,
			})
			entry.Stroke:SetAttribute("_BaliRestStr", 0.22)
			entry.Stroke:SetAttribute("_BaliCascadeStroke", 0.22)
			Theme.Bind(entry.TitleLabel, { TextColor3 = "AccentText" })
			if entry.IconObj then
				Icons.SetColor(entry.IconObj, "AccentText")
			end
			for _, m in ipairs(entry.MetricRows) do
				Theme.Bind(m.Label, { TextColor3 = "AccentText" })
				m.Label.TextTransparency = 0.08
				Theme.Bind(m.Value, { TextColor3 = "AccentText" })
			end
		else
			entry.Gradient.Enabled = false
			Theme.Bind(entry.Button, {
				BackgroundColor3 = entry.Hovered and "TileHover" or "Tile",
				BackgroundTransparency = "TileTransparency",
			})
			entry.Button:SetAttribute("_BaliRestBg", Theme.Current.TileTransparency)
			entry.Button:SetAttribute("_BaliCascadeBg", Theme.Current.TileTransparency)
			Theme.Bind(entry.Stroke, {
				Color = "Stroke",
				Transparency = "StrokeTransparency",
			})
			entry.Stroke:SetAttribute("_BaliRestStr", Theme.Current.StrokeTransparency)
			entry.Stroke:SetAttribute("_BaliCascadeStroke", Theme.Current.StrokeTransparency)
			Theme.Bind(entry.TitleLabel, { TextColor3 = "Text" })
			if entry.IconObj then
				Icons.SetColor(entry.IconObj, "Accent")
			end
			for _, m in ipairs(entry.MetricRows) do
				Theme.Bind(m.Label, { TextColor3 = "SubText" })
				m.Label.TextTransparency = 0
				Theme.Bind(m.Value, { TextColor3 = "Text" })
			end
		end
	end

	local function refreshAllCards()
		for id, entry in pairs(cardEntries) do
			styleCardEntry(entry, id == activeId)
		end
	end

	local themeConn = Theme.Changed:Connect(refreshAllCards)
	self.Maid:Give(themeConn)

	local function buildCard(index, card)
		local btn = Create.New("TextButton", {
			Name = "Card_" .. tostring(card.Id or index),
			LayoutOrder = index,
			Corner = 11,
			Padding = 11,
			Theme = {
				BackgroundColor3 = "Tile",
				BackgroundTransparency = "TileTransparency",
			},
			Parent = container,
		})
		local stroke = Create.GlassStroke(btn, 0.05)

		local grad = Instance.new("UIGradient")
		grad.Rotation = 135
		grad.Color = Theme.AccentSequence()
		grad.Enabled = false
		grad.Parent = btn

		local inner = Create.New("Frame", {
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Parent = btn,
		})
		Create.List(inner, { Gap = 8 })

		local top = Create.New("Frame", {
			Name = "Header",
			Size = UDim2.new(1, 0, 0, 22),
			BackgroundTransparency = 1,
			LayoutOrder = 1,
			Parent = inner,
		})

		local iconOffset = 0
		local iconObj
		if card.Icon then
			iconOffset = 20
			iconObj = Icons.Create(card.Icon, {
				Size = UDim2.fromOffset(15, 15),
				Position = UDim2.new(0, 0, 0.5, 0),
				AnchorPoint = Vector2.new(0, 0.5),
				Color = "Accent",
				Parent = top,
			})
		end

		local titleLbl = Create.Text({
			Size = UDim2.new(1, -iconOffset, 1, 0),
			Position = UDim2.fromOffset(iconOffset, 0),
			Text = tostring(card.Title or card.Id or ""),
			TextSize = 13,
			Font = "SemiBold",
			TextTruncate = Enum.TextTruncate.AtEnd,
			Color = "Text",
			Parent = top,
		})

		local metricsBox = Create.New("Frame", {
			Name = "Metrics",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 2,
			Parent = inner,
		})
		Create.List(metricsBox, { Gap = 4 })

		local metricRows = {}
		if type(card.Metrics) == "table" then
			for mIdx, metric in ipairs(card.Metrics) do
				local mRow = Create.New("Frame", {
					Size = UDim2.new(1, 0, 0, 16),
					BackgroundTransparency = 1,
					LayoutOrder = mIdx,
					Parent = metricsBox,
				})
				local lbl = Create.Text({
					Size = UDim2.new(0.55, 0, 1, 0),
					Text = tostring(metric.Label or ""),
					TextSize = 11,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Color = "SubText",
					Parent = mRow,
				})
				local val = Create.Text({
					Size = UDim2.new(0.45, 0, 1, 0),
					Position = UDim2.fromScale(1, 0),
					AnchorPoint = Vector2.new(1, 0),
					Text = tostring(metric.Value or ""),
					TextSize = 11,
					Font = "SemiBold",
					TextXAlignment = Enum.TextXAlignment.Right,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Color = "Text",
					Parent = mRow,
				})
				table.insert(metricRows, { Label = lbl, Value = val })
			end
		end

		local entry = {
			Card = card,
			Button = btn,
			Stroke = stroke,
			Gradient = grad,
			TitleLabel = titleLbl,
			IconObj = iconObj,
			MetricRows = metricRows,
			Hovered = false,
		}

		btn.MouseEnter:Connect(function()
			entry.Hovered = true
			if activeId ~= card.Id then
				Theme.Bind(btn, { BackgroundColor3 = "TileHover" })
			end
		end)
		btn.MouseLeave:Connect(function()
			entry.Hovered = false
			if activeId ~= card.Id then
				Theme.Bind(btn, { BackgroundColor3 = "Tile" })
			end
		end)
		btn.Activated:Connect(function()
			Transition.Ripple(btn, nil, "Accent")
			self:SetActive(card.Id, false)
		end)

		cardEntries[card.Id] = entry
		styleCardEntry(entry, card.Id == activeId)
	end

	local function rebuildAll()
		for _, entry in pairs(cardEntries) do
			entry.Button:Destroy()
		end
		table.clear(cardEntries)
		for index, card in ipairs(cards) do
			buildCard(index, card)
		end
		updateGridCellSize()
	end

	container:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateGridCellSize)

	function self:SetActive(id, silent)
		activeId = id
		self.Value = activeId
		refreshAllCards()
		if not silent then
			local entry = cardEntries[id]
			local cardData = entry and entry.Card or nil
			if opts.Callback then
				Util.Spawn(opts.Callback, id, cardData)
			end
			self.Changed:Fire(id, cardData)
		end
	end
	self.Set = self.SetActive

	function self:UpdateCard(id, data)
		if type(data) ~= "table" then
			return
		end
		for i, card in ipairs(cards) do
			if card.Id == id then
				for k, v in pairs(data) do
					card[k] = v
				end
				if data.Active == true then
					activeId = card.Id
					self.Value = activeId
				end
				local old = cardEntries[id]
				if old then
					old.Button:Destroy()
					cardEntries[id] = nil
				end
				buildCard(i, card)
				updateGridCellSize()
				refreshAllCards()
				return
			end
		end
	end

	function self:Get()
		return activeId
	end

	rebuildAll()
	return self
end

Analytics.StatCard = StatCard
Analytics.Chart = Chart
Analytics.ProgressBar = ProgressBar
Analytics.Table = Table
Analytics.CardGrid = CardGrid

return Analytics
end

__modules["Elements/Base"] = function()
--[[
	Bali UI · Elements/Base
	Shared element lifecycle, Tile rows, Glass cards, badges, lock overlays, and flash feedback.
]]

local Util = require("Core/Util")
local Signal = require("Core/Signal")
local Maid = require("Core/Maid")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Tooltip = require("Systems/Tooltip")

local Base = {}

local uiByFrame = setmetatable({}, { __mode = "k" })
local tooltipBound = setmetatable({}, { __mode = "k" })

local function bindColor(instance, prop, colorKey, fallback)
	local key = colorKey or fallback or "Accent"
	if typeof(key) == "Color3" then
		Theme.Unbind(instance, prop)
		instance[prop] = key
	else
		Theme.Bind(instance, { [prop] = key })
	end
end

local function resolveColor(colorKey, fallback)
	local key = colorKey or fallback or "Accent"
	if typeof(key) == "Color3" then
		return key
	end
	return Theme.Resolve(key) or Theme.Current.Accent
end

local function bindTooltipOnce(frame, tooltipOpt, maid)
	if not frame or not tooltipOpt or tooltipBound[frame] then
		return
	end
	tooltipBound[frame] = true
	local ok, cleanup = pcall(Tooltip.Bind, frame, tooltipOpt)
	if ok and cleanup ~= nil and maid then
		maid:Give(cleanup)
	end
end

function Base.FlashFrame(frame, stroke, surfaceKey)
	if not frame or not frame.Parent then
		return
	end
	local token = (frame:GetAttribute("_BaliFlashToken") or 0) + 1
	frame:SetAttribute("_BaliFlashToken", token)

	local targetStroke = stroke or frame:FindFirstChildOfClass("UIStroke")
	local accent = Theme.Current.Accent
	local baseBgKey = surfaceKey or frame:GetAttribute("_BaliSurfaceKey") or "Tile"
	local baseBg = Theme.Resolve(baseBgKey) or Theme.Current.Tile
	local hoverBg = Theme.Current.TileHover or baseBg
	local hasBg = frame.BackgroundTransparency < 0.95

	if targetStroke then
		Tween.Play(targetStroke, {
			Color = accent,
			Transparency = 0.05,
			Thickness = 1.8,
		}, Tween.Fast, Enum.EasingStyle.Quad)
	end
	if hasBg and typeof(baseBg) == "Color3" then
		Tween.Play(frame, {
			BackgroundColor3 = Util.LerpColor(hoverBg, accent, 0.16),
		}, Tween.Fast, Enum.EasingStyle.Quad)
	end

	task.delay(Tween.Reduced and 0.05 or 0.36, function()
		if not frame.Parent or frame:GetAttribute("_BaliFlashToken") ~= token then
			return
		end
		if targetStroke and targetStroke.Parent then
			local restTrans = math.max(Theme.Current.StrokeTransparency - 0.02, 0)
			Tween.Play(targetStroke, {
				Color = Theme.Current.Stroke,
				Transparency = restTrans,
				Thickness = 1,
			}, Tween.Smooth, Enum.EasingStyle.Quad)
		end
		if hasBg and frame.Parent then
			local restoreColor = Theme.Resolve(baseBgKey)
			if typeof(restoreColor) == "Color3" then
				Tween.Play(frame, {
					BackgroundColor3 = restoreColor,
				}, Tween.Smooth, Enum.EasingStyle.Quad)
			end
		end
	end)
end

local function createLockOverlay(frame, cornerRadius)
	local overlay = Create.New("Frame", {
		Name = "LockOverlay",
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromScale(0, 0),
		BackgroundTransparency = 0.22,
		Theme = { BackgroundColor3 = "Background" },
		Corner = cornerRadius or 10,
		Active = true,
		Visible = false,
		ZIndex = 30,
		Parent = frame,
	})

	local pill = Create.New("Frame", {
		Name = "LockPill",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -12, 0.5, 0),
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		Theme = { BackgroundColor3 = "Elevated" },
		BackgroundTransparency = 0,
		Corner = UDim.new(1, 0),
		Padding = { 5, 11, 5, 11 },
		Stroke = {
			Theme = { Color = "Stroke" },
			Transparency = 0.65,
			Thickness = 1,
		},
		ZIndex = 31,
		Parent = overlay,
	})

	Create.List(pill, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 6,
	})

	Icons.Create("lock", {
		Size = UDim2.fromOffset(13, 13),
		Color = "SubText",
		LayoutOrder = 1,
		ZIndex = 32,
		Parent = pill,
	})

	local textLabel = Create.Text({
		Name = "LockText",
		Text = "Locked",
		Font = "Medium",
		TextSize = 11,
		Color = "SubText",
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		LayoutOrder = 2,
		ZIndex = 32,
		Parent = pill,
	})

	return overlay, textLabel
end

function Base.Badge(parent, text, colorKey)
	colorKey = colorKey or "Accent"

	local frame = Create.New("Frame", {
		Name = "Badge",
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		BackgroundTransparency = 0.84,
		Corner = UDim.new(1, 0),
		Padding = { 3, 8, 3, 8 },
		Parent = parent,
	})
	bindColor(frame, "BackgroundColor3", colorKey, "Accent")

	local stroke = Create.Stroke(frame, {
		Transparency = 0.72,
		Thickness = 1,
	})
	bindColor(stroke, "Color", colorKey, "Accent")

	local label = Create.Text({
		Name = "Label",
		Text = tostring(text or ""),
		Font = "SemiBold",
		TextSize = 11,
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextYAlignment = Enum.TextYAlignment.Center,
		Parent = frame,
	})
	bindColor(label, "TextColor3", colorKey, "Accent")

	local badge = {
		Frame = frame,
		Label = label,
		Stroke = stroke,
	}

	function badge:SetText(newText)
		label.Text = tostring(newText or "")
	end

	function badge:SetColor(newColorKey)
		newColorKey = newColorKey or "Accent"
		bindColor(frame, "BackgroundColor3", newColorKey, "Accent")
		bindColor(stroke, "Color", newColorKey, "Accent")
		bindColor(label, "TextColor3", newColorKey, "Accent")
	end

	return badge
end

function Base.IconBadge(parent, icon, colorKey)
	colorKey = colorKey or "Accent"

	local frame = Create.New("Frame", {
		Name = "IconBadge",
		Size = UDim2.fromOffset(30, 30),
		BackgroundTransparency = 0.84,
		Corner = 8,
		Parent = parent,
	})
	bindColor(frame, "BackgroundColor3", colorKey, "Accent")

	local stroke = Create.Stroke(frame, {
		Transparency = 0.74,
		Thickness = 1,
	})
	bindColor(stroke, "Color", colorKey, "Accent")

	local iconObj = Icons.Create(icon or "sparkles", {
		Size = UDim2.fromOffset(16, 16),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Color = colorKey,
		Parent = frame,
	})

	local badge = {
		Frame = frame,
		Icon = iconObj,
		Stroke = stroke,
	}

	function badge:SetIcon(newIcon)
		if iconObj then
			Icons.Set(iconObj, newIcon)
		end
	end

	function badge:SetColor(newColorKey)
		newColorKey = newColorKey or "Accent"
		bindColor(frame, "BackgroundColor3", newColorKey, "Accent")
		bindColor(stroke, "Color", newColorKey, "Accent")
		if iconObj then
			Icons.SetColor(iconObj, newColorKey)
		end
	end

	return badge
end

function Base.Card(parent, options)
	options = options or {}
	local surfaceKey = options.SurfaceKey or "Tile"
	local transKey = options.SurfaceTransparency or "TileTransparency"
	local cornerRadius = options.Corner or 10

	local frame = Create.New("Frame", {
		Name = options.Name or "Card",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = {
			BackgroundColor3 = surfaceKey,
			BackgroundTransparency = transKey,
		},
		Corner = cornerRadius,
		Parent = parent,
	})
	frame:SetAttribute("_BaliSurfaceKey", surfaceKey)

	if options.MinHeight and options.MinHeight > 0 then
		local constraint = Instance.new("UISizeConstraint")
		constraint.MinSize = Vector2.new(0, options.MinHeight)
		constraint.Parent = frame
	end

	local stroke = Create.GlassStroke(frame, options.StrokeStrength or 0.02)

	if options.Padding ~= nil then
		Create.Padding(frame, options.Padding)
	end

	local lockOverlay, lockLabel = createLockOverlay(frame, cornerRadius)
	if options.Padding ~= nil then
		-- Compensate LockOverlay bounds when caller places UIPadding directly on Card.Frame
		local p = options.Padding
		local top, right, bottom, left
		if type(p) == "number" then
			top, right, bottom, left = p, p, p, p
		else
			top = p[1] or 0
			right = p[2] or top
			bottom = p[3] or top
			left = p[4] or right
		end
		lockOverlay.Position = UDim2.fromOffset(-left, -top)
		lockOverlay.Size = UDim2.new(1, left + right, 1, top + bottom)
	end

	local card = {
		Frame = frame,
		Stroke = stroke,
		LockOverlay = lockOverlay,
		_disabled = false,
		_locked = false,
	}

	function card:SetDisabled(disabled)
		card._disabled = (disabled == true)
		for _, desc in ipairs(frame:GetDescendants()) do
			if desc ~= lockOverlay and not desc:IsDescendantOf(lockOverlay) then
				if desc:IsA("TextLabel") or desc:IsA("TextButton") or desc:IsA("TextBox") then
					if desc:GetAttribute("_BaliOrigTextTrans") == nil then
						desc:SetAttribute("_BaliOrigTextTrans", desc.TextTransparency)
					end
					local baseT = desc:GetAttribute("_BaliOrigTextTrans") or 0
					desc.TextTransparency = card._disabled and math.min(baseT + 0.45, 0.78) or baseT
				elseif desc:IsA("ImageLabel") or desc:IsA("ImageButton") then
					if desc:GetAttribute("_BaliOrigImgTrans") == nil then
						desc:SetAttribute("_BaliOrigImgTrans", desc.ImageTransparency)
					end
					local baseT = desc:GetAttribute("_BaliOrigImgTrans") or 0
					desc.ImageTransparency = card._disabled and math.min(baseT + 0.45, 0.78) or baseT
				end
			end
		end
	end

	function card:Lock(reason)
		card._locked = true
		lockLabel.Text = (reason and reason ~= "") and tostring(reason) or "Locked"
		lockOverlay.Visible = true
	end

	function card:Unlock()
		card._locked = false
		lockOverlay.Visible = false
	end

	function card:Flash()
		Base.FlashFrame(frame, stroke, surfaceKey)
	end

	uiByFrame[frame] = card
	return card
end

function Base.Row(parent, options, rightWidth)
	options = options or {}
	rightWidth = rightWidth or 0
	local surfaceKey = options.SurfaceKey or "Tile"
	local transKey = options.SurfaceTransparency or "TileTransparency"
	local cornerRadius = options.Corner or 10

	local frame = Create.New("Frame", {
		Name = options.Name or "Row",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = {
			BackgroundColor3 = surfaceKey,
			BackgroundTransparency = transKey,
		},
		Corner = cornerRadius,
		Parent = parent,
	})
	frame:SetAttribute("_BaliSurfaceKey", surfaceKey)

	local constraint = Instance.new("UISizeConstraint")
	constraint.MinSize = Vector2.new(0, options.MinHeight or 42)
	constraint.Parent = frame

	local stroke = Create.GlassStroke(frame, options.StrokeStrength or 0.02)

	local body = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = options.Padding or { 10, 12, 10, 12 },
		ZIndex = 2,
		Parent = frame,
	})

	local bodyList = Create.List(body, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		HAlign = Enum.HorizontalAlignment.Left,
		Gap = 10,
	})

	local left = Create.New("Frame", {
		Name = "Left",
		LayoutOrder = 1,
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, rightWidth > 0 and -(rightWidth + 10) or 0, 0, 0),
		Parent = body,
	})

	Create.List(left, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		HAlign = Enum.HorizontalAlignment.Left,
		Gap = 10,
	})

	local iconObj = nil
	local iconBadge = nil
	local iconWidth = 0
	if options.Icon and options.Icon ~= "" and options.Icon ~= false then
		if options.IconBadge == false then
			iconObj = Icons.Create(options.Icon, {
				Size = UDim2.fromOffset(18, 18),
				Color = options.IconColor or "SubText",
				LayoutOrder = 1,
				Parent = left,
			})
			iconWidth = 18
		else
			iconBadge = Base.IconBadge(left, options.Icon, options.IconColor or "Accent")
			iconBadge.Frame.LayoutOrder = 1
			iconObj = iconBadge.Icon
			iconWidth = 30
		end
	end

	local textCol = Create.New("Frame", {
		Name = "TextColumn",
		LayoutOrder = 2,
		BackgroundTransparency = 1,
		AutomaticSize = Enum.AutomaticSize.Y,
		Size = UDim2.new(1, iconWidth > 0 and -(iconWidth + 10) or 0, 0, 0),
		Parent = left,
	})

	Create.List(textCol, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 2,
	})

	local titleText = tostring(options.Title or options.Name or "")
	local descText = tostring(options.Description or options.Desc or "")

	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = options.TitleFont or "Medium",
		TextSize = options.TitleSize or 13,
		Color = options.TitleColor or "Text",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Visible = titleText ~= "",
		Parent = textCol,
	})

	local descLabel = Create.Text({
		Name = "Description",
		Text = descText,
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = descText ~= "",
		Parent = textCol,
	})

	local right = Create.New("Frame", {
		Name = "Right",
		LayoutOrder = 2,
		BackgroundTransparency = 1,
		Size = UDim2.new(0, rightWidth, 0, 0),
		AutomaticSize = rightWidth > 0 and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
		Visible = rightWidth > 0,
		Parent = body,
	})

	local reservedRight = rightWidth
	local rightConstraint = nil
	if reservedRight <= 0 then
		rightConstraint = Instance.new("UISizeConstraint")
		rightConstraint.MaxSize = Vector2.new(9999, 9999)
		rightConstraint.Parent = right
	end

	local function updateLeftInset()
		local hasVisibleChild = false
		if reservedRight <= 0 then
			for _, child in ipairs(right:GetChildren()) do
				if child:IsA("GuiObject") and child.Visible then
					hasVisibleChild = true
					break
				end
			end
		end
		right.Visible = (reservedRight > 0) or hasVisibleChild
		local bodyW = math.floor(body.AbsoluteSize.X)
		local rightLayout = reservedRight <= 0 and right:FindFirstChildOfClass("UIListLayout") or nil
		local naturalRightW = rightLayout and math.ceil(rightLayout.AbsoluteContentSize.X) or math.ceil(right.AbsoluteSize.X)
		local measureW = reservedRight > 0 and reservedRight or naturalRightW
		local actualW = right.Visible and math.max(reservedRight, measureW) or 0
		local availLeft = bodyW - 24 - actualW - 10 - (iconWidth > 0 and (iconWidth + 10) or 0)
		local stackRight = (options.StackRight == true) or (options.StackRight ~= false and actualW >= 132 and bodyW > 0 and availLeft < 104)
		local compactStack = stackRight and (options._compactStack == true or (reservedRight > 0 and reservedRight < 130) or (reservedRight <= 0 and actualW > 0 and actualW < 130))

		if rightConstraint then
			if stackRight or bodyW <= 180 or titleText == "" then
				rightConstraint.MaxSize = Vector2.new(9999, 9999)
			else
				local maxR = (options.StackRight == false) and math.max(120, bodyW - 110) or math.max(96, bodyW - math.max(132, math.floor(bodyW * 0.44)) - 10)
				rightConstraint.MaxSize = Vector2.new(maxR, 9999)
			end
		end

		if stackRight and right.Visible then
			bodyList.FillDirection = Enum.FillDirection.Vertical
			bodyList.VerticalAlignment = Enum.VerticalAlignment.Top
			bodyList.HorizontalAlignment = compactStack and Enum.HorizontalAlignment.Right or Enum.HorizontalAlignment.Left
			bodyList.Padding = UDim.new(0, 8)
			left.Size = UDim2.new(1, 0, 0, 0)
			if compactStack then
				right.Size = UDim2.new(0, math.max(reservedRight, actualW), 0, 0)
			else
				right.Size = UDim2.new(1, 0, 0, 0)
			end
			right.AutomaticSize = Enum.AutomaticSize.Y
		else
			bodyList.FillDirection = Enum.FillDirection.Horizontal
			bodyList.VerticalAlignment = Enum.VerticalAlignment.Center
			bodyList.HorizontalAlignment = Enum.HorizontalAlignment.Left
			bodyList.Padding = UDim.new(0, 10)
			right.Size = UDim2.new(0, reservedRight, 0, 0)
			right.AutomaticSize = reservedRight > 0 and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY
			left.Size = UDim2.new(1, actualW > 0 and -(actualW + 10) or 0, 0, 0)
		end
	end

	right.ChildAdded:Connect(function(child)
		if child:IsA("GuiObject") then
			child:GetPropertyChangedSignal("Visible"):Connect(updateLeftInset)
		end
		task.defer(updateLeftInset)
	end)

	right:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateLeftInset)
	body:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateLeftInset)

	local lockOverlay, lockLabel = createLockOverlay(frame, cornerRadius)

	local row = {
		Frame = frame,
		Body = body,
		Left = left,
		Right = right,
		TextColumn = textCol,
		TitleLabel = titleLabel,
		DescLabel = descLabel,
		IconObj = iconObj,
		IconBadge = iconBadge,
		Stroke = stroke,
		LockOverlay = lockOverlay,
		_disabled = false,
		_locked = false,
	}

	function row:SetRightWidth(w)
		reservedRight = math.max(w or 0, 0)
		right.Size = UDim2.new(0, reservedRight, 0, 0)
		right.AutomaticSize = reservedRight > 0 and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY
		right.Visible = reservedRight > 0 or (#right:GetChildren() > 0)
		updateLeftInset()
	end

	function row:SetTitle(s)
		local text = tostring(s or "")
		titleLabel.Text = text
		titleLabel.Visible = (text ~= "")
	end

	function row:SetDesc(s)
		local text = tostring(s or "")
		descLabel.Text = text
		descLabel.Visible = (text ~= "")
	end

	function row:SetDisabled(disabled)
		row._disabled = (disabled == true)
		local targetTextTrans = row._disabled and 0.48 or 0
		titleLabel.TextTransparency = targetTextTrans
		descLabel.TextTransparency = targetTextTrans
		if iconObj then
			Icons.SetTransparency(iconObj, row._disabled and 0.48 or 0)
		end
		if iconBadge then
			iconBadge.Frame.BackgroundTransparency = row._disabled and 0.92 or 0.84
		end
	end

	function row:Lock(reason)
		row._locked = true
		lockLabel.Text = (reason and reason ~= "") and tostring(reason) or "Locked"
		lockOverlay.Visible = true
	end

	function row:Unlock()
		row._locked = false
		lockOverlay.Visible = false
	end

	function row:Flash()
		Base.FlashFrame(frame, stroke, surfaceKey)
	end

	uiByFrame[frame] = row
	return row
end

function Base.New(typeName, parent, options, ctx)
	options = Util.Options(options, {}, "Title")
	ctx = ctx or {}

	local title = tostring(options.Title or options.Name or "")
	local desc = tostring(options.Description or options.Desc or options.Content or "")

	local element = {
		Type = typeName,
		Flag = options.Flag,
		Title = title,
		Desc = desc,
		Frame = nil,
		Value = options.Default,
		Changed = Signal.new(),
		Maid = Maid.new(),
		Tab = ctx.Tab,
		SubTab = ctx.SubTab,
		Section = ctx.Section,
		Options = options,
		IgnoreConfig = (options.IgnoreConfig == true),
		Disabled = false,
		Locked = false,
		Visible = options.Visible ~= false,
		_destroyed = false,
		_ui = nil,
		_lockReason = nil,
	}

	local function getUI()
		if element._ui then
			return element._ui
		end
		if element.Frame then
			return uiByFrame[element.Frame]
		end
		return nil
	end

	function element:BindUI(ui)
		self._ui = ui
		if type(ui) == "table" and ui.Frame then
			self.Frame = ui.Frame
		elseif typeof(ui) == "Instance" then
			self.Frame = ui
		end
		if self.Frame then
			if self.Visible == false then
				self.Frame.Visible = false
			end
			if options.Tooltip then
				bindTooltipOnce(self.Frame, options.Tooltip, self.Maid)
			end
		end
		local resolvedUI = getUI()
		if resolvedUI then
			if self.Disabled and type(resolvedUI.SetDisabled) == "function" then
				resolvedUI:SetDisabled(true)
			end
			if self.Locked and type(resolvedUI.Lock) == "function" then
				resolvedUI:Lock(self._lockReason)
			end
		end
		return self
	end

	function element:SetTitle(s)
		local text = tostring(s or "")
		self.Title = text
		if self._record then
			self._record.Title = text
		end
		local ui = getUI()
		if ui and type(ui.SetTitle) == "function" then
			ui:SetTitle(text)
		elseif ui and ui.TitleLabel then
			ui.TitleLabel.Text = text
			ui.TitleLabel.Visible = (text ~= "")
		end
	end

	function element:SetDesc(s)
		local text = tostring(s or "")
		self.Desc = text
		if self._record then
			self._record.Desc = text
		end
		local ui = getUI()
		if ui and type(ui.SetDesc) == "function" then
			ui:SetDesc(text)
		elseif ui and ui.DescLabel then
			ui.DescLabel.Text = text
			ui.DescLabel.Visible = (text ~= "")
		end
	end

	function element:SetVisible(b)
		local visible = (b ~= false)
		self.Visible = visible
		if self.Frame then
			self.Frame.Visible = visible
		end
	end

	function element:SetDisabled(b)
		local disabled = (b == true)
		self.Disabled = disabled
		local ui = getUI()
		if ui and type(ui.SetDisabled) == "function" then
			ui:SetDisabled(disabled)
		end
		if type(self._onDisabled) == "function" then
			self._onDisabled(disabled)
		end
	end

	function element:Lock(reason)
		self.Locked = true
		self._lockReason = reason
		local ui = getUI()
		if ui and type(ui.Lock) == "function" then
			ui:Lock(reason)
		end
		if type(self._onLocked) == "function" then
			self._onLocked(true, reason)
		end
	end

	function element:Unlock()
		self.Locked = false
		self._lockReason = nil
		local ui = getUI()
		if ui and type(ui.Unlock) == "function" then
			ui:Unlock()
		end
		if type(self._onLocked) == "function" then
			self._onLocked(false, nil)
		end
	end

	function element:Flash()
		local ui = getUI()
		if ui and type(ui.Flash) == "function" then
			ui:Flash()
		elseif self.Frame then
			Base.FlashFrame(self.Frame)
		end
	end

	function element:OnChanged(fn)
		if type(fn) ~= "function" then
			return nil
		end
		local conn = self.Changed:Connect(fn)
		self.Maid:Give(conn)
		return conn
	end

	function element:Destroy()
		if self._destroyed then
			return
		end
		self._destroyed = true
		self.Maid:Clean()
		self.Changed:Destroy()
		if self.Frame and self.Frame.Parent then
			self.Frame:Destroy()
		end
		self.Frame = nil
		self._ui = nil
	end

	-- Support callers that assign element.Frame directly without calling :BindUI
	if options.Tooltip or options.Visible == false then
		task.defer(function()
			if element._destroyed or not element.Frame then
				return
			end
			if options.Visible == false then
				element.Frame.Visible = false
			end
			if options.Tooltip then
				bindTooltipOnce(element.Frame, options.Tooltip, element.Maid)
			end
		end)
	end

	if ctx.Maid then
		ctx.Maid:Give(element)
	end

	local record = {
		Type = element.Type,
		Title = element.Title,
		Desc = element.Desc,
		Flag = element.Flag,
		Tab = element.Tab,
		SubTab = element.SubTab,
		Section = element.Section,
		Element = element,
	}
	element._record = record
	if type(ctx.RegisterElement) == "function" then
		ctx.RegisterElement(record)
	end

	return element
end

return Base
end

__modules["Elements/Button"] = function()
--[[
	Bali UI · Elements/Button
	Interactive action buttons (with 2-step confirmation) and equal-width ButtonGroup rows.
]]

local Util = require("Core/Util")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Tooltip = require("Systems/Tooltip")
local Base = require("Elements/Base")

local ButtonModule = {}

local function applyButtonVariant(btnFrame, stroke, label, iconObj, grad, variant, isConfirming, isHovered)
	if isConfirming then
		if grad then
			grad.Enabled = false
		end
		Theme.Bind(btnFrame, { BackgroundColor3 = "Error" })
		btnFrame.BackgroundTransparency = isHovered and 0.68 or 0.78
		if stroke then
			Theme.Bind(stroke, { Color = "Error" })
			stroke.Transparency = 0.25
		end
		if label then
			Theme.Bind(label, {
				TextColor3 = function(t)
					return Util.LerpColor(t.Error, Color3.new(1, 1, 1), 0.42)
				end,
			})
		end
		if iconObj then
			Icons.SetColor(iconObj, "Error")
		end
		return
	end

	if variant == "Primary" then
		Theme.Unbind(btnFrame, "BackgroundColor3")
		btnFrame.BackgroundColor3 = Color3.new(1, 1, 1)
		btnFrame.BackgroundTransparency = isHovered and 0.08 or 0
		if grad then
			grad.Color = Theme.AccentSequence()
			grad.Enabled = true
		end
		if stroke then
			Theme.Bind(stroke, { Color = "Accent" })
			stroke.Transparency = isHovered and 0.25 or 0.45
		end
		if label then
			Theme.Bind(label, { TextColor3 = "AccentText" })
		end
		if iconObj then
			Icons.SetColor(iconObj, "AccentText")
		end
	elseif variant == "Danger" then
		if grad then
			grad.Enabled = false
		end
		Theme.Bind(btnFrame, { BackgroundColor3 = "Error" })
		btnFrame.BackgroundTransparency = isHovered and 0.72 or 0.84
		if stroke then
			Theme.Bind(stroke, { Color = "Error" })
			stroke.Transparency = isHovered and 0.35 or 0.55
		end
		if label then
			Theme.Bind(label, {
				TextColor3 = function(t)
					return Util.LerpColor(t.Error, Color3.new(1, 1, 1), 0.42)
				end,
			})
		end
		if iconObj then
			Icons.SetColor(iconObj, "Error")
		end
	elseif variant == "Ghost" then
		if grad then
			grad.Enabled = false
		end
		Theme.Bind(btnFrame, { BackgroundColor3 = isHovered and "TileHover" or "Tile" })
		btnFrame.BackgroundTransparency = isHovered and 0.45 or 1
		if stroke then
			Theme.Bind(stroke, { Color = "Stroke" })
			stroke.Transparency = isHovered and 0.86 or 0.94
		end
		if label then
			Theme.Bind(label, { TextColor3 = isHovered and "Text" or "SubText" })
		end
		if iconObj then
			Icons.SetColor(iconObj, isHovered and "Text" or "SubText")
		end
	else
		-- "Default"
		if grad then
			grad.Enabled = false
		end
		Theme.Bind(btnFrame, {
			BackgroundColor3 = isHovered and "TileHover" or "Tile",
			BackgroundTransparency = "TileTransparency",
		})
		if stroke then
			Theme.Bind(stroke, {
				Color = "Stroke",
				Transparency = function(t)
					local base = math.max(t.StrokeTransparency - 0.02, 0)
					return isHovered and math.max(base - 0.08, 0) or base
				end,
			})
		end
		if label then
			Theme.Bind(label, { TextColor3 = "Text" })
		end
		if iconObj then
			Icons.SetColor(iconObj, "Accent")
		end
	end
end

local function applyStateTransition(frame, stroke, variant, hovered, pressed, confirming, animate)
	local theme = Theme.Current
	local targetBg = frame.BackgroundColor3
	local targetTrans = frame.BackgroundTransparency
	local targetStroke = stroke.Transparency
	local tileHover = theme.TileHover or theme.Tile
	local accentHover = theme.AccentHover or theme.Accent

	if not confirming and variant == "Default" then
		targetBg = pressed and Util.LerpColor(tileHover, theme.Accent, 0.08) or (hovered and tileHover or theme.Tile)
		targetTrans = pressed and math.max(0.06, theme.TileTransparency - 0.14)
			or (hovered and math.max(0.12, theme.TileTransparency - 0.08) or theme.TileTransparency)
		targetStroke = pressed and 0.42 or (hovered and 0.56 or theme.StrokeTransparency)
	elseif variant == "Primary" and not confirming then
		targetBg = pressed and Util.LerpColor(accentHover, Color3.new(1, 1, 1), 0.08)
			or (hovered and accentHover or theme.Accent)
		targetTrans = pressed and 0.02 or (hovered and 0.06 or 0.14)
	end

	if animate then
		Tween.Play(frame, { BackgroundColor3 = targetBg, BackgroundTransparency = targetTrans }, Tween.Fast, Enum.EasingStyle.Exponential)
		Tween.Play(stroke, { Transparency = targetStroke }, Tween.Fast, Enum.EasingStyle.Exponential)
	else
		frame.BackgroundColor3 = targetBg
		frame.BackgroundTransparency = targetTrans
		stroke.Transparency = targetStroke
	end
end

-- ─── Button ──────────────────────────────────────────────────────────────────

local Button = {}
function Button.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Title")
	local element = Base.New("Button", parent, opts, ctx)

	local rowOpts = table.clone(opts)
	if rowOpts.IconBadge == nil then
		rowOpts.IconBadge = false
	end

	local variant = opts.Variant or "Default"
	local row = Base.Row(parent, rowOpts, 0)
	element:BindUI(row)

	local grad = Instance.new("UIGradient")
	grad.Color = Theme.AccentSequence()
	grad.Rotation = 15
	grad.Enabled = false
	grad.Parent = row.Frame

	local rightIcon = nil
	if opts.ShowArrow ~= false then
		Create.List(row.Right, {
			Direction = Enum.FillDirection.Horizontal,
			VAlign = Enum.VerticalAlignment.Center,
			HAlign = Enum.HorizontalAlignment.Right,
			Gap = 6,
		})
		if opts.Badge then
			local bText = type(opts.Badge) == "table" and (opts.Badge.Text or opts.Badge[1]) or tostring(opts.Badge)
			local bColor = type(opts.Badge) == "table" and (opts.Badge.Color or opts.Badge[2]) or "Accent"
			local b = Base.Badge(row.Right, bText, bColor)
			b.Frame.LayoutOrder = 1
		end
		rightIcon = Icons.Create(opts.RightIcon or "chevron-right", {
			Size = UDim2.fromOffset(15, 15),
			Color = "Muted",
			LayoutOrder = 2,
			Parent = row.Right,
		})
	end

	local hitBtn = Create.New("TextButton", {
		Name = "HitButton",
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromScale(0, 0),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 12,
		Parent = row.Frame,
	})

	row.Left.ZIndex = 2
	row.Right.ZIndex = 2

	local hovered = false
	local pressed = false
	local confirming = false
	local confirmToken = 0
	local baseTitle = element.Title

	local function refreshVisual(animate)
		applyButtonVariant(row.Frame, row.Stroke, row.TitleLabel, row.IconObj, grad, variant, confirming, hovered or pressed)

		if row.DescLabel then
			if confirming then
				Theme.Bind(row.DescLabel, { TextColor3 = "Error" })
			elseif variant == "Primary" then
				Theme.Bind(row.DescLabel, { TextColor3 = "AccentText" })
				row.DescLabel.TextTransparency = 0.18
			elseif variant == "Danger" then
				Theme.Bind(row.DescLabel, { TextColor3 = "SubText" })
				row.DescLabel.TextTransparency = element.Disabled and 0.48 or 0.25
			else
				Theme.Bind(row.DescLabel, { TextColor3 = "SubText" })
				row.DescLabel.TextTransparency = element.Disabled and 0.48 or 0
			end
		end

		if rightIcon then
			Icons.SetColor(rightIcon, confirming and "Error" or (variant == "Primary" and "AccentText" or "Muted"))
		end

		applyStateTransition(row.Frame, row.Stroke, variant, hovered, pressed, confirming, animate)
	end

	refreshVisual(false)
	element.Maid:Give(Theme.Changed:Connect(function()
		if not element._destroyed then
			refreshVisual(false)
		end
	end))

	element._onDisabled = function(disabled)
		hitBtn.Visible = not disabled
		if disabled then
			hovered = false
			pressed = false
		end
		refreshVisual(false)
	end

	element.Maid:Give(hitBtn.MouseEnter:Connect(function()
		if element.Disabled or element.Locked or Util.IsTouchDevice() then
			return
		end
		hovered = true
		refreshVisual(true)
	end))

	element.Maid:Give(hitBtn.MouseLeave:Connect(function()
		hovered = false
		pressed = false
		refreshVisual(true)
	end))

	local lastPointerPos = nil
	element.Maid:Give(hitBtn.InputBegan:Connect(function(input)
		if element.Disabled or element.Locked then
			return
		end
		if Util.IsPointer(input) then
			lastPointerPos = Vector2.new(input.Position.X, input.Position.Y)
			pressed = true
			refreshVisual(true)
		end
	end))

	element.Maid:Give(hitBtn.InputEnded:Connect(function(input)
		if Util.IsPointer(input) then
			pressed = false
			refreshVisual(true)
		end
	end))

	local function shakeBody()
		if Tween.Reduced or not row.Body or not row.Body.Parent then
			return
		end
		local offsets = { -5, 5, -3, 3, 0 }
		task.spawn(function()
			for _, x in ipairs(offsets) do
				if element._destroyed or not row.Body.Parent then
					return
				end
				Tween.Play(row.Body, { Position = UDim2.fromOffset(x, 0) }, 0.04, Enum.EasingStyle.Sine)
				task.wait(0.045)
			end
			if row.Body and row.Body.Parent then
				row.Body.Position = UDim2.fromOffset(0, 0)
			end
		end)
	end

	local function resetConfirm()
		confirming = false
		row:SetTitle(baseTitle)
		if rightIcon then
			Icons.Set(rightIcon, opts.RightIcon or "chevron-right")
		end
		refreshVisual(true)
	end

	local function executeCallback()
		element.Changed:Fire()
		if type(opts.Callback) == "function" then
			Util.Spawn(opts.Callback)
		end
	end

	local function trigger(posOverride)
		if element.Disabled or element.Locked then
			return
		end
		local rippleColor = variant == "Primary" and "AccentText" or (variant == "Danger" and "Error" or "Accent")
		Transition.Ripple(row.Frame, posOverride or lastPointerPos, rippleColor)

		if opts.Confirm then
			if not confirming then
				confirming = true
				confirmToken += 1
				local myToken = confirmToken
				local confirmPrompt = type(opts.Confirm) == "string" and opts.Confirm or "Click again to confirm"
				row:SetTitle(confirmPrompt)
				if rightIcon then
					Icons.Set(rightIcon, "triangle-alert")
				end
				refreshVisual(true)
				shakeBody()
				task.delay(3, function()
					if not element._destroyed and confirming and confirmToken == myToken then
						resetConfirm()
					end
				end)
				return
			else
				confirmToken += 1
				resetConfirm()
			end
		end

		executeCallback()
	end

	element.Maid:Give(hitBtn.Activated:Connect(function(inputObj)
		local pos = lastPointerPos
		if inputObj and inputObj.Position then
			pos = Vector2.new(inputObj.Position.X, inputObj.Position.Y)
		end
		trigger(pos)
	end))

	function element:SetText(s)
		local text = tostring(s or "")
		baseTitle = text
		self.Title = text
		if self._record then
			self._record.Title = text
		end
		if not confirming then
			row:SetTitle(text)
		end
	end
	element.SetTitle = element.SetText

	function element:SetVariant(newVariant)
		variant = newVariant or "Default"
		refreshVisual(true)
	end

	function element:Fire()
		if self.Disabled or self.Locked then
			return
		end
		Transition.Ripple(row.Frame, nil, variant == "Primary" and "AccentText" or "Accent")
		executeCallback()
	end

	return element
end

-- ─── ButtonGroup ─────────────────────────────────────────────────────────────

local ButtonGroup = {}
function ButtonGroup.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Title")
	local element = Base.New("ButtonGroup", parent, opts, ctx)

	local wrapper = Create.New("Frame", {
		Name = "ButtonGroup",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = parent,
	})

	Create.List(wrapper, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 6,
	})

	local titleText = tostring(opts.Title or "")
	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "Medium",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Visible = titleText ~= "",
		Parent = wrapper,
	})

	local row = Create.New("Frame", {
		Name = "Row",
		Size = UDim2.new(1, 0, 0, 38),
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		Parent = wrapper,
	})

	local gap = opts.Gap or 8
	Create.List(row, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = gap,
	})

	local buttonsList = opts.Buttons or {}
	local count = math.max(#buttonsList, 1)
	local createdButtons = {}

	for index, item in ipairs(buttonsList) do
		local bOpts = type(item) == "table" and item or { Title = tostring(item) }
		local bVariant = bOpts.Variant or "Default"
		local widthOffset = -((count - 1) * gap) / count

		local btn = Create.New("TextButton", {
			Name = "Pill_" .. index,
			Size = UDim2.new(1 / count, widthOffset, 0, 38),
			Theme = { BackgroundColor3 = "Tile" },
			Corner = UDim.new(1, 0),
			Padding = { 0, 12, 0, 12 },
			Text = "",
			AutoButtonColor = false,
			LayoutOrder = index,
			Parent = row,
		})

		local stroke = Create.GlassStroke(btn, 0.02)
		local grad = Instance.new("UIGradient")
		grad.Color = Theme.AccentSequence()
		grad.Rotation = 15
		grad.Enabled = false
		grad.Parent = btn

		local content = Create.New("Frame", {
			Name = "Content",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			ClipsDescendants = true,
			Parent = btn,
		})

		Create.List(content, {
			Direction = Enum.FillDirection.Horizontal,
			HAlign = Enum.HorizontalAlignment.Center,
			VAlign = Enum.VerticalAlignment.Center,
			Gap = 6,
		})

		local iconObj = nil
		if bOpts.Icon and bOpts.Icon ~= "" and bOpts.Icon ~= false then
			iconObj = Icons.Create(bOpts.Icon, {
				Size = UDim2.fromOffset(14, 14),
				Color = "Text",
				LayoutOrder = 1,
				Parent = content,
			})
		end

		local lbl = Create.Text({
			Name = "Label",
			Text = tostring(bOpts.Title or bOpts.Text or ("Action " .. index)),
			Font = "SemiBold",
			TextSize = 12,
			Color = "Text",
			Size = UDim2.fromOffset(0, 0),
			AutomaticSize = Enum.AutomaticSize.XY,
			TextXAlignment = Enum.TextXAlignment.Center,
			TextTruncate = Enum.TextTruncate.AtEnd,
			LayoutOrder = 2,
			Parent = content,
		})

		local isHovered = false
		local isPressed = false
		local itemDisabled = (bOpts.Disabled == true)

		local function refreshBtn(animate)
			applyButtonVariant(btn, stroke, lbl, iconObj, grad, bVariant, false, isHovered or isPressed)
			local dim = (element.Disabled or itemDisabled) and 0.48 or 0
			lbl.TextTransparency = dim
			if iconObj then
				Icons.SetTransparency(iconObj, dim)
			end

			applyStateTransition(btn, stroke, bVariant, isHovered, isPressed, false, animate)
		end

		refreshBtn(false)
		element.Maid:Give(Theme.Changed:Connect(function()
			if not element._destroyed then
				refreshBtn(false)
			end
		end))

		if bOpts.Tooltip then
			pcall(Tooltip.Bind, btn, bOpts.Tooltip)
		end

		element.Maid:Give(btn.MouseEnter:Connect(function()
			if element.Disabled or element.Locked or itemDisabled or Util.IsTouchDevice() then
				return
			end
			isHovered = true
			refreshBtn(true)
		end))

		element.Maid:Give(btn.MouseLeave:Connect(function()
			isHovered = false
			isPressed = false
			refreshBtn(true)
		end))

		local lastPos = nil
		element.Maid:Give(btn.InputBegan:Connect(function(input)
			if element.Disabled or element.Locked or itemDisabled then
				return
			end
			if Util.IsPointer(input) then
				lastPos = Vector2.new(input.Position.X, input.Position.Y)
				isPressed = true
				refreshBtn(true)
			end
		end))

		element.Maid:Give(btn.InputEnded:Connect(function(input)
			if Util.IsPointer(input) then
				isPressed = false
				refreshBtn(true)
			end
		end))

		element.Maid:Give(btn.Activated:Connect(function(inputObj)
			if element.Disabled or element.Locked or itemDisabled then
				return
			end
			local pos = (inputObj and inputObj.Position) and Vector2.new(inputObj.Position.X, inputObj.Position.Y) or lastPos
			Transition.Ripple(btn, pos, bVariant == "Primary" and "AccentText" or "Accent")
			element.Changed:Fire(index, bOpts.Title)
			if type(bOpts.Callback) == "function" then
				Util.Spawn(bOpts.Callback)
			end
		end))

		createdButtons[index] = {
			Frame = btn,
			Label = lbl,
			Icon = iconObj,
			SetText = function(_, s)
				lbl.Text = tostring(s or "")
			end,
			SetVariant = function(_, v)
				bVariant = v or "Default"
				refreshBtn()
			end,
			SetDisabled = function(_, d)
				itemDisabled = (d == true)
				refreshBtn()
			end,
			Refresh = refreshBtn,
		}
	end

	element:BindUI({
		Frame = wrapper,
		TitleLabel = titleLabel,
		SetTitle = function(_, s)
			local txt = tostring(s or "")
			titleLabel.Text = txt
			titleLabel.Visible = (txt ~= "")
		end,
		SetDisabled = function(_, disabled)
			for _, b in ipairs(createdButtons) do
				b.Refresh()
			end
		end,
		Flash = function()
			for _, b in ipairs(createdButtons) do
				Base.FlashFrame(b.Frame)
			end
		end,
	})

	function element:GetButton(index)
		return createdButtons[index]
	end

	return element
end

ButtonModule.Button = Button
ButtonModule.ButtonGroup = ButtonGroup

return ButtonModule
end

__modules["Elements/ColorPicker"] = function()
--[[
	Bali UI · Elements/ColorPicker
	Apple-premium dark glass color picker with swatch pill, 2D SV gradient canvas,
	7-stop Hue spectrum, optional Transparency slider, live #HEX & RGB inputs,
	Rainbow mode, and quick preset swatches inside PopupLayer.
]]

local Services = require("Core/Services")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")
local Tooltip = require("Systems/Tooltip")

local ColorPicker = {}
ColorPicker.__index = ColorPicker

local DEFAULT_PRESETS = {
	Color3.fromRGB(214, 64, 236),
	Color3.fromRGB(59, 130, 246),
	Color3.fromRGB(45, 212, 191),
	Color3.fromRGB(52, 211, 153),
	Color3.fromRGB(251, 113, 133),
	Color3.fromRGB(251, 191, 36),
}

local HUE_SEQUENCE = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 0, 0)),
	ColorSequenceKeypoint.new(1 / 6, Color3.fromRGB(255, 255, 0)),
	ColorSequenceKeypoint.new(2 / 6, Color3.fromRGB(0, 255, 0)),
	ColorSequenceKeypoint.new(3 / 6, Color3.fromRGB(0, 255, 255)),
	ColorSequenceKeypoint.new(4 / 6, Color3.fromRGB(0, 0, 255)),
	ColorSequenceKeypoint.new(5 / 6, Color3.fromRGB(255, 0, 255)),
	ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 0, 0)),
})

local function parseColorInput(input, fallback)
	if typeof(input) == "Color3" then
		return input
	elseif type(input) == "string" then
		return Util.FromHex(input) or fallback
	elseif type(input) == "table" then
		if typeof(input.Color) == "Color3" then
			return input.Color
		elseif type(input.Color) == "string" then
			return Util.FromHex(input.Color) or fallback
		elseif type(input.Hex) == "string" then
			return Util.FromHex(input.Hex) or fallback
		elseif input.R and input.G and input.B then
			return Color3.new(input.R, input.G, input.B)
		elseif typeof(input[1]) == "Color3" then
			return input[1]
		elseif type(input[1]) == "number" and type(input[2]) == "number" and type(input[3]) == "number" then
			if input[1] > 1 or input[2] > 1 or input[3] > 1 then
				return Color3.fromRGB(input[1], input[2], input[3])
			end
			return Color3.new(input[1], input[2], input[3])
		end
	end
	return fallback
end

local function isDisabledOrLocked(self)
	return self.Disabled == true or self.Locked == true or self._disabled == true or self._locked == true
end

function ColorPicker.new(parent, opts, ctx)
	local rawOpts = type(opts) == "table" and opts or {}
	local hasAlpha = rawOpts.Alpha == true or rawOpts.Transparency ~= nil

	opts = Util.Options(opts, {
		Title = "Color Picker",
		Description = nil,
		Default = Theme.Current.Accent,
		Transparency = 0,
		Rainbow = false,
		Presets = DEFAULT_PRESETS,
		Callback = nil,
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("ColorPicker", parent, opts, ctx)
	local rowParent = (typeof(self.Frame) == "Instance") and self.Frame or parent
	local rightWidth = 92
	local rowOpts = table.clone(opts)
	if rowOpts.IconBadge == nil then
		rowOpts.IconBadge = false
	end
	local row = Base.Row(rowParent, rowOpts, rightWidth)

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = row.Frame
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
	end

	if self.BindUI then
		self:BindUI(row)
	end

	self._row = row
	self.Row = row
	self.TitleLabel = row.TitleLabel
	self.DescLabel = row.DescLabel
	self.Stroke = row.Stroke
	self.LockOverlay = row.LockOverlay

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, row.Frame, opts.Tooltip)
	end

	local initialColor = parseColorInput(opts.Default, Theme.Current.Accent)
	local initialAlpha = Util.Clamp(tonumber(opts.Transparency) or 0, 0, 1)
	if type(rawOpts.Default) == "table" and rawOpts.Default.Alpha ~= nil then
		initialAlpha = Util.Clamp(tonumber(rawOpts.Default.Alpha) or initialAlpha, 0, 1)
	end

	local hue, sat, val = Color3.toHSV(initialColor)
	local currentColor = initialColor
	local currentAlpha = initialAlpha
	local rainbowEnabled = opts.Rainbow == true
