	local function findItemByInput(val)
		if val == nil then
			return nil
		end
		for _, item in ipairs(items) do
			if item.Value == val then
				return item
			end
		end
		local strVal = tostring(val)
		for _, item in ipairs(items) do
			if item.Title == strVal or tostring(item.Value) == strVal then
				return item
			end
		end
		if type(val) == "number" and items[val] then
			return items[val]
		end
		return nil
	end

	local function getSelectedValues()
		if multi then
			local list = {}
			for _, item in ipairs(items) do
				if selectedMap[item] then
					table.insert(list, item.Value)
				end
			end
			return list
		end
		return selectedSingle and selectedSingle.Value or nil
	end

	local function clearTriggerIcon()
		for _, child in ipairs(triggerIconHolder:GetChildren()) do
			child:Destroy()
		end
		triggerIconHolder.Visible = false
	end

	local function applyColorOrToken(inst, prop, col, token, fallbackToken)
		if col then
			Theme.Unbind(inst, prop)
			inst[prop] = col
		else
			Theme.Bind(inst, { [prop] = token or fallbackToken })
		end
	end

	local function updateSummary()
		local previewItem = nil
		local titles = nil
		if multi then
			local selectedItems = {}
			titles = {}
			for _, item in ipairs(items) do
				if selectedMap[item] then
					table.insert(selectedItems, item)
					table.insert(titles, item.Title)
				end
			end
			if #selectedItems == 1 then
				previewItem = selectedItems[1]
			end
		else
			previewItem = selectedSingle
		end

		if previewItem then
			local leftReserve = 0
			local imgAsset = normalizeImageAsset(previewItem.Image)
			if imgAsset then
				clearTriggerIcon()
				triggerThumb.Image = imgAsset
				triggerThumb.Visible = true
				leftReserve = 26
			elseif previewItem.Icon then
				triggerThumb.Visible = false
				clearTriggerIcon()
				local iconCol, iconToken = resolveCustomColor(previewItem.IconColor or previewItem.Color)
				Icons.Create(previewItem.Icon, {
					Size = UDim2.fromOffset(15, 15),
					Position = UDim2.fromScale(0.5, 0.5),
					AnchorPoint = Vector2.new(0.5, 0.5),
					Color = iconCol or iconToken or "Accent",
					Parent = triggerIconHolder,
				})
				triggerIconHolder.Visible = true
				leftReserve = 22
			else
				triggerThumb.Visible = false
				clearTriggerIcon()
			end

			local rightReserve = 20
			if previewItem.Badge ~= nil and previewItem.Badge ~= "" then
				local badgeStr = tostring(previewItem.Badge)
				local badgeCol, badgeToken = resolveCustomColor(previewItem.BadgeColor)
				triggerBadgeText.Text = badgeStr
				applyColorOrToken(triggerBadge, "BackgroundColor3", badgeCol, badgeToken, "Accent")
				applyColorOrToken(triggerBadgeStroke, "Color", badgeCol, badgeToken, "Accent")
				applyColorOrToken(triggerBadgeText, "TextColor3", badgeCol, badgeToken, "Accent")
				triggerBadge.Visible = true
				triggerRightText.Visible = false
				local badgeW = math.clamp(#badgeStr * 6 + 18, 34, 72)
				rightReserve = 24 + badgeW
			elseif previewItem.RightText ~= nil and previewItem.RightText ~= "" then
				local hintStr = tostring(previewItem.RightText)
				local hintCol, hintToken = resolveCustomColor(previewItem.BadgeColor)
				triggerRightText.Text = hintStr
				applyColorOrToken(triggerRightText, "TextColor3", hintCol, hintToken, "Muted")
				triggerRightText.Visible = true
				triggerBadge.Visible = false
				local hintW = math.clamp(#hintStr * 6 + 6, 26, 68)
				rightReserve = 24 + hintW
			else
				triggerBadge.Visible = false
				triggerRightText.Visible = false
			end

			summaryLabel.Position = UDim2.fromOffset(leftReserve, 0)
			summaryLabel.Size = UDim2.new(1, -(leftReserve + rightReserve), 1, 0)
			summaryLabel.Text = previewItem.Title
			local customCol, customToken = resolveCustomColor(previewItem.Color)
			if customCol then
				Theme.Unbind(summaryLabel, "TextColor3")
				Theme.Bind(summaryLabel, { FontFace = "@SemiBold" })
				summaryLabel.TextColor3 = customCol
			else
				Theme.Bind(summaryLabel, {
					TextColor3 = customToken or "Text",
					FontFace = "@SemiBold",
				})
			end
			return
		end

		triggerThumb.Visible = false
		clearTriggerIcon()
		triggerBadge.Visible = false
		triggerRightText.Visible = false
		summaryLabel.Position = UDim2.fromOffset(0, 0)
		summaryLabel.Size = UDim2.new(1, -20, 1, 0)

		if multi then
			if not titles or #titles == 0 then
				summaryLabel.Text = "None"
				Theme.Bind(summaryLabel, { TextColor3 = "Muted", FontFace = "@Medium" })
			else
				summaryLabel.Text = table.concat(titles, ", ")
				Theme.Bind(summaryLabel, { TextColor3 = "Text", FontFace = "@Medium" })
			end
		else
			summaryLabel.Text = "Select..."
			Theme.Bind(summaryLabel, { TextColor3 = "Muted", FontFace = "@Medium" })
		end
	end

	local function isItemSelected(item)
		if multi then
			return selectedMap[item] == true
		end
		return selectedSingle == item
	end

	local function cancelEntryTweens(entry)
		if entry._bgTween then
			pcall(function()
				entry._bgTween:Cancel()
			end)
			entry._bgTween = nil
		end
		if entry._strTween then
			pcall(function()
				entry._strTween:Cancel()
			end)
			entry._strTween = nil
		end
		if entry._chkTween then
			pcall(function()
				entry._chkTween:Cancel()
			end)
			entry._chkTween = nil
		end
	end

	local function syncEntryVisual(entry, animated)
		local item = entry.Item
		local active = isItemSelected(item)
		local disabled = item.Disabled == true
		local targetBg = active and 0.82 or ((entry.Hovered and not disabled) and 0.42 or 1)
		local targetStroke = active and 0.52 or ((entry.Hovered and not disabled) and 0.86 or 1)
		local targetCheck = active and 0 or 1

		Theme.Bind(entry.Button, {
			BackgroundColor3 = active and "Accent" or "TileHover",
		})
		Theme.Bind(entry.Stroke, {
			Color = active and "Accent" or "Stroke",
		})

		local customCol, customToken = resolveCustomColor(item.Color)
		if customCol then
			Theme.Unbind(entry.TitleLabel, "TextColor3")
			Theme.Bind(entry.TitleLabel, {
				FontFace = active and "@SemiBold" or "@Medium",
			})
			entry.TitleLabel.TextColor3 = customCol
		else
			Theme.Bind(entry.TitleLabel, {
				TextColor3 = customToken or (active and "Text" or "SubText"),
				FontFace = active and "@SemiBold" or "@Medium",
			})
		end
		entry.TitleLabel.TextTransparency = disabled and 0.48 or 0

		if entry.IconInst and not item.IconColor then
			Icons.SetColor(entry.IconInst, active and "Accent" or "SubText")
		end

		cancelEntryTweens(entry)
		if animated and not Tween.Reduced and isOpen then
			entry.Button:SetAttribute("_BaliRestBg", targetBg)
			entry.Stroke:SetAttribute("_BaliRestStr", targetStroke)
			entry._bgTween = Tween.Play(entry.Button, { BackgroundTransparency = targetBg }, Tween.Fast, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			entry._strTween = Tween.Play(entry.Stroke, { Transparency = targetStroke }, Tween.Fast, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			if entry.CheckIcon then
				entry.CheckIcon.Visible = true
				entry.CheckIcon:SetAttribute("_BaliRestImg", targetCheck)
				entry._chkTween = Tween.Play(entry.CheckIcon, { ImageTransparency = targetCheck }, Tween.Fast, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			end
		else
			entry.Button.BackgroundTransparency = targetBg
			entry.Button:SetAttribute("_BaliRestBg", targetBg)
			entry.Stroke.Transparency = targetStroke
			entry.Stroke:SetAttribute("_BaliRestStr", targetStroke)
			if entry.CheckIcon then
				entry.CheckIcon.Visible = true
				entry.CheckIcon.ImageTransparency = targetCheck
				entry.CheckIcon:SetAttribute("_BaliRestImg", targetCheck)
			end
		end
	end

	local function updateOptionVisuals(animated)
		local animateNow = (animated == true) and isOpen
		for _, entry in ipairs(optionRows) do
			syncEntryVisual(entry, animateNow)
		end
	end

	local function resizePopup(preserveFlip, animateInline)
		local searchH = searchable and 38 or 0
		local visibleCount = 0
		local hasDesc = false
		for _, entry in ipairs(optionRows) do
			if entry.Button.Visible then
				visibleCount += 1
				if entry.Item.Desc and entry.Item.Desc ~= "" then
					hasDesc = true
				end
			end
		end

		local padV = 8
		local contentH = scrollLayout.AbsoluteContentSize.Y
		local estPerRow = hasDesc and 44 or 28
		local maxListH = maxVisible * estPerRow + math.max(0, maxVisible - 1) * 3 + padV
		local estAllH = visibleCount * estPerRow + math.max(0, visibleCount - 1) * 3 + padV
		local fullContentH = (contentH > 0) and (contentH + padV) or estAllH

		local listH
		if visibleCount == 0 then
			listH = 36
		elseif contentH > 0 then
			listH = math.min(contentH + padV, maxListH)
		else
			local shown = math.min(visibleCount, maxVisible)
			listH = shown * estPerRow + math.max(0, shown - 1) * 3 + padV
		end

		local needsScroll = (visibleCount > maxVisible) or (fullContentH > listH)
		scroll.ScrollingEnabled = needsScroll
		scroll.ScrollBarThickness = needsScroll and 3 or 0
		scroll.CanvasSize = UDim2.fromOffset(0, needsScroll and fullContentH or 0)

		if mode == "Inline" then
			local inlineTotalH = 16 + searchH + listH
			local inlineClipH = inlineTotalH + 1
			scroll.Size = UDim2.new(1, 0, 0, listH)
			popupInner.Position = UDim2.fromOffset(0, 1)
			popupInner.Size = UDim2.new(1, 0, 0, inlineTotalH)
			if isOpen and animateInline then
				cancelInlineTween()
				inlineTween = Tween.Play(inlineClip, { Size = UDim2.new(1, 0, 0, inlineClipH) }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			end
			return inlineClipH
		end

		local layerH = (ctx.PopupLayer and ctx.PopupLayer.AbsoluteSize.Y > 0) and ctx.PopupLayer.AbsoluteSize.Y or 680
		local anchorW = (trigger.AbsoluteSize.X > 0) and trigger.AbsoluteSize.X or 168
		local width = (anchorW >= 180) and anchorW or Util.Clamp(math.max(anchorW + 40, 200), 200, 252)
		local totalH = math.min(16 + searchH + listH, math.max(120, layerH - 16))
		listH = math.max(36, totalH - 16 - searchH)

		local prevBottom = popup.AbsolutePosition.Y + popup.AbsoluteSize.Y
		local anchorTop = trigger.AbsolutePosition.Y
		local wasFlipped = preserveFlip == true and isOpen and popup.Parent ~= nil and prevBottom <= anchorTop + 4

		needsScroll = (visibleCount > maxVisible) or (fullContentH > listH)
		scroll.ScrollingEnabled = needsScroll
		scroll.ScrollBarThickness = needsScroll and 3 or 0
		scroll.CanvasSize = UDim2.fromOffset(0, needsScroll and fullContentH or 0)
		scroll.Size = UDim2.new(1, 0, 0, listH)
		popupInner.Position = UDim2.fromOffset(0, 0)
		popupInner.Size = UDim2.fromScale(1, 1)
		popup.Size = UDim2.fromOffset(width, totalH)

		-- Keep bottom anchored if popup flipped above trigger and search shrank height
		if wasFlipped and popup.AbsolutePosition.Y > 0 then
			local newY = anchorTop - totalH - 6
			popup.Position = UDim2.fromOffset(popup.Position.X.Offset, math.max(8, newY))
		end

		return totalH
	end

	self.Maid:Give(scrollLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
		if isOpen then
			resizePopup(true, mode == "Inline")
		end
	end))

	local function applyFilter(preserveFlip)
		local anyVisible = false
		for _, entry in ipairs(optionRows) do
			local match = Util.Matches(entry.Item.Title, searchQuery)
				or (entry.Item.Desc and Util.Matches(entry.Item.Desc, searchQuery))
			entry.Button.Visible = match
			if match then
				anyVisible = true
			end
		end
		emptyLabel.Visible = not anyVisible
		if clearSearchBtn then
			clearSearchBtn.Visible = searchQuery ~= ""
		end
		task.defer(function()
			if isOpen and ((mode == "Inline" and inlineClip.Parent) or popup.Parent) then
				resizePopup(preserveFlip, mode == "Inline")
			end
		end)
	end

	local function fireSelection(silent, animated)
		if animated == nil then
			animated = true
		end
		local value = getSelectedValues()
		self.Value = value
		updateSummary()
		updateOptionVisuals(animated)
		if not silent then
			if opts.Callback then
				Util.Spawn(opts.Callback, multi and cloneArray(value) or value)
			end
			self.Changed:Fire(multi and cloneArray(value) or value)
		end
	end

	local function onSelectItem(item)
		if isDisabledOrLocked(self) or item.Disabled then
			return
		end
		if multi then
			if selectedMap[item] then
				if not allowNull then
					local count = 0
					for _ in pairs(selectedMap) do
						count += 1
					end
					if count <= 1 then
						return
					end
				end
				selectedMap[item] = nil
			else
				selectedMap[item] = true
			end
			fireSelection(false, true)
		else
			if selectedSingle == item then
				if allowNull then
					selectedSingle = nil
					fireSelection(false, false)
				end
			else
				selectedSingle = item
				fireSelection(false, false)
			end
			self:Close()
		end
	end

	local function rebuildOptions()
		for _, entry in ipairs(optionRows) do
			cancelEntryTweens(entry)
			entry.Button:Destroy()
		end
		table.clear(optionRows)

		for index, item in ipairs(items) do
			local hasDesc = (item.Desc ~= nil and item.Desc ~= "")
			local imgAsset = normalizeImageAsset(item.Image)
			local hasAccessory = (item.Badge ~= nil and item.Badge ~= "") or (item.RightText ~= nil and item.RightText ~= "")
			local btn = Create.New("TextButton", {
				Name = "Opt_" .. index,
				Size = UDim2.new(1, 0, 0, hasDesc and 44 or 28),
				AutomaticSize = hasDesc and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
				LayoutOrder = index,
				AutoButtonColor = false,
				Active = not item.Disabled,
				ZIndex = 113,
				Corner = 7,
				Padding = hasDesc and { 6, 10, 6, 10 } or { 0, 10, 0, 10 },
				BackgroundTransparency = 1,
				Theme = { BackgroundColor3 = "TileHover" },
				Parent = scroll,
			})
			local optStroke = Create.Stroke(btn, {
				Transparency = 1,
				Theme = { Color = "Accent" },
			})

			local leftReserve = imgAsset and 26 or (item.Icon and 22 or 0)
			local rightReserve = hasAccessory and 82 or 20
			local iconInst = nil
			local thumbInst = nil

			if imgAsset then
				thumbInst = Create.New("ImageLabel", {
					Name = "Thumb",
					Size = UDim2.fromOffset(18, 18),
					Position = UDim2.new(0, 0, 0.5, 0),
					AnchorPoint = Vector2.new(0, 0.5),
					BackgroundTransparency = 1,
					Image = imgAsset,
					ScaleType = Enum.ScaleType.Crop,
					Corner = 5,
					ZIndex = 114,
					Parent = btn,
				})
				Create.Stroke(thumbInst, {
					Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
					Thickness = 1,
				})
			elseif item.Icon then
				local iconCol, iconToken = resolveCustomColor(item.IconColor)
				iconInst = Icons.Create(item.Icon, {
					Size = UDim2.fromOffset(15, 15),
					Position = UDim2.new(0, 0, 0.5, 0),
					AnchorPoint = Vector2.new(0, 0.5),
					Color = iconCol or iconToken or "SubText",
					Transparency = item.Disabled and 0.45 or 0,
					ZIndex = 114,
					Parent = btn,
				})
			end

			if item.Badge ~= nil and item.Badge ~= "" then
				local badgeCol, badgeToken = resolveCustomColor(item.BadgeColor)
				local badgeFrame = Create.New("Frame", {
					Name = "OptionBadge",
					Size = UDim2.fromOffset(0, 18),
					AutomaticSize = Enum.AutomaticSize.X,
					Position = UDim2.new(1, -20, 0.5, 0),
					AnchorPoint = Vector2.new(1, 0.5),
					Corner = 99,
					Padding = { 0, 7, 0, 7 },
					BackgroundTransparency = 0.82,
					BackgroundColor3 = badgeCol or Color3.new(1, 1, 1),
					Theme = (not badgeCol) and { BackgroundColor3 = badgeToken or "Accent" } or nil,
					ZIndex = 114,
					Parent = btn,
				})
				Create.Stroke(badgeFrame, {
					Color = badgeCol,
					Theme = (not badgeCol) and { Color = badgeToken or "Accent" } or nil,
					Transparency = 0.55,
					Thickness = 1,
				})
				local badgeTxt = Create.Text({
					Size = UDim2.fromOffset(0, 18),
					AutomaticSize = Enum.AutomaticSize.X,
					Text = tostring(item.Badge),
					Font = "SemiBold",
					TextSize = 10,
					Color = badgeToken or "Accent",
					TextYAlignment = Enum.TextYAlignment.Center,
					ZIndex = 115,
					Parent = badgeFrame,
				})
				if badgeCol then
					Theme.Unbind(badgeTxt, "TextColor3")
					badgeTxt.TextColor3 = badgeCol
				end
			elseif item.RightText ~= nil and item.RightText ~= "" then
				local hintCol, hintToken = resolveCustomColor(item.BadgeColor)
				local hintTxt = Create.Text({
					Name = "RightText",
					Size = UDim2.fromOffset(0, 16),
					AutomaticSize = Enum.AutomaticSize.X,
					Position = UDim2.new(1, -20, 0.5, 0),
					AnchorPoint = Vector2.new(1, 0.5),
					Text = tostring(item.RightText),
					Font = "Medium",
					TextSize = 11,
					Color = hintToken or "Muted",
					TextYAlignment = Enum.TextYAlignment.Center,
					ZIndex = 114,
					Parent = btn,
				})
				if hintCol then
					Theme.Unbind(hintTxt, "TextColor3")
					hintTxt.TextColor3 = hintCol
				end
			end

			local titleLbl
			local descLbl
			if hasDesc then
				local textCol = Create.New("Frame", {
					Size = UDim2.new(1, -(leftReserve + rightReserve), 0, 0),
					Position = UDim2.fromOffset(leftReserve, 0),
					AutomaticSize = Enum.AutomaticSize.Y,
					BackgroundTransparency = 1,
					ZIndex = 114,
					Parent = btn,
				})
				Create.List(textCol, { Gap = 2 })

				titleLbl = Create.Text({
					Size = UDim2.new(1, 0, 0, 0),
					AutomaticSize = Enum.AutomaticSize.Y,
					Text = item.Title,
					TextSize = 12,
					TextWrapped = true,
					Font = "Medium",
					Color = "SubText",
					LayoutOrder = 1,
					ZIndex = 114,
					Parent = textCol,
				})

				descLbl = Create.Text({
					Size = UDim2.new(1, 0, 0, 0),
					AutomaticSize = Enum.AutomaticSize.Y,
					Text = item.Desc,
					TextSize = 10,
					TextWrapped = true,
					Color = "Muted",
					LayoutOrder = 2,
					ZIndex = 114,
					Parent = textCol,
				})
			else
				titleLbl = Create.Text({
					Size = UDim2.new(1, -(leftReserve + rightReserve), 1, 0),
					Position = UDim2.fromOffset(leftReserve, 0),
					AutomaticSize = Enum.AutomaticSize.None,
					Text = item.Title,
					TextSize = 12,
					TextWrapped = false,
					TextTruncate = Enum.TextTruncate.AtEnd,
					TextYAlignment = Enum.TextYAlignment.Center,
					Font = "Medium",
					Color = "SubText",
					ZIndex = 114,
					Parent = btn,
				})
			end

			local checkIcon = Icons.Create("check", {
				Size = UDim2.fromOffset(14, 14),
				Position = UDim2.new(1, 0, 0.5, 0),
				AnchorPoint = Vector2.new(1, 0.5),
				Color = "Accent",
				ZIndex = 114,
				Parent = btn,
			})
			if checkIcon then
				checkIcon.Visible = true
				checkIcon.ImageTransparency = 1
			end

			local entry = {
				Item = item,
				Button = btn,
				Stroke = optStroke,
				TitleLabel = titleLbl,
				DescLabel = descLbl,
				CheckIcon = checkIcon,
				IconInst = iconInst,
				ThumbInst = thumbInst,
				Hovered = false,
			}

			btn.MouseEnter:Connect(function()
				if item.Disabled or Transition.IsOverlayBlocking(btn) then
					return
				end
				entry.Hovered = true
				syncEntryVisual(entry, true)
			end)
			btn.MouseLeave:Connect(function()
				if item.Disabled then
					return
				end
				entry.Hovered = false
				syncEntryVisual(entry, true)
			end)
			btn.Activated:Connect(function()
				if item.Disabled or Transition.IsOverlayBlocking(btn) then
					return
				end
				Transition.Ripple(btn, nil, "Accent")
				onSelectItem(item)
			end)

			table.insert(optionRows, entry)
		end

		updateOptionVisuals(false)
		applyFilter()
	end

	if searchBox then
		searchBox:GetPropertyChangedSignal("Text"):Connect(function()
			searchQuery = Util.Trim(searchBox.Text)
			applyFilter(true)
		end)
		clearSearchBtn.Activated:Connect(function()
			searchBox.Text = ""
			searchQuery = ""
			applyFilter(true)
		end)
	end

	-- Fallback screen positioning if ctx.OpenPopup is unavailable
	local fallbackOutsideConn
	local function placePopupFallback()
		local layer = ctx.PopupLayer or row.Frame:FindFirstAncestorOfClass("ScreenGui")
		if not layer then
			return
		end
		popup.Parent = layer
		local viewSize = layer.AbsoluteSize
		local anchorPos = trigger.AbsolutePosition
		local anchorSize = trigger.AbsoluteSize
		local popSize = popup.Size
		local px = Util.Clamp(anchorPos.X + anchorSize.X - popSize.X.Offset, 8, math.max(8, viewSize.X - popSize.X.Offset - 8))
		local py = anchorPos.Y + anchorSize.Y + 6
		if py + popSize.Y.Offset > viewSize.Y - 8 then
			local above = anchorPos.Y - popSize.Y.Offset - 6
			if above >= 8 then
				py = above
			end
		end
		popup.Position = UDim2.fromOffset(px, py)
	end

	local function handleClosedState()
		if not isOpen then
			return
		end
		isOpen = false
		openGen += 1
		local myGen = openGen
		for _, entry in ipairs(optionRows) do
			entry.Hovered = false
			syncEntryVisual(entry, false)
		end
		if scroll then
			Transition.RestoreCascade(scroll)
		end
		if chevron then
			Tween.Play(chevron, { Rotation = chevronBaseRot }, Tween.Fast)
		end
		if fallbackOutsideConn then
			fallbackOutsideConn:Disconnect()
			fallbackOutsideConn = nil
		end
		if mode == "Inline" then
			cancelInlineTween()
			local currentH = inlineClip.AbsoluteSize.Y
			if currentH <= 0 then
				currentH = inlineClip.Size.Y.Offset
			end
			if currentH > 0 then
				inlineClip.Size = UDim2.new(1, 0, 0, currentH)
			end
			dividerTween = Tween.Play(inlineDivider, { BackgroundTransparency = 1 }, Tween.Fast, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			inlineTween = Tween.Play(inlineClip, { Size = UDim2.new(1, 0, 0, 0) }, 0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			Tween.Then(inlineTween, function()
				if openGen == myGen and not isOpen then
					inlineClip.Visible = false
				end
			end)
			return
		end
		Transition.Unmount(popup, 0.94, function()
			if openGen == myGen and not isOpen then
				popup.Visible = false
			end
		end)
	end

	function self:Open()
		if isOpen or isDisabledOrLocked(self) then
			return
		end
		isOpen = true
		openGen += 1

		for _, entry in ipairs(optionRows) do
			entry.Hovered = false
		end
		if searchBox then
			searchBox.Text = ""
			searchQuery = ""
			applyFilter()
		end
		updateOptionVisuals(false)

		if chevron then
			Tween.Play(chevron, { Rotation = chevronBaseRot + 180 }, Tween.Fast)
		end

		if mode == "Inline" then
			cancelInlineTween()
			popup.Visible = false
			popupInner.Parent = inlineClip
			local targetClipH = resizePopup(false, false)
			local tNow = Theme.Current
			Theme.Bind(inlineDivider, {
				BackgroundColor3 = "Divider",
				BackgroundTransparency = "DividerTransparency",
			})
			inlineDivider.BackgroundTransparency = tNow and tNow.DividerTransparency or 0.85
			inlineClip.Size = UDim2.new(1, 0, 0, 0)
			inlineClip.Visible = true
			inlineTween = Tween.Play(inlineClip, { Size = UDim2.new(1, 0, 0, targetClipH) }, Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			return
		end

		inlineClip.Visible = false
		inlineClip.Size = UDim2.new(1, 0, 0, 0)
		popupInner.Parent = popup
		resizePopup()
		popup.Visible = true

		if ctx.OpenPopup then
			if ctx.PopupLayer then
				popup.Parent = ctx.PopupLayer
			end
			ctx.OpenPopup(popupId, popup, trigger, handleClosedState)
		else
			placePopupFallback()
			fallbackOutsideConn = Services.UserInputService.InputBegan:Connect(function(input)
				if input.KeyCode == Enum.KeyCode.Escape then
					self:Close()
				elseif Util.IsPointer(input) then
					local pos = Util.MousePosition()
					local pPos, pSize = popup.AbsolutePosition, popup.AbsoluteSize
					local tPos, tSize = trigger.AbsolutePosition, trigger.AbsoluteSize
					local insidePopup = pos.X >= pPos.X and pos.X <= pPos.X + pSize.X and pos.Y >= pPos.Y and pos.Y <= pPos.Y + pSize.Y
					local insideTrigger = pos.X >= tPos.X and pos.X <= tPos.X + tSize.X and pos.Y >= tPos.Y and pos.Y <= tPos.Y + tSize.Y
					if not insidePopup and not insideTrigger then
						self:Close()
					end
				end
			end)
		end

		Transition.Mount(popup, 0.94)
	end

	function self:Close()
		if not isOpen then
			return
		end
		local wasPopup = (mode == "Popup")
		handleClosedState()
		if wasPopup and ctx.ClosePopup then
			ctx.ClosePopup(popupId)
		end
	end

	function self:SetMode(newMode)
		local resolved
		if newMode == true then
			resolved = "Inline"
		elseif newMode == false then
			resolved = "Popup"
		elseif type(newMode) == "string" then
			local lower = string.lower(newMode)
			if lower == "inline" or lower == "expand" or lower == "push" then
				resolved = "Inline"
			else
				resolved = "Popup"
			end
		else
			resolved = "Popup"
		end
		if resolved == mode then
			return
		end
		if isOpen then
			self:Close()
		end
		cancelInlineTween()
		mode = resolved
		self.Mode = mode
		if mode == "Inline" then
			popup.Visible = false
			inlineClip.Size = UDim2.new(1, 0, 0, 0)
			inlineClip.Visible = false
			popupInner.Parent = inlineClip
		else
			inlineClip.Visible = false
			inlineClip.Size = UDim2.new(1, 0, 0, 0)
			popupInner.Parent = popup
		end
	end

	function self:GetMode()
		return mode
	end

	function self:Set(val, silent)
		if multi then
			table.clear(selectedMap)
			if type(val) == "table" then
				local isArray = #val > 0
				if isArray then
					for _, v in ipairs(val) do
						local found = findItemByInput(v)
						if found then
							selectedMap[found] = true
						end
					end
				else
					for k, flag in pairs(val) do
						if flag == true then
							local found = findItemByInput(k)
							if found then
								selectedMap[found] = true
							end
						end
					end
				end
			elseif val ~= nil then
				local found = findItemByInput(val)
				if found then
					selectedMap[found] = true
				end
			end
		else
			selectedSingle = findItemByInput(val)
			if not selectedSingle and not allowNull and #items > 0 and val ~= nil then
				selectedSingle = items[1]
			end
		end
		fireSelection(silent == true)
	end

	function self:Get()
		return getSelectedValues()
	end

	function self:SetValues(list)
		local prev = getSelectedValues()
		items = normalizeList(list)
		rebuildOptions()
		if multi then
			self:Set(prev, true)
		else
			local found = findItemByInput(prev)
			if found then
				selectedSingle = found
			elseif not allowNull and #items > 0 then
				selectedSingle = items[1]
			else
				selectedSingle = nil
			end
			self.Value = getSelectedValues()
			updateSummary()
			updateOptionVisuals()
		end
	end
	self.Refresh = self.SetValues

	trigger.Activated:Connect(function()
		if isDisabledOrLocked(self) or Transition.IsOverlayBlocking(trigger) then
			return
		end
		Transition.Ripple(trigger, nil, "Accent")
		if isOpen then
			self:Close()
		else
			self:Open()
		end
	end)

	-- Wrap Base lifecycle methods to ensure row updates + popup dismissal
	local baseSetTitle = self.SetTitle
	function self:SetTitle(text)
		if baseSetTitle then
			pcall(baseSetTitle, self, text)
		end
		if row.TitleLabel then
			row.TitleLabel.Text = tostring(text or "")
		end
	end

	local baseSetDesc = self.SetDesc
	function self:SetDesc(text)
		if baseSetDesc then
			pcall(baseSetDesc, self, text)
		end
		if row.DescLabel then
			local str = text and tostring(text) or ""
			row.DescLabel.Text = str
			row.DescLabel.Visible = str ~= ""
		end
	end

	local baseSetDisabled = self.SetDisabled
	function self:SetDisabled(disabled)
		self.Disabled = disabled == true
		if disabled then
			self:Close()
		end
		if baseSetDisabled then
			pcall(baseSetDisabled, self, disabled)
		end
	end

	local baseLock = self.Lock
	function self:Lock(reason)
		self.Locked = true
		self:Close()
		if baseLock then
			pcall(baseLock, self, reason)
		end
	end

	local baseUnlock = self.Unlock
	function self:Unlock()
		self.Locked = false
		if baseUnlock then
			pcall(baseUnlock, self)
		end
	end

	self.Maid:Give(function()
		self:Close()
		cancelInlineTween()
		if fallbackOutsideConn then
			fallbackOutsideConn:Disconnect()
			fallbackOutsideConn = nil
		end
		popup:Destroy()
	end)

	if mode == "Inline" then
		popupInner.Parent = inlineClip
		popupInner.Position = UDim2.fromOffset(0, 1)
	end

	rebuildOptions()
	if opts.Default ~= nil then
		self:Set(opts.Default, true)
	elseif not multi and not allowNull and #items > 0 then
		selectedSingle = items[1]
		self.Value = selectedSingle.Value
		updateSummary()
		updateOptionVisuals()
	else
		self.Value = getSelectedValues()
		updateSummary()
	end

	return self
end

return Dropdown
end

__modules["Elements/Input"] = function()
--[[
	Bali UI · Elements/Input
	Obsidian glass text input with focus accent glow, numeric filtering,
	password mask toggle (eye/eye-off), clear button, and Live/Finished modes.
]]

local Util = require("Core/Util")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")

local Input = {}

local BULLET = "●"

local function splitUtf8(str)
	local chars = {}
	local ok = pcall(function()
		for _, cp in utf8.codes(str) do
			table.insert(chars, utf8.char(cp))
		end
	end)
	if not ok then
		for i = 1, #str do
			chars[i] = string.sub(str, i, i)
		end
	end
	return chars
end

local function countCharsBeforeByte(str, bytePos)
	if not bytePos or bytePos <= 1 then
		return 0
	end
	local count = 0
	local ok = pcall(function()
		for pos in utf8.codes(str) do
			if pos < bytePos then
				count += 1
			else
				break
			end
		end
	end)
	if not ok then
		return math.max(0, bytePos - 1)
	end
	return count
end

local function reconcileMasked(oldReal, displayedText, cursorBytePos)
	if displayedText == "" then
		return ""
	end
	local realChars = splitUtf8(oldReal)
	local dispChars = splitUtf8(displayedText)

	local p = 0
	while p < #dispChars and dispChars[p + 1] == BULLET do
		p += 1
	end

	local s = 0
	while (#dispChars - s) > p and dispChars[#dispChars - s] == BULLET do
		s += 1
	end

	if p + s == #dispChars then
		if #dispChars == #realChars then
			return oldReal
		elseif #dispChars < #realChars then
			local delCount = #realChars - #dispChars
			local k = countCharsBeforeByte(displayedText, cursorBytePos)
			if cursorBytePos == nil or cursorBytePos < 0 then
				k = #dispChars
			end
			k = Util.Clamp(k, 0, #dispChars)
			local head = k > 0 and table.concat(realChars, "", 1, k) or ""
			local tailStart = k + delCount + 1
			local tail = tailStart <= #realChars and table.concat(realChars, "", tailStart, #realChars) or ""
			return head .. tail
		else
			-- Extra bullets pasted/typed: keep oldReal
			return oldReal
		end
	end

	local mid = table.concat(dispChars, "", p + 1, #dispChars - s)
	local safeP = math.min(p, #realChars)
	local safeTailStart = math.max(safeP + 1, #realChars - s + 1)
	local head = safeP > 0 and table.concat(realChars, "", 1, safeP) or ""
	local tail = safeTailStart <= #realChars and table.concat(realChars, "", safeTailStart, #realChars) or ""
	return head .. mid .. tail
end

local function filterNumeric(text, allowDecimal)
	local out = {}
	local seenDot = false
	for i = 1, #text do
		local ch = string.sub(text, i, i)
		if ch >= "0" and ch <= "9" then
			table.insert(out, ch)
		elseif ch == "-" and #out == 0 then
			table.insert(out, ch)
		elseif allowDecimal and ch == "." and not seenDot then
			seenDot = true
			table.insert(out, ch)
		end
	end
	return table.concat(out)
end

function Input.new(parent, opts, ctx)
	opts = Util.Options(opts, { Default = "" }, "Title")
	local element = Base.New("Input", parent, opts, ctx)

	local isNumeric = (opts.Numeric == true or opts.Integer == true)
	local allowDecimal = (opts.Integer ~= true)
	local isMaskFeature = (opts.Mask == true or opts.Password == true)
	local masked = isMaskFeature
	local clearable = (opts.Clearable == true)
	local isLive = (opts.Live == true)
	if opts.Finished == false then
		isLive = true
	end
	local maxLength = tonumber(opts.MaxLength)

	local realText = tostring(opts.Default or "")
	if isNumeric then
		realText = filterNumeric(realText, allowDecimal)
	end
	if maxLength and #realText > maxLength then
		realText = string.sub(realText, 1, maxLength)
	end
	element.Value = realText

	local card = Base.Card(parent, { Padding = 0 })

	local body = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 10, 12, 12, 12 },
		ZIndex = 2,
		Parent = card.Frame,
	})

	Create.List(body, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 8,
	})

	local titleText = tostring(opts.Title or "")
	local descText = tostring(opts.Description or opts.Desc or "")

	local header = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Visible = (titleText ~= "" or descText ~= "" or (opts.Icon ~= nil and opts.Icon ~= "")),
		Parent = body,
	})

	Create.List(header, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 8,
	})

	local iconWidth = 0
	if opts.Icon and opts.Icon ~= "" and opts.Icon ~= false then
		Icons.Create(opts.Icon, {
			Size = UDim2.fromOffset(17, 17),
			Color = opts.IconColor or "SubText",
			LayoutOrder = 1,
			Parent = header,
		})
		iconWidth = 17
	end

	local textCol = Create.New("Frame", {
		Name = "TextColumn",
		Size = UDim2.new(1, iconWidth > 0 and -(iconWidth + 8) or 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		Parent = header,
	})

	Create.List(textCol, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 2,
	})

	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "Medium",
		TextSize = 13,
		Color = "Text",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Visible = titleText ~= "",
		Parent = textCol,
	})

	local descLabel = Create.Text({
		Name = "Description",
		Text = descText,
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = descText ~= "",
		Parent = textCol,
	})

	-- Field container
	local multiline = (opts.Multiline == true)
	local boxHeight = multiline and (opts.Height or 76) or 36

	local fieldBox = Create.New("Frame", {
		Name = "FieldBox",
		Size = UDim2.new(1, 0, 0, boxHeight),
		Theme = { BackgroundColor3 = "Field" },
		Corner = 8,
		Padding = multiline and { 8, 10, 8, 10 } or { 0, 10, 0, 10 },
		LayoutOrder = 2,
		Parent = body,
	})

	local fieldStroke = Create.Stroke(fieldBox, {
		Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
		Thickness = 1,
	})

	Create.List(fieldBox, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = multiline and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Center,
		Gap = 6,
	})

	local leadingIconWidth = 0
	if opts.BoxIcon and opts.BoxIcon ~= "" then
		Icons.Create(opts.BoxIcon, {
			Size = UDim2.fromOffset(15, 15),
			Color = "Muted",
			LayoutOrder = 1,
			Parent = fieldBox,
		})
		leadingIconWidth = 15 + 6
	end

	local function maskedString(s)
		local len = #splitUtf8(s)
		return string.rep(BULLET, len)
	end

	local textBox = Create.New("TextBox", {
		Name = "TextBox",
		Size = UDim2.new(1, -leadingIconWidth, 1, 0),
		BackgroundTransparency = 1,
		Text = masked and maskedString(realText) or realText,
		PlaceholderText = tostring(opts.Placeholder or "Enter value..."),
		TextSize = 13,
		Font = "Regular",
		Theme = {
			TextColor3 = "Text",
			PlaceholderColor3 = "Muted",
		},
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = multiline and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center,
		MultiLine = multiline,
		TextWrapped = multiline,
		ClipsDescendants = true,
		ClearTextOnFocus = (opts.ClearOnFocus == true),
		LayoutOrder = 2,
		Parent = fieldBox,
	})

	local trailingWrap = Create.New("Frame", {
		Name = "Trailing",
		Size = UDim2.fromOffset(0, 24),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		LayoutOrder = 3,
		Parent = fieldBox,
	})

	Create.List(trailingWrap, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 4,
	})

	local clearBtn, eyeBtn, eyeIcon

	if clearable then
		clearBtn = Create.New("TextButton", {
			Name = "ClearButton",
			Size = UDim2.fromOffset(22, 22),
			Theme = { BackgroundColor3 = "Tile" },
			BackgroundTransparency = 1,
			Corner = 6,
			Text = "",
			AutoButtonColor = false,
			LayoutOrder = 1,
			Visible = (realText ~= ""),
			ZIndex = 4,
			Parent = trailingWrap,
		})
		Icons.Create("x", {
			Size = UDim2.fromOffset(14, 14),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Color = "SubText",
			Parent = clearBtn,
		})
		element.Maid:Give(clearBtn.MouseEnter:Connect(function()
			clearBtn.BackgroundTransparency = 0.4
		end))
		element.Maid:Give(clearBtn.MouseLeave:Connect(function()
			clearBtn.BackgroundTransparency = 1
		end))
	end

	if isMaskFeature then
		eyeBtn = Create.New("TextButton", {
			Name = "MaskButton",
			Size = UDim2.fromOffset(22, 22),
			Theme = { BackgroundColor3 = "Tile" },
			BackgroundTransparency = 1,
			Corner = 6,
			Text = "",
			AutoButtonColor = false,
			LayoutOrder = 2,
			ZIndex = 4,
			Parent = trailingWrap,
		})
		eyeIcon = Icons.Create(masked and "eye-off" or "eye", {
			Size = UDim2.fromOffset(14, 14),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Color = "SubText",
			Parent = eyeBtn,
		})
		element.Maid:Give(eyeBtn.MouseEnter:Connect(function()
			eyeBtn.BackgroundTransparency = 0.4
		end))
		element.Maid:Give(eyeBtn.MouseLeave:Connect(function()
			eyeBtn.BackgroundTransparency = 1
		end))
	end

	local function syncBoxWidth()
		local trailingW = math.ceil(trailingWrap.AbsoluteSize.X)
		local extraGap = trailingW > 0 and (trailingW + 6) or 0
		textBox.Size = UDim2.new(1, -(leadingIconWidth + extraGap), 1, 0)
	end

	element.Maid:Give(trailingWrap:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncBoxWidth))
	task.defer(syncBoxWidth)

	local guard = false
	local focused = false
	local lastCommitted = realText

	local function syncTrailingState()
		if clearBtn then
			clearBtn.Visible = (realText ~= "") and not element.Disabled and not element.Locked
		end
		syncBoxWidth()
	end

	local function commit(val, enterPressed, forceFire)
		local nextVal = tostring(val or "")
		if isNumeric then
			nextVal = filterNumeric(nextVal, allowDecimal)
		end
		if maxLength and #nextVal > maxLength then
			nextVal = string.sub(nextVal, 1, maxLength)
		end

		local changed = (nextVal ~= lastCommitted)
		realText = nextVal
		lastCommitted = nextVal
		element.Value = realText

		guard = true
		textBox.Text = masked and maskedString(realText) or realText
		guard = false
		syncTrailingState()

		if changed or forceFire then
			element.Changed:Fire(realText, enterPressed)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, realText, enterPressed)
			end
		end
	end

	element.Maid:Give(textBox:GetPropertyChangedSignal("Text"):Connect(function()
		if guard then
			return
		end
		local rawDisp = textBox.Text
		local nextReal
		if masked then
			nextReal = reconcileMasked(realText, rawDisp, textBox.CursorPosition)
		else
			nextReal = rawDisp
		end

		if isNumeric then
			nextReal = filterNumeric(nextReal, allowDecimal)
		end
		if maxLength and #nextReal > maxLength then
			nextReal = string.sub(nextReal, 1, maxLength)
		end

		realText = nextReal
		element.Value = realText

		local expectedDisp = masked and maskedString(realText) or realText
		if textBox.Text ~= expectedDisp then
			local pos = textBox.CursorPosition
			guard = true
			textBox.Text = expectedDisp
			if masked and pos > 0 then
				-- Keep cursor consistent with bullet byte length
				textBox.CursorPosition = math.min(#expectedDisp + 1, pos)
			end
			guard = false
		end

		syncTrailingState()

		if isLive and realText ~= lastCommitted then
			lastCommitted = realText
			element.Changed:Fire(realText, false)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, realText, false)
			end
		end
	end))

	element.Maid:Give(textBox.Focused:Connect(function()
		if element.Disabled or element.Locked then
			textBox:ReleaseFocus()
			return
		end
		focused = true
		Tween.Play(fieldStroke, {
			Color = Theme.Current.Accent,
			Transparency = 0.15,
			Thickness = 1.5,
		}, Tween.Fast, Enum.EasingStyle.Quad)
		Tween.Play(fieldBox, {
			BackgroundColor3 = Theme.Current.FieldHover,
		}, Tween.Fast, Enum.EasingStyle.Quad)
	end))

	element.Maid:Give(textBox.FocusLost:Connect(function(enterPressed)
		focused = false
		Tween.Play(fieldStroke, {
			Color = Theme.Current.Stroke,
			Transparency = Theme.Current.StrokeTransparency,
			Thickness = 1,
		}, Tween.Fast, Enum.EasingStyle.Quad)
		Tween.Play(fieldBox, {
			BackgroundColor3 = Theme.Current.Field,
		}, Tween.Fast, Enum.EasingStyle.Quad)

		if not isLive then
			if opts.EnterOnly and not enterPressed then
				return
			end
			commit(realText, enterPressed, enterPressed == true)
		end
	end))

	element.Maid:Give(Theme.Changed:Connect(function(t)
		if element._destroyed then
			return
		end
		if focused then
			fieldStroke.Color = t.Accent
			fieldBox.BackgroundColor3 = t.FieldHover
		end
	end))

	if clearBtn then
		element.Maid:Give(clearBtn.Activated:Connect(function(inputObj)
			if element.Disabled or element.Locked then
				return
			end
			Transition.Ripple(clearBtn, inputObj, "Accent")
			commit("", false, false)
		end))
	end

	if eyeBtn then
		element.Maid:Give(eyeBtn.Activated:Connect(function(inputObj)
			if element.Disabled or element.Locked then
				return
			end
			Transition.Ripple(eyeBtn, inputObj, "Accent")
			masked = not masked
			if eyeIcon then
				Icons.Set(eyeIcon, masked and "eye-off" or "eye")
			end
			guard = true
			textBox.Text = masked and maskedString(realText) or realText
			guard = false
		end))
	end

	function element:Set(str, silent)
		local nextVal = tostring(str or "")
		if isNumeric then
			nextVal = filterNumeric(nextVal, allowDecimal)
		end
		if maxLength and #nextVal > maxLength then
			nextVal = string.sub(nextVal, 1, maxLength)
		end
		local changed = (nextVal ~= realText)
		realText = nextVal
		lastCommitted = nextVal
		self.Value = realText
		guard = true
		textBox.Text = masked and maskedString(realText) or realText
		guard = false
		syncTrailingState()
		if changed and not silent then
			self.Changed:Fire(realText, false)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, realText, false)
			end
		end
	end

	function element:Get()
		return realText
	end

	function element:Focus()
		if not self.Disabled and not self.Locked then
			textBox:CaptureFocus()
		end
	end

	element._onDisabled = function(disabled)
		textBox.TextEditable = not disabled
		if disabled and textBox:IsFocused() then
			textBox:ReleaseFocus()
		end
		syncTrailingState()
	end

	card.TitleLabel = titleLabel
	card.DescLabel = descLabel
	function card:SetTitle(s)
		local txt = tostring(s or "")
		titleLabel.Text = txt
		titleLabel.Visible = (txt ~= "")
		header.Visible = (txt ~= "" or descLabel.Text ~= "" or iconWidth > 0)
	end
	function card:SetDesc(s)
		local txt = tostring(s or "")
		descLabel.Text = txt
		descLabel.Visible = (txt ~= "")
		header.Visible = (titleLabel.Text ~= "" or txt ~= "" or iconWidth > 0)
	end

	element:BindUI(card)
	return element
end

return Input
end

__modules["Elements/Keybind"] = function()
--[[
	Bali UI · Elements/Keybind
	Interactive keybind row with key capture pulse state, Mode pill & PopupLayer mode menu,
	Systems/Input integration, and Systems/KeybindList live synchronization.
]]

local Services = require("Core/Services")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Tween = require("Core/Tween")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")
local Input = require("Systems/Input")
local KeybindList = require("Systems/KeybindList")
local Tooltip = require("Systems/Tooltip")

local Keybind = {}
Keybind.__index = Keybind

local MODES = { "Toggle", "Hold", "Always" }

local function normalizeMode(mode)
	if type(mode) == "string" then
		local lower = string.lower(mode)
		if lower == "toggle" then
			return "Toggle"
		elseif lower == "hold" then
			return "Hold"
		elseif lower == "always" then
			return "Always"
		end
	end
	return "Toggle"
end

local function resolveKeySafe(key)
	if type(key) == "string" then
		key = key:gsub("^Enum%.KeyCode%.", ""):gsub("^Enum%.UserInputType%.", "")
	end
	return Util.ResolveKey(key)
end

local function isDisabledOrLocked(self)
	return self.Disabled == true or self.Locked == true or self._disabled == true or self._locked == true
end

function Keybind.new(parent, opts, ctx)
	opts = Util.Options(opts, {
		Title = "Keybind",
		Description = nil,
		Default = nil,
		Mode = "Toggle",
		AllowMouse = true,
		SyncList = true,
		Callback = nil,
		ChangedCallback = nil,
		Flag = nil,
		Tooltip = nil,
	}, "Title")
	ctx = ctx or {}

	local self = Base.New("Keybind", parent, opts, ctx)
	local rowParent = (typeof(self.Frame) == "Instance") and self.Frame or parent
	local rightWidth = 114
	local rowOpts = table.clone(opts)
	if rowOpts.IconBadge == nil then
		rowOpts.IconBadge = false
	end
	local row = Base.Row(rowParent, rowOpts, rightWidth)

	if typeof(self.Frame) ~= "Instance" then
		self.Frame = row.Frame
	else
		self.Frame.BackgroundTransparency = 1
		self.Frame.Size = UDim2.new(1, 0, 0, 0)
		self.Frame.AutomaticSize = Enum.AutomaticSize.Y
	end

	if self.BindUI then
		self:BindUI(row)
	end

	self._row = row
	self.Row = row
	self.TitleLabel = row.TitleLabel
	self.DescLabel = row.DescLabel
	self.Stroke = row.Stroke
	self.LockOverlay = row.LockOverlay

	if opts.Tooltip and Tooltip and Tooltip.Bind then
		pcall(Tooltip.Bind, row.Frame, opts.Tooltip)
	end

	local bindId = "Keybind_" .. Util.RandomString(8)
	local currentTitle = tostring(opts.Title or "Keybind")
	local currentKey = resolveKeySafe(opts.Default)
	local currentMode = normalizeMode(opts.Mode)
	local allowMouse = opts.AllowMouse ~= false
	local syncList = opts.SyncList ~= false
	local activeState = currentMode == "Always"

	local listening = false
	local stopPulse = nil
	local modeOpen = false
	local modePopupId = "KeybindMode_" .. Util.RandomString(8)
	local modeOpenGen = 0

	self.Value = currentKey
	self.Mode = currentMode

	-- Right container holds Mode pill + Key chip aligned cleanly on right
	local controls = Create.New("Frame", {
		Name = "Controls",
		Size = UDim2.new(1, 0, 0, 28),
		BackgroundTransparency = 1,
		Parent = row.Right,
	})
	Create.List(controls, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 6,
		HAlign = Enum.HorizontalAlignment.Right,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local modePill = Create.New("TextButton", {
		Name = "ModePill",
		Size = UDim2.fromOffset(0, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 1,
		Text = "",
		Corner = 7,
		Padding = { 0, 8, 0, 8 },
		BackgroundTransparency = 0.45,
		Theme = { BackgroundColor3 = "Field" },
		Parent = controls,
	})
	local modeStroke = Create.Stroke(modePill, {
		Theme = {
			Color = "Stroke",
			Transparency = function(t)
				return math.min((t.StrokeTransparency or 0.85) + 0.08, 0.94)
			end,
		},
	})
	local modeLabel = Create.Text({
		Name = "ModeText",
		Size = UDim2.fromOffset(0, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		Position = UDim2.fromScale(0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0),
		Text = currentMode,
		TextSize = 11,
		Font = "Medium",
		TextXAlignment = Enum.TextXAlignment.Center,
		Color = "SubText",
		Parent = modePill,
	})
	Transition.Hover(modePill, modePill, "Field", "FieldHover", modeStroke)

	local keyChip = Create.New("TextButton", {
		Name = "KeyChip",
		Size = UDim2.fromOffset(34, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Text = "",
		Corner = 7,
		Padding = { 0, 9, 0, 9 },
		Theme = { BackgroundColor3 = "Field" },
		Parent = controls,
	})
	local keyStroke = Create.Stroke(keyChip, {
		Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
	})
	local keyLabel = Create.Text({
		Name = "KeyText",
		Size = UDim2.fromOffset(0, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		Position = UDim2.fromScale(0.5, 0),
		AnchorPoint = Vector2.new(0.5, 0),
		Text = Util.KeyName(currentKey),
		TextSize = 11,
		Font = "SemiBold",
		TextXAlignment = Enum.TextXAlignment.Center,
		Color = currentKey and "Text" or "Muted",
		Parent = keyChip,
	})
	Transition.Hover(keyChip, keyChip, "Field", "FieldHover", keyStroke)

	-- Floating Mode selection menu in PopupLayer
	local shadowInfo = Assets.Shadow()
	local shadowInset = shadowInfo.Inset or 24
	local modePopup = Create.New("Frame", {
		Name = modePopupId,
		Size = UDim2.fromOffset(122, 108),
		Visible = false,
		ZIndex = 110,
		Corner = 9,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.min(t.CardTransparency or 0.12, 0.04)
			end,
		},
	})
	Create.GlassStroke(modePopup, 0.06)

	Create.New("ImageLabel", {
		Name = "Shadow",
		Size = UDim2.new(1, shadowInset * 2, 1, shadowInset * 2),
		Position = UDim2.fromOffset(-shadowInset, -shadowInset),
		Image = shadowInfo.Image,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = shadowInfo.Slice,
		ZIndex = 109,
		Theme = {
			ImageColor3 = "Shadow",
			ImageTransparency = "ShadowTransparency",
		},
		Parent = modePopup,
	})

	local modePopupInner = Create.New("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 111,
		Padding = { 6, 6, 6, 6 },
		Parent = modePopup,
	})
	Create.List(modePopupInner, { Gap = 3 })

	local modeButtons = {}

	local function syncKeybindList()
		if not syncList or not KeybindList or not KeybindList.Update then
			return
		end
		KeybindList.Update(bindId, {
			Title = currentTitle,
			KeyName = Util.KeyName(currentKey),
			Mode = currentMode,
			Active = activeState,
		})
	end

	local function updateChipVisuals()
		if not listening then
			keyLabel.Text = Util.KeyName(currentKey)
			Theme.Bind(keyLabel, { TextColor3 = currentKey and "Text" or "Muted" })
			Theme.Bind(keyStroke, { Color = "Stroke", Transparency = "StrokeTransparency" })
		end
		modeLabel.Text = currentMode
		for modeName, entry in pairs(modeButtons) do
			local active = modeName == currentMode
			Theme.Bind(entry.Button, {
				BackgroundColor3 = active and "Accent" or "TileHover",
				BackgroundTransparency = active and function() return 0.84 end or function() return entry.Hovered and 0.4 or 1 end,
			})
			Theme.Bind(entry.Label, {
				TextColor3 = active and "Text" or "SubText",
				FontFace = active and "@SemiBold" or "@Medium",
			})
			if entry.Check then
				entry.Check.Visible = active
			end
		end
	end

	local inputHandle
	local function onTriggered(active)
		activeState = active == true
		syncKeybindList()
		if opts.Callback then
			Util.Spawn(opts.Callback, activeState)
		end
	end

	if Input and Input.RegisterKeybind then
		inputHandle = Input.RegisterKeybind(bindId, currentKey, onTriggered, currentMode)
		if inputHandle and inputHandle.Active ~= nil then
			activeState = inputHandle.Active == true
		end
	end

	if syncList and KeybindList and KeybindList.Register then
		KeybindList.Register(bindId, {
			Title = currentTitle,
			KeyName = Util.KeyName(currentKey),
			Mode = currentMode,
			Active = activeState,
		})
	end

	local fallbackModeConn
	local function handleModeClosed()
		if not modeOpen then
			return
		end
		modeOpen = false
		modeOpenGen += 1
		local myGen = modeOpenGen
		if fallbackModeConn then
			fallbackModeConn:Disconnect()
			fallbackModeConn = nil
		end
		Transition.Unmount(modePopup, 0.94, function()
			if modeOpenGen == myGen and not modeOpen then
				modePopup.Visible = false
			end
		end)
	end

	local function closeModeMenu()
		if not modeOpen then
			return
		end
		handleModeClosed()
		if ctx.ClosePopup then
			ctx.ClosePopup(modePopupId)
		end
	end

	local function openModeMenu()
		if modeOpen or isDisabledOrLocked(self) then
			return
		end
		modeOpen = true
		modeOpenGen += 1
		modePopup.Visible = true
		if ctx.OpenPopup then
			if ctx.PopupLayer then
				modePopup.Parent = ctx.PopupLayer
			end
			ctx.OpenPopup(modePopupId, modePopup, modePill, handleModeClosed)
		else
			local layer = ctx.PopupLayer or row.Frame:FindFirstAncestorOfClass("ScreenGui")
			if layer then
				modePopup.Parent = layer
				local view = layer.AbsoluteSize
				local aPos, aSize = modePill.AbsolutePosition, modePill.AbsoluteSize
				local px = Util.Clamp(aPos.X + aSize.X - 122, 8, math.max(8, view.X - 130))
				local py = aPos.Y + aSize.Y + 6
				if py + 108 > view.Y - 8 then
					py = math.max(8, aPos.Y - 114)
				end
				modePopup.Position = UDim2.fromOffset(px, py)
				fallbackModeConn = Services.UserInputService.InputBegan:Connect(function(input)
					if input.KeyCode == Enum.KeyCode.Escape then
						closeModeMenu()
					elseif Util.IsPointer(input) then
						local pos = Util.MousePosition()
						local pPos, pSize = modePopup.AbsolutePosition, modePopup.AbsoluteSize
						if pos.X < pPos.X or pos.X > pPos.X + pSize.X or pos.Y < pPos.Y or pos.Y > pPos.Y + pSize.Y then
							closeModeMenu()
						end
					end
				end)
			end
		end
		Transition.Mount(modePopup, 0.94)
	end

	for index, modeName in ipairs(MODES) do
		local btn = Create.New("TextButton", {
			Name = "Mode_" .. modeName,
			Size = UDim2.new(1, 0, 0, 28),
			LayoutOrder = index,
			ZIndex = 112,
			Corner = 6,
			Padding = { 0, 8, 0, 8 },
			BackgroundTransparency = 1,
			Theme = { BackgroundColor3 = "TileHover" },
			Parent = modePopupInner,
		})
		local lbl = Create.Text({
			Size = UDim2.new(1, -18, 1, 0),
			Text = modeName,
			TextSize = 12,
			Font = "Medium",
			Color = "SubText",
			ZIndex = 113,
			Parent = btn,
		})
		local chk = Icons.Create("check", {
			Size = UDim2.fromOffset(14, 14),
			Position = UDim2.new(1, 0, 0.5, 0),
			AnchorPoint = Vector2.new(1, 0.5),
			Color = "Accent",
			ZIndex = 113,
			Parent = btn,
		})
		local entry = { Button = btn, Label = lbl, Check = chk, Hovered = false }
		btn.MouseEnter:Connect(function()
			entry.Hovered = true
			if currentMode ~= modeName then
				Theme.Bind(btn, { BackgroundColor3 = "TileHover", BackgroundTransparency = function() return 0.45 end })
			end
		end)
		btn.MouseLeave:Connect(function()
			entry.Hovered = false
			if currentMode ~= modeName then
				Theme.Bind(btn, { BackgroundColor3 = "TileHover", BackgroundTransparency = function() return 1 end })
			end
		end)
		btn.Activated:Connect(function()
			Transition.Ripple(btn, nil, "Accent")
			self:Set(currentKey, modeName, false)
			closeModeMenu()
		end)
		modeButtons[modeName] = entry
	end

	local function stopListening()
		if not listening then
			return
		end
		listening = false
		if stopPulse then
			pcall(stopPulse)
			stopPulse = nil
		end
		updateChipVisuals()
	end

	local function startListening()
		if isDisabledOrLocked(self) then
			return
		end
		closeModeMenu()
		listening = true
		keyLabel.Text = "Listening..."
		Theme.Bind(keyLabel, { TextColor3 = "Accent" })
		Theme.Bind(keyStroke, { Color = "Accent", Transparency = function() return 0.25 end })
		if stopPulse then
			pcall(stopPulse)
		end
		stopPulse = Transition.Pulse(keyStroke, "Transparency", 0.15, 0.72, 0.75)

		if Input and Input.CaptureKey then
			Input.CaptureKey(function(captured, cancelled)
				if not listening then
					return
				end
				if cancelled or captured == Enum.KeyCode.Escape then
					stopListening()
					return
				end
				if captured == nil or captured == Enum.KeyCode.Backspace or captured == Enum.KeyCode.Delete then
					stopListening()
					self:Set(nil, currentMode, false)
					return
				end
				if not allowMouse and typeof(captured) == "EnumItem" and captured.EnumType == Enum.UserInputType then
					-- Mouse binds disabled: keep waiting for a keyboard key
					stopListening()
					task.defer(startListening)
					return
				end
				stopListening()
				self:Set(captured, currentMode, false)
			end, { AllowMouse = allowMouse })
		end
	end

	local function cycleMode()
		if isDisabledOrLocked(self) then
			return
		end
		local idx = table.find(MODES, currentMode) or 1
		local nextMode = MODES[(idx % #MODES) + 1]
		self:Set(currentKey, nextMode, false)
	end

	keyChip.Activated:Connect(function()
		if isDisabledOrLocked(self) then
			return
		end
		Transition.Ripple(keyChip, nil, "Accent")
		if listening then
			if Input and Input.CancelCapture then
				Input.CancelCapture()
			end
			stopListening()
		else
			startListening()
		end
	end)

	modePill.Activated:Connect(function()
		if isDisabledOrLocked(self) then
			return
		end
		Transition.Ripple(modePill, nil, "Accent")
		if modeOpen then
			closeModeMenu()
		else
			openModeMenu()
		end
	end)

	-- Right-click cycles Mode quickly on both Mode pill and Key chip
	local function bindRightClick(btn)
		btn.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton2 and not isDisabledOrLocked(self) then
				closeModeMenu()
				cycleMode()
			end
		end)
	end
	bindRightClick(modePill)
	bindRightClick(keyChip)

	function self:Set(key, modeOrSilent, silentArg)
		local nextKey = key
		local nextMode = currentMode
		local silent = false

		if type(key) == "table" then
			nextKey = key.Key ~= nil and key.Key or key[1]
			if key.Mode ~= nil then
				nextMode = normalizeMode(key.Mode)
			end
		end
		if type(modeOrSilent) == "boolean" then
			silent = modeOrSilent
		elseif type(modeOrSilent) == "string" then
			nextMode = normalizeMode(modeOrSilent)
			silent = silentArg == true
		elseif silentArg ~= nil then
			silent = silentArg == true
		end

		currentKey = resolveKeySafe(nextKey)
		currentMode = nextMode
		self.Value = currentKey
		self.Mode = currentMode

		if inputHandle then
			if inputHandle.SetKey then
				inputHandle:SetKey(currentKey)
			end
			if inputHandle.SetMode then
				inputHandle:SetMode(currentMode)
			end
			activeState = inputHandle.Active == true or currentMode == "Always"
		else
			activeState = currentMode == "Always"
		end

		updateChipVisuals()
		syncKeybindList()

		if not silent then
			if opts.ChangedCallback then
				Util.Spawn(opts.ChangedCallback, currentKey, currentMode)
			end
			self.Changed:Fire(currentKey, currentMode)
		end
	end

	function self:Get()
		return currentKey, currentMode
	end

	function self:GetState()
		if currentMode == "Always" then
			return true
		end
		if inputHandle and inputHandle.Active ~= nil then
			return inputHandle.Active == true
		end
		return activeState
	end

	local baseSetTitle = self.SetTitle
	function self:SetTitle(text)
		currentTitle = tostring(text or "")
		if baseSetTitle then
			pcall(baseSetTitle, self, text)
		end
		if row.TitleLabel then
			row.TitleLabel.Text = currentTitle
		end
		syncKeybindList()
	end

	local baseSetDesc = self.SetDesc
	function self:SetDesc(text)
		if baseSetDesc then
			pcall(baseSetDesc, self, text)
		end
		if row.DescLabel then
			local str = text and tostring(text) or ""
			row.DescLabel.Text = str
			row.DescLabel.Visible = str ~= ""
		end
	end

	local baseSetDisabled = self.SetDisabled
	function self:SetDisabled(disabled)
		self.Disabled = disabled == true
		if disabled then
			closeModeMenu()
			if listening and Input and Input.CancelCapture then
				Input.CancelCapture()
			end
			stopListening()
		end
		if baseSetDisabled then
			pcall(baseSetDisabled, self, disabled)
		end
	end

	local baseLock = self.Lock
	function self:Lock(reason)
		self.Locked = true
		closeModeMenu()
		if listening and Input and Input.CancelCapture then
			Input.CancelCapture()
		end
		stopListening()
		if baseLock then
			pcall(baseLock, self, reason)
		end
	end

	local baseUnlock = self.Unlock
	function self:Unlock()
		self.Locked = false
		if baseUnlock then
			pcall(baseUnlock, self)
		end
	end

	self.Maid:Give(function()
		closeModeMenu()
		if listening and Input and Input.CancelCapture then
			Input.CancelCapture()
		end
		stopListening()
		if fallbackModeConn then
			fallbackModeConn:Disconnect()
			fallbackModeConn = nil
		end
		if inputHandle and inputHandle.Destroy then
			inputHandle:Destroy()
		end
		if syncList and KeybindList and KeybindList.Unregister then
			KeybindList.Unregister(bindId)
		end
		modePopup:Destroy()
	end)

	updateChipVisuals()
	return self
end

return Keybind
end

__modules["Elements/Segmented"] = function()
--[[
	Bali UI · Elements/Segmented
	Apple-style sliding pill segmented control with optional icons and smooth indicator glide.
]]

local Util = require("Core/Util")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")

local Segmented = {}

local function normalizeItems(values)
	local items = {}
	if type(values) ~= "table" then
		return items
	end
	for index, raw in ipairs(values) do
		if type(raw) == "table" then
			local title = tostring(raw.Title or raw.Name or raw.Text or raw[1] or ("Option " .. index))
			local val = raw.Value ~= nil and raw.Value or title
			table.insert(items, {
				Title = title,
				Icon = raw.Icon,
				Value = val,
			})
		else
			local str = tostring(raw)
			table.insert(items, {
				Title = str,
				Icon = nil,
				Value = raw,
			})
		end
	end
	return items
end

function Segmented.new(parent, opts, ctx)
	opts = Util.Options(opts, { Values = { "One", "Two" } }, "Title")
	local element = Base.New("Segmented", parent, opts, ctx)

	local useAccent = (opts.Accent == true)
	local titleText = tostring(opts.Title or "")
	local descText = tostring(opts.Description or opts.Desc or "")
	local hasHeader = (titleText ~= "" or descText ~= "")

	local container
	local card = nil
	local titleLabel = nil
	local descLabel = nil
	local body

	if hasHeader then
		card = Base.Card(parent, { Padding = 0 })
		container = card.Frame
		body = Create.New("Frame", {
			Name = "Body",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			Padding = { 10, 12, 12, 12 },
			ZIndex = 2,
			Parent = card.Frame,
		})
		Create.List(body, {
			Direction = Enum.FillDirection.Vertical,
			Gap = 8,
		})

		local headerParent = body
		local textLayoutOrder = 1
		local hasHeaderIcon = type(opts.Icon) == "string" and opts.Icon ~= "" and titleText ~= ""
		if hasHeaderIcon then
			local headerRow = Create.New("Frame", {
				Name = "HeaderRow",
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				LayoutOrder = 1,
				Parent = body,
			})
			Create.List(headerRow, {
				Direction = Enum.FillDirection.Horizontal,
				Gap = 10,
				VAlign = Enum.VerticalAlignment.Center,
			})
			Icons.Create(opts.Icon, {
				Name = "Icon",
				Size = UDim2.fromOffset(18, 18),
				Color = "SubText",
				LayoutOrder = 1,
				Parent = headerRow,
			})
			headerParent = headerRow
			textLayoutOrder = 2
		end

		local textCol = Create.New("Frame", {
			Name = "TextColumn",
			Size = hasHeaderIcon and UDim2.new(1, -28, 0, 0) or UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = textLayoutOrder,
			Parent = headerParent,
		})
		Create.List(textCol, {
			Direction = Enum.FillDirection.Vertical,
			Gap = 2,
		})

		titleLabel = Create.Text({
			Name = "Title",
			Text = titleText,
			Font = "Medium",
			TextSize = 13,
			Color = "Text",
			TextWrapped = true,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 1,
			Visible = titleText ~= "",
			Parent = textCol,
		})

		descLabel = Create.Text({
			Name = "Description",
			Text = descText,
			Font = "Regular",
			TextSize = 12,
			Color = "SubText",
			TextWrapped = true,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 2,
			Visible = descText ~= "",
			Parent = textCol,
		})
	else
		container = Create.New("Frame", {
			Name = "Segmented",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			Parent = parent,
		})
		body = container
	end

	local barTrack = Create.New("Frame", {
		Name = "Bar",
		Size = UDim2.new(1, 0, 0, 34),
		Theme = { BackgroundColor3 = "Field" },
		Corner = 9,
		Padding = 3,
		Stroke = {
			Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
			Thickness = 1,
		},
		LayoutOrder = 2,
		Parent = body,
	})

	local inner = Create.New("Frame", {
		Name = "Inner",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Parent = barTrack,
	})

	local indicator = Create.New("Frame", {
		Name = "Indicator",
		Size = UDim2.new(0, 0, 1, 0),
		Position = UDim2.fromScale(0, 0),
		Corner = 6,
		ZIndex = 2,
		Visible = false,
		Parent = inner,
	})

	local indicatorGrad = nil
	if useAccent then
		indicator.BackgroundColor3 = Color3.new(1, 1, 1)
		indicatorGrad = Instance.new("UIGradient")
		indicatorGrad.Color = Theme.AccentSequence()
		indicatorGrad.Rotation = 15
		indicatorGrad.Parent = indicator
		Create.Stroke(indicator, {
			Theme = { Color = "Accent" },
			Transparency = 0.45,
			Thickness = 1,
		})
		element.Maid:Give(Theme.Changed:Connect(function(t)
			if not element._destroyed and indicatorGrad then
				indicatorGrad.Color = Theme.AccentSequence(t)
			end
		end))
	else
		Theme.Bind(indicator, { BackgroundColor3 = "TileHover" })
		Create.Stroke(indicator, {
			Theme = { Color = "Stroke" },
			Transparency = 0.82,
			Thickness = 1,
		})
	end

	local buttonsRow = Create.New("Frame", {
		Name = "Buttons",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 3,
		Parent = inner,
	})

	local GAP = 2
	Create.List(buttonsRow, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = GAP,
	})

	local items = {}
	local segments = {}
	local activeIndex = nil
	local currentValue = nil

	local function resolveIndex(valOrIdx)
		if #items == 0 then
			return nil
		end
		for i, item in ipairs(items) do
			if item.Value == valOrIdx or item.Title == valOrIdx then
				return i
			end
		end
		if type(valOrIdx) == "number" and items[valOrIdx] then
			return valOrIdx
		end
		return nil
	end

	local function updateIndicator(animate)
		local n = #items
		if n == 0 or not activeIndex or not items[activeIndex] then
			indicator.Visible = false
			return
		end
		indicator.Visible = true
		local idx = activeIndex
		local targetSize = UDim2.new(1 / n, -((n - 1) * GAP) / n, 1, 0)
		local targetPos = UDim2.new((idx - 1) / n, ((idx - 1) * GAP) / n, 0, 0)

		if animate then
			Tween.Play(indicator, {
				Size = targetSize,
				Position = targetPos,
			}, Tween.Fast + 0.04, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		else
			indicator.Size = targetSize
			indicator.Position = targetPos
		end

		for i, seg in ipairs(segments) do
			local isActive = (i == activeIndex)
			local textColorKey = isActive and (useAccent and "AccentText" or "Text") or "SubText"
			Theme.Bind(seg.Label, {
				TextColor3 = textColorKey,
				FontFace = isActive and "@SemiBold" or "@Medium",
			})
			if seg.Icon then
				Icons.SetColor(seg.Icon, textColorKey)
			end
		end
	end

	local function rebuild(rawValues, targetDefault)
		for _, seg in ipairs(segments) do
			if seg.Button and seg.Button.Parent then
				seg.Button:Destroy()
			end
		end
		table.clear(segments)
		items = normalizeItems(rawValues)

		local n = #items
		if n == 0 then
			activeIndex = nil
			currentValue = nil
			element.Value = nil
			indicator.Visible = false
			return
		end

		local widthOffset = -((n - 1) * GAP) / n
		for i, item in ipairs(items) do
			local btn = Create.New("TextButton", {
				Name = "Seg_" .. i,
				Size = UDim2.new(1 / n, widthOffset, 1, 0),
				BackgroundTransparency = 1,
				Corner = 6,
				Padding = { 0, 6, 0, 6 },
				Text = "",
				AutoButtonColor = false,
				LayoutOrder = i,
				ZIndex = 4,
				Parent = buttonsRow,
			})

			local content = Create.New("Frame", {
				Name = "Content",
				Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1,
				ClipsDescendants = true,
				Parent = btn,
			})

			Create.List(content, {
				Direction = Enum.FillDirection.Horizontal,
				HAlign = Enum.HorizontalAlignment.Center,
				VAlign = Enum.VerticalAlignment.Center,
				Gap = 5,
			})

			local iconObj = nil
			if item.Icon and item.Icon ~= "" and item.Icon ~= false then
				iconObj = Icons.Create(item.Icon, {
					Size = UDim2.fromOffset(14, 14),
					Color = "SubText",
					LayoutOrder = 1,
					ZIndex = 5,
					Parent = content,
				})
			end

			local lbl = Create.Text({
				Name = "Label",
				Text = item.Title,
				Font = "Medium",
				TextSize = 12,
				Color = "SubText",
				Size = UDim2.fromOffset(0, 0),
				AutomaticSize = Enum.AutomaticSize.XY,
				TextXAlignment = Enum.TextXAlignment.Center,
				TextTruncate = Enum.TextTruncate.AtEnd,
				LayoutOrder = 2,
				ZIndex = 5,
				Parent = content,
			})

			local sizeLimit = Instance.new("UISizeConstraint")
			sizeLimit.MaxSize = Vector2.new(9999, 28)
			sizeLimit.Parent = lbl

			btn.MouseEnter:Connect(function()
				if element.Disabled or element.Locked or activeIndex == i or Util.IsTouchDevice() then
					return
				end
				Theme.Bind(lbl, { TextColor3 = "Text" })
			end)

			btn.MouseLeave:Connect(function()
				if activeIndex ~= i then
					Theme.Bind(lbl, { TextColor3 = "SubText" })
				end
			end)

			btn.Activated:Connect(function(inputObj)
				if element.Disabled or element.Locked then
					return
				end
				Transition.Ripple(btn, inputObj, useAccent and "AccentText" or "Accent")
				element:Set(item.Value, false)
			end)

			segments[i] = {
				Button = btn,
				Label = lbl,
				Icon = iconObj,
			}
		end

		local initialIdx = resolveIndex(targetDefault) or 1
		activeIndex = initialIdx
		currentValue = items[initialIdx].Value
		element.Value = currentValue
		updateIndicator(false)
	end

	rebuild(opts.Values, opts.Default)

	function element:Set(valOrIdx, silent)
		local nextIdx = resolveIndex(valOrIdx)
		if not nextIdx then
			return
		end
		local nextVal = items[nextIdx].Value
		local changed = (nextIdx ~= activeIndex or nextVal ~= currentValue)
		activeIndex = nextIdx
		currentValue = nextVal
		self.Value = currentValue
		updateIndicator(true)
		if changed and not silent then
			self.Changed:Fire(currentValue, activeIndex)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, currentValue, activeIndex)
			end
		end
	end

	function element:Get()
		return currentValue
	end

	function element:SetValues(newValues, defaultOverride)
		local target = defaultOverride ~= nil and defaultOverride or currentValue
		rebuild(newValues, target)
	end

	element._onDisabled = function(disabled)
		for _, seg in ipairs(segments) do
			seg.Button.Active = not disabled
			seg.Label.TextTransparency = disabled and 0.48 or 0
			if seg.Icon then
				Icons.SetTransparency(seg.Icon, disabled and 0.48 or 0)
			end
		end
	end

	if card then
		card.TitleLabel = titleLabel
		card.DescLabel = descLabel
		function card:SetTitle(s)
			local txt = tostring(s or "")
			titleLabel.Text = txt
			titleLabel.Visible = (txt ~= "")
		end
		function card:SetDesc(s)
			local txt = tostring(s or "")
			descLabel.Text = txt
			descLabel.Visible = (txt ~= "")
		end
		element:BindUI(card)
	else
		element:BindUI({
			Frame = container,
			Flash = function()
				Base.FlashFrame(barTrack, nil, "Field")
			end,
		})
	end

	return element
end

return Segmented
end

__modules["Elements/Slider"] = function()
--[[
	Bali UI · Elements/Slider
	Interactive Slider (with editable numeric pill), dual-thumb RangeSlider, and Stepper.
]]

local Services = require("Core/Services")
local Util = require("Core/Util")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")

local SliderModule = {}

local function resolveNumericSpec(opts)
	local step = opts.Step or opts.Increment
	if not step or step <= 0 then
		if opts.Rounding ~= nil and opts.Rounding > 0 then
			step = 10 ^ (-opts.Rounding)
		else
			step = 1
		end
	end
	local decimals = opts.Rounding ~= nil and math.max(0, math.floor(opts.Rounding)) or Util.Decimals(step)
	local minVal = tonumber(opts.Min) or 0
	local maxVal = tonumber(opts.Max) or 100
	if maxVal <= minVal then
		maxVal = minVal + step
	end
	return minVal, maxVal, step, decimals
end

local function createThumb(track, zBase)
	local thumb = Create.New("Frame", {
		Name = "Thumb",
		Size = UDim2.fromOffset(14, 14),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Theme = { BackgroundColor3 = "Knob" },
		Corner = UDim.new(1, 0),
		ZIndex = zBase or 4,
		Parent = track,
	})

	local stroke = Create.Stroke(thumb, {
		Theme = { Color = "Accent" },
		Transparency = 0.25,
		Thickness = 1.5,
	})

	local glowAsset = Assets.Get("Glow")
	local glow
	if glowAsset then
		glow = Create.New("ImageLabel", {
			Name = "Glow",
			Size = UDim2.fromOffset(28, 28),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			BackgroundTransparency = 1,
			Image = glowAsset,
			Theme = { ImageColor3 = "Accent" },
			ImageTransparency = 0.72,
			ZIndex = (zBase or 4) - 1,
			Parent = thumb,
		})
	else
		glow = Create.New("Frame", {
			Name = "Glow",
			Size = UDim2.fromOffset(22, 22),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Corner = UDim.new(1, 0),
			Theme = { BackgroundColor3 = "Accent" },
			BackgroundTransparency = 0.78,
			ZIndex = (zBase or 4) - 1,
			Parent = thumb,
		})
	end

	local function setActive(active)
		Tween.Play(thumb, { Size = active and UDim2.fromOffset(17, 17) or UDim2.fromOffset(14, 14) }, Tween.Instant, Enum.EasingStyle.Quad)
		if glow:IsA("ImageLabel") then
			Tween.Play(glow, { ImageTransparency = active and 0.42 or 0.72 }, Tween.Instant, Enum.EasingStyle.Quad)
		else
			Tween.Play(glow, { BackgroundTransparency = active and 0.52 or 0.78 }, Tween.Instant, Enum.EasingStyle.Quad)
		end
	end

	return thumb, nil, stroke, setActive
end

-- ─── Slider ──────────────────────────────────────────────────────────────────

local Slider = {}
function Slider.new(parent, opts, ctx)
	opts = Util.Options(opts, { Min = 0, Max = 100 }, "Title")
	local element = Base.New("Slider", parent, opts, ctx)

	local minVal, maxVal, step, decimals = resolveNumericSpec(opts)
	local prefix = tostring(opts.Prefix or "")
	local suffix = tostring(opts.Suffix or "")

	local function snap(v)
		return Util.Snap(tonumber(v) or minVal, minVal, maxVal, step)
	end

	local function formatVal(v)
		return prefix .. Util.FormatNumber(v, decimals) .. suffix
	end

	local currentVal = snap(opts.Default ~= nil and opts.Default or minVal)
	element.Value = currentVal

	local card = Base.Card(parent, { Padding = 0 })

	local body = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 10, 12, 12, 12 },
		ZIndex = 2,
		Parent = card.Frame,
	})

	Create.List(body, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 8,
	})

	local header = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = body,
	})

	Create.List(header, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 10,
	})

	local left = Create.New("Frame", {
		Name = "Left",
		Size = UDim2.new(1, -64, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = header,
	})

	Create.List(left, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 8,
	})

	local iconWidth = 0
	if opts.Icon and opts.Icon ~= "" and opts.Icon ~= false then
		Icons.Create(opts.Icon, {
			Size = UDim2.fromOffset(17, 17),
			Color = opts.IconColor or "SubText",
			LayoutOrder = 1,
			Parent = left,
		})
		iconWidth = 17
	end

	local textCol = Create.New("Frame", {
		Name = "TextColumn",
		Size = UDim2.new(1, iconWidth > 0 and -(iconWidth + 8) or 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		Parent = left,
	})

	Create.List(textCol, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 2,
	})

	local titleText = tostring(opts.Title or "Slider")
	local descText = tostring(opts.Description or opts.Desc or "")

	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "Medium",
		TextSize = 13,
		Color = "Text",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Visible = titleText ~= "",
		Parent = textCol,
	})

	local descLabel = Create.Text({
		Name = "Description",
		Text = descText,
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = descText ~= "",
		Parent = textCol,
	})

	local pill = Create.New("Frame", {
		Name = "ValuePill",
		Size = UDim2.fromOffset(0, 24),
		AutomaticSize = Enum.AutomaticSize.X,
		Theme = { BackgroundColor3 = "Field" },
		Corner = 6,
		Padding = { 0, 8, 0, 8 },
		LayoutOrder = 2,
		Parent = header,
	})

	local pillConstraint = Instance.new("UISizeConstraint")
	pillConstraint.MinSize = Vector2.new(44, 24)
	pillConstraint.Parent = pill

	local pillStroke = Create.Stroke(pill, {
		Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
		Thickness = 1,
	})

	local readoutBox = Create.New("TextBox", {
		Name = "Readout",
		Size = UDim2.fromOffset(0, 24),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Text = formatVal(currentVal),
		TextSize = 12,
		Font = "SemiBold",
		Theme = { TextColor3 = "Text" },
		TextXAlignment = Enum.TextXAlignment.Center,
		ClearTextOnFocus = false,
		ZIndex = 4,
		Parent = pill,
	})

	local function syncHeaderInset()
		local pw = math.max(44, math.ceil(pill.AbsoluteSize.X))
		left.Size = UDim2.new(1, -(pw + 10), 0, 0)
	end
	element.Maid:Give(pill:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncHeaderInset))
	task.defer(syncHeaderInset)

	-- Track & Thumb
	local trackHit = Create.New("Frame", {
		Name = "TrackHit",
		Size = UDim2.new(1, 0, 0, 22),
		BackgroundTransparency = 1,
		Active = true,
		LayoutOrder = 2,
		Parent = body,
	})

	local track = Create.New("Frame", {
		Name = "Track",
		Size = UDim2.new(1, 0, 0, 6),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Theme = { BackgroundColor3 = "ToggleOff" },
		Corner = UDim.new(1, 0),
		Parent = trackHit,
	})

	local fill = Create.New("Frame", {
		Name = "Fill",
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = Color3.new(1, 1, 1),
		Corner = UDim.new(1, 0),
		ZIndex = 2,
		Parent = track,
	})

	local fillGrad = Instance.new("UIGradient")
	fillGrad.Color = Theme.AccentSequence()
	fillGrad.Parent = fill

	local thumb, _, _, setThumbActive = createThumb(track, 4)

	local function updateVisual(animate)
		local alpha = Util.Clamp((currentVal - minVal) / (maxVal - minVal), 0, 1)
		if not readoutBox:IsFocused() then
			readoutBox.Text = formatVal(currentVal)
		end
		if animate then
			Tween.Play(fill, { Size = UDim2.fromScale(alpha, 1) }, Tween.Instant, Enum.EasingStyle.Quad)
			Tween.Play(thumb, { Position = UDim2.fromScale(alpha, 0.5) }, Tween.Instant, Enum.EasingStyle.Quad)
		else
			fill.Size = UDim2.fromScale(alpha, 1)
			thumb.Position = UDim2.fromScale(alpha, 0.5)
		end
	end

	updateVisual(false)
	element.Maid:Give(Theme.Changed:Connect(function(t)
		if not element._destroyed then
			fillGrad.Color = Theme.AccentSequence(t)
		end
	end))

	function element:Set(val, silent)
		local nextVal = snap(val)
		local changed = (nextVal ~= currentVal)
		currentVal = nextVal
		self.Value = currentVal
		updateVisual(true)
		if changed and not silent then
			self.Changed:Fire(currentVal)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, currentVal)
			end
		end
	end

	function element:Get()
		return currentVal
	end

	function element:SetMin(newMin)
		minVal = tonumber(newMin) or minVal
		if maxVal <= minVal then
			maxVal = minVal + step
		end
		self:Set(currentVal, true)
	end

	function element:SetMax(newMax)
		maxVal = tonumber(newMax) or maxVal
		if maxVal <= minVal then
			maxVal = minVal + step
		end
		self:Set(currentVal, true)
	end

	-- Editable readout pill
	element.Maid:Give(readoutBox.Focused:Connect(function()
		if element.Disabled or element.Locked then
			readoutBox:ReleaseFocus()
			return
		end
		readoutBox.Text = tostring(currentVal)
		Tween.Play(pillStroke, {
			Color = Theme.Current.Accent,
			Transparency = 0.18,
		}, Tween.Fast, Enum.EasingStyle.Quad)
	end))

	element.Maid:Give(readoutBox.FocusLost:Connect(function()
		Tween.Play(pillStroke, {
			Color = Theme.Current.Stroke,
			Transparency = Theme.Current.StrokeTransparency,
		}, Tween.Fast, Enum.EasingStyle.Quad)
		local raw = Util.Trim(readoutBox.Text)
		raw = raw:gsub(",", "")
		local parsed = tonumber(raw)
		if not parsed then
			local extracted = raw:match("[%-]?%d+%.?%d*")
			parsed = extracted and tonumber(extracted) or nil
		end
		if parsed then
			element:Set(parsed, false)
		end
		readoutBox.Text = formatVal(currentVal)
	end))

	-- Dragging (mouse & touch)
	local dragging = false
	local hovered = false
	local activeInput = nil

	local function applyPointerX(posX)
		local width = math.max(track.AbsoluteSize.X, 1)
		local alpha = Util.Clamp((posX - track.AbsolutePosition.X) / width, 0, 1)
		element:Set(minVal + (maxVal - minVal) * alpha, false)
	end

	element.Maid:Give(trackHit.MouseEnter:Connect(function()
		if element.Disabled or element.Locked or Util.IsTouchDevice() or Transition.IsOverlayBlocking(trackHit) then
			return
		end
		hovered = true
		setThumbActive(true)
	end))

	element.Maid:Give(trackHit.MouseLeave:Connect(function()
		hovered = false
		if not dragging then
			setThumbActive(false)
		end
	end))

	element.Maid:Give(trackHit.InputBegan:Connect(function(input)
		if element.Disabled or element.Locked or Transition.IsOverlayBlocking(trackHit) then
			return
		end
		if Util.IsPointer(input) then
			dragging = true
			activeInput = input
			setThumbActive(true)
			applyPointerX(input.Position.X)
		end
	end))

	element.Maid:Give(Services.UserInputService.InputChanged:Connect(function(input)
		if not dragging then
			return
		end
		if Transition.IsOverlayBlocking(trackHit) then
			dragging = false
			activeInput = nil
			setThumbActive(false)
			return
		end
		local isTouch = activeInput and activeInput.UserInputType == Enum.UserInputType.Touch
		if (isTouch and input == activeInput) or (not isTouch and input.UserInputType == Enum.UserInputType.MouseMovement) then
			applyPointerX(input.Position.X)
		end
	end))

	element.Maid:Give(Services.UserInputService.InputEnded:Connect(function(input)
		if not dragging then
			return
		end
		local isTouch = activeInput and activeInput.UserInputType == Enum.UserInputType.Touch
		if (isTouch and input == activeInput) or (not isTouch and input.UserInputType == Enum.UserInputType.MouseButton1) then
			dragging = false
			activeInput = nil
			setThumbActive(hovered)
		end
	end))

	element._onDisabled = function(disabled)
		readoutBox.TextEditable = not disabled
		trackHit.Active = not disabled
		if disabled then
			dragging = false
			activeInput = nil
			setThumbActive(false)
		end
	end

	card.TitleLabel = titleLabel
	card.DescLabel = descLabel
	function card:SetTitle(s)
		local txt = tostring(s or "")
		titleLabel.Text = txt
		titleLabel.Visible = (txt ~= "")
	end
	function card:SetDesc(s)
		local txt = tostring(s or "")
		descLabel.Text = txt
		descLabel.Visible = (txt ~= "")
	end

	element:BindUI(card)
	return element
end

-- ─── RangeSlider ─────────────────────────────────────────────────────────────

local RangeSlider = {}
function RangeSlider.new(parent, opts, ctx)
	opts = Util.Options(opts, { Min = 0, Max = 100 }, "Title")
	local element = Base.New("RangeSlider", parent, opts, ctx)

	local minVal, maxVal, step, decimals = resolveNumericSpec(opts)
	local prefix = tostring(opts.Prefix or "")
	local suffix = tostring(opts.Suffix or "")
	local minGap = math.max(tonumber(opts.MinGap) or 0, 0)

	local function snap(v)
		return Util.Snap(tonumber(v) or minVal, minVal, maxVal, step)
	end

	local function formatRange(lo, hi)
		local a = prefix .. Util.FormatNumber(lo, decimals) .. suffix
		local b = prefix .. Util.FormatNumber(hi, decimals) .. suffix
		return a .. " – " .. b
	end

	local defLow, defHigh = minVal, maxVal
	if type(opts.Default) == "table" then
		defLow = opts.Default.Min ~= nil and opts.Default.Min or (opts.Default[1] ~= nil and opts.Default[1] or minVal)
		defHigh = opts.Default.Max ~= nil and opts.Default.Max or (opts.Default[2] ~= nil and opts.Default[2] or maxVal)
	end

	local lowVal = snap(defLow)
	local highVal = snap(defHigh)
	if highVal < lowVal then
		lowVal, highVal = highVal, lowVal
	end
	if highVal - lowVal < minGap then
		highVal = snap(math.min(maxVal, lowVal + minGap))
		if highVal - lowVal < minGap then
			lowVal = snap(math.max(minVal, highVal - minGap))
		end
	end
	element.Value = { Min = lowVal, Max = highVal }

	local card = Base.Card(parent, { Padding = 0 })

	local body = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 10, 12, 12, 12 },
		ZIndex = 2,
		Parent = card.Frame,
	})

	Create.List(body, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 8,
	})

	local header = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = body,
	})

	Create.List(header, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 10,
	})

	local left = Create.New("Frame", {
		Name = "Left",
		Size = UDim2.new(1, -90, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = header,
	})

	Create.List(left, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 2,
	})

	local titleText = tostring(opts.Title or "Range")
	local descText = tostring(opts.Description or opts.Desc or "")

	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "Medium",
		TextSize = 13,
		Color = "Text",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Visible = titleText ~= "",
		Parent = left,
	})

	local descLabel = Create.Text({
		Name = "Description",
		Text = descText,
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = descText ~= "",
		Parent = left,
	})

	local pill = Create.New("Frame", {
		Name = "ValuePill",
		Size = UDim2.fromOffset(0, 24),
		AutomaticSize = Enum.AutomaticSize.X,
		Theme = { BackgroundColor3 = "Field" },
		Corner = 6,
		Padding = { 0, 8, 0, 8 },
		Stroke = {
			Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
			Thickness = 1,
		},
		LayoutOrder = 2,
		Parent = header,
	})

	local readoutLabel = Create.Text({
		Name = "Readout",
		Text = formatRange(lowVal, highVal),
		Font = "SemiBold",
		TextSize = 12,
		Color = "Text",
		Size = UDim2.fromOffset(0, 24),
		AutomaticSize = Enum.AutomaticSize.X,
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = pill,
	})

	local function syncHeaderInset()
		local pw = math.ceil(pill.AbsoluteSize.X)
		left.Size = UDim2.new(1, -(pw + 10), 0, 0)
	end
	element.Maid:Give(pill:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncHeaderInset))
	task.defer(syncHeaderInset)

	local trackHit = Create.New("Frame", {
		Name = "TrackHit",
		Size = UDim2.new(1, 0, 0, 22),
		BackgroundTransparency = 1,
		Active = true,
		LayoutOrder = 2,
		Parent = body,
	})

	local track = Create.New("Frame", {
		Name = "Track",
		Size = UDim2.new(1, 0, 0, 6),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Theme = { BackgroundColor3 = "ToggleOff" },
		Corner = UDim.new(1, 0),
		Parent = trackHit,
	})

	local fill = Create.New("Frame", {
		Name = "Fill",
		Position = UDim2.fromScale(0, 0),
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = Color3.new(1, 1, 1),
		Corner = UDim.new(1, 0),
		ZIndex = 2,
		Parent = track,
	})

	local fillGrad = Instance.new("UIGradient")
	fillGrad.Color = Theme.AccentSequence()
	fillGrad.Parent = fill

	local thumbLow, _, _, setLowActive = createThumb(track, 4)
	local thumbHigh, _, _, setHighActive = createThumb(track, 5)

	local function updateVisual(animate)
		local span = maxVal - minVal
		local aLow = Util.Clamp((lowVal - minVal) / span, 0, 1)
		local aHigh = Util.Clamp((highVal - minVal) / span, 0, 1)
		readoutLabel.Text = formatRange(lowVal, highVal)
		local fillPos = UDim2.fromScale(aLow, 0)
		local fillSize = UDim2.fromScale(math.max(0, aHigh - aLow), 1)
		local posLow = UDim2.fromScale(aLow, 0.5)
		local posHigh = UDim2.fromScale(aHigh, 0.5)

		if animate then
			Tween.Play(fill, { Position = fillPos, Size = fillSize }, Tween.Instant, Enum.EasingStyle.Quad)
			Tween.Play(thumbLow, { Position = posLow }, Tween.Instant, Enum.EasingStyle.Quad)
			Tween.Play(thumbHigh, { Position = posHigh }, Tween.Instant, Enum.EasingStyle.Quad)
		else
			fill.Position = fillPos
			fill.Size = fillSize
			thumbLow.Position = posLow
			thumbHigh.Position = posHigh
		end
	end

	updateVisual(false)
	element.Maid:Give(Theme.Changed:Connect(function(t)
		if not element._destroyed then
			fillGrad.Color = Theme.AccentSequence(t)
		end
	end))

	function element:Set(valOrMin, maxOrSilent, silentArg)
		local rawLow, rawHigh, silent
		if type(valOrMin) == "table" then
			rawLow = valOrMin.Min ~= nil and valOrMin.Min or (valOrMin[1] ~= nil and valOrMin[1] or lowVal)
			rawHigh = valOrMin.Max ~= nil and valOrMin.Max or (valOrMin[2] ~= nil and valOrMin[2] or highVal)
			silent = (maxOrSilent == true)
		else
			rawLow = tonumber(valOrMin) or lowVal
			rawHigh = tonumber(maxOrSilent) or highVal
			silent = (silentArg == true)
		end

		local nextLow = snap(rawLow)
		local nextHigh = snap(rawHigh)
		if nextHigh < nextLow then
			nextLow, nextHigh = nextHigh, nextLow
		end
		if nextHigh - nextLow < minGap then
			nextHigh = snap(math.min(maxVal, nextLow + minGap))
			if nextHigh - nextLow < minGap then
				nextLow = snap(math.max(minVal, nextHigh - minGap))
			end
		end

		local changed = (nextLow ~= lowVal or nextHigh ~= highVal)
		lowVal = nextLow
		highVal = nextHigh
		self.Value = { Min = lowVal, Max = highVal }
		updateVisual(true)

		if changed and not silent then
			local payload = { Min = lowVal, Max = highVal }
			self.Changed:Fire(payload)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, payload)
			end
		end
	end

	function element:Get()
		return { Min = lowVal, Max = highVal }
	end

	local activeHandle = nil -- "Min" | "Max" | nil
	local activeInput = nil

	local function applyPointerX(posX)
		local width = math.max(track.AbsoluteSize.X, 1)
		local alpha = Util.Clamp((posX - track.AbsolutePosition.X) / width, 0, 1)
		local targetVal = snap(minVal + (maxVal - minVal) * alpha)
		if activeHandle == "Min" then
			local capped = snap(math.min(targetVal, highVal - minGap))
			element:Set(capped, highVal, false)
		elseif activeHandle == "Max" then
			local floored = snap(math.max(targetVal, lowVal + minGap))
			element:Set(lowVal, floored, false)
		end
	end

	element.Maid:Give(trackHit.InputBegan:Connect(function(input)
		if element.Disabled or element.Locked or Transition.IsOverlayBlocking(trackHit) then
			return
		end
		if Util.IsPointer(input) then
			local width = math.max(track.AbsoluteSize.X, 1)
			local pointerAlpha = Util.Clamp((input.Position.X - track.AbsolutePosition.X) / width, 0, 1)
			local span = maxVal - minVal
			local aLow = (lowVal - minVal) / span
			local aHigh = (highVal - minVal) / span
			local dLow = math.abs(pointerAlpha - aLow)
			local dHigh = math.abs(pointerAlpha - aHigh)

			if dLow < dHigh or (math.abs(dLow - dHigh) < 1e-4 and pointerAlpha < aLow) then
				activeHandle = "Min"
				thumbLow.ZIndex = 6
				thumbHigh.ZIndex = 4
				setLowActive(true)
			else
				activeHandle = "Max"
				thumbHigh.ZIndex = 6
				thumbLow.ZIndex = 4
				setHighActive(true)
			end
			activeInput = input
			applyPointerX(input.Position.X)
		end
	end))

	element.Maid:Give(Services.UserInputService.InputChanged:Connect(function(input)
		if not activeHandle then
			return
		end
		if Transition.IsOverlayBlocking(trackHit) then
			setLowActive(false)
			setHighActive(false)
			activeHandle = nil
			activeInput = nil
			return
		end
		local isTouch = activeInput and activeInput.UserInputType == Enum.UserInputType.Touch
		if (isTouch and input == activeInput) or (not isTouch and input.UserInputType == Enum.UserInputType.MouseMovement) then
			applyPointerX(input.Position.X)
		end
	end))

	element.Maid:Give(Services.UserInputService.InputEnded:Connect(function(input)
		if not activeHandle then
			return
		end
		local isTouch = activeInput and activeInput.UserInputType == Enum.UserInputType.Touch
		if (isTouch and input == activeInput) or (not isTouch and input.UserInputType == Enum.UserInputType.MouseButton1) then
			setLowActive(false)
			setHighActive(false)
			activeHandle = nil
			activeInput = nil
		end
	end))

	element._onDisabled = function(disabled)
		trackHit.Active = not disabled
		if disabled then
			activeHandle = nil
			activeInput = nil
			setLowActive(false)
			setHighActive(false)
		end
	end

	card.TitleLabel = titleLabel
	card.DescLabel = descLabel
	function card:SetTitle(s)
		local txt = tostring(s or "")
		titleLabel.Text = txt
		titleLabel.Visible = (txt ~= "")
	end
	function card:SetDesc(s)
		local txt = tostring(s or "")
		descLabel.Text = txt
		descLabel.Visible = (txt ~= "")
	end

	element:BindUI(card)
	return element
end

-- ─── Stepper ─────────────────────────────────────────────────────────────────

local Stepper = {}
function Stepper.new(parent, opts, ctx)
	opts = Util.Options(opts, { Min = 0, Max = 100 }, "Title")
	local element = Base.New("Stepper", parent, opts, ctx)

	local minVal, maxVal, step, decimals = resolveNumericSpec(opts)
	local prefix = tostring(opts.Prefix or "")
	local suffix = tostring(opts.Suffix or "")

	local function snap(v)
		return Util.Snap(tonumber(v) or minVal, minVal, maxVal, step)
	end

	local function formatVal(v)
		return prefix .. Util.FormatNumber(v, decimals) .. suffix
	end

	local currentVal = snap(opts.Default ~= nil and opts.Default or minVal)
	element.Value = currentVal

	local rowOpts = table.clone(opts)
	if rowOpts.IconBadge == nil then
		rowOpts.IconBadge = false
	end

	local row = Base.Row(parent, rowOpts, 132)
	element:BindUI(row)

	local pill = Create.New("Frame", {
		Name = "StepperPill",
		Size = UDim2.fromOffset(0, 30),
		AutomaticSize = Enum.AutomaticSize.X,
		Theme = { BackgroundColor3 = "Field" },
		Corner = 8,
		Stroke = {
			Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
			Thickness = 1,
		},
		Parent = row.Right,
	})

	Create.List(pill, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 0,
	})

	local minusBtn = Create.New("TextButton", {
		Name = "Minus",
		Size = UDim2.fromOffset(28, 30),
		Theme = { BackgroundColor3 = "Field" },
		Corner = 8,
		Text = "",
		AutoButtonColor = false,
		LayoutOrder = 1,
		Parent = pill,
	})

	local minusIcon = Icons.Create("minus", {
		Size = UDim2.fromOffset(13, 13),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Color = "Text",
		Parent = minusBtn,
	})

	Create.New("Frame", {
		Name = "Sep1",
		Size = UDim2.fromOffset(1, 18),
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		LayoutOrder = 2,
		Parent = pill,
	})

	local valueBox = Create.New("TextBox", {
		Name = "Value",
		Size = UDim2.fromOffset(0, 30),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Text = formatVal(currentVal),
		TextSize = 12,
		Font = "SemiBold",
		Theme = { TextColor3 = "Text" },
		TextXAlignment = Enum.TextXAlignment.Center,
		ClearTextOnFocus = false,
		Padding = { 0, 8, 0, 8 },
		LayoutOrder = 3,
		Parent = pill,
	})

	local valConstraint = Instance.new("UISizeConstraint")
	valConstraint.MinSize = Vector2.new(54, 30)
	valConstraint.Parent = valueBox

	Create.New("Frame", {
		Name = "Sep2",
		Size = UDim2.fromOffset(1, 18),
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		LayoutOrder = 4,
		Parent = pill,
	})

	local plusBtn = Create.New("TextButton", {
		Name = "Plus",
		Size = UDim2.fromOffset(28, 30),
		Theme = { BackgroundColor3 = "Field" },
		Corner = 8,
		Text = "",
		AutoButtonColor = false,
		LayoutOrder = 5,
		Parent = pill,
	})

	local plusIcon = Icons.Create("plus", {
		Size = UDim2.fromOffset(13, 13),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Color = "Text",
		Parent = plusBtn,
	})

	element.Maid:Give(Transition.Hover(minusBtn, minusBtn, "Field", "TileHover"))
	element.Maid:Give(Transition.Hover(plusBtn, plusBtn, "Field", "TileHover"))

	local function syncPillWidth()
		row:SetRightWidth(math.max(114, math.ceil(pill.AbsoluteSize.X)))
	end
	element.Maid:Give(pill:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncPillWidth))
	task.defer(syncPillWidth)

	local function refreshStepperVisual()
		if not valueBox:IsFocused() then
			valueBox.Text = formatVal(currentVal)
		end
		if minusIcon then
			local atMin = (currentVal <= minVal) or element.Disabled
			Icons.SetTransparency(minusIcon, atMin and 0.65 or 0)
		end
		if plusIcon then
			local atMax = (currentVal >= maxVal) or element.Disabled
			Icons.SetTransparency(plusIcon, atMax and 0.65 or 0)
		end
	end

	refreshStepperVisual()

	function element:Set(val, silent)
		local nextVal = snap(val)
		local changed = (nextVal ~= currentVal)
		currentVal = nextVal
		self.Value = currentVal
		refreshStepperVisual()
		if changed and not silent then
			self.Changed:Fire(currentVal)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, currentVal)
			end
		end
	end

	function element:Get()
		return currentVal
	end

	function element:Step(delta)
		self:Set(currentVal + delta * step, false)
	end

	local function bindRepeatButton(btn, delta)
		local holdToken = 0
		element.Maid:Give(btn.InputBegan:Connect(function(input)
			if element.Disabled or element.Locked or Transition.IsOverlayBlocking(btn) or not Util.IsPointer(input) then
				return
			end
			Transition.Ripple(btn, input, "Accent")
			element:Step(delta)

			holdToken += 1
			local myToken = holdToken
			task.spawn(function()
				task.wait(0.38)
				while not element._destroyed and holdToken == myToken and not element.Disabled and not element.Locked and not Transition.IsOverlayBlocking(btn) do
					element:Step(delta)
					task.wait(0.08)
				end
			end)
		end))

		local function cancelHold()
			holdToken += 1
		end
		element.Maid:Give(btn.InputEnded:Connect(cancelHold))
		element.Maid:Give(btn.MouseLeave:Connect(cancelHold))
	end

	bindRepeatButton(minusBtn, -1)
	bindRepeatButton(plusBtn, 1)

	element.Maid:Give(valueBox.Focused:Connect(function()
		if element.Disabled or element.Locked then
			valueBox:ReleaseFocus()
			return
		end
		valueBox.Text = tostring(currentVal)
	end))

	element.Maid:Give(valueBox.FocusLost:Connect(function()
		local raw = Util.Trim(valueBox.Text):gsub(",", "")
		local parsed = tonumber(raw)
		if not parsed then
			local extracted = raw:match("[%-]?%d+%.?%d*")
			parsed = extracted and tonumber(extracted) or nil
		end
		if parsed then
			element:Set(parsed, false)
		end
		valueBox.Text = formatVal(currentVal)
	end))

	element._onDisabled = function(disabled)
		valueBox.TextEditable = not disabled
		refreshStepperVisual()
	end

	return element
end

SliderModule.Slider = Slider
SliderModule.RangeSlider = RangeSlider
SliderModule.Stepper = Stepper

return SliderModule
end

__modules["Elements/Static"] = function()
--[[
	Bali UI · Elements/Static
	Display elements: Label, Paragraph, Divider, Header, CodeBlock, Image, ProfileCard.
]]

local Services = require("Core/Services")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Assets = require("Core/Assets")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Base = require("Elements/Base")

local Static = {}

-- ─── Label ───────────────────────────────────────────────────────────────────

local Label = {}
function Label.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Title")
	local element = Base.New("Label", parent, opts, ctx)

	local rowOpts = table.clone(opts)
	if rowOpts.IconBadge == nil then
		rowOpts.IconBadge = false
	end
	rowOpts._compactStack = true

	local row = Base.Row(parent, rowOpts, 0)
	element:BindUI(row)

	Create.List(row.Right, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		HAlign = Enum.HorizontalAlignment.Right,
		Gap = 6,
	})

	local statusDot = Create.New("Frame", {
		Name = "StatusDot",
		Size = UDim2.fromOffset(8, 8),
		Corner = UDim.new(1, 0),
		Theme = { BackgroundColor3 = opts.DotColor or opts.BadgeColor or "Success" },
		Visible = (opts.StatusDot == true or opts.DotColor ~= nil),
		LayoutOrder = 0,
		Parent = row.Right,
	})
	element.Maid:Give(Transition.Pulse(statusDot, "BackgroundTransparency", 0, 0.35, 1.8))

	local valueText = opts.Value ~= nil and tostring(opts.Value) or (opts.Text ~= nil and tostring(opts.Text) or "")
	element.Value = valueText

	local valueLabel = Create.Text({
		Name = "Value",
		Text = valueText,
		Font = "Medium",
		TextSize = 12,
		Color = opts.ValueColor or "SubText",
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 1,
		Visible = valueText ~= "",
		Parent = row.Right,
	})
	local valueConstraint = Instance.new("UISizeConstraint")
	valueConstraint.MaxSize = Vector2.new(140, 60)
	valueConstraint.Parent = valueLabel

	local badgeObj = nil
	if opts.Badge then
		local bText, bColor
		if type(opts.Badge) == "table" then
			bText = opts.Badge.Text or opts.Badge[1] or ""
			bColor = opts.Badge.Color or opts.Badge[2] or "Accent"
		else
			bText = tostring(opts.Badge)
			bColor = opts.BadgeColor or "Accent"
		end
		badgeObj = Base.Badge(row.Right, bText, bColor)
		badgeObj.Frame.LayoutOrder = 2
	end

	local copyBtn = nil
	local copyIcon = nil
	if opts.Copyable then
		copyBtn = Create.New("TextButton", {
			Name = "CopyButton",
			Size = UDim2.fromOffset(24, 24),
			Theme = { BackgroundColor3 = "Field" },
			Corner = 6,
			Stroke = {
				Theme = { Color = "Stroke" },
				Transparency = 0.86,
				Thickness = 1,
			},
			LayoutOrder = 3,
			ZIndex = 4,
			Parent = row.Right,
		})
		copyIcon = Icons.Create("copy", {
			Size = UDim2.fromOffset(14, 14),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Color = "SubText",
			Parent = copyBtn,
		})
		element.Maid:Give(Transition.Hover(copyBtn, copyBtn, "Field", "TileHover"))

		local copyToken = 0
		element.Maid:Give(copyBtn.Activated:Connect(function(inputObj)
			if element.Disabled or element.Locked then
				return
			end
			local toCopy = opts.CopyValue
			if toCopy == nil then
				toCopy = (element.Value ~= "" and element.Value) or element.Title
			end
			Util.SetClipboard(tostring(toCopy or ""))
			Transition.Ripple(copyBtn, inputObj, "Accent")

			copyToken += 1
			local myToken = copyToken
			if copyIcon then
				Icons.Set(copyIcon, "check")
				Icons.SetColor(copyIcon, "Success")
			end
			task.delay(1.5, function()
				if element._destroyed or copyToken ~= myToken then
					return
				end
				if copyIcon then
					Icons.Set(copyIcon, "copy")
					Icons.SetColor(copyIcon, "SubText")
				end
			end)
		end))
	end

	function element:SetText(s)
		self:SetTitle(s)
	end

	function element:SetValue(v)
		local text = v ~= nil and tostring(v) or ""
		self.Value = text
		valueLabel.Text = text
		valueLabel.Visible = (text ~= "")
	end

	function element:Get()
		return self.Value
	end

	function element:SetBadge(text, colorKey)
		if text == nil or text == "" then
			if badgeObj then
				badgeObj.Frame.Visible = false
			end
			return
		end
		if not badgeObj then
			badgeObj = Base.Badge(row.Right, text, colorKey or "Accent")
			badgeObj.Frame.LayoutOrder = 2
		else
			badgeObj.Frame.Visible = true
			badgeObj:SetText(text)
			if colorKey then
				badgeObj:SetColor(colorKey)
			end
		end
	end

	function element:SetDot(colorKey, visible)
		if visible == false then
			statusDot.Visible = false
			return
		end
		statusDot.Visible = true
		if typeof(colorKey) == "Color3" then
			Theme.Unbind(statusDot, "BackgroundColor3")
			statusDot.BackgroundColor3 = colorKey
		elseif type(colorKey) == "string" and colorKey ~= "" then
			Theme.Bind(statusDot, { BackgroundColor3 = colorKey })
		end
	end

	function element:SetStatus(valueTextArg, badgeText, colorKey)
		if valueTextArg ~= nil then
			self:SetValue(valueTextArg)
		end
		if badgeText ~= nil then
			self:SetBadge(badgeText, colorKey)
		end
		self:SetDot(colorKey or opts.DotColor or opts.BadgeColor or "Success", true)
	end

	return element
end

-- ─── Paragraph ───────────────────────────────────────────────────────────────

local Paragraph = {}
function Paragraph.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Title")
	local element = Base.New("Paragraph", parent, opts, ctx)

	local card = Base.Card(parent, { Padding = 0, ClipsDescendants = true })
	local accentColor = opts.Color or "Accent"
	local showBar = (opts.AccentBar ~= false)

	local glow = nil
	local bar = nil
	local barGrad = nil
	local iconBadge = nil

	if showBar then
		local glowAsset = Assets and Assets.Get and Assets.Get("Glow")
		if glowAsset and Assets.Available then
			glow = Create.New("ImageLabel", {
				Name = "Glow",
				Image = glowAsset,
				Size = UDim2.fromOffset(170, 72),
				Position = UDim2.fromOffset(8, 2),
				BackgroundTransparency = 1,
				ImageTransparency = 0.88,
				ZIndex = 0,
				Parent = card.Frame,
			})
		end

		bar = Create.New("Frame", {
			Name = "AccentBar",
			Size = UDim2.new(1, -20, 0, 2),
			Position = UDim2.new(0, 10, 0, 0),
			BackgroundColor3 = Color3.new(1, 1, 1),
			BackgroundTransparency = 0.12,
			Corner = UDim.new(1, 0),
			ZIndex = 3,
			Parent = card.Frame,
		})
		barGrad = Instance.new("UIGradient")
		barGrad.Rotation = 0
		barGrad.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.08, 0.35),
			NumberSequenceKeypoint.new(0.22, 0),
			NumberSequenceKeypoint.new(0.52, 0.25),
			NumberSequenceKeypoint.new(0.85, 0.82),
			NumberSequenceKeypoint.new(1, 1),
		})
		barGrad.Parent = bar
	end

	local body = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 13, 14, 12, 14 },
		ZIndex = 2,
		Parent = card.Frame,
	})

	Create.List(body, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 6,
	})

	local titleText = tostring(opts.Title or "")
	local contentText = tostring(opts.Content or opts.Description or opts.Desc or "")

	local header = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Visible = (titleText ~= "" or (opts.Icon ~= nil and opts.Icon ~= "")),
		Parent = body,
	})

	Create.List(header, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 10,
	})

	local iconWidth = 0
	if opts.Icon and opts.Icon ~= "" and opts.Icon ~= false then
		iconBadge = Base.IconBadge(header, opts.Icon, accentColor)
		iconBadge.Frame.LayoutOrder = 1
		iconWidth = 30
	end

	local function applyAccentColor(colorSpec, themeTable)
		accentColor = colorSpec or "Accent"
		local activeTheme = themeTable or Theme.Current
		if glow then
			if typeof(accentColor) == "Color3" then
				Theme.Unbind(glow, "ImageColor3")
				glow.ImageColor3 = accentColor
			else
				Theme.Bind(glow, { ImageColor3 = accentColor })
			end
		end
		if barGrad then
			if typeof(accentColor) == "Color3" then
				barGrad.Color = ColorSequence.new(accentColor)
			elseif accentColor == "Accent" then
				barGrad.Color = Theme.AccentSequence(activeTheme)
			else
				barGrad.Color = ColorSequence.new(activeTheme[accentColor] or activeTheme.Accent)
			end
		end
		if iconBadge and colorSpec ~= nil then
			iconBadge:SetColor(accentColor)
		end
	end

	applyAccentColor(accentColor)
	element.Maid:Give(Theme.Changed:Connect(function(t)
		applyAccentColor(accentColor, t)
	end))

	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "SemiBold",
		TextSize = 14,
		Color = "Text",
		TextWrapped = true,
		Size = UDim2.new(1, iconWidth > 0 and -(iconWidth + 10) or 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = titleText ~= "",
		Parent = header,
	})

	local maxContentH = tonumber(opts.Height or opts.MaxHeight)
	local contentScroll = nil
	local contentParent = body
	if maxContentH and maxContentH > 0 then
		contentScroll = Create.New("ScrollingFrame", {
			Name = "ParagraphScroll",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.None,
			AutomaticCanvasSize = Enum.AutomaticSize.None,
			CanvasSize = UDim2.new(0, 0, 0, 0),
			ScrollBarThickness = 4,
			ScrollBarImageTransparency = 0.25,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			Active = true,
			ScrollingEnabled = true,
			ClipsDescendants = true,
			BackgroundTransparency = 1,
			Theme = { ScrollBarImageColor3 = "Muted" },
			LayoutOrder = 2,
			Visible = contentText ~= "",
			Parent = body,
		})
		Create.Padding(contentScroll, { 0, 10, 0, 0 })
		contentParent = contentScroll
	end

	local contentLabel = Create.Text({
		Name = "Content",
		Text = contentText,
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = contentText ~= "",
		Parent = contentParent,
	})

	local function updateParagraphScrollBounds()
		if not contentScroll then
			return
		end
		local hasContent = contentLabel.Text ~= ""
		contentScroll.Visible = hasContent
		if not hasContent then
			contentScroll.Size = UDim2.new(1, 0, 0, 0)
			contentScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
			return
		end
		local textH = math.ceil(contentLabel.AbsoluteSize.Y)
		if textH <= 0 then
			local approxLines = 1
			for _ in string.gmatch(contentLabel.Text, "\n") do
				approxLines += 1
			end
			textH = math.max(16, approxLines * 16)
		end
		local fixedH = tonumber(opts.Height)
		local visibleH = fixedH or math.min(textH, maxContentH)
		contentScroll.Size = UDim2.new(1, 0, 0, visibleH)
		contentScroll.CanvasSize = UDim2.fromOffset(0, textH)
	end

	if contentScroll then
		element.Maid:Give(contentLabel:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateParagraphScrollBounds))
		updateParagraphScrollBounds()
	end

	local tagsRow = Create.New("Frame", {
		Name = "Tags",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 3,
		Visible = false,
		Parent = body,
	})

	Create.List(tagsRow, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 6,
		Wraps = true,
	})

	local function buildTags(tags)
		for _, child in ipairs(tagsRow:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		if type(tags) ~= "table" or #tags == 0 then
			tagsRow.Visible = false
			return
		end
		tagsRow.Visible = true
		for idx, tag in ipairs(tags) do
			local tText, tColor
			if type(tag) == "table" then
				tText = tag.Text or tag[1] or ""
				tColor = tag.Color or tag[2] or "Accent"
			else
				tText = tostring(tag)
				tColor = "Accent"
			end
			local b = Base.Badge(tagsRow, tText, tColor)
			b.Frame.LayoutOrder = idx
		end
	end

	buildTags(opts.Tags)

	card.TitleLabel = titleLabel
	card.DescLabel = contentLabel

	function card:SetTitle(s)
		local txt = tostring(s or "")
		titleLabel.Text = txt
		titleLabel.Visible = (txt ~= "")
		header.Visible = (txt ~= "" or iconWidth > 0)
	end

	function card:SetDesc(s)
		local txt = tostring(s or "")
		contentLabel.Text = txt
		contentLabel.Visible = (txt ~= "")
		if contentScroll then
			updateParagraphScrollBounds()
		end
	end

	element:BindUI(card)

	function element:SetContent(s)
		self:SetDesc(s)
	end

	function element:SetTags(tags)
		buildTags(tags)
	end

	function element:SetColor(newColor)
		applyAccentColor(newColor)
	end

	function element:SetIcon(newIcon)
		if iconBadge then
			iconBadge:SetIcon(newIcon)
		end
	end

	return element
end

