local Header = {}
function Header.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Title")
	local element = Base.New("Header", parent, opts, ctx)

	local uppercase = (opts.Uppercase ~= false)
	local rawTitle = tostring(opts.Title or "")

	local frame = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 6, 2, 2, 2 },
		Parent = parent,
	})

	Create.List(frame, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 6,
	})

	local iconWidth = 0
	if opts.Icon and opts.Icon ~= "" and opts.Icon ~= false then
		Icons.Create(opts.Icon, {
			Size = UDim2.fromOffset(14, 14),
			Color = opts.IconColor or "Accent",
			LayoutOrder = 1,
			Parent = frame,
		})
		iconWidth = 14
	end

	local titleLabel = Create.Text({
		Name = "Title",
		Text = uppercase and string.upper(rawTitle) or rawTitle,
		Font = "Bold",
		TextSize = 11,
		Color = opts.Color or "SubText",
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		TextWrapped = true,
		LayoutOrder = 2,
		Parent = frame,
	})

	if opts.Badge then
		local bText, bColor
		if type(opts.Badge) == "table" then
			bText = opts.Badge.Text or opts.Badge[1] or ""
			bColor = opts.Badge.Color or opts.Badge[2] or "Accent"
		else
			bText = tostring(opts.Badge)
			bColor = "Accent"
		end
		local b = Base.Badge(frame, bText, bColor)
		b.Frame.LayoutOrder = 3
	end

	element:BindUI({
		Frame = frame,
		TitleLabel = titleLabel,
		SetTitle = function(_, s)
			local text = tostring(s or "")
			titleLabel.Text = uppercase and string.upper(text) or text
		end,
	})

	return element
end

-- ─── CodeBlock ───────────────────────────────────────────────────────────────

local LUAU_KEYWORDS = {
	["and"] = true, ["break"] = true, ["continue"] = true, ["do"] = true,
	["else"] = true, ["elseif"] = true, ["end"] = true, ["export"] = true,
	["for"] = true, ["function"] = true, ["if"] = true, ["in"] = true,
	["local"] = true, ["not"] = true, ["or"] = true, ["repeat"] = true,
	["return"] = true, ["then"] = true, ["type"] = true, ["until"] = true,
	["while"] = true,
}

local LUAU_LITERALS = {
	["true"] = true, ["false"] = true, ["nil"] = true, ["self"] = true,
}

local LUAU_BUILTINS = {
	require = true, print = true, warn = true, error = true, assert = true,
	pcall = true, xpcall = true, pairs = true, ipairs = true, next = true,
	select = true, tostring = true, tonumber = true, typeof = true,
	setmetatable = true, getmetatable = true, unpack = true,
	task = true, math = true, string = true, table = true, bit32 = true,
	game = true, workspace = true, script = true, Enum = true, Instance = true,
	UDim = true, UDim2 = true, Vector2 = true, Vector3 = true, Color3 = true,
	CFrame = true, TweenInfo = true, NumberSequence = true, ColorSequence = true,
}

local GENERIC_KEYWORDS = {
	["async"] = true, ["await"] = true, ["break"] = true, ["case"] = true,
	["catch"] = true, ["class"] = true, ["const"] = true, ["continue"] = true,
	["def"] = true, ["default"] = true, ["elif"] = true, ["else"] = true,
	["export"] = true, ["finally"] = true, ["for"] = true, ["from"] = true,
	["function"] = true, ["if"] = true, ["import"] = true, ["in"] = true,
	["interface"] = true, ["let"] = true, ["return"] = true, ["switch"] = true,
	["throw"] = true, ["try"] = true, ["type"] = true, ["var"] = true,
	["while"] = true, ["with"] = true, ["yield"] = true,
}

local GENERIC_LITERALS = {
	["true"] = true, ["false"] = true, ["True"] = true, ["False"] = true,
	["null"] = true, ["None"] = true, ["undefined"] = true, ["this"] = true, ["self"] = true,
}

local SYNTAX_COLORS = {
	Keyword = "#C084FC",
	Literal = "#F472B6",
	String = "#86EFAC",
	Number = "#FDBA74",
	Builtin = "#7DD3FC",
	Member = "#93C5FD",
	Key = "#7DD3FC",
	Comment = "#7A7A94",
}

local function escapeRichText(str)
	local s = string.gsub(str, "&", "&amp;")
	s = string.gsub(s, "<", "&lt;")
	s = string.gsub(s, ">", "&gt;")
	return s
end

local function wrapColor(text, hex)
	if text == "" then
		return ""
	end
	if not hex then
		return escapeRichText(text)
	end
	return '<font color="' .. hex .. '">' .. escapeRichText(text) .. "</font>"
end

local function detectCodeLanguage(opts, code)
	local hint = string.lower(tostring(opts.Language or opts.Lang or ""))
	if hint == "json" then
		return "json"
	elseif hint == "js" or hint == "javascript" or hint == "ts" or hint == "typescript" then
		return "js"
	elseif hint == "py" or hint == "python" then
		return "py"
	elseif hint == "lua" or hint == "luau" then
		return "luau"
	end
	local titleHint = string.lower(tostring(opts.Title or ""))
	if string.find(titleHint, "json", 1, true) then
		return "json"
	elseif string.find(titleHint, "python", 1, true) then
		return "py"
	elseif string.find(titleHint, "typescript", 1, true) or string.find(titleHint, "javascript", 1, true) then
		return "js"
	end
	local trimmed = tostring(code or ""):match("^%s*(.-)%s*$") or ""
	if trimmed:sub(1, 1) == "{" or trimmed:sub(1, 1) == "[" then
		if string.find(trimmed, '":', 1, true) then
			return "json"
		end
	end
	return "luau"
end

local function highlightCodeLine(line, lang, inBlockComment)
	if line == "" then
		return "", inBlockComment
	end

	local out = {}
	local n = #line
	local i = 1

	if inBlockComment then
		local closeStart, closeEnd = string.find(line, "]]", 1, true)
		if closeStart then
			table.insert(out, wrapColor(string.sub(line, 1, closeEnd), SYNTAX_COLORS.Comment))
			i = closeEnd + 1
			inBlockComment = false
		else
			return wrapColor(line, SYNTAX_COLORS.Comment), true
		end
	end

	while i <= n do
		local ch = string.sub(line, i, i)

		-- Comments
		if (lang == "luau") and string.sub(line, i, i + 1) == "--" then
			if string.sub(line, i + 2, i + 3) == "[[" then
				local closeStart, closeEnd = string.find(line, "]]", i + 4, true)
				if closeStart then
					table.insert(out, wrapColor(string.sub(line, i, closeEnd), SYNTAX_COLORS.Comment))
					i = closeEnd + 1
				else
					table.insert(out, wrapColor(string.sub(line, i), SYNTAX_COLORS.Comment))
					inBlockComment = true
					break
				end
			else
				table.insert(out, wrapColor(string.sub(line, i), SYNTAX_COLORS.Comment))
				break
			end
		elseif (lang == "js" and string.sub(line, i, i + 1) == "//") or (lang == "py" and ch == "#") then
			table.insert(out, wrapColor(string.sub(line, i), SYNTAX_COLORS.Comment))
			break
		-- Long bracket strings in Luau
		elseif lang == "luau" and string.sub(line, i, i + 1) == "[[" then
			local closeStart, closeEnd = string.find(line, "]]", i + 2, true)
			if closeStart then
				table.insert(out, wrapColor(string.sub(line, i, closeEnd), SYNTAX_COLORS.String))
				i = closeEnd + 1
			else
				table.insert(out, wrapColor(string.sub(line, i), SYNTAX_COLORS.String))
				break
			end
		-- Quoted strings
		elseif ch == '"' or ch == "'" or (lang == "js" and ch == "`") then
			local j = i + 1
			local escaped = false
			while j <= n do
				local c = string.sub(line, j, j)
				if escaped then
					escaped = false
				elseif c == "\\" then
					escaped = true
				elseif c == ch then
					j += 1
					break
				end
				j += 1
			end
			local strTok = string.sub(line, i, j - 1)
			local tokColor = SYNTAX_COLORS.String
			if lang == "json" and string.match(string.sub(line, j), "^%s*:") then
				tokColor = SYNTAX_COLORS.Key
			end
			table.insert(out, wrapColor(strTok, tokColor))
			i = j
		-- Numbers
		elseif string.match(ch, "%d") then
			local _, numEnd = string.find(line, "^0[xX][%da-fA-F_]+", i)
			if not numEnd then
				_, numEnd = string.find(line, "^%d[%d_]*%.?[%d_]*", i)
			end
			numEnd = numEnd or i
			table.insert(out, wrapColor(string.sub(line, i, numEnd), SYNTAX_COLORS.Number))
			i = numEnd + 1
		-- Identifiers / keywords / builtins / members
		elseif string.match(ch, "[%a_]") then
			local _, idEnd = string.find(line, "^[%w_]+", i)
			idEnd = idEnd or i
			local ident = string.sub(line, i, idEnd)
			local prevChar = i > 1 and string.sub(line, i - 1, i - 1) or ""
			local kwMap = (lang == "luau") and LUAU_KEYWORDS or GENERIC_KEYWORDS
			local litMap = (lang == "luau") and LUAU_LITERALS or GENERIC_LITERALS

			if kwMap[ident] and prevChar ~= "." and prevChar ~= ":" then
				table.insert(out, wrapColor(ident, SYNTAX_COLORS.Keyword))
			elseif litMap[ident] and prevChar ~= "." and prevChar ~= ":" then
				table.insert(out, wrapColor(ident, SYNTAX_COLORS.Literal))
			elseif prevChar == "." or prevChar == ":" then
				table.insert(out, wrapColor(ident, SYNTAX_COLORS.Member))
			elseif lang == "luau" and LUAU_BUILTINS[ident] then
				table.insert(out, wrapColor(ident, SYNTAX_COLORS.Builtin))
			else
				table.insert(out, escapeRichText(ident))
			end
			i = idEnd + 1
		else
			table.insert(out, escapeRichText(ch))
			i += 1
		end
	end

	return table.concat(out), inBlockComment
end

local CodeBlock = {}
function CodeBlock.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Code")
	local element = Base.New("CodeBlock", parent, opts, ctx)

	local currentCode = tostring(opts.Code or opts.Text or opts.Content or "")
	element.Value = currentCode

	local card = Base.Card(parent, {
		SurfaceKey = "Field",
		SurfaceTransparency = 0,
		Padding = 0,
	})
	card.Frame.ClipsDescendants = true

	local body = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = card.Frame,
	})

	Create.List(body, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 0,
	})

	local header = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 32),
		BackgroundTransparency = 1,
		Padding = { 0, 8, 0, 12 },
		LayoutOrder = 1,
		Parent = body,
	})

	local headerLeft = Create.New("Frame", {
		Name = "Left",
		Size = UDim2.new(1, -84, 1, 0),
		BackgroundTransparency = 1,
		Parent = header,
	})

	Create.List(headerLeft, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 6,
	})

	Icons.Create(opts.Icon or "code", {
		Size = UDim2.fromOffset(14, 14),
		Color = "Accent",
		LayoutOrder = 1,
		Parent = headerLeft,
	})

	local titleText = tostring(opts.Title or opts.Language or "Code")
	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "Medium",
		TextSize = 12,
		Color = "SubText",
		Size = UDim2.new(1, -22, 1, 0),
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 2,
		Parent = headerLeft,
	})

	local copyBtn = Create.New("TextButton", {
		Name = "CopyButton",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromScale(1, 0.5),
		Size = UDim2.fromOffset(0, 22),
		AutomaticSize = Enum.AutomaticSize.X,
		Theme = { BackgroundColor3 = "Tile" },
		Corner = 6,
		Padding = { 0, 8, 0, 8 },
		Stroke = {
			Theme = { Color = "Stroke" },
			Transparency = 0.86,
			Thickness = 1,
		},
		ZIndex = 4,
		Parent = header,
	})

	Create.List(copyBtn, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 5,
	})

	local copyIcon = Icons.Create("copy", {
		Size = UDim2.fromOffset(14, 14),
		Color = "SubText",
		LayoutOrder = 1,
		Parent = copyBtn,
	})

	local copyLabel = Create.Text({
		Name = "Label",
		Text = "Copy",
		Font = "Medium",
		TextSize = 11,
		Color = "SubText",
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		LayoutOrder = 2,
		Parent = copyBtn,
	})

	element.Maid:Give(Transition.Hover(copyBtn, copyBtn, "Tile", "TileHover"))

	local sep = Create.New("Frame", {
		Name = "Separator",
		Size = UDim2.new(1, 0, 0, 1),
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		LayoutOrder = 2,
		Parent = body,
	})

	local wrap = (opts.Wrap == true)
	local scroll = Create.New("ScrollingFrame", {
		Name = "CodeScroll",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.None,
		AutomaticCanvasSize = Enum.AutomaticSize.None,
		CanvasSize = UDim2.new(0, 0, 0, 0),
		ScrollBarThickness = 4,
		ScrollBarImageTransparency = 0.25,
		ScrollingDirection = wrap and Enum.ScrollingDirection.Y or Enum.ScrollingDirection.XY,
		Active = true,
		ScrollingEnabled = true,
		ClipsDescendants = true,
		BackgroundTransparency = 1,
		Theme = { ScrollBarImageColor3 = "Muted" },
		LayoutOrder = 3,
		Parent = body,
	})

	local padTop = 8
	local padBottom = wrap and 14 or 18
	local padLeft = 10
	local padRight = 14

	local codeList = Create.New("Frame", {
		Name = "CodeList",
		Size = wrap and UDim2.new(1, 0, 0, 0) or UDim2.fromOffset(0, 0),
		AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
		BackgroundTransparency = 1,
		Padding = { padTop, padRight, padBottom, padLeft },
		Parent = scroll,
	})

	local codeLayout = Create.List(codeList, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 2,
	})

	local lastLineCount = 1
	local function updateCodeScrollBounds(lineCount)
		lastLineCount = math.max(1, tonumber(lineCount) or lastLineCount or 1)
		local layoutSize = codeLayout.AbsoluteContentSize
		local fallbackH = lastLineCount * 18 - 2
		local innerH = (layoutSize.Y > 0) and layoutSize.Y or fallbackH
		local contentH = math.max(innerH + padTop + padBottom, 34)
		local fixedH = tonumber(opts.Height)
		local maxH = fixedH or tonumber(opts.MaxHeight) or 180
		local visibleH = fixedH or math.min(contentH, maxH)
		local contentW = (not wrap and layoutSize.X > 0) and (layoutSize.X + padLeft + padRight) or 0
		scroll.Size = UDim2.new(1, 0, 0, visibleH)
		scroll.CanvasSize = UDim2.fromOffset(contentW, contentH)
	end

	element.Maid:Give(codeLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
		updateCodeScrollBounds(lastLineCount)
	end))

	local showLines = (opts.LineNumbers ~= false)
	local codeLang = detectCodeLanguage(opts, currentCode)

	local function splitLines(src)
		local out = {}
		local startIdx = 1
		while true do
			local nl = string.find(src, "\n", startIdx, true)
			if nl then
				local seg = string.sub(src, startIdx, nl - 1)
				seg = string.gsub(seg, "\r$", "")
				seg = string.gsub(seg, "\t", "    ")
				table.insert(out, seg)
				startIdx = nl + 1
			else
				local seg = string.sub(src, startIdx)
				seg = string.gsub(seg, "\r$", "")
				seg = string.gsub(seg, "\t", "    ")
				table.insert(out, seg)
				break
			end
		end
		return out
	end

	local function refreshCode(src)
		currentCode = tostring(src or "")
		element.Value = currentCode
		for _, child in ipairs(codeList:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end

		local lines = splitLines(currentCode)
		local gutterW = math.max(18, #tostring(#lines) * 8 + 4)
		local textOffset = showLines and (gutterW + 10) or 0
		local inBlockComment = false

		for lineIdx, rawLine in ipairs(lines) do
			local highlighted
			highlighted, inBlockComment = highlightCodeLine(rawLine, codeLang, inBlockComment)

			local rowFrame = Create.New("Frame", {
				Name = "Line_" .. lineIdx,
				Size = wrap and UDim2.new(1, 0, 0, 0) or UDim2.fromOffset(0, 0),
				AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
				BackgroundTransparency = 1,
				LayoutOrder = lineIdx,
				Parent = codeList,
			})

			if showLines then
				Create.New("TextLabel", {
					Name = "Num",
					Size = UDim2.fromOffset(gutterW, 16),
					Position = UDim2.fromOffset(0, 0),
					BackgroundTransparency = 1,
					Text = tostring(lineIdx),
					TextSize = 12,
					FontFace = Theme.Mono("Regular"),
					TextXAlignment = Enum.TextXAlignment.Right,
					TextYAlignment = Enum.TextYAlignment.Top,
					Theme = { TextColor3 = "Muted" },
					Parent = rowFrame,
				})
			end

			Create.New("TextLabel", {
				Name = "Code",
				Position = UDim2.fromOffset(textOffset, 0),
				Size = wrap and UDim2.new(1, -textOffset, 0, 0) or UDim2.fromOffset(0, 0),
				AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.XY,
				BackgroundTransparency = 1,
				Text = highlighted ~= "" and highlighted or " ",
				TextSize = 12,
				FontFace = Theme.Mono("Regular"),
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				TextWrapped = wrap,
				RichText = true,
				Theme = { TextColor3 = "Text" },
				Parent = rowFrame,
			})
		end

		updateCodeScrollBounds(#lines)
	end

	refreshCode(currentCode)

	local copyToken = 0
	element.Maid:Give(copyBtn.Activated:Connect(function(inputObj)
		if element.Disabled or element.Locked then
			return
		end
		Util.SetClipboard(currentCode)
		Transition.Ripple(copyBtn, inputObj, "Accent")

		copyToken += 1
		local myToken = copyToken
		if copyIcon then
			Icons.Set(copyIcon, "check")
			Icons.SetColor(copyIcon, "Success")
		end
		Theme.Bind(copyLabel, { TextColor3 = "Success" })
		copyLabel.Text = "Copied!"

		task.delay(1.5, function()
			if element._destroyed or copyToken ~= myToken then
				return
			end
			if copyIcon then
				Icons.Set(copyIcon, "copy")
				Icons.SetColor(copyIcon, "SubText")
			end
			Theme.Bind(copyLabel, { TextColor3 = "SubText" })
			copyLabel.Text = "Copy"
		end)
	end))

	card.TitleLabel = titleLabel
	function card:SetTitle(s)
		titleLabel.Text = tostring(s or "")
	end

	element:BindUI(card)

	function element:SetCode(src)
		refreshCode(src)
	end
	element.SetText = element.SetCode

	function element:Get()
		return currentCode
	end

	return element
end

-- ─── Image ───────────────────────────────────────────────────────────────────

local Image = {}
function Image.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Image")
	local element = Base.New("Image", parent, opts, ctx)

	local card = Base.Card(parent, {
		Padding = 0,
		Corner = opts.Corner or 10,
	})
	card.Frame.ClipsDescendants = true
	Create.List(card.Frame, { Gap = 0 })

	local titleText = tostring(opts.Title or "")
	local captionText = tostring(opts.Caption or opts.Description or opts.Desc or "")
	local useOverlay = opts.Overlay == true or opts.GradientOverlay == true or opts.Badge ~= nil or opts.Icon ~= nil
	local cornerRadius = opts.Corner or 10
	local fullBleed = useOverlay or (titleText == "" and captionText == "")

	local defaultHeight = opts.Height or (opts.Overlay and 148 or 150)
	local mediaWrap = Create.New("Frame", {
		Name = "MediaWrap",
		Size = UDim2.new(1, 0, 0, defaultHeight),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		LayoutOrder = 1,
		Parent = card.Frame,
	})

	local picClip = Create.New("CanvasGroup", {
		Name = "PictureClip",
		Size = fullBleed and UDim2.fromScale(1, 1) or UDim2.new(1, 0, 1, cornerRadius),
		Position = UDim2.fromOffset(0, 0),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Corner = cornerRadius,
		ZIndex = 1,
		Parent = mediaWrap,
	})

	local imgLabel = Create.New("ImageLabel", {
		Name = "Picture",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ScaleType = opts.ScaleType or Enum.ScaleType.Crop,
		ZIndex = 1,
		Parent = picClip,
	})

	local fallbackIcon = Icons.Create("image", {
		Size = UDim2.fromOffset(28, 28),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Color = "Muted",
		Visible = false,
		ZIndex = 2,
		Parent = mediaWrap,
	})

	local function applyImage(source)
		local resolved = Icons.Resolve(source)
		if resolved and resolved.Kind == "Asset" then
			imgLabel.Image = resolved.Image
			imgLabel.ImageRectOffset = Vector2.zero
			imgLabel.ImageRectSize = Vector2.zero
			if fallbackIcon then
				fallbackIcon.Visible = false
			end
		elseif resolved and resolved.Kind == "Atlas" then
			imgLabel.Image = resolved.Image
			imgLabel.ImageRectOffset = resolved.Offset
			imgLabel.ImageRectSize = resolved.Size
			if fallbackIcon then
				fallbackIcon.Visible = false
			end
		else
			imgLabel.Image = ""
			if fallbackIcon then
				fallbackIcon.Visible = true
			end
		end
	end

	applyImage(opts.Image)

	if opts.AspectRatio and opts.AspectRatio > 0 then
		local ratio = opts.AspectRatio
		local function updateAspect()
			local w = card.Frame.AbsoluteSize.X
			if w > 0 then
				mediaWrap.Size = UDim2.new(1, 0, 0, math.max(48, math.floor(w / ratio)))
			end
		end
		element.Maid:Give(card.Frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateAspect))
		task.defer(updateAspect)
	end

	if opts.Badge ~= nil and opts.Badge ~= "" and opts.Badge ~= false then
		local badgePill = Create.New("Frame", {
			Name = "Badge",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -10, 0, 10),
			Size = UDim2.fromOffset(0, 22),
			AutomaticSize = Enum.AutomaticSize.X,
			Corner = 6,
			BackgroundTransparency = 0.16,
			Theme = { BackgroundColor3 = "Card" },
			Padding = { 0, 8, 0, 8 },
			ZIndex = 5,
			Parent = mediaWrap,
		})
		Create.Stroke(badgePill, {
			Theme = { Color = "Accent" },
			Transparency = 0.45,
		})
		Create.Text({
			Text = tostring(opts.Badge),
			Font = "SemiBold",
			TextSize = 11,
			Color = "Text",
			Size = UDim2.fromScale(0, 1),
			AutomaticSize = Enum.AutomaticSize.X,
			TextXAlignment = Enum.TextXAlignment.Center,
			ZIndex = 6,
			Parent = badgePill,
		})
	end

	local scrim
	if useOverlay then
		scrim = Create.New("Frame", {
			Name = "CaptionOverlay",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.fromScale(0, 1),
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Corner = cornerRadius,
			BackgroundColor3 = Color3.fromRGB(10, 10, 16),
			BackgroundTransparency = 0,
			Padding = { 26, 12, 11, 12 },
			Visible = (titleText ~= "" or captionText ~= ""),
			ZIndex = 3,
			Parent = mediaWrap,
		})
		local scrimGrad = Instance.new("UIGradient")
		scrimGrad.Rotation = -90
		scrimGrad.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.06),
			NumberSequenceKeypoint.new(0.55, 0.28),
			NumberSequenceKeypoint.new(1, 1),
		})
		scrimGrad.Parent = scrim
	else
		scrim = Create.New("Frame", {
			Name = "CaptionOverlay",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Theme = { BackgroundColor3 = "Tile" },
			BackgroundTransparency = 0.25,
			Padding = { 10, 12, 10, 12 },
			Visible = (titleText ~= "" or captionText ~= ""),
			LayoutOrder = 2,
			ZIndex = 3,
			Parent = card.Frame,
		})
	end

	local textColParent = scrim
	if opts.Icon then
		Create.List(scrim, {
			Direction = Enum.FillDirection.Horizontal,
			Gap = 10,
			VAlign = Enum.VerticalAlignment.Center,
		})
		local iconChip = Create.New("Frame", {
			Name = "IconChip",
			Size = UDim2.fromOffset(28, 28),
			Corner = 8,
			BackgroundTransparency = 0.80,
			Theme = { BackgroundColor3 = "Accent" },
			LayoutOrder = 1,
			ZIndex = 4,
			Parent = scrim,
		})
		Create.Stroke(iconChip, {
			Theme = { Color = "Accent" },
			Transparency = 0.55,
		})
		Icons.Create(opts.Icon, {
			Size = UDim2.fromOffset(15, 15),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Color = "Accent",
			ZIndex = 5,
			Parent = iconChip,
		})
		textColParent = Create.New("Frame", {
			Name = "TextCol",
			Size = UDim2.new(1, -38, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 2,
			ZIndex = 4,
			Parent = scrim,
		})
	end

	Create.List(textColParent, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 2,
	})

	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "SemiBold",
		TextSize = 13,
		Color = "Text",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Visible = titleText ~= "",
		ZIndex = 4,
		Parent = textColParent,
	})

	local captionLabel = Create.Text({
		Name = "Caption",
		Text = captionText,
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = captionText ~= "",
		ZIndex = 4,
		Parent = textColParent,
	})

	local function refreshScrim()
		scrim.Visible = (titleLabel.Text ~= "" or captionLabel.Text ~= "")
	end

	card.TitleLabel = titleLabel
	card.DescLabel = captionLabel
	function card:SetTitle(s)
		local txt = tostring(s or "")
		titleLabel.Text = txt
		titleLabel.Visible = (txt ~= "")
		refreshScrim()
	end
	function card:SetDesc(s)
		local txt = tostring(s or "")
		captionLabel.Text = txt
		captionLabel.Visible = (txt ~= "")
		refreshScrim()
	end

	element:BindUI(card)

	function element:SetImage(src)
		applyImage(src)
	end

	function element:SetCaption(s)
		self:SetDesc(s)
	end

	return element
end

-- ─── ProfileCard ─────────────────────────────────────────────────────────────

local ProfileCard = {}
function ProfileCard.new(parent, opts, ctx)
	opts = Util.Options(opts, {}, "Title")
	local element = Base.New("ProfileCard", parent, opts, ctx)

	local localPlayer = Services.Players.LocalPlayer
	local userId = opts.UserId or (localPlayer and localPlayer.UserId) or 0
	local defaultTitle = localPlayer and ("Welcome Back, " .. localPlayer.DisplayName) or "Welcome Back"
	local defaultSub = localPlayer and ("@" .. localPlayer.Name) or "Guest"

	local titleText = tostring(opts.Title or defaultTitle)
	local subtitleText = tostring(opts.Subtitle or opts.Description or opts.Desc or defaultSub)
	local statusText = tostring(opts.Status or "Online")
	local statusColor = opts.StatusColor or "Success"

	element.Title = titleText
	element.Desc = subtitleText

	local card = Base.Card(parent, { Padding = 0 })
	card.Frame.ClipsDescendants = true

	if Assets.Get("Glow") then
		Create.New("ImageLabel", {
			Name = "Glow",
			Size = UDim2.fromOffset(160, 72),
			Position = UDim2.fromOffset(-36, -32),
			BackgroundTransparency = 1,
			Image = Assets.Get("Glow"),
			Corner = 10,
			Theme = {
				ImageColor3 = "Accent",
				ImageTransparency = "GlowTransparency",
			},
			ZIndex = 1,
			Parent = card.Frame,
		})
	end

	local body = Create.New("Frame", {
		Name = "Body",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 12, 12, 12, 12 },
		ZIndex = 2,
		Parent = card.Frame,
	})

	Create.List(body, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		Gap = 12,
	})

	local avatarWrap = Create.New("Frame", {
		Name = "Avatar",
		Size = UDim2.fromOffset(44, 44),
		Theme = { BackgroundColor3 = "Field" },
		Corner = UDim.new(1, 0),
		Stroke = {
			Theme = { Color = "Accent" },
			Transparency = 0.55,
			Thickness = 1.5,
		},
		LayoutOrder = 1,
		Parent = body,
	})

	local fallbackIcon = Icons.Create("user", {
		Size = UDim2.fromOffset(20, 20),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Color = "SubText",
		Parent = avatarWrap,
	})

	local avatarImg = Create.New("ImageLabel", {
		Name = "AvatarImage",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Corner = UDim.new(1, 0),
		Visible = false,
		ZIndex = 2,
		Parent = avatarWrap,
	})

	local statusDot = Create.New("Frame", {
		Name = "StatusDot",
		Size = UDim2.fromOffset(10, 10),
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.fromScale(1, 1),
		Corner = UDim.new(1, 0),
		Theme = { BackgroundColor3 = statusColor },
		Stroke = {
			Theme = { Color = "Tile" },
			Transparency = 0,
			Thickness = 2,
		},
		ZIndex = 4,
		Parent = avatarWrap,
	})
	element.Maid:Give(Transition.Pulse(statusDot, "BackgroundTransparency", 0, 0.28, 2.4))

	if userId and userId > 0 then
		task.spawn(function()
			local ok, thumbUrl, isReady = pcall(function()
				return Services.Players:GetUserThumbnailAsync(
					userId,
					Enum.ThumbnailType.HeadShot,
					Enum.ThumbnailSize.Size150x150
				)
			end)
			if element._destroyed or not avatarImg.Parent then
				return
			end
			if ok and type(thumbUrl) == "string" and thumbUrl ~= "" then
				avatarImg.Image = thumbUrl
				avatarImg.Visible = true
				if fallbackIcon then
					fallbackIcon.Visible = false
				end
			end
		end)
	end

	local infoCol = Create.New("Frame", {
		Name = "Info",
		Size = UDim2.new(1, -(44 + 12), 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		Parent = body,
	})

	Create.List(infoCol, {
		Direction = Enum.FillDirection.Vertical,
		Gap = 3,
	})

	local titleLabel = Create.Text({
		Name = "Title",
		Text = titleText,
		Font = "SemiBold",
		TextSize = 14,
		Color = "Text",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 1,
		Parent = infoCol,
	})

	local subLabel = Create.Text({
		Name = "Subtitle",
		Text = subtitleText,
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextWrapped = true,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = 2,
		Visible = subtitleText ~= "",
		Parent = infoCol,
	})

	local badgeWrap = Create.New("Frame", {
		Name = "StatusWrap",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 2, 0, 0, 0 },
		LayoutOrder = 3,
		Visible = statusText ~= "",
		Parent = infoCol,
	})

	local statusBadge = Base.Badge(badgeWrap, statusText, statusColor)

	if opts.Button then
		local btnOpts = type(opts.Button) == "table" and opts.Button or { Title = tostring(opts.Button) }
		local pillBtn = Create.New("TextButton", {
			Name = "ActionButton",
			Size = UDim2.fromOffset(0, 30),
			AutomaticSize = Enum.AutomaticSize.X,
			ClipsDescendants = true,
			Theme = { BackgroundColor3 = "Field" },
			Corner = UDim.new(1, 0),
			Padding = { 0, 12, 0, 12 },
			Stroke = {
				Theme = { Color = "Stroke" },
				Transparency = 0.84,
				Thickness = 1,
			},
			LayoutOrder = 3,
			ZIndex = 4,
			Parent = body,
		})

		Create.List(pillBtn, {
			Direction = Enum.FillDirection.Horizontal,
			VAlign = Enum.VerticalAlignment.Center,
			Gap = 5,
		})

		if btnOpts.Icon then
			Icons.Create(btnOpts.Icon, {
				Size = UDim2.fromOffset(14, 14),
				Color = "Text",
				LayoutOrder = 1,
				Parent = pillBtn,
			})
		end

		Create.Text({
			Name = "Label",
			Text = tostring(btnOpts.Title or "Action"),
			Font = "Medium",
			TextSize = 12,
			Color = "Text",
			Size = UDim2.fromOffset(0, 0),
			AutomaticSize = Enum.AutomaticSize.XY,
			LayoutOrder = 2,
			Parent = pillBtn,
		})

		element.Maid:Give(Transition.Hover(pillBtn, pillBtn, "Field", "TileHover"))
		element.Maid:Give(pillBtn.Activated:Connect(function(inputObj)
			if element.Disabled or element.Locked then
				return
			end
			Transition.Ripple(pillBtn, inputObj, "Accent")
			if type(btnOpts.Callback) == "function" then
				Util.Spawn(btnOpts.Callback)
			end
		end))

		local function syncInfoWidth()
			local bodyW = body.AbsoluteSize.X > 0 and body.AbsoluteSize.X or 320
			local rawBtnW = math.ceil(pillBtn.AbsoluteSize.X)
			local maxBtnW = math.max(64, math.floor(bodyW * 0.42))
			local btnW = math.min(rawBtnW > 0 and rawBtnW or 108, maxBtnW)
			infoCol.Size = UDim2.new(1, -(44 + 12 + btnW + 12), 0, 0)
		end
		element.Maid:Give(pillBtn:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncInfoWidth))
		element.Maid:Give(body:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncInfoWidth))
		task.defer(syncInfoWidth)
	end

	card.TitleLabel = titleLabel
	card.DescLabel = subLabel
	function card:SetTitle(s)
		local txt = tostring(s or "")
		titleLabel.Text = txt
		titleLabel.Visible = (txt ~= "")
	end
	function card:SetDesc(s)
		local txt = tostring(s or "")
		subLabel.Text = txt
		subLabel.Visible = (txt ~= "")
	end

	element:BindUI(card)

	function element:SetStatus(text, colorKey)
		local txt = tostring(text or "")
		statusBadge:SetText(txt)
		badgeWrap.Visible = (txt ~= "")
		if colorKey then
			statusBadge:SetColor(colorKey)
			Theme.Bind(statusDot, { BackgroundColor3 = colorKey })
		end
	end

	return element
end

Static.Label = Label
Static.Paragraph = Paragraph
Static.Divider = Divider
Static.Header = Header
Static.CodeBlock = CodeBlock
Static.Image = Image
Static.ProfileCard = ProfileCard

return Static
end

__modules["Elements/Toggle"] = function()
--[[
	Bali UI · Elements/Toggle
	Apple pill Toggle switch (with optional inline Keybind sub-chip) and Checkbox.
]]

local Util = require("Core/Util")
local Tween = require("Core/Tween")
local Theme = require("Core/Theme")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Transition = require("Core/Transition")
local Input = require("Systems/Input")
local KeybindList = require("Systems/KeybindList")
local Base = require("Elements/Base")

local ToggleModule = {}

-- ─── Toggle ──────────────────────────────────────────────────────────────────

local Toggle = {}
function Toggle.new(parent, opts, ctx)
	opts = Util.Options(opts, { Default = false }, "Title")
	local element = Base.New("Toggle", parent, opts, ctx)

	local state = opts.Default == true
	element.Value = state

	local rowOpts = table.clone(opts)
	if rowOpts.IconBadge == nil then
		rowOpts.IconBadge = false
	end

	local hasKeybind = opts.Keybind ~= nil
	element._hasKeybind = hasKeybind
	local row = Base.Row(parent, rowOpts, hasKeybind and 86 or 44)
	element:BindUI(row)

	Create.List(row.Right, {
		Direction = Enum.FillDirection.Horizontal,
		VAlign = Enum.VerticalAlignment.Center,
		HAlign = Enum.HorizontalAlignment.Right,
		Gap = 6,
	})

	-- Pill switch (42x22)
	local track = Create.New("Frame", {
		Name = "Track",
		Size = UDim2.fromOffset(42, 22),
		Theme = {
			BackgroundColor3 = function(t)
				return state and t.Accent or t.Field
			end,
		},
		Corner = UDim.new(1, 0),
		LayoutOrder = 2,
		Parent = row.Right,
	})

	local trackStroke = Create.Stroke(track, {
		Theme = {
			Color = function(t)
				return state and t.Accent or t.Stroke
			end,
			Transparency = function(t)
				return state and 1 or math.min(0.48, t.StrokeTransparency)
			end,
		},
		Thickness = 1.2,
	})

	local knob = Create.New("Frame", {
		Name = "Knob",
		Size = state and UDim2.fromOffset(18, 18) or UDim2.fromOffset(16, 16),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, state and 22 or 3, 0.5, 0),
		BackgroundColor3 = state and Theme.Current.Knob or (Theme.Current.Dark and Color3.fromRGB(186, 192, 206) or Theme.Current.Knob),
		Corner = UDim.new(1, 0),
		ZIndex = 3,
		Parent = track,
	})

	local inputHandle = nil
	local currentKey = nil
	local listening = false
	local stopPulse = nil
	local syncKeybindList = nil
	local keyChip, keyStroke, keyLabel

	local function applyVisual(animate)
		local targetPos = UDim2.new(0, state and 22 or 3, 0.5, 0)
		local targetSize = state and UDim2.fromOffset(18, 18) or UDim2.fromOffset(16, 16)
		local targetKnobColor = state and Theme.Current.Knob or (Theme.Current.Dark and Color3.fromRGB(186, 192, 206) or Theme.Current.Knob)
		local targetTrackBg = state and Theme.Current.Accent or Theme.Current.Field
		local targetStrokeColor = state and Theme.Current.Accent or Theme.Current.Stroke
		local targetStrokeTrans = state and 1 or math.min(0.48, Theme.Current.StrokeTransparency)

		if animate then
			Tween.Spring(knob, { Position = targetPos }, Tween.Fast + 0.08)
			Tween.Play(knob, {
				Size = UDim2.fromOffset(22, state and 18 or 16),
				BackgroundColor3 = targetKnobColor,
			}, 0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			task.delay(0.07, function()
				if knob.Parent and not element._destroyed then
					Tween.Spring(knob, { Size = state and UDim2.fromOffset(18, 18) or UDim2.fromOffset(16, 16) }, 0.13)
				end
			end)
			Tween.Play(track, { BackgroundColor3 = targetTrackBg }, Tween.Fast, Enum.EasingStyle.Quad)
			Tween.Play(trackStroke, {
				Color = targetStrokeColor,
				Transparency = targetStrokeTrans,
			}, Tween.Fast, Enum.EasingStyle.Quad)
		else
			knob.Position = targetPos
			knob.Size = targetSize
			knob.BackgroundColor3 = targetKnobColor
			track.BackgroundColor3 = targetTrackBg
			trackStroke.Color = targetStrokeColor
			trackStroke.Transparency = targetStrokeTrans
		end
	end

	element.Maid:Give(Theme.Changed:Connect(function(t)
		if element._destroyed then
			return
		end
		applyVisual(false)
	end))

	-- Optional inline Keybind sub-chip
	if hasKeybind then
		local rawKey = type(opts.Keybind) == "table" and opts.Keybind.Key or (opts.Keybind == true and nil or opts.Keybind)
		currentKey = Util.ResolveKey(rawKey)
		local bindId = "ToggleKB_" .. Util.RandomString(8)

		keyChip = Create.New("TextButton", {
			Name = "KeyChip",
			Size = UDim2.fromOffset(0, 22),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 0.12,
			Theme = { BackgroundColor3 = "TileHover" },
			Corner = 6,
			Padding = { 0, 7, 0, 7 },
			Text = "",
			AutoButtonColor = false,
			LayoutOrder = 1,
			ZIndex = 16,
			Parent = row.Right,
		})

		keyStroke = Create.Stroke(keyChip, {
			Theme = { Color = "Stroke" },
			Transparency = 0.48,
			Thickness = 1,
		})

		keyLabel = Create.Text({
			Name = "KeyLabel",
			Text = Util.KeyName(currentKey),
			Font = "SemiBold",
			TextSize = 11,
			Color = currentKey and "Text" or "Muted",
			Size = UDim2.fromOffset(0, 22),
			AutomaticSize = Enum.AutomaticSize.X,
			TextXAlignment = Enum.TextXAlignment.Center,
			ZIndex = 17,
			Parent = keyChip,
		})

		element.Maid:Give(Transition.Hover(keyChip, keyChip, "TileHover", "FieldHover", keyStroke))

		local function syncChip()
			if not listening then
				keyLabel.Text = Util.KeyName(currentKey)
				Theme.Bind(keyLabel, { TextColor3 = currentKey and "Text" or "Muted" })
				Theme.Bind(keyStroke, { Color = "Stroke" })
				keyStroke.Transparency = 0.48
			end
			local chipW = math.max(28, math.ceil(keyChip.AbsoluteSize.X))
			row:SetRightWidth(42 + 6 + chipW)
		end

		element.Maid:Give(keyChip:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncChip))
		task.defer(syncChip)

		local function stopListening()
			if not listening then
				return
			end
			listening = false
			if stopPulse then
				pcall(stopPulse)
				stopPulse = nil
			end
			syncChip()
		end

		local syncList = opts.SyncList ~= false
		syncKeybindList = function()
			if not syncList or not KeybindList or not KeybindList.Update then
				return
			end
			KeybindList.Update(bindId, {
				Title = tostring(element.Title or opts.Title or "Toggle"),
				KeyName = Util.KeyName(currentKey),
				Mode = "Toggle",
				Active = state,
			})
		end

		inputHandle = Input.RegisterKeybind(bindId, currentKey, function(active)
			if element._destroyed or element.Disabled or element.Locked then
				if inputHandle then
					inputHandle.SetActive(state, true)
				end
				return
			end
			element:Set(active)
		end, "Toggle")
		inputHandle.SetActive(state, true)

		if syncList and KeybindList and KeybindList.Register then
			KeybindList.Register(bindId, {
				Title = tostring(opts.Title or "Toggle"),
				KeyName = Util.KeyName(currentKey),
				Mode = "Toggle",
				Active = state,
			})
		end

		element.Maid:Give(function()
			if listening then
				Input.CancelCapture()
			end
			stopListening()
			if inputHandle then
				inputHandle.Destroy()
				inputHandle = nil
			end
			if syncList and KeybindList and KeybindList.Unregister then
				KeybindList.Unregister(bindId)
			end
		end)

		element.Maid:Give(keyChip.Activated:Connect(function(inputObj)
			if element.Disabled or element.Locked then
				return
			end
			Transition.Ripple(keyChip, inputObj, "Accent")
			if listening then
				Input.CancelCapture()
				stopListening()
				return
			end
			listening = true
			keyLabel.Text = "..."
			Theme.Bind(keyLabel, { TextColor3 = "Accent" })
			Theme.Bind(keyStroke, { Color = "Accent" })
			keyStroke.Transparency = 0.25
			if stopPulse then
				pcall(stopPulse)
			end
			stopPulse = Transition.Pulse(keyStroke, "Transparency", 0.15, 0.72, 0.75)

			Input.CaptureKey(function(captured, cancelled)
				if element._destroyed or not listening then
					return
				end
				stopListening()
				if cancelled then
					return
				end
				currentKey = Util.ResolveKey(captured)
				if inputHandle then
					inputHandle.SetKey(currentKey)
				end
				syncKeybindList()
				syncChip()
				element.Changed:Fire(state, currentKey)
			end)
		end))
	end

	local hitBtn = Create.New("TextButton", {
		Name = "HitButton",
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromScale(0, 0),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 12,
		Parent = row.Frame,
	})

	element.Maid:Give(Transition.Hover(hitBtn, row.Frame, "Tile", "TileHover", row.Stroke))

	local lastPointerPos = nil
	element.Maid:Give(hitBtn.InputBegan:Connect(function(input)
		if element.Disabled or element.Locked then
			return
		end
		if Util.IsPointer(input) then
			lastPointerPos = Vector2.new(input.Position.X, input.Position.Y)
		end
	end))

	element._onDisabled = function(disabled)
		hitBtn.Visible = not disabled
		if keyChip then
			keyChip.Active = not disabled
		end
		track.BackgroundTransparency = disabled and 0.45 or 0
	end

	function element:Set(val, silent)
		local nextState = (val == true)
		local changed = (state ~= nextState)
		state = nextState
		self.Value = state
		applyVisual(true)
		if inputHandle then
			inputHandle.SetActive(state, true)
		end
		if syncKeybindList then
			syncKeybindList()
		end
		if changed and not silent then
			self.Changed:Fire(state)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, state)
			end
		end
	end

	function element:Get()
		return state
	end

	function element:Toggle()
		self:Set(not state, false)
	end

	function element:Fire()
		self:Toggle()
	end

	function element:SetKeybind(key)
		if not hasKeybind then
			return
		end
		currentKey = Util.ResolveKey(key)
		if inputHandle then
			inputHandle.SetKey(currentKey)
		end
		if syncKeybindList then
			syncKeybindList()
		end
		if keyLabel then
			keyLabel.Text = Util.KeyName(currentKey)
			Theme.Bind(keyLabel, { TextColor3 = currentKey and "Text" or "Muted" })
		end
	end

	function element:GetKeybind()
		return currentKey
	end

	element.Maid:Give(hitBtn.Activated:Connect(function(inputObj)
		if element.Disabled or element.Locked then
			return
		end
		local pos = (inputObj and inputObj.Position) and Vector2.new(inputObj.Position.X, inputObj.Position.Y) or lastPointerPos
		Transition.Ripple(row.Frame, pos, "Accent")
		element:Toggle()
	end))

	return element
end

-- ─── Checkbox ────────────────────────────────────────────────────────────────

local Checkbox = {}
function Checkbox.new(parent, opts, ctx)
	opts = Util.Options(opts, { Default = false }, "Title")
	local element = Base.New("Checkbox", parent, opts, ctx)

	local state = opts.Default == true
	element.Value = state

	local rowOpts = table.clone(opts)
	if rowOpts.IconBadge == nil then
		rowOpts.IconBadge = false
	end

	local row = Base.Row(parent, rowOpts, 24)
	element:BindUI(row)

	local box = Create.New("Frame", {
		Name = "CheckBox",
		Size = UDim2.fromOffset(20, 20),
		Position = UDim2.fromScale(1, 0.5),
		AnchorPoint = Vector2.new(1, 0.5),
		Theme = {
			BackgroundColor3 = function(t)
				return state and t.Accent or t.Field
			end,
		},
		Corner = 6,
		Parent = row.Right,
	})

	local boxStroke = Create.Stroke(box, {
		Theme = {
			Color = function(t)
				return state and t.Accent or t.Stroke
			end,
			Transparency = function(t)
				return state and 1 or 0.38
			end,
		},
		Thickness = 1.25,
	})

	local checkIcon = Icons.Create("check", {
		Size = UDim2.fromOffset(14, 14),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Color = "AccentText",
		Transparency = state and 0 or 1,
		ZIndex = 3,
		Parent = box,
	})

	local function applyVisual(animate)
		local targetAlpha = state and 0 or 1
		local targetBg = state and Theme.Current.Accent or Theme.Current.Field
		local targetSize = state and UDim2.fromOffset(14, 14) or UDim2.fromOffset(6, 6)
		local targetStrokeColor = state and Theme.Current.Accent or Theme.Current.Stroke
		local targetStrokeTrans = state and 1 or 0.38
		local iconTarget = checkIcon and Icons.TransparencyTarget(checkIcon) or nil
		local iconTransProp = iconTarget and Icons.TransparencyProperty(iconTarget) or "ImageTransparency"

		if animate then
			Tween.Play(box, { BackgroundColor3 = targetBg }, Tween.Fast, Enum.EasingStyle.Quad)
			if checkIcon and iconTarget then
				if iconTarget == checkIcon then
					Tween.Play(checkIcon, { [iconTransProp] = targetAlpha, Size = targetSize }, Tween.Fast, Enum.EasingStyle.Exponential)
				else
					Tween.Play(iconTarget, { [iconTransProp] = targetAlpha }, Tween.Fast, Enum.EasingStyle.Exponential)
					Tween.Play(checkIcon, { Size = targetSize }, Tween.Fast, Enum.EasingStyle.Exponential)
				end
			end
			Tween.Play(boxStroke, {
				Color = targetStrokeColor,
				Transparency = targetStrokeTrans,
			}, Tween.Fast, Enum.EasingStyle.Quad)
		else
			box.BackgroundColor3 = targetBg
			if checkIcon and iconTarget then
				iconTarget[iconTransProp] = targetAlpha
				checkIcon.Size = targetSize
			end
			boxStroke.Color = targetStrokeColor
			boxStroke.Transparency = targetStrokeTrans
		end
	end

	element.Maid:Give(Theme.Changed:Connect(function()
		if element._destroyed then
			return
		end
		applyVisual(false)
	end))

	local hitBtn = Create.New("TextButton", {
		Name = "HitButton",
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromScale(0, 0),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ZIndex = 12,
		Parent = row.Frame,
	})

	element.Maid:Give(Transition.Hover(hitBtn, row.Frame, "Tile", "TileHover", row.Stroke))

	local lastPointerPos = nil
	element.Maid:Give(hitBtn.InputBegan:Connect(function(input)
		if element.Disabled or element.Locked then
			return
		end
		if Util.IsPointer(input) then
			lastPointerPos = Vector2.new(input.Position.X, input.Position.Y)
		end
	end))

	element._onDisabled = function(disabled)
		hitBtn.Visible = not disabled
		box.BackgroundTransparency = disabled and 0.5 or 0
	end

	function element:Set(val, silent)
		local nextState = (val == true)
		local changed = (state ~= nextState)
		state = nextState
		self.Value = state
		applyVisual(true)
		if changed and not silent then
			self.Changed:Fire(state)
			if type(opts.Callback) == "function" then
				Util.Spawn(opts.Callback, state)
			end
		end
	end

	function element:Get()
		return state
	end

	function element:Toggle()
		self:Set(not state, false)
	end

	function element:Fire()
		self:Toggle()
	end

	element.Maid:Give(hitBtn.Activated:Connect(function(inputObj)
		if element.Disabled or element.Locked then
			return
		end
		local pos = (inputObj and inputObj.Position) and Vector2.new(inputObj.Position.X, inputObj.Position.Y) or lastPointerPos
		Transition.Ripple(row.Frame, pos, "Accent")
		element:Toggle()
	end))

	return element
end

ToggleModule.Toggle = Toggle
ToggleModule.Checkbox = Checkbox

return ToggleModule
end

__modules["Window/Container"] = function()
--[[
	Bali UI · Window/Container
	Attaches all element factory methods and common aliases onto any container
	(Section, Accordion, Tab, SubTab), providing unified ctx wiring.
]]

local Config = require("Systems/Config")
local Static = require("Elements/Static")
local Button = require("Elements/Button")
local Toggle = require("Elements/Toggle")
local Slider = require("Elements/Slider")
local Input = require("Elements/Input")
local Segmented = require("Elements/Segmented")
local Dropdown = require("Elements/Dropdown")
local Keybind = require("Elements/Keybind")
local ColorPicker = require("Elements/ColorPicker")
local Analytics = require("Elements/Analytics")
local Accordion = require("Elements/Accordion")

local Container = {}

local function resolveCtor(module, exportKey)
	if type(module) == "table" then
		if type(module.new) == "function" then
			return module.new
		end
		local nested = exportKey and module[exportKey]
		if type(nested) == "table" and type(nested.new) == "function" then
			return nested.new
		end
	elseif type(module) == "function" then
		return module
	end
	error("[Bali] Missing element constructor for " .. tostring(exportKey))
end

local FACTORIES = {
	{ Methods = { "AddLabel", "Label" }, Ctor = resolveCtor(Static.Label, "Label") },
	{ Methods = { "AddParagraph", "Paragraph" }, Ctor = resolveCtor(Static.Paragraph, "Paragraph") },
	{ Methods = { "AddDivider", "Divider" }, Ctor = resolveCtor(Static.Divider, "Divider") },
	{ Methods = { "AddHeader", "Header" }, Ctor = resolveCtor(Static.Header, "Header") },
	{ Methods = { "AddCodeBlock", "CodeBlock" }, Ctor = resolveCtor(Static.CodeBlock, "CodeBlock") },
	{ Methods = { "AddImage", "Image", "AddBanner", "Banner" }, Ctor = resolveCtor(Static.Image, "Image") },
	{ Methods = { "AddProfileCard", "ProfileCard" }, Ctor = resolveCtor(Static.ProfileCard, "ProfileCard") },

	{ Methods = { "AddButton", "Button" }, Ctor = resolveCtor(Button.Button, "Button") },
	{ Methods = { "AddButtonGroup", "ButtonGroup" }, Ctor = resolveCtor(Button.ButtonGroup, "ButtonGroup") },

	{ Methods = { "AddToggle", "Toggle" }, Ctor = resolveCtor(Toggle.Toggle, "Toggle") },
	{ Methods = { "AddCheckbox", "Checkbox" }, Ctor = resolveCtor(Toggle.Checkbox, "Checkbox") },

	{ Methods = { "AddSlider", "Slider" }, Ctor = resolveCtor(Slider.Slider, "Slider") },
	{ Methods = { "AddRangeSlider", "RangeSlider" }, Ctor = resolveCtor(Slider.RangeSlider, "RangeSlider") },
	{ Methods = { "AddStepper", "Stepper" }, Ctor = resolveCtor(Slider.Stepper, "Stepper") },

	{ Methods = { "AddInput", "Input", "AddTextBox" }, Ctor = resolveCtor(Input, "Input") },
	{ Methods = { "AddSegmented", "Segmented" }, Ctor = resolveCtor(Segmented, "Segmented") },
	{ Methods = { "AddDropdown", "Dropdown" }, Ctor = resolveCtor(Dropdown, "Dropdown") },
	{ Methods = { "AddKeybind", "Keybind" }, Ctor = resolveCtor(Keybind, "Keybind") },
	{ Methods = { "AddColorPicker", "ColorPicker" }, Ctor = resolveCtor(ColorPicker, "ColorPicker") },

	{ Methods = { "AddStatCard", "StatCard" }, Ctor = resolveCtor(Analytics.StatCard, "StatCard") },
	{ Methods = { "AddChart", "Chart" }, Ctor = resolveCtor(Analytics.Chart, "Chart") },
	{ Methods = { "AddProgressBar", "ProgressBar" }, Ctor = resolveCtor(Analytics.ProgressBar, "ProgressBar") },
	{ Methods = { "AddTable", "Table" }, Ctor = resolveCtor(Analytics.Table, "Table") },
	{ Methods = { "AddCardGrid", "CardGrid" }, Ctor = resolveCtor(Analytics.CardGrid, "CardGrid") },

	{ Methods = { "AddAccordion", "Accordion" }, Ctor = resolveCtor(Accordion, "Accordion") },
}

local function normalizeOptions(options, extra)
	if type(options) == "string" and type(extra) == "function" then
		return { Title = options, Callback = extra }
	end
	return options
end

function Container.Attach(target, parentFrame, tab, section, window, subTab)
	assert(type(target) == "table", "[Bali] Container.Attach expects a target table")
	assert(typeof(parentFrame) == "Instance", "[Bali] Container.Attach expects a parent Instance")

	local ctx = {
		Window = window,
		Tab = tab,
		SubTab = subTab,
		Section = section,
		PopupLayer = window and window.PopupLayer or nil,
		DialogLayer = window and window.DialogLayer or nil,
		Maid = target.Maid
			or (section and section.Maid)
			or (subTab and subTab.Maid)
			or (tab and tab.Maid)
			or (window and window.Maid),
	}

	local function registerUnnamedIfReady(elem, entry)
		if not window or type(elem) ~= "table" or type(elem.Set) ~= "function" or type(window._unnamedRegistry) ~= "table" then
			return
		end
		if type(entry) ~= "table" or entry._unnamedRegistered then
			return
		end
		local flag = entry.Flag or elem.Flag
		if flag ~= nil and flag ~= "" then
			return
		end
		local ignoreConfig = (elem.IgnoreConfig == true or (type(elem.Options) == "table" and elem.Options.IgnoreConfig == true))
			or (tab and tab._isSettingsTab == true)
		if ignoreConfig then
			return
		end

		local baseKey = string.format(
			"%s/%s/%s/%s:%s",
			tostring(tab and tab.Title or "Main"),
			tostring(subTab and subTab.Title or ""),
			tostring(section and section.Title or ""),
			tostring(elem.Type or "Control"),
			tostring(elem.Title or "Item")
		)
		local autoKey = baseKey
		local idx = 2
		while window._unnamedRegistry[autoKey] do
			autoKey = baseKey .. "#" .. tostring(idx)
			idx += 1
		end
		window._unnamedRegistry[autoKey] = elem
		entry._unnamedRegistered = true
		entry._unnamedKey = autoKey
		if Config.HasLoadedAutoSave() then
			Config.TryApplyCachedAutoSave(autoKey, elem, false)
		end

		if type(elem.Maid) == "table" and type(elem.Maid.Give) == "function" then
			elem.Maid:Give(function()
				if type(window._unnamedRegistry) == "table" and window._unnamedRegistry[autoKey] == elem then
					window._unnamedRegistry[autoKey] = nil
				end
			end)
		end
	end

	local function applyFlaggedIfReady(elem, entry)
		if not window or type(elem) ~= "table" or type(elem.Set) ~= "function" or type(entry) ~= "table" or entry._flaggedAutoApplied then
			return
		end
		local flag = entry.Flag or elem.Flag
		if flag == nil or flag == "" then
			return
		end
		local ignoreConfig = (elem.IgnoreConfig == true or (type(elem.Options) == "table" and elem.Options.IgnoreConfig == true))
			or (tab and tab._isSettingsTab == true)
		if ignoreConfig then
			return
		end
		entry._flaggedAutoApplied = true
		if Config.HasLoadedAutoSave() then
			Config.TryApplyCachedAutoSave(flag, elem, true)
		end
	end

	function ctx.RegisterElement(record)
		if type(record) ~= "table" then
			return nil
		end

		local elem = record.Element or record
		local entry = record
		if not record.Element then
			entry = {
				Type = elem.Type or "Element",
				Title = elem.Title,
				Desc = elem.Desc or elem.Description,
				Flag = elem.Flag,
				Tab = tab,
				SubTab = subTab,
				Section = section,
				Element = elem,
			}
		else
			entry.Tab = entry.Tab or tab
			entry.SubTab = entry.SubTab or subTab
			entry.Section = entry.Section or section
			entry.Flag = entry.Flag or (elem and elem.Flag)
		end

		if window then
			if type(window._elements) == "table" then
				table.insert(window._elements, entry)
			end
			local flag = entry.Flag
			local ignoreConfig = (type(elem) == "table" and (elem.IgnoreConfig == true or (type(elem.Options) == "table" and elem.Options.IgnoreConfig == true)))
				or (tab and tab._isSettingsTab == true)

			if flag ~= nil and flag ~= "" then
				if type(window._registry) == "table" then
					window._registry[flag] = elem
				end
				if type(window.Flags) == "table" and window.Flags ~= window._registry then
					window.Flags[flag] = elem
				end
				applyFlaggedIfReady(elem, entry)
			else
				-- Defer check too via finalizeElement after ctor attaches :Set()
				registerUnnamedIfReady(elem, entry)
			end

			if not ignoreConfig and type(elem) == "table" and elem.Changed and type(elem.Changed.Connect) == "function" then
				local conn = elem.Changed:Connect(function()
					if not Config.IsLoading() then
						Config.TriggerAutoSave()
					end
				end)
				if type(elem.Maid) == "table" and type(elem.Maid.Give) == "function" then
					elem.Maid:Give(conn)
				elseif window.Maid and window.Maid.Give then
					window.Maid:Give(conn)
				end
			end

			if elem and type(elem.Maid) == "table" and type(elem.Maid.Give) == "function" then
				elem.Maid:Give(function()
					if type(window._elements) == "table" then
						local index = table.find(window._elements, entry)
						if index then
							table.remove(window._elements, index)
						end
					end
					if flag ~= nil and flag ~= "" then
						if type(window._registry) == "table" and window._registry[flag] == elem then
							window._registry[flag] = nil
						end
						if type(window.Flags) == "table" and window.Flags[flag] == elem then
							window.Flags[flag] = nil
						end
					end
				end)
			end
		end

		return entry
	end

	function ctx.OpenPopup(id, frame, anchorGui, onClose)
		if window and type(window.OpenPopup) == "function" then
			return window:OpenPopup(id, frame, anchorGui, onClose)
		end
		return nil
	end

	function ctx.ClosePopup(id)
		if window and type(window.ClosePopup) == "function" then
			window:ClosePopup(id)
		end
	end

	function ctx.AttachContainer(subTarget, subParent, subTabArg, subSectionArg, subWindowArg)
		return Container.Attach(
			subTarget,
			subParent,
			subTabArg or tab,
			subSectionArg or section,
			subWindowArg or window,
			subTab
		)
	end

	local nextOrder = 0

	for _, factory in ipairs(FACTORIES) do
		local ctor = factory.Ctor
		local function addElement(self, options, extra)
			if type(self._beforeAdd) == "function" then
				self:_beforeAdd()
			end
			local resolved = normalizeOptions(options, extra)
			local element = ctor(parentFrame, resolved, ctx)
			if type(element) == "table" then
				if type(element._record) == "table" then
					registerUnnamedIfReady(element, element._record)
					applyFlaggedIfReady(element, element._record)
				end
				if typeof(element.Frame) == "Instance" and element.Frame.LayoutOrder == 0 then
					nextOrder += 1
					element.Frame.LayoutOrder = nextOrder
				end
			end
			return element
		end

		for _, methodName in ipairs(factory.Methods) do
			if target[methodName] == nil then
				target[methodName] = addElement
			end
		end
	end

	target._ctx = ctx
	return target
end

return Container
end

__modules["Window/Dialog"] = function()
--[[
	Bali UI · Window/Dialog
	Centered obsidian glass modal dialog over a dimmed backdrop with spring mount,
	optional icon badge, text input field, action buttons, and Escape support.
]]

local Assets = require("Core/Assets")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Maid = require("Core/Maid")
local Services = require("Core/Services")
local Theme = require("Core/Theme")
local Transition = require("Core/Transition")
local Tween = require("Core/Tween")
local Util = require("Core/Util")

local Dialog = {}

local function applyButtonStyle(button, stroke, label, variant)
	if variant == "Primary" then
		Theme.Bind(button, { BackgroundColor3 = "Accent", BackgroundTransparency = 0 })
		Theme.Bind(label, { TextColor3 = "AccentText" })
		if stroke then
			Theme.Bind(stroke, { Color = "Accent", Transparency = 0.55 })
		end
		local gradient = Instance.new("UIGradient")
		gradient.Color = Theme.AccentSequence()
		gradient.Rotation = 18
		gradient.Parent = button
		return gradient
	elseif variant == "Danger" then
		Theme.Bind(button, { BackgroundColor3 = "Error", BackgroundTransparency = 0.82 })
		Theme.Bind(label, { TextColor3 = "Error" })
		if stroke then
			Theme.Bind(stroke, { Color = "Error", Transparency = 0.55 })
		end
	elseif variant == "Ghost" then
		Theme.Bind(button, { BackgroundColor3 = "Tile", BackgroundTransparency = 1 })
		Theme.Bind(label, { TextColor3 = "SubText" })
		if stroke then
			Theme.Bind(stroke, { Color = "Stroke", Transparency = 1 })
		end
	else
		Theme.Bind(button, { BackgroundColor3 = "Tile", BackgroundTransparency = "TileTransparency" })
		Theme.Bind(label, { TextColor3 = "Text" })
		if stroke then
			Theme.Bind(stroke, { Color = "Stroke", Transparency = "StrokeTransparency" })
		end
	end
	return nil
end

function Dialog.Show(dialogLayer, options)
	assert(typeof(dialogLayer) == "Instance", "[Bali] Dialog.Show expects a dialogLayer Instance")
	options = Util.Options(options, {
		Title = "Confirm",
		Content = nil,
		Description = nil,
		Message = nil,
		Icon = nil,
		Buttons = nil,
		Input = nil,
		Dismissible = true,
		OnClose = nil,
	}, "Title")

	local maid = Maid.new()
	local closed = false

	-- Dimmed click-catcher backdrop
	local backdrop = Create.New("TextButton", {
		Name = "DialogBackdrop",
		Size = UDim2.fromScale(1, 1),
		Text = "",
		AutoButtonColor = false,
		Theme = { BackgroundColor3 = "Overlay" },
		BackgroundTransparency = 1,
		ZIndex = 1,
		Parent = dialogLayer,
	})
	maid:Give(backdrop)

	local container = Create.New("Frame", {
		Name = "DialogContainer",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(1, -32, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = dialogLayer,
	})
	maid:Give(container)

	local constraint = Instance.new("UISizeConstraint")
	constraint.MaxSize = Vector2.new(400, 620)
	constraint.Parent = container

	local shadowDesc = Assets.Shadow()
	local shadow = Create.New("ImageLabel", {
		Name = "Shadow",
		Image = shadowDesc.Image,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = shadowDesc.Slice,
		Position = UDim2.fromOffset(-shadowDesc.Inset, -shadowDesc.Inset + 4),
		Size = UDim2.new(1, shadowDesc.Inset * 2, 1, shadowDesc.Inset * 2),
		BackgroundTransparency = 1,
		Theme = {
			ImageColor3 = "Shadow",
			ImageTransparency = "ShadowTransparency",
		},
		ZIndex = 1,
		Parent = container,
	})

	local modal = Create.New("Frame", {
		Name = "DialogModal",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.min(t.CardTransparency or 0.12, 0.03)
			end,
		},
		Corner = 14,
		ClipsDescendants = true,
		ZIndex = 2,
		Parent = container,
	})
	Create.GlassStroke(modal, 0.05)

	local glowAsset = Assets.Get("Glow")
	if glowAsset and Assets.Available then
		Create.New("ImageLabel", {
			Name = "Glow",
			Image = glowAsset,
			Size = UDim2.fromOffset(240, 150),
			Position = UDim2.fromOffset(-80, -75),
			Corner = 14,
			BackgroundTransparency = 1,
			Theme = {
				ImageColor3 = "Accent",
				ImageTransparency = "GlowTransparency",
			},
			ZIndex = 1,
			Parent = modal,
		})
	end

	local inner = Create.New("Frame", {
		Name = "Inner",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = 18,
		ZIndex = 2,
		Parent = modal,
	})
	Create.List(inner, { Gap = 12 })

	-- Header row
	local header = Create.New("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = inner,
	})
	Create.List(header, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 10,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local hasIcon = false
	if options.Icon then
		local iconBadge = Create.New("Frame", {
			Name = "IconBadge",
			Size = UDim2.fromOffset(34, 34),
			Corner = 9,
			Theme = { BackgroundColor3 = "Accent" },
			BackgroundTransparency = 0.86,
			LayoutOrder = 1,
			Parent = header,
		})
		Create.Stroke(iconBadge, { Theme = { Color = "Accent" }, Transparency = 0.72 })
		local iconInst = Icons.Create(options.Icon, {
			Size = UDim2.fromOffset(17, 17),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Color = "Accent",
			Parent = iconBadge,
		})
		if iconInst then
			hasIcon = true
		else
			iconBadge:Destroy()
		end
	end

	local titleLabel = Create.Text({
		Name = "Title",
		Text = tostring(options.Title or "Confirm"),
		Font = "SemiBold",
		TextSize = 15,
		Color = "Text",
		Size = UDim2.new(1, hasIcon and -44 or 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		TextWrapped = true,
		LayoutOrder = 2,
		Parent = header,
	})

	local bodyText = options.Content or options.Description or options.Message
	if bodyText ~= nil and tostring(bodyText) ~= "" then
		Create.Text({
			Name = "Content",
			Text = tostring(bodyText),
			Font = "Regular",
			TextSize = 13,
			Color = "SubText",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			TextWrapped = true,
			LayoutOrder = 2,
			Parent = inner,
		})
	end

	-- Optional Input field
	local inputBox
	if options.Input then
		local inputOpts = type(options.Input) == "table" and options.Input
			or { Placeholder = type(options.Input) == "string" and options.Input or "Enter value..." }

		local inputWrap = Create.New("Frame", {
			Name = "InputWrap",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 3,
			Parent = inner,
		})
		Create.List(inputWrap, { Gap = 6 })

		if inputOpts.Label and inputOpts.Label ~= "" then
			Create.Text({
				Text = tostring(inputOpts.Label),
				Font = "Medium",
				TextSize = 12,
				Color = "SubText",
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				LayoutOrder = 1,
				Parent = inputWrap,
			})
		end

		local field = Create.New("Frame", {
			Name = "Field",
			Size = UDim2.new(1, 0, 0, 36),
			Corner = 8,
			Theme = { BackgroundColor3 = "Field" },
			LayoutOrder = 2,
			Parent = inputWrap,
		})
		local fieldStroke = Create.Stroke(field, {
			Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
		})

		local isMasked = inputOpts.Mask == true or inputOpts.Password == true
		local showMasked = isMasked

		inputBox = Create.New("TextBox", {
			Name = "Input",
			Position = UDim2.fromOffset(10, 0),
			Size = UDim2.new(1, isMasked and -42 or -20, 1, 0),
			Text = tostring(inputOpts.Default or ""),
			PlaceholderText = tostring(inputOpts.Placeholder or "Type here..."),
			TextSize = 13,
			Font = "Regular",
			Theme = {
				TextColor3 = "Text",
				PlaceholderColor3 = "Muted",
			},
			Parent = field,
		})

		if isMasked then
			local maskOverlay = Create.Text({
				Name = "MaskOverlay",
				Position = inputBox.Position,
				Size = inputBox.Size,
				Text = string.rep("●", #inputBox.Text),
				Font = "SemiBold",
				TextSize = 11,
				Color = "Text",
				TextTruncate = Enum.TextTruncate.AtEnd,
				Visible = showMasked,
				ZIndex = inputBox.ZIndex + 1,
				Parent = field,
			})
			local function syncMask()
				maskOverlay.Text = string.rep("●", #inputBox.Text)
				maskOverlay.Visible = showMasked and inputBox.Text ~= ""
				inputBox.TextTransparency = (showMasked and inputBox.Text ~= "") and 1 or 0
			end
			maid:Give(inputBox:GetPropertyChangedSignal("Text"):Connect(syncMask))

			local eyeBtn = Create.New("TextButton", {
				Name = "MaskToggle",
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, -6, 0.5, 0),
				Size = UDim2.fromOffset(24, 24),
				Text = "",
				Corner = 6,
				BackgroundTransparency = 1,
				Parent = field,
			})
			local eyeIcon = Icons.Create("eye-off", {
				Size = UDim2.fromOffset(14, 14),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Color = "SubText",
				Parent = eyeBtn,
			})
			maid:Give(eyeBtn.Activated:Connect(function()
				showMasked = not showMasked
				if eyeIcon then
					Icons.Set(eyeIcon, showMasked and "eye-off" or "eye")
				end
				syncMask()
			end))
			syncMask()
		end

		if inputOpts.Numeric then
			maid:Give(inputBox:GetPropertyChangedSignal("Text"):Connect(function()
				local filtered = inputBox.Text:gsub("[^%d%.%-]", "")
				if filtered ~= inputBox.Text then
					inputBox.Text = filtered
				end
			end))
		end

		maid:Give(inputBox.Focused:Connect(function()
			Theme.Bind(fieldStroke, { Color = "Accent" })
			Tween.Play(fieldStroke, { Transparency = 0.25 }, Tween.Fast)
		end))

		maid:Give(inputBox.FocusLost:Connect(function()
			Theme.Bind(fieldStroke, { Color = "Stroke", Transparency = "StrokeTransparency" })
		end))
	end

	-- Buttons row
	local buttonDefs = (type(options.Buttons) == "table" and #options.Buttons > 0)
		and options.Buttons
		or { { Title = "OK", Variant = "Primary" } }

	local btnRow = Create.New("Frame", {
		Name = "Buttons",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 4,
		Parent = inner,
	})
	Create.List(btnRow, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 8,
		HAlign = Enum.HorizontalAlignment.Right,
		Wraps = true,
	})

	local controller = {
		Frame = container,
		Modal = modal,
		InputBox = inputBox,
		TitleLabel = titleLabel,
		Shadow = shadow,
	}

	function controller:Close()
		if closed then
			return
		end
		closed = true
		backdrop.Active = false
		backdrop:SetAttribute("_BaliClosing", true)
		Tween.Play(backdrop, { BackgroundTransparency = 1 }, Tween.Fast)
		Transition.Unmount(container, 0.94, function()
			maid:Clean()
			if type(options.OnClose) == "function" then
				Util.Spawn(options.OnClose)
			end
		end)
	end

	local primaryAction
	for index, def in ipairs(buttonDefs) do
		local variant = def.Variant
		if not variant then
			if def.Primary then
				variant = "Primary"
			elseif def.Danger then
				variant = "Danger"
			else
				variant = "Default"
			end
		end

		local btnTitle = tostring(def.Title or def.Text or "Button")
		local btn = Create.New("TextButton", {
			Name = "DialogBtn_" .. index,
			Size = UDim2.fromOffset(0, 34),
			AutomaticSize = Enum.AutomaticSize.X,
			Text = "",
			AutoButtonColor = false,
			ClipsDescendants = true,
			Corner = 9,
			Padding = { 0, 14, 0, 14 },
			LayoutOrder = index,
			Parent = btnRow,
		})
		local sizeMin = Instance.new("UISizeConstraint")
		sizeMin.MinSize = Vector2.new(74, 34)
		sizeMin.Parent = btn

		local btnStroke = Create.Stroke(btn, { Thickness = 1 })
		local btnContent = Create.New("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			Parent = btn,
		})
		Create.List(btnContent, {
			Direction = Enum.FillDirection.Horizontal,
			Gap = 6,
			HAlign = Enum.HorizontalAlignment.Center,
			VAlign = Enum.VerticalAlignment.Center,
		})

		local btnLabel = Create.Text({
			Text = btnTitle,
			Font = (variant == "Primary") and "SemiBold" or "Medium",
			TextSize = 13,
			Size = UDim2.fromScale(0, 1),
			AutomaticSize = Enum.AutomaticSize.X,
			TextXAlignment = Enum.TextXAlignment.Center,
			LayoutOrder = 2,
			Parent = btnContent,
		})

		local resolvedIcon = def.Icon
		if resolvedIcon == nil then
			local lower = string.lower(btnTitle)
			if lower == "cancel" or lower == "close" or lower == "dismiss" or lower == "no" then
				resolvedIcon = "x"
			elseif variant == "Danger" then
				resolvedIcon = "trash"
			elseif variant == "Primary" then
				resolvedIcon = "check"
			end
		end

		if resolvedIcon and resolvedIcon ~= false then
			Icons.Create(resolvedIcon, {
				Size = UDim2.fromOffset(14, 14),
				Color = (variant == "Primary") and "AccentText" or (variant == "Danger" and "Error" or "Text"),
				LayoutOrder = 1,
				Parent = btnContent,
			})
		end

		local grad = applyButtonStyle(btn, btnStroke, btnLabel, variant)
		if grad then
			maid:Give(Theme.Changed:Connect(function(theme)
				grad.Color = Theme.AccentSequence(theme)
			end))
		end

		if variant == "Default" then
			Transition.Hover(btn, btn, "Tile", "TileHover", btnStroke)
		end

		local function trigger(input)
			if closed then
				return
			end
			Transition.Ripple(btn, input, variant == "Primary" and "AccentText" or "Accent")
			local value = inputBox and inputBox.Text or nil
			if def.CloseOnClick ~= false then
				controller:Close()
			end
			if type(def.Callback) == "function" then
				Util.Spawn(def.Callback, value)
			end
		end

		if not primaryAction and variant == "Primary" then
			primaryAction = trigger
		end

		maid:Give(btn.Activated:Connect(function(input)
			trigger(input)
		end))
	end

	if inputBox then
		maid:Give(inputBox.FocusLost:Connect(function(enterPressed)
			if enterPressed and primaryAction and not closed then
				primaryAction()
			end
		end))
	end

	if options.Dismissible ~= false then
		maid:Give(backdrop.Activated:Connect(function()
			controller:Close()
		end))
		maid:Give(Services.UserInputService.InputBegan:Connect(function(input)
			if input.KeyCode == Enum.KeyCode.Escape then
				controller:Close()
			end
		end))
	end

	local targetOverlayTrans = math.max(0.32, (Theme.Current.OverlayTransparency or 0.56) - 0.14)
	Tween.Play(backdrop, { BackgroundTransparency = targetOverlayTrans }, Tween.Fast)
	maid:Give(Theme.Changed:Connect(function(theme)
		if not closed then
			backdrop.BackgroundTransparency = math.max(0.32, (theme.OverlayTransparency or 0.56) - 0.14)
		end
	end))
	Transition.Mount(container, 0.94)

	return controller
end

return Dialog
end

__modules["Window/Loader"] = function()
--[[
	Bali UI · Window/Loader
	Glassmorphic LoadingScreen splash and KeySystem verification modal with
	Get Key clipboard copy, Check Key verification, error shake, and saved key support.
]]

local Assets = require("Core/Assets")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Maid = require("Core/Maid")
local Services = require("Core/Services")
local Theme = require("Core/Theme")
local Transition = require("Core/Transition")
local Tween = require("Core/Tween")
local Util = require("Core/Util")

local Loader = {}

local function createBackdropAndCard(parentGui, maid, maxWidth, withOverlay)
	local root = Create.New("Frame", {
		Name = "LoaderOverlay",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 250,
		Parent = parentGui,
	})
	maid:Give(root)

	local backdrop
	if withOverlay then
		backdrop = Create.New("TextButton", {
			Name = "Backdrop",
			Size = UDim2.fromScale(1, 1),
			Text = "",
			AutoButtonColor = false,
			Theme = { BackgroundColor3 = "Overlay" },
			BackgroundTransparency = 1,
			ZIndex = 1,
			Parent = root,
		})
		Tween.Play(backdrop, { BackgroundTransparency = Theme.Current.OverlayTransparency }, Tween.Fast)
	end

	local container = Create.New("Frame", {
		Name = "CardContainer",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.new(1, -32, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = root,
	})

	local constraint = Instance.new("UISizeConstraint")
	constraint.MaxSize = Vector2.new(maxWidth or 380, 560)
	constraint.Parent = container

	local shadowDesc = Assets.Shadow()
	if shadowDesc and shadowDesc.Image and shadowDesc.Image ~= "" then
		Create.New("ImageLabel", {
			Name = "Shadow",
			Image = shadowDesc.Image,
			ScaleType = Enum.ScaleType.Slice,
			SliceCenter = shadowDesc.Slice,
			Position = UDim2.fromOffset(-shadowDesc.Inset, -shadowDesc.Inset + 6),
			Size = UDim2.new(1, shadowDesc.Inset * 2, 1, shadowDesc.Inset * 2),
			BackgroundTransparency = 1,
			Theme = {
				ImageColor3 = "Shadow",
				ImageTransparency = "ShadowTransparency",
			},
			ZIndex = 1,
			Parent = container,
		})
	end

	local card = Create.New("Frame", {
		Name = "GlassCard",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.min(t.CardTransparency, 0.03)
			end,
		},
		Corner = 14,
		ClipsDescendants = true,
		ZIndex = 2,
		Parent = container,
	})
	Create.GlassStroke(card, 0.05)

	local glowAsset = Assets.Get("Glow")
	if glowAsset and Assets.Available then
		Create.New("ImageLabel", {
			Name = "GlowTop",
			Image = glowAsset,
			Size = UDim2.fromOffset(240, 150),
			Position = UDim2.fromOffset(-80, -80),
			Corner = 14,
			BackgroundTransparency = 1,
			Theme = {
				ImageColor3 = "Accent",
				ImageTransparency = "GlowTransparency",
			},
			ZIndex = 1,
			Parent = card,
		})
	end

	local inner = Create.New("Frame", {
		Name = "Inner",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = 20,
		ZIndex = 2,
		Parent = card,
	})
	Create.List(inner, { Gap = 14 })

	return root, backdrop, container, card, inner
end

-- ─── LoadingScreen ───────────────────────────────────────────────────────────

function Loader.LoadingScreen(parentGui, options)
	assert(typeof(parentGui) == "Instance", "[Bali] Loader.LoadingScreen expects a parentGui Instance")
	if not Assets.Loaded then
		pcall(Assets.Load)
	end

	options = Util.Options(options, {
		Title = "Bali",
		Subtitle = "Preparing workspace...",
		Icon = "bali-logo",
		Duration = 1.6,
		Steps = nil,
		AutoClose = true,
		Backdrop = true,
		Yield = false,
		OnComplete = nil,
		Callback = nil,
	}, "Title")

	local maid = Maid.new()
	local closed = false
	local finished = false
	local root, backdrop, container, _, inner = createBackdropAndCard(parentGui, maid, 360, options.Backdrop ~= false)

	local header = Create.New("Frame", {
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = inner,
	})
	Create.List(header, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 12,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local customIcon = options.Icon and options.Icon ~= "bali-logo" and options.Icon ~= "bali"
	local badge = Create.New("Frame", {
		Size = UDim2.fromOffset(40, 40),
		Corner = 11,
		Theme = { BackgroundColor3 = customIcon and "Accent" or "TileHover" },
		BackgroundTransparency = customIcon and 0.88 or 0.8,
		LayoutOrder = 1,
		Parent = header,
	})
	Create.Stroke(badge, {
		Theme = { Color = customIcon and "Accent" or "Stroke" },
		Transparency = customIcon and 0.65 or 0.52,
		Thickness = 1,
	})

	local badgeIcon = Icons.Create(options.Icon or "bali-logo", {
		Size = UDim2.fromOffset(customIcon and 22 or 26, customIcon and 22 or 26),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = customIcon and "Accent" or Color3.fromRGB(255, 255, 255),
		Parent = badge,
	})
	local stopPulse = nil
	if badgeIcon then
		local pulseTarget = Icons.TransparencyTarget(badgeIcon) or badgeIcon
		stopPulse = Transition.Pulse(pulseTarget, Icons.TransparencyProperty(pulseTarget), 0, 0.45, 0.9)
		maid:Give(stopPulse)
	end

	local titleCol = Create.New("Frame", {
		Size = UDim2.new(1, -52, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
