function Loader.KeySystem(parentGui, options)
	assert(typeof(parentGui) == "Instance", "[Bali] Loader.KeySystem expects a parentGui Instance")
	if not Assets.Loaded then
		pcall(Assets.Load)
	end

	options = Util.Options(options, {
		Title = "Key Verification",
		Subtitle = "Key System",
		Version = "v1.0.0",
		Note = nil,
		Icon = "key",
		Key = nil,
		Keys = nil,
		KeyHashes = nil,
		KeySalt = nil,
		Verify = nil,
		CheckKey = nil,
		Callback = nil,
		KeyUrl = nil,
		GetKeyUrl = nil,
		Link = nil,
		KeyLink = nil,
		OnGetKey = nil,
		SaveKey = false,
		RememberByDefault = nil,
		Folder = "Bali",
		FileName = "key.txt",
		SavePath = nil,
		SupportedGames = nil,
		DefaultSupported = true,
		DiscordName = nil,
		DiscordInvite = nil,
		DiscordGuildId = nil,
		DiscordIcon = nil,
		Changelog = nil,
		MaxAttempts = 5,
		Cooldown = 8,
		Closable = true,
		Minimizable = true,
		Yield = false,
		OnSuccess = nil,
		OnCancel = nil,
	}, "Title")

	local rememberKey = options.SaveKey == true or options.RememberByDefault == true
	local runtimeOpts = table.clone(options)
	runtimeOpts.SaveKey = rememberKey

	local customVerify = options.Verify or options.CheckKey or options.Callback
	local function verifyKey(candidate)
		candidate = Util.SanitizeKeyInput(candidate, 128)
		if candidate == "" then
			return false, "Please enter a key."
		end
		local okInt, intMsg = Util.VerifyIntegrity()
		if not okInt then
			return false, intMsg or "Integrity check failed."
		end
		if type(customVerify) == "function" then
			local ok, result, message = pcall(customVerify, candidate)
			if not ok then
				return false, "Verification error: " .. tostring(result)
			end
			if result == true then
				return true, message
			end
			return false, tostring(message or "Invalid key. Please try again.")
		end
		local hashList = options.KeyHashes
		if type(hashList) == "table" and #hashList > 0 then
			local candidateHash = string.lower(Util.HashKey(candidate, options.KeySalt))
			for _, validHash in ipairs(hashList) do
				if Util.ConstantTimeEquals(candidateHash, string.lower(tostring(validHash))) then
					return true
				end
			end
			return false, "Invalid key. Please try again."
		end
		local list = options.Keys
		if type(list) == "table" then
			for _, valid in ipairs(list) do
				if Util.ConstantTimeEquals(candidate, tostring(valid)) then
					return true
				end
			end
			return false, "Invalid key. Please try again."
		end
		if options.Key ~= nil then
			if Util.ConstantTimeEquals(candidate, tostring(options.Key)) then
				return true
			end
			return false, "Invalid key. Please try again."
		end
		return true
	end

	local savedValid = checkSavedKey(runtimeOpts, verifyKey)
	if savedValid then
		if type(options.OnSuccess) == "function" then
			Util.Spawn(options.OnSuccess, savedValid)
		end
		local immediate = {
			Verified = true,
			Key = savedValid,
			Wait = function()
				return true, savedValid
			end,
			Close = function() end,
			Destroy = function() end,
		}
		if options.Yield then
			return true, savedValid
		end
		return immediate
	end

	local maid = Maid.new()
	local closed = false
	local done = false
	local verified = false
	local finalKey = nil
	local busy = false
	local minimized = false
