			if inviteCode ~= "" then
				local urls = {
					"https://discord.com/api/v10/invites/" .. inviteCode .. "?with_counts=true&with_expiration=true",
					"https://discord.com/api/v9/invites/" .. inviteCode .. "?with_counts=true&with_expiration=true",
					"https://discordapp.com/api/v9/invites/" .. inviteCode .. "?with_counts=true&with_expiration=true",
				}
				for _, url in ipairs(urls) do
					local d, status = fetchJson(url)
					data = d
					if (data and (data.approximate_member_count ~= nil or data.approximate_presence_count ~= nil)) or status == 404 then
						break
					end
				end
			end
			if closed or not dcOnlineLabel.Parent then
				return
			end
			if type(data) == "table" and (data.approximate_member_count ~= nil or data.approximate_presence_count ~= nil) then
				local online = tonumber(data.approximate_presence_count) or 0
				local total = tonumber(data.approximate_member_count) or online
				dcOnlineLabel.Text = Util.FormatNumber(online)
				dcOfflineLabel.Text = Util.FormatNumber(math.max(total - online, 0))
				if data.guild and data.guild.name and (not options.DiscordName or options.DiscordName == "") then
					dcTitleLabel.Text = tostring(data.guild.name)
				end
				if (not options.DiscordIcon or options.DiscordIcon == "") and data.guild and data.guild.id and data.guild.icon then
					applyDiscordIcon("https://cdn.discordapp.com/icons/" .. tostring(data.guild.id) .. "/" .. tostring(data.guild.icon) .. ".png?size=128")
				end
			elseif options.DiscordGuildId and options.DiscordGuildId ~= "" then
				local w = fetchJson("https://discord.com/api/guilds/" .. tostring(options.DiscordGuildId) .. "/widget.json")
				if not closed and w and (w.presence_count ~= nil or type(w.members) == "table") then
					local online = tonumber(w.presence_count) or (type(w.members) == "table" and #w.members or 0)
					dcOnlineLabel.Text = Util.FormatNumber(online)
					dcOfflineLabel.Text = "—"
				else
					local fbOnline = tonumber(options.DiscordOnline)
					local fbTotal = tonumber(options.DiscordMembers)
					local fbOffline = tonumber(options.DiscordOffline)
					dcOnlineLabel.Text = fbOnline and Util.FormatNumber(fbOnline) or "—"
					if fbOffline then
						dcOfflineLabel.Text = Util.FormatNumber(fbOffline)
					elseif fbTotal and fbOnline then
						dcOfflineLabel.Text = Util.FormatNumber(math.max(fbTotal - fbOnline, 0))
					elseif fbTotal then
						dcOfflineLabel.Text = Util.FormatNumber(fbTotal)
					else
						dcOfflineLabel.Text = "—"
					end
				end
			else
				local fbOnline = tonumber(options.DiscordOnline)
				local fbTotal = tonumber(options.DiscordMembers)
				local fbOffline = tonumber(options.DiscordOffline)
				dcOnlineLabel.Text = fbOnline and Util.FormatNumber(fbOnline) or "—"
				if fbOffline then
					dcOfflineLabel.Text = Util.FormatNumber(fbOffline)
				elseif fbTotal and fbOnline then
					dcOfflineLabel.Text = Util.FormatNumber(math.max(fbTotal - fbOnline, 0))
				elseif fbTotal then
					dcOfflineLabel.Text = Util.FormatNumber(fbTotal)
				else
					dcOfflineLabel.Text = "—"
				end
			end
		end)
	end

	-- Information / Changelog Card (opens Slide-In Information Drawer)
	local infoCard = Create.New("TextButton", {
		Position = UDim2.fromOffset(0, 236),
		Size = UDim2.new(1, 0, 0, 74),
		Text = "",
		AutoButtonColor = false,
		Corner = 12,
		Theme = { BackgroundColor3 = "Tile" },
		BackgroundTransparency = 0.25,
		Visible = useWide,
		Parent = rightPane,
	})
	local infoCardStroke = Create.Stroke(infoCard, { Theme = { Color = "Stroke", Transparency = "StrokeTransparency" } })
	Transition.Hover(infoCard, infoCard, "Tile", "TileHover", infoCardStroke)

	local infoBadge = Create.New("Frame", {
		Position = UDim2.fromOffset(12, 12),
		Size = UDim2.fromOffset(34, 34),
		Corner = 9,
		Theme = { BackgroundColor3 = "Accent" },
		BackgroundTransparency = 0.85,
		Parent = infoCard,
	})
	Icons.Create("info", {
		Size = UDim2.fromOffset(16, 16),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = "Accent",
		Parent = infoBadge,
	})
	Create.Text({
		Position = UDim2.fromOffset(55, 11),
		Size = UDim2.new(1, -82, 0, 17),
		Text = "Information",
		Font = "SemiBold",
		TextSize = 13,
		Color = "Text",
		Parent = infoCard,
	})
	Create.Text({
		Position = UDim2.fromOffset(55, 29),
		Size = UDim2.new(1, -82, 0, 15),
		Text = "Tap to view guide & updates",
		Font = "Regular",
		TextSize = 11,
		Color = "SubText",
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = infoCard,
	})
	Icons.Create("chevron-right", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -12, 0.5, -6),
		Size = UDim2.fromOffset(14, 14),
		Color = "SubText",
		Parent = infoCard,
	})
	Create.Text({
		Position = UDim2.fromOffset(12, 52),
		Size = UDim2.new(1, -24, 0, 14),
		Text = "What's new in " .. tostring(options.Version or "v1.0.0"),
		Font = "Medium",
		TextSize = 11,
		Color = "Accent",
		Parent = infoCard,
	})

	-- ─── Slide-In Information Drawer Overlay ──────────────────────────────────
	local infoOverlay = Create.New("TextButton", {
		Name = "InfoOverlay",
		Size = UDim2.fromScale(1, 1),
		Text = "",
		AutoButtonColor = false,
		Theme = { BackgroundColor3 = "Overlay" },
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 20,
		Parent = mainCard,
	})
	local drawer = Create.New("Frame", {
		Name = "InfoDrawer",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 340, 0, 10),
		Size = UDim2.new(0, math.min(320, cardW - 24), 1, -20),
		Corner = 13,
		Theme = { BackgroundColor3 = "Card" },
		BackgroundTransparency = 0,
		ZIndex = 21,
		Parent = infoOverlay,
	})
	Create.GlassStroke(drawer, 0.05)

	Create.Text({
		Position = UDim2.fromOffset(16, 14),
		Size = UDim2.new(1, -60, 0, 20),
		Text = "Information",
		Font = "Bold",
		TextSize = 15,
		Color = "Text",
		Parent = drawer,
	})
	local drawerClose = Create.New("TextButton", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -12, 0, 12),
		Size = UDim2.fromOffset(26, 26),
		Text = "",
		AutoButtonColor = false,
		Corner = 7,
		Theme = { BackgroundColor3 = "Tile" },
		Parent = drawer,
	})
	Create.Stroke(drawerClose, { Theme = { Color = "Stroke", Transparency = "StrokeTransparency" } })
	Icons.Create("x", {
		Size = UDim2.fromOffset(13, 13),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = "SubText",
		Parent = drawerClose,
	})

	local drawerScroll = Create.New("ScrollingFrame", {
		Position = UDim2.fromOffset(0, 48),
		Size = UDim2.new(1, 0, 1, -54),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ScrollBarThickness = 3,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Padding = { 4, 14, 10, 14 },
		Parent = drawer,
	})
	Create.List(drawerScroll, { Gap = 8 })

	local function addDrawerRow(labelText, valText, colorKey)
		local row = Create.New("Frame", {
			Size = UDim2.new(1, 0, 0, 34),
			Corner = 9,
			Theme = { BackgroundColor3 = "Tile" },
			BackgroundTransparency = 0.2,
			Padding = { 0, 10, 0, 10 },
			Parent = drawerScroll,
		})
		Create.Stroke(row, { Theme = { Color = "Stroke", Transparency = "StrokeTransparency" } })
		Create.Text({
			Text = labelText,
			Font = "Regular",
			TextSize = 12,
			Color = "SubText",
			Size = UDim2.new(0.5, 0, 1, 0),
			Parent = row,
		})
		Create.Text({
			Position = UDim2.fromScale(0.5, 0),
			Size = UDim2.new(0.5, 0, 1, 0),
			Text = tostring(valText),
			Font = "SemiBold",
			TextSize = 12,
			Color = colorKey or "Text",
			TextXAlignment = Enum.TextXAlignment.Right,
			Parent = row,
		})
	end

	Create.Text({
		Text = "SESSION STATUS",
		Font = "Bold",
		TextSize = 11,
		Color = "Accent",
		Size = UDim2.new(1, 0, 0, 18),
		Parent = drawerScroll,
	})
	addDrawerRow("Game Status", statusText, statusColorKey)
	addDrawerRow("Executor", execName)
	addDrawerRow("Place ID", tostring(game.PlaceId or 0))

	local changelogList = type(options.Changelog) == "table" and options.Changelog or {
		{ Version = tostring(options.Version or "v1.0.0"), Date = "Latest", Changes = { "Hardware-accelerated animations & Key System" } },
	}
	Create.Text({
		Text = "CHANGELOG",
		Font = "Bold",
		TextSize = 11,
		Color = "Accent",
		Size = UDim2.new(1, 0, 0, 20),
		Parent = drawerScroll,
	})
	for _, entry in ipairs(changelogList) do
		local cFrame = Create.New("Frame", {
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Corner = 10,
			Theme = { BackgroundColor3 = "Tile" },
			BackgroundTransparency = 0.2,
			Padding = { 9, 10, 9, 10 },
			Parent = drawerScroll,
		})
		Create.Stroke(cFrame, { Theme = { Color = "Stroke", Transparency = "StrokeTransparency" } })
		Create.List(cFrame, { Gap = 4 })
		Create.Text({
			Text = tostring(entry.Version or "Release") .. "  ·  " .. tostring(entry.Date or ""),
			Font = "SemiBold",
			TextSize = 11,
			Color = "Accent",
			Size = UDim2.new(1, 0, 0, 16),
			Parent = cFrame,
		})
		for _, ch in ipairs(entry.Changes or {}) do
			Create.Text({
				Text = "•  " .. tostring(ch),
				Font = "Regular",
				TextSize = 11,
				Color = "SubText",
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				TextWrapped = true,
				Parent = cFrame,
			})
		end
	end

	local infoOpen = false
	local function openInfoDrawer()
		if infoOpen then
			return
		end
		infoOpen = true
		infoOverlay.Visible = true
		Tween.Play(infoOverlay, { BackgroundTransparency = 0.45 }, Tween.Fast)
		drawer.Position = UDim2.new(1, 340, 0, 10)
		Tween.Spring(drawer, { Position = UDim2.new(1, -10, 0, 10) }, 0.26)
	end
	local function closeInfoDrawer()
		if not infoOpen then
			return
		end
		infoOpen = false
		Tween.Play(infoOverlay, { BackgroundTransparency = 1 }, Tween.Fast)
		Tween.Play(drawer, { Position = UDim2.new(1, 340, 0, 10) }, 0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		task.delay(0.2, function()
			if not infoOpen and infoOverlay.Parent then
				infoOverlay.Visible = false
			end
		end)
	end

	maid:Give(infoCard.Activated:Connect(openInfoDrawer))
	maid:Give(infoIconBtn.Activated:Connect(openInfoDrawer))
	maid:Give(helpBtn.Activated:Connect(openInfoDrawer))
	maid:Give(drawerClose.Activated:Connect(closeInfoDrawer))
	maid:Give(infoOverlay.Activated:Connect(closeInfoDrawer))

	-- ─── Animated Access Granted Overlay ──────────────────────────────────────
	local successView = Create.New("Frame", {
		Name = "SuccessOverlay",
		Size = UDim2.fromScale(1, 1),
		Theme = { BackgroundColor3 = "Card" },
		BackgroundTransparency = 0.02,
		Corner = 16,
		Visible = false,
		ZIndex = 30,
		Parent = mainCard,
	})
	local sCircle = Create.New("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, -42),
		Size = UDim2.fromOffset(66, 66),
		Corner = 999,
		Theme = { BackgroundColor3 = "Accent" },
		Parent = successView,
	})
	local sGrad = Instance.new("UIGradient")
	sGrad.Color = Theme.AccentSequence()
	sGrad.Rotation = 40
	sGrad.Parent = sCircle
	Icons.Create("check", {
		Size = UDim2.fromOffset(28, 28),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = "AccentText",
		Parent = sCircle,
	})
	Create.Text({
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.5, 6),
		Size = UDim2.fromOffset(320, 26),
		Text = "Access granted",
		Font = "Bold",
		TextSize = 20,
		Color = "Text",
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = successView,
	})
	Create.Text({
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.5, 34),
		Size = UDim2.fromOffset(340, 18),
		Text = "Welcome — preparing " .. tostring(options.Title or "Bali"),
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = successView,
	})
	local sTrack = Create.New("Frame", {
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0.5, 66),
		Size = UDim2.fromOffset(220, 6),
		Corner = UDim.new(1, 0),
		Theme = { BackgroundColor3 = "Tile" },
		ClipsDescendants = true,
		Parent = successView,
	})
	local sFill = Create.New("Frame", {
		Size = UDim2.fromScale(0, 1),
		Corner = UDim.new(1, 0),
		Theme = { BackgroundColor3 = "Accent" },
		Parent = sTrack,
	})

	-- ─── Submit / Verify Handler ──────────────────────────────────────────────
	local function submit(input)
		if busy or closed then
			return
		end
		if os.clock() < cooldownUntil then
			shakeError(string.format("Too many attempts. Wait %.0fs.", math.ceil(cooldownUntil - os.clock())))
			return
		end

		busy = true
		if input then
			Transition.Ripple(verifyBtn, input, "AccentText")
		end
		verifyLabel.Text = "Verifying..."
		local entered = Util.SanitizeKeyInput(keyBox.Text, 128)

		task.spawn(function()
			local ok, message = verifyKey(entered)
			busy = false
			if closed then
				return
			end
			if ok then
				verified = true
				finalKey = entered
				controller.Verified = true
				controller.Key = entered
				writeSavedKey(runtimeOpts, entered)
				verifyLabel.Text = "Verified"
				feedbackLabel.Text = tostring(message or "Access granted.")
				Theme.Bind(feedbackLabel, { TextColor3 = "Success" })
				feedbackLabel.Visible = true
				Theme.Bind(fieldStroke, { Color = "Success" })

				successView.Visible = true
				Tween.Play(sFill, { Size = UDim2.fromScale(1, 1) }, 0.34, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
				task.wait(0.38)
				controller:Close()
				if type(options.OnSuccess) == "function" then
					Util.Spawn(options.OnSuccess, entered)
				end
			else
				if (tonumber(options.MaxAttempts) or 0) > 0 then
					attemptsLeft = math.max(attemptsLeft - 1, 0)
					if attemptsLeft <= 0 then
						cooldownTriggers += 1
						local baseCooldown = tonumber(options.Cooldown) or 8
						local waitSec = baseCooldown * (2 ^ math.min(cooldownTriggers - 1, 4))
						cooldownUntil = os.clock() + waitSec
						attemptsLeft = tonumber(options.MaxAttempts) or 5
						attemptsLabel.Text = "Cooldown..."
					else
						attemptsLabel.Text = tostring(attemptsLeft) .. " left"
					end
				end
				verifyLabel.Text = "Verify Key"
				shakeError(message)
			end
		end)
	end

	maid:Give(verifyBtn.Activated:Connect(submit))
	maid:Give(keyBox.FocusLost:Connect(function(enterPressed)
		if enterPressed then
			submit()
		end
	end))

	Transition.Mount(container, 0.94)

	if options.Yield then
		return controller:Wait()
	end
	return controller
end

return Loader
end

__modules["Window/MobileButton"] = function()
--[[
	Bali UI · Window/MobileButton
	Draggable glass floating pill button for mobile/touch users and minimized windows.
	Uses a pointer drag-distance threshold so dragging never accidentally toggles the UI.
]]

local Assets = require("Core/Assets")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Maid = require("Core/Maid")
local Services = require("Core/Services")
local Theme = require("Core/Theme")
local Transition = require("Core/Transition")
local Util = require("Core/Util")

local MobileButton = {}
MobileButton.__index = MobileButton

local DRAG_THRESHOLD = 6

function MobileButton.new(parentLayer, window, options)
	assert(typeof(parentLayer) == "Instance", "[Bali] MobileButton expects a parentLayer Instance")
	options = Util.Options(options, {
		Title = "Bali",
		Subtitle = "Tap to show",
		Icon = "bali-logo",
		Enabled = true,
		AlwaysShow = false,
		Centered = true,
		Position = nil,
	}, "Title")

	local maid = Maid.new()
	local userDragged = options.Position ~= nil

	local function defaultCenteredPos()
		local vpX = parentLayer.AbsoluteSize.X
		local approxW = 168
		local x = vpX > 0 and math.floor((vpX - approxW) * 0.5) or 18
		return UDim2.fromOffset(math.max(8, x), 12)
	end

	local wrapper = Create.New("Frame", {
		Name = "BaliMobileButton",
		Position = options.Position or defaultCenteredPos(),
		Size = UDim2.fromOffset(0, 42),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 10,
		Parent = parentLayer,
	})
	maid:Give(wrapper)

	local shadowDesc = Assets.Shadow()
	Create.New("ImageLabel", {
		Name = "Shadow",
		Image = shadowDesc.Image,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = shadowDesc.Slice,
		Position = UDim2.fromOffset(-shadowDesc.Inset, -shadowDesc.Inset + 3),
		Size = UDim2.new(1, shadowDesc.Inset * 2, 1, shadowDesc.Inset * 2),
		BackgroundTransparency = 1,
		Theme = {
			ImageColor3 = "Shadow",
			ImageTransparency = "ShadowTransparency",
		},
		ZIndex = 1,
		Parent = wrapper,
	})

	local pill = Create.New("TextButton", {
		Name = "Pill",
		Size = UDim2.fromOffset(0, 42),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = "",
		AutoButtonColor = false,
		ClipsDescendants = true,
		Corner = 999,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = function(t)
				return math.min(t.CardTransparency, 0.04)
			end,
		},
		Padding = { 0, 14, 0, 10 },
		ZIndex = 2,
		Parent = wrapper,
	})
	local stroke = Create.GlassStroke(pill, 0.05)

	local content = Create.New("Frame", {
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = pill,
	})
	Create.List(content, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 9,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local customIcon = options.Icon and options.Icon ~= "bali-logo" and options.Icon ~= "bali"
	local badge = Create.New("Frame", {
		Size = UDim2.fromOffset(24, 24),
		Corner = 7,
		Theme = {
			BackgroundColor3 = customIcon and "Accent" or function(t)
				return (t and t.Dark == false) and Color3.fromRGB(24, 24, 32) or t.TileHover
			end,
			BackgroundTransparency = customIcon and 0.88 or function(t)
				return (t and t.Dark == false) and 0.12 or 0.82
			end,
		},
		LayoutOrder = 1,
		Parent = content,
	})
	Create.Stroke(badge, {
		Theme = { Color = customIcon and "Accent" or "Stroke" },
		Transparency = customIcon and 0.68 or 0.55,
		Thickness = 1,
	})

	Icons.Create(options.Icon or "bali-logo", {
		Size = UDim2.fromOffset(customIcon and 15 or 17, customIcon and 15 or 17),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = customIcon and "Accent" or Color3.fromRGB(255, 255, 255),
		Parent = badge,
	})

	local textCol = Create.New("Frame", {
		Size = UDim2.fromOffset(0, 0),
		AutomaticSize = Enum.AutomaticSize.XY,
		BackgroundTransparency = 1,
		LayoutOrder = 2,
		Parent = content,
	})
	Create.List(textCol, {
		Gap = 1,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local titleLabel = Create.Text({
		Text = tostring(options.Title or "Bali"),
		Font = "SemiBold",
		TextSize = 12,
		Color = "Text",
		Size = UDim2.fromOffset(0, 14),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 1,
		Parent = textCol,
	})

	local subLabel = Create.Text({
		Text = tostring(options.Subtitle or "Tap to show"),
		Font = "Regular",
		TextSize = 10,
		Color = "SubText",
		Size = UDim2.fromOffset(0, 12),
		AutomaticSize = Enum.AutomaticSize.X,
		LayoutOrder = 2,
		Parent = textCol,
	})

	local statusDot = Create.New("Frame", {
		Size = UDim2.fromOffset(6, 6),
		Corner = 999,
		Theme = { BackgroundColor3 = "Success" },
		LayoutOrder = 3,
		Parent = content,
	})

	Transition.Hover(pill, pill, "Card", "TileHover", stroke)

	local self = setmetatable({
		Frame = wrapper,
		Pill = pill,
		Window = window,
		Maid = maid,
		Enabled = options.Enabled ~= false,
		AlwaysShow = options.AlwaysShow == true,
		_titleLabel = titleLabel,
		_subLabel = subLabel,
		_statusDot = statusDot,
	}, MobileButton)

	-- Drag + tap threshold logic
	local dragging = false
	local moved = false
	local dragStartMouse
	local dragStartPos

	local function clampPosition(x, y)
		local vp = parentLayer.AbsoluteSize
		local size = wrapper.AbsoluteSize
		local maxX = math.max(8, vp.X - size.X - 8)
		local maxY = math.max(8, vp.Y - size.Y - 8)
		return Util.Clamp(x, 8, maxX), Util.Clamp(y, 8, maxY)
	end

	local function recenterIfAuto()
		if userDragged then
			return
		end
		local vpX = parentLayer.AbsoluteSize.X
		local w = wrapper.AbsoluteSize.X > 0 and wrapper.AbsoluteSize.X or 168
		if vpX > 0 then
			local nx, ny = clampPosition(math.floor((vpX - w) * 0.5), 12)
			wrapper.Position = UDim2.fromOffset(math.floor(nx), math.floor(ny))
		end
	end

	maid:Give(pill.InputBegan:Connect(function(input)
		if not Util.IsPointer(input) then
			return
		end
		dragging = true
		moved = false
		dragStartMouse = Vector2.new(input.Position.X, input.Position.Y)
		dragStartPos = Vector2.new(wrapper.Position.X.Offset, wrapper.Position.Y.Offset)
	end))

	maid:Give(Services.UserInputService.InputChanged:Connect(function(input)
		if not dragging or not Util.IsMove(input) then
			return
		end
		local delta = Vector2.new(input.Position.X, input.Position.Y) - dragStartMouse
		if not moved and delta.Magnitude >= DRAG_THRESHOLD then
			moved = true
			userDragged = true
		end
		if moved then
			local nx, ny = clampPosition(dragStartPos.X + delta.X, dragStartPos.Y + delta.Y)
			wrapper.Position = UDim2.fromOffset(math.floor(nx), math.floor(ny))
		end
	end))

	maid:Give(Services.UserInputService.InputEnded:Connect(function(input)
		if not dragging or not Util.IsPointer(input) then
			return
		end
		local wasMoved = moved
		dragging = false
		moved = false
		if not wasMoved and self.Window and type(self.Window.Toggle) == "function" then
			Transition.Ripple(pill, input, "Accent")
			self.Window:Toggle()
		end
	end))

	maid:Give(parentLayer:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		if not userDragged then
			recenterIfAuto()
		else
			local nx, ny = clampPosition(wrapper.Position.X.Offset, wrapper.Position.Y.Offset)
			wrapper.Position = UDim2.fromOffset(math.floor(nx), math.floor(ny))
		end
	end))
	maid:Give(wrapper:GetPropertyChangedSignal("AbsoluteSize"):Connect(recenterIfAuto))

	self:UpdateVisibility()
	return self
end

function MobileButton:GetRect()
	local w = self.Frame.AbsoluteSize.X > 0 and self.Frame.AbsoluteSize.X or 168
	local h = self.Frame.AbsoluteSize.Y > 0 and self.Frame.AbsoluteSize.Y or 40
	local vp = self.Frame.Parent and self.Frame.Parent.AbsoluteSize or Vector2.new(1280, 720)
	local slideTarget = self.Frame:GetAttribute("_BaliSlideTargetPos")
	local refPos = typeof(slideTarget) == "UDim2" and slideTarget or self.Frame.Position
	local x = refPos.X.Offset
	if x <= 0 and vp.X > 0 then
		x = math.floor((vp.X - w) * 0.5)
	end
	local y = refPos.Y.Offset > 0 and refPos.Y.Offset or 12
	return x, y, w, h
end

function MobileButton:SetTitle(text)
	self._titleLabel.Text = tostring(text or "Bali")
end

function MobileButton:SetEnabled(enabled)
	self.Enabled = enabled == true
	self:UpdateVisibility()
end

function MobileButton:IsEnabled()
	return self.Enabled
end

function MobileButton:SetVisible(visible)
	self.Frame.Visible = visible == true
end

function MobileButton:UpdateVisibility()
	local wasVisible = self.Frame.Visible
	local winVisible = self.Window and self.Window:IsVisible()
	local mobileMode = self.Window and type(self.Window.IsMobileMode) == "function" and self.Window:IsMobileMode()
	Theme.Bind(self._statusDot, { BackgroundColor3 = winVisible and "Success" or "Muted" })
	local shouldShow = self.Enabled and (self.AlwaysShow or mobileMode or Util.IsTouchDevice() or not winVisible)
	self.Frame.Visible = shouldShow
	if shouldShow and not wasVisible and self.Frame.Parent then
		Transition.SlideFade(self.Frame, 0, -8)
	end
end

function MobileButton:Destroy()
	self.Maid:Clean()
end

return MobileButton
end

__modules["Window/Section"] = function()
--[[
	Bali UI · Window/Section
	Obsidian glass card container inside a Tab/SubTab page with optional icon,
	subtitle, collapsible header, and attached element factory methods.
]]

local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Maid = require("Core/Maid")
local Theme = require("Core/Theme")
local Transition = require("Core/Transition")
local Tween = require("Core/Tween")
local Util = require("Core/Util")
local Container = require("Window/Container")

local Section = {}
Section.__index = Section

function Section.new(parent, options, tab, window, subTab)
	options = Util.Options(options, {
		Title = "",
		Subtitle = nil,
		Description = nil,
		Desc = nil,
		Icon = nil,
		Side = "Auto",
		Collapsible = false,
		DefaultOpen = true,
		LayoutOrder = 0,
	}, "Title")

	local subtitleText = options.Subtitle or options.Description or options.Desc
	local hasTitle = options.Title ~= nil and options.Title ~= ""
	local hasSubtitle = subtitleText ~= nil and subtitleText ~= ""
	local hasHeader = hasTitle or hasSubtitle or options.Icon ~= nil or options.Collapsible == true
	local isOpen = options.Open ~= nil and (options.Open ~= false) or (options.DefaultOpen ~= false)

	local maid = Maid.new()

	local card = Create.New("Frame", {
		Name = "Section_" .. (hasTitle and tostring(options.Title) or "Card"),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = options.LayoutOrder or 0,
		Theme = {
			BackgroundColor3 = "Card",
			BackgroundTransparency = "CardTransparency",
		},
		Corner = 12,
		Padding = { 10, 10, 10, 10 },
		Parent = parent,
	})
	maid:Give(card)
	Create.GlassStroke(card, 0.03)
	Create.List(card, { Gap = 10 })

	local headerBtn
	local titleLabel
	local subtitleLabel
	local chevronIcon
	local chevronWrap
	local baseChevronRot = 0

	if hasHeader then
		headerBtn = Create.New("TextButton", {
			Name = "Header",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			Text = "",
			Active = options.Collapsible == true,
			Selectable = false,
			LayoutOrder = 1,
			Parent = card,
		})

		local titleBlock = Create.New("Frame", {
			Name = "TitleBlock",
			Size = UDim2.new(1, options.Collapsible and -30 or 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			Parent = headerBtn,
		})
		Create.List(titleBlock, {
			Direction = Enum.FillDirection.Horizontal,
			Gap = 8,
			VAlign = Enum.VerticalAlignment.Center,
		})

		local hasIcon = false
		if options.Icon then
			local iconBadge = Create.New("Frame", {
				Name = "IconBadge",
				Size = UDim2.fromOffset(24, 24),
				Corner = 7,
				Theme = { BackgroundColor3 = "Accent" },
				BackgroundTransparency = 0.88,
				LayoutOrder = 1,
				Parent = titleBlock,
			})
			local iconInst = Icons.Create(options.Icon, {
				Size = UDim2.fromOffset(14, 14),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Color = "Accent",
				Parent = iconBadge,
			})
			if iconInst then
				hasIcon = true
			else
				iconBadge:Destroy()
			end
		end

		local textCol = Create.New("Frame", {
			Name = "TextColumn",
			Size = UDim2.new(1, hasIcon and -32 or 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 2,
			Parent = titleBlock,
		})
		Create.List(textCol, { Gap = 2 })

		titleLabel = Create.Text({
			Name = "Title",
			Text = options.Title or "",
			Font = "SemiBold",
			TextSize = 14,
			Color = "Text",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			TextWrapped = true,
			Visible = hasTitle,
			LayoutOrder = 1,
			Parent = textCol,
		})

		subtitleLabel = Create.Text({
			Name = "Subtitle",
			Text = subtitleText or "",
			Font = "Regular",
			TextSize = 11,
			Color = "SubText",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			TextWrapped = true,
			Visible = hasSubtitle,
			LayoutOrder = 2,
			Parent = textCol,
		})

		if options.Collapsible then
			chevronWrap = Create.New("Frame", {
				Name = "Chevron",
				Size = UDim2.fromOffset(22, 22),
				AnchorPoint = Vector2.new(1, 0.5),
				Position = UDim2.new(1, 0, 0.5, 0),
				Corner = 6,
				Theme = { BackgroundColor3 = "Tile" },
				BackgroundTransparency = 1,
				Parent = headerBtn,
			})
			chevronIcon = Icons.Create("chevron-down", {
				Size = UDim2.fromOffset(14, 14),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Color = "SubText",
				Parent = chevronWrap,
			})
			baseChevronRot = chevronIcon and chevronIcon.Rotation or 0
		end
	end

	local contentHolder = Create.New("Frame", {
		Name = "ContentHolder",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ClipsDescendants = not isOpen,
		Visible = isOpen,
		LayoutOrder = 2,
		Parent = card,
	})

	local content = Create.New("Frame", {
		Name = "Content",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 2, 2, 2, 2 },
		Parent = contentHolder,
	})
	local contentLayout = Create.List(content, { Gap = 8 })

	local self = setmetatable({
		Type = "Section",
		Title = options.Title or "",
		Subtitle = subtitleText or "",
		Icon = options.Icon,
		Side = options.Side or "Auto",
		Collapsible = options.Collapsible == true,
		Open = isOpen,
		Tab = tab,
		SubTab = subTab,
		Window = window,
		Maid = maid,
		Frame = card,
		_header = headerBtn,
		ContentHolder = contentHolder,
		Content = content,
		_contentLayout = contentLayout,
		_titleLabel = titleLabel,
		_subtitleLabel = subtitleLabel,
		_chevronIcon = chevronIcon,
		_baseChevronRot = baseChevronRot,
	}, Section)

	if chevronIcon and not isOpen then
		chevronIcon.Rotation = baseChevronRot - 90
	end

	if options.Collapsible and headerBtn then
		maid:Give(headerBtn.MouseEnter:Connect(function()
			if chevronWrap then
				Tween.Play(chevronWrap, { BackgroundTransparency = Theme.Current.TileTransparency }, Tween.Instant)
			end
			if chevronIcon then
				Icons.SetColor(chevronIcon, "Text")
			end
		end))
		maid:Give(headerBtn.MouseLeave:Connect(function()
			if chevronWrap then
				Tween.Play(chevronWrap, { BackgroundTransparency = 1 }, Tween.Instant)
			end
			if chevronIcon then
				Icons.SetColor(chevronIcon, "SubText")
			end
		end))
		maid:Give(headerBtn.Activated:Connect(function()
			self:SetOpen(not self.Open)
		end))
	end

	if tab and tab.Maid then
		tab.Maid:Give(self)
	end

	Container.Attach(self, content, tab, self, window, subTab)
	return self
end

function Section:SetTitle(text)
	self.Title = tostring(text or "")
	if self._titleLabel then
		self._titleLabel.Text = self.Title
		self._titleLabel.Visible = self.Title ~= ""
	end
end

function Section:SetSubtitle(text)
	self.Subtitle = tostring(text or "")
	if self._subtitleLabel then
		self._subtitleLabel.Text = self.Subtitle
		self._subtitleLabel.Visible = self.Subtitle ~= ""
	end
end

Section.SetDesc = Section.SetSubtitle

function Section:SetVisible(visible)
	if self.Frame then
		self.Frame.Visible = visible == true
	end
end

function Section:SetOpen(open, instant)
	open = open ~= false
	if self.Open == open and not instant then
		return
	end
	self.Open = open

	local holder = self.ContentHolder
	local content = self.Content
	local chevron = self._chevronIcon
	local targetRot = open and self._baseChevronRot or (self._baseChevronRot - 90)

	if self._sizeTween then
		pcall(function()
			self._sizeTween:Cancel()
		end)
		self._sizeTween = nil
	end

	if instant then
		if chevron then
			chevron.Rotation = targetRot
		end
		holder.AutomaticSize = Enum.AutomaticSize.Y
		holder.Size = UDim2.new(1, 0, 0, 0)
		holder.ClipsDescendants = not open
		holder.Visible = open
		return
	end

	if chevron then
		Tween.Play(chevron, { Rotation = targetRot }, Tween.Fast)
	end

	if open then
		holder.ClipsDescendants = true
		holder.Visible = true
		local targetHeight = math.max(content.AbsoluteSize.Y, self._contentLayout.AbsoluteContentSize.Y + 4)
		holder.AutomaticSize = Enum.AutomaticSize.None
		holder.Size = UDim2.new(1, 0, 0, 0)
		local tween = Tween.Play(holder, { Size = UDim2.new(1, 0, 0, targetHeight) }, Tween.Normal)
		self._sizeTween = tween
		Tween.Then(tween, function()
			if self.Open then
				holder.AutomaticSize = Enum.AutomaticSize.Y
				holder.Size = UDim2.new(1, 0, 0, 0)
				holder.ClipsDescendants = false
			end
		end)
	else
		holder.ClipsDescendants = true
		local currentHeight = math.max(holder.AbsoluteSize.Y, content.AbsoluteSize.Y)
		holder.AutomaticSize = Enum.AutomaticSize.None
		holder.Size = UDim2.new(1, 0, 0, currentHeight)
		local tween = Tween.Play(holder, { Size = UDim2.new(1, 0, 0, 0) }, Tween.Fast)
		self._sizeTween = tween
		Tween.Then(tween, function()
			if not self.Open then
				holder.Visible = false
			end
		end)
	end
end

Section.SetExpanded = Section.SetOpen

function Section:Toggle()
	self:SetOpen(not self.Open)
end

function Section:Flash()
	if not self.Open then
		self:SetOpen(true, true)
	end
	if self.Frame then
		Transition.SlideFade(self.Frame, 4)
	end
end

function Section:Destroy()
	self.Maid:Clean()
end

return Section
end

__modules["Window/Tab"] = function()
--[[
	Bali UI · Window/Tab
	Sidebar category headers, grouped tab buttons with animated active pill &
	collapse rail support, Apple segmented SubTab bar, and responsive 2-col -> 1-col layout.
]]

local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Maid = require("Core/Maid")
local Theme = require("Core/Theme")
local Transition = require("Core/Transition")
local Tween = require("Core/Tween")
local Util = require("Core/Util")
local Tooltip = require("Systems/Tooltip")
local Container = require("Window/Container")
local Section = require("Window/Section")

local Tab = {}
Tab.__index = Tab

-- ─── Category Header Helper ──────────────────────────────────────────────────

function Tab.CategoryHeader(parent, name, layoutOrder)
	local header = Create.New("Frame", {
		Name = "Category_" .. tostring(name),
		Size = UDim2.new(1, 0, 0, 24),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		LayoutOrder = layoutOrder or 0,
		Parent = parent,
	})

	local label = Create.Text({
		Name = "Label",
		Text = string.upper(tostring(name)),
		Font = "Bold",
		TextSize = 10,
		Color = "Muted",
		Position = UDim2.fromOffset(10, 6),
		Size = UDim2.new(1, -16, 0, 14),
		TextTruncate = Enum.TextTruncate.AtEnd,
		Parent = header,
	})

	local compactLine = Create.New("Frame", {
		Name = "CompactDivider",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(20, 1),
		Visible = false,
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		Parent = header,
	})

	local obj = {
		Name = name,
		Frame = header,
		Label = label,
		CompactLine = compactLine,
	}

	function obj:SetCompact(compact, instant)
		compact = compact == true
		label.Visible = not compact
		compactLine.Visible = compact
		local targetHeight = compact and 12 or 24
		if instant then
			header.Size = UDim2.new(1, 0, 0, targetHeight)
		else
			Tween.Play(header, { Size = UDim2.new(1, 0, 0, targetHeight) }, Tween.Fast)
		end
	end

	return obj
end

-- ─── Responsive Flow Page Helper ─────────────────────────────────────────────

local function createFlowController(tab, parent, subTab)
	local window = tab.Window

	local scroll = Create.New("ScrollingFrame", {
		Name = subTab and ("SubPage_" .. tostring(subTab.Title)) or "DefaultPage",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(),
		ScrollBarThickness = 2,
		ScrollBarImageTransparency = 0.45,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Theme = { ScrollBarImageColor3 = "Muted" },
		Padding = (window and window.IsMobileMode and window:IsMobileMode()) and { 10, 10, 14, 10 } or { 14, 16, 18, 16 },
		Parent = parent,
	})
	Create.List(scroll, { Gap = 12 })

	local flow = {
		Scroll = scroll,
		SubTab = subTab,
		CurrentPair = nil,
		Order = 0,
		_pairs = {},
	}

	function flow.NextOrder()
		flow.Order += 1
		return flow.Order
	end

	function flow.ClosePair()
		flow.CurrentPair = nil
	end

	local function getOrCreatePair()
		if flow.CurrentPair then
			return flow.CurrentPair
		end

		local row = Create.New("Frame", {
			Name = "ColumnRow",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = flow.NextOrder(),
			Parent = scroll,
		})

		local rowLayout = Create.List(row, {
			Direction = Enum.FillDirection.Horizontal,
			Gap = 12,
		})

		local leftCol = Create.New("Frame", {
			Name = "LeftColumn",
			Size = UDim2.new(0.5, -6, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 1,
			Parent = row,
		})
		local leftLayout = Create.List(leftCol, { Gap = 12 })

		local rightCol = Create.New("Frame", {
			Name = "RightColumn",
			Size = UDim2.new(0.5, -6, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 2,
			Parent = row,
		})
		local rightLayout = Create.List(rightCol, { Gap = 12 })

		local pair = {
			Row = row,
			Left = leftCol,
			Right = rightCol,
			LeftLayout = leftLayout,
			RightLayout = rightLayout,
			LeftCount = 0,
			RightCount = 0,
		}

		function pair.ApplyLayout(windowWidth)
			local isMobile = window and window.IsMobileMode and window:IsMobileMode()
			local stacked = isMobile or (windowWidth or 820) < 620
			if stacked then
				rowLayout.FillDirection = Enum.FillDirection.Vertical
				leftCol.Size = UDim2.new(1, 0, 0, 0)
				rightCol.Size = UDim2.new(1, 0, 0, 0)
				leftCol.Visible = pair.LeftCount > 0
				rightCol.Visible = pair.RightCount > 0
			else
				rowLayout.FillDirection = Enum.FillDirection.Horizontal
				leftCol.Size = UDim2.new(0.5, -6, 0, 0)
				rightCol.Size = UDim2.new(0.5, -6, 0, 0)
				leftCol.Visible = true
				rightCol.Visible = true
			end
		end

		if window and window._layoutChanged then
			tab.Maid:Give(window._layoutChanged:Connect(function(size)
				pair.ApplyLayout(size.X)
			end))
		end
		pair.ApplyLayout(window and window:GetWidth() or 820)

		table.insert(flow._pairs, pair)
		flow.CurrentPair = pair
		return pair
	end

	function flow.RefreshLayout(windowWidth)
		local isMobile = window and window.IsMobileMode and window:IsMobileMode()
		local pad = scroll:FindFirstChildOfClass("UIPadding")
		if pad then
			pad.PaddingTop = UDim.new(0, isMobile and 10 or 14)
			pad.PaddingRight = UDim.new(0, isMobile and 10 or 16)
			pad.PaddingBottom = UDim.new(0, isMobile and 14 or 18)
			pad.PaddingLeft = UDim.new(0, isMobile and 10 or 16)
		end
		for _, pair in ipairs(flow._pairs) do
			pair.ApplyLayout(windowWidth)
		end
	end

	function flow.AddSection(opts)
		opts = Util.Options(opts, { Side = "Auto" }, "Title")
		local side = string.lower(tostring(opts.Side or "Auto"))

		if side == "full" then
			flow.ClosePair()
			opts.LayoutOrder = flow.NextOrder()
			return Section.new(scroll, opts, tab, window, subTab)
		end

		local pair = getOrCreatePair()
		local targetSide
		if side == "left" then
			targetSide = "left"
		elseif side == "right" then
			targetSide = "right"
		else
			local leftH = pair.LeftLayout.AbsoluteContentSize.Y
			local rightH = pair.RightLayout.AbsoluteContentSize.Y
			if leftH ~= rightH and (leftH > 0 or rightH > 0) then
				targetSide = (leftH <= rightH) and "left" or "right"
			else
				targetSide = (pair.LeftCount <= pair.RightCount) and "left" or "right"
			end
		end

		local colParent
		if targetSide == "left" then
			pair.LeftCount += 1
			opts.LayoutOrder = pair.LeftCount
			colParent = pair.Left
		else
			pair.RightCount += 1
			opts.LayoutOrder = pair.RightCount
			colParent = pair.Right
		end

		pair.ApplyLayout(window and window:GetWidth() or 820)
		return Section.new(colParent, opts, tab, window, subTab)
	end

	return flow
end

-- ─── Tab Constructor ─────────────────────────────────────────────────────────

function Tab.new(window, options)
	options = Util.Options(options, {
		Title = "Tab",
		Icon = nil,
		Category = nil,
		Badge = nil,
		LayoutOrder = 0,
	}, "Title")

	local maid = Maid.new()

	-- Sidebar navigation button
	local button = Create.New("TextButton", {
		Name = "Tab_" .. tostring(options.Title),
		Size = UDim2.new(1, 0, 0, 36),
		Theme = { BackgroundColor3 = "Tile" },
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		ClipsDescendants = true,
		Corner = 9,
		LayoutOrder = options.LayoutOrder or 0,
		Parent = window._tabScroll,
	})
	maid:Give(button)

	local activeFill = Create.New("Frame", {
		Name = "ActiveFill",
		Size = UDim2.fromScale(1, 1),
		Theme = { BackgroundColor3 = "Accent" },
		BackgroundTransparency = 1,
		Corner = 9,
		ZIndex = 1,
		Parent = button,
	})
	local fillGradient = Instance.new("UIGradient")
	fillGradient.Rotation = 0
	fillGradient.Color = Theme.AccentSequence()
	fillGradient.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0.15),
		NumberSequenceKeypoint.new(1, 0.55),
	})
	fillGradient.Parent = activeFill
	maid:Give(Theme.Changed:Connect(function(theme)
		fillGradient.Color = Theme.AccentSequence(theme)
	end))

	local activeStroke = Create.Stroke(button, {
		Theme = { Color = "Accent" },
		Thickness = 1,
		Transparency = 1,
	})

	local indicator = Create.New("Frame", {
		Name = "Indicator",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 4, 0.5, 0),
		Size = UDim2.fromOffset(2, 0),
		Corner = UDim.new(1, 0),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BackgroundTransparency = 0.12,
		ZIndex = 3,
		Parent = button,
	})
	local indGradient = Instance.new("UIGradient")
	indGradient.Rotation = 90
	indGradient.Color = Theme.AccentSequence()
	indGradient.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0.35),
		NumberSequenceKeypoint.new(0.5, 0),
		NumberSequenceKeypoint.new(1, 0.35),
	})
	indGradient.Parent = indicator
	maid:Give(Theme.Changed:Connect(function(theme)
		indGradient.Color = Theme.AccentSequence(theme)
	end))

	local iconInst = Icons.Create(options.Icon, {
		Name = "Icon",
		Size = UDim2.fromOffset(16, 16),
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 13, 0.5, 0),
		Color = "SubText",
		ZIndex = 3,
		Parent = button,
	})

	local titleLabel = Create.Text({
		Name = "Title",
		Text = tostring(options.Title),
		Font = "Medium",
		TextSize = 13,
		Color = "SubText",
		Position = UDim2.new(0, iconInst and 38 or 12, 0, 0),
		Size = UDim2.new(1, iconInst and -46 or -20, 1, 0),
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 3,
		Parent = button,
	})

	local badgeFrame = Create.New("Frame", {
		Name = "Badge",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -8, 0.5, 0),
		Size = UDim2.fromOffset(0, 18),
		AutomaticSize = Enum.AutomaticSize.X,
		Corner = 999,
		Theme = { BackgroundColor3 = "Accent" },
		BackgroundTransparency = 0.82,
		Visible = false,
		ZIndex = 3,
		Padding = { 0, 7, 0, 7 },
		Parent = button,
	})
	local badgeLabel = Create.Text({
		Name = "Text",
		Text = "",
		Font = "SemiBold",
		TextSize = 10,
		Color = "Accent",
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = badgeFrame,
	})

	-- Main tab page container
	local page = Create.New("Frame", {
		Name = "Page_" .. tostring(options.Title),
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		ClipsDescendants = true,
		Parent = window.PageContainer,
	})
	maid:Give(page)

	-- Optional SubTab header bar (hidden until AddSubTab is called)
	local subTabWrap = Create.New("Frame", {
		Name = "SubTabBar",
		Position = UDim2.fromOffset(16, 12),
		Size = UDim2.new(1, -32, 0, 36),
		Corner = 10,
		Theme = { BackgroundColor3 = "Field" },
		Visible = false,
		Padding = 3,
		Parent = page,
	})
	Create.GlassStroke(subTabWrap, 0.02)

	local subTabScroll = Create.New("ScrollingFrame", {
		Name = "SubTabScroll",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		AutomaticCanvasSize = Enum.AutomaticSize.None,
		CanvasSize = UDim2.new(),
		ScrollBarThickness = 0,
		ScrollingDirection = Enum.ScrollingDirection.X,
		Parent = subTabWrap,
	})

	local subTabIndicator = Create.New("Frame", {
		Name = "ActivePill",
		Position = UDim2.fromOffset(2, 2),
		Size = UDim2.new(0, 0, 1, -4),
		Corner = 7,
		Theme = { BackgroundColor3 = "Elevated" },
		BackgroundTransparency = 0.14,
		Visible = false,
		ZIndex = 1,
		Parent = subTabScroll,
	})
	Create.New("UIGradient", {
		Color = ColorSequence.new(Color3.new(1, 1, 1)),
		Rotation = 90,
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.05),
			NumberSequenceKeypoint.new(1, 0.28),
		}),
		Parent = subTabIndicator,
	})
	Create.GlassStroke(subTabIndicator, 0.05)

	local subTabButtons = Create.New("Frame", {
		Name = "Buttons",
		Position = UDim2.fromOffset(2, 0),
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = subTabScroll,
	})
	local subTabLayout = Create.List(subTabButtons, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 4,
		VAlign = Enum.VerticalAlignment.Center,
	})
	local function syncSubTabWrapSize()
		local contentW = subTabLayout.AbsoluteContentSize.X + 4
		subTabScroll.CanvasSize = UDim2.fromOffset(contentW, 0)
		if contentW > 4 then
			local pageW = page.AbsoluteSize.X
			local maxW = (pageW > 64) and (pageW - 32) or 9999
			subTabWrap.Size = UDim2.fromOffset(math.min(contentW + 6, maxW), 36)
		end
	end
	maid:Give(subTabLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncSubTabWrapSize))
	maid:Give(page:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncSubTabWrapSize))

	local subPageHolder = Create.New("Frame", {
		Name = "SubPages",
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Parent = page,
	})

	local self = setmetatable({
		Type = "Tab",
		Title = tostring(options.Title),
		Icon = options.Icon,
		Category = options.Category,
		Window = window,
		Maid = maid,
		_button = button,
		Page = page,
		SubTabs = {},
		ActiveSubTab = nil,
		Selected = false,
		_compact = window._sidebarCollapsed == true,
		_activeFill = activeFill,
		_activeStroke = activeStroke,
		_indicator = indicator,
		_iconInst = iconInst,
		_titleLabel = titleLabel,
		_badgeFrame = badgeFrame,
		_badgeLabel = badgeLabel,
		_subTabWrap = subTabWrap,
		_subTabScroll = subTabScroll,
		_subTabIndicator = subTabIndicator,
		_subTabButtons = subTabButtons,
		_subPageHolder = subPageHolder,
	}, Tab)

	self._defaultFlow = createFlowController(self, subPageHolder, nil)
	self._flows = { self._defaultFlow }

	-- Attach Container directly onto Tab as a convenience fallback for direct calls
	self._beforeAdd = function()
		self._defaultFlow.ClosePair()
	end
	Container.Attach(self, self._defaultFlow.Scroll, self, nil, window, nil)

	if options.Badge ~= nil then
		self:SetBadge(options.Badge)
	end
	self:SetCompact(self._compact, true)

	maid:Give(button.MouseEnter:Connect(function()
		if not window._visible or window._morphing or window._unloading or window._destroyed then
			return
		end
		if not self.Selected and not Transition.IsOverlayBlocking(button) then
			Tween.Play(button, { BackgroundTransparency = 0.55 }, Tween.Instant)
			if self._iconInst then
				Icons.SetColor(self._iconInst, "Text")
			end
			Theme.Bind(titleLabel, { TextColor3 = "Text" })
		end
	end))

	maid:Give(button.MouseLeave:Connect(function()
		if not self.Selected then
			Tween.Play(button, { BackgroundTransparency = 1 }, Tween.Instant)
			if self._iconInst then
				Icons.SetColor(self._iconInst, "SubText")
			end
			Theme.Bind(titleLabel, { TextColor3 = "SubText" })
		end
	end))

	maid:Give(button.Activated:Connect(function(input)
		if not window._visible or window._morphing or window._unloading or window._destroyed or Transition.IsOverlayBlocking(button) then
			return
		end
		Transition.Ripple(button, input, "Accent")
		self:Select()
	end))

	Tooltip.Bind(button, function()
		if window._sidebarCollapsed then
			return self.Title
		end
		return ""
	end, { Side = "Right" })

	return self
end

function Tab:SetTitle(text)
	self.Title = tostring(text or "")
	self._titleLabel.Text = self.Title
	if self.Window and self.Window.ActiveTab == self then
		self.Window:_updateBreadcrumb()
	end
end

function Tab:SetBadge(text)
	if text == nil or text == "" or text == false then
		self._badgeFrame.Visible = false
		self._badgeLabel.Text = ""
	else
		self._badgeLabel.Text = tostring(text)
		self._badgeFrame.Visible = not self._compact
	end
	local rightPad = self._badgeFrame.Visible and -86 or -46
	local leftX = self._iconInst and 38 or 12
	self._titleLabel.Size = UDim2.new(1, self._iconInst and rightPad or -20, 1, 0)
	self._titleLabel.Position = UDim2.new(0, leftX, 0, 0)
end

function Tab:SetCompact(compact, instant)
	compact = compact == true
	self._compact = compact
	if compact then
		self._titleLabel.Visible = false
		self._badgeFrame.Visible = false
		if self._iconInst then
			self._iconInst.AnchorPoint = Vector2.new(0.5, 0.5)
			self._iconInst.Position = UDim2.fromScale(0.5, 0.5)
		end
	else
		self._titleLabel.Visible = true
		self._titleLabel.TextTransparency = 1
		self._badgeFrame.Visible = self._badgeLabel.Text ~= ""
		if self._iconInst then
			self._iconInst.AnchorPoint = Vector2.new(0, 0.5)
			self._iconInst.Position = UDim2.new(0, 13, 0.5, 0)
		end
		if instant then
			self._titleLabel.TextTransparency = 0
		else
			Tween.Play(self._titleLabel, { TextTransparency = 0 }, Tween.Fast)
		end
	end
	if self._indicator then
		self._indicator.Position = UDim2.new(0, compact and 5 or 4, 0.5, 0)
		if self.Selected then
			self._indicator.Size = compact and UDim2.fromOffset(2, 12) or UDim2.fromOffset(2, 14)
		else
			self._indicator.Size = UDim2.fromOffset(2, 0)
		end
	end
end

function Tab:_setActiveVisual(active, instant)
	self.Selected = active == true
	local fillT = active and 0.8 or 1
	local strokeT = active and 0.68 or 1
	local indW = 2
	local indH = active and (self._compact and 12 or 14) or 0
	local indSize = UDim2.fromOffset(indW, indH)

	if active then
		Theme.Bind(self._titleLabel, { TextColor3 = "Text", FontFace = "@SemiBold" })
		if self._iconInst then
			Icons.SetColor(self._iconInst, "Accent")
		end
	else
		Theme.Bind(self._titleLabel, { TextColor3 = "SubText", FontFace = "@Medium" })
		if self._iconInst then
			Icons.SetColor(self._iconInst, "SubText")
		end
	end

	if instant then
		self._button.BackgroundTransparency = 1
		self._activeFill.BackgroundTransparency = fillT
		self._activeStroke.Transparency = strokeT
		self._indicator.Size = indSize
	else
		Tween.Play(self._button, { BackgroundTransparency = 1 }, Tween.Fast)
		Tween.Play(self._activeFill, { BackgroundTransparency = fillT }, Tween.Fast)
		Tween.Play(self._activeStroke, { Transparency = strokeT }, Tween.Fast)
		Tween.Spring(self._indicator, { Size = indSize }, Tween.Normal)
	end

	if not active then
		if self._defaultFlow and self._defaultFlow.Scroll then
			Transition.RestoreCascade(self._defaultFlow.Scroll)
		end
		for _, candidate in ipairs(self.SubTabs) do
			if candidate.Scroll then
				Transition.RestoreCascade(candidate.Scroll)
			end
		end
	else
		self:_syncSubTabIndicator(instant)
	end
	self.Page.Visible = active
	if active then
		local activeScroll = self.ActiveSubTab and self.ActiveSubTab.Scroll or self._defaultFlow.Scroll
		if instant then
			Transition.RestoreCascade(activeScroll)
		else
			Transition.Cascade(activeScroll, 0.018, 12, 10)
		end
	end
end

function Tab:_syncSubTabIndicator(instant)
	local subTab = self.ActiveSubTab
	if not subTab or not subTab._button then
		return
	end
	local btn = subTab._button
	local function applyPill()
		if not btn.Parent or not self._subTabButtons.Parent then
			return
		end
		local x = btn.AbsolutePosition.X - self._subTabButtons.AbsolutePosition.X
		local w = btn.AbsoluteSize.X
		if w <= 0 then
			return
		end
		self._subTabIndicator.Visible = true
		local targetPos = UDim2.fromOffset(x + 2, 2)
		local targetSize = UDim2.new(0, w, 1, -4)
		if instant then
			self._subTabIndicator.Position = targetPos
			self._subTabIndicator.Size = targetSize
		else
			Tween.Play(
				self._subTabIndicator,
				{ Position = targetPos, Size = targetSize },
				Tween.Normal,
				Enum.EasingStyle.Exponential,
				Enum.EasingDirection.Out
			)
		end
	end
	applyPill()
	task.defer(applyPill)
end

function Tab:Select()
	if self.Window and type(self.Window.SelectTab) == "function" then
		self.Window:SelectTab(self)
	end
end

function Tab:AddSection(options)
	return self._defaultFlow.AddSection(options)
end

function Tab:SelectSubTab(subTab, instant)
	if type(subTab) == "string" then
		for _, candidate in ipairs(self.SubTabs) do
			if candidate.Title == subTab then
				subTab = candidate
				break
			end
		end
	elseif type(subTab) == "number" then
		subTab = self.SubTabs[subTab]
	end
	if type(subTab) ~= "table" or not subTab.Scroll then
		return
	end

	local effectiveInstant = instant == true or (self.Window ~= nil and (not self.Window._visible or self.Window._morphing or self.Window._unloading))
	if self.ActiveSubTab == subTab and not effectiveInstant then
		return
	end

	local oldIdx, newIdx = 1, 1
	for idx, candidate in ipairs(self.SubTabs) do
		if candidate == self.ActiveSubTab then
			oldIdx = idx
		end
		if candidate == subTab then
			newIdx = idx
		end
	end
	local dir = (newIdx >= oldIdx) and 1 or -1

	for _, candidate in ipairs(self.SubTabs) do
		local isCurrent = (candidate == subTab)
		if not isCurrent and candidate.Scroll then
			Transition.RestoreCascade(candidate.Scroll)
		end
		candidate.Scroll.Visible = isCurrent
		Theme.Bind(candidate._titleLabel, {
			TextColor3 = isCurrent and "Text" or "SubText",
			FontFace = isCurrent and "@Bold" or "@Medium",
		})
		if candidate._iconInst then
			Icons.SetColor(candidate._iconInst, isCurrent and "Accent" or "SubText")
		end
	end

	self.ActiveSubTab = subTab
	if effectiveInstant then
		Transition.RestoreCascade(subTab.Scroll)
	else
		Transition.Cascade(subTab.Scroll, 0.018, 12, dir * 12)
	end
	self:_syncSubTabIndicator(effectiveInstant)

	if self.Window and self.Window.ActiveTab == self then
		self.Window:_updateBreadcrumb()
	end
end

function Tab:AddSubTab(options)
	options = Util.Options(options, { Title = "SubTab", Icon = nil }, "Title")

	if not self._subTabWrap.Visible then
		self._subTabWrap.Visible = true
		self._defaultFlow.Scroll.Visible = false
		self._subPageHolder.Position = UDim2.fromOffset(0, 50)
		self._subPageHolder.Size = UDim2.new(1, 0, 1, -50)
	end

	local order = #self.SubTabs + 1
	local subBtn = Create.New("TextButton", {
		Name = "SubTab_" .. tostring(options.Title),
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		Corner = 8,
		Padding = { 0, 12, 0, 12 },
		LayoutOrder = order,
		Parent = self._subTabButtons,
	})
	Create.List(subBtn, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 6,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local subIcon = Icons.Create(options.Icon, {
		Size = UDim2.fromOffset(14, 14),
		Color = "SubText",
		LayoutOrder = 1,
		Parent = subBtn,
	})

	local subLabel = Create.Text({
		Name = "Title",
		Text = tostring(options.Title),
		Font = "Medium",
		TextSize = 12,
		Color = "SubText",
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		TextXAlignment = Enum.TextXAlignment.Center,
		LayoutOrder = 2,
		Parent = subBtn,
	})

	local subTab = {
		Type = "SubTab",
		Title = tostring(options.Title),
		Icon = options.Icon,
		Tab = self,
		Window = self.Window,
		Maid = self.Maid,
		_button = subBtn,
		_titleLabel = subLabel,
		_iconInst = subIcon,
	}

	local flow = createFlowController(self, self._subPageHolder, subTab)
	table.insert(self._flows, flow)
	flow.Scroll.Visible = false
	subTab.Scroll = flow.Scroll
	subTab.Page = flow.Scroll
	subTab._beforeAdd = function()
		flow.ClosePair()
	end

	function subTab:AddSection(secOpts)
		return flow.AddSection(secOpts)
	end

	function subTab:Select()
		self.Tab:SelectSubTab(self)
	end

	function subTab:SetTitle(text)
		self.Title = tostring(text or "")
		self._titleLabel.Text = self.Title
		if self.Tab.ActiveSubTab == self and self.Window and self.Window.ActiveTab == self.Tab then
			self.Window:_updateBreadcrumb()
		end
	end

	Container.Attach(subTab, flow.Scroll, self, nil, self.Window, subTab)

	Theme.Bind(subBtn, { BackgroundColor3 = "Tile" })
	local subHovered = false
	self.Maid:Give(subBtn.MouseEnter:Connect(function()
		if (self.Window and (not self.Window._visible or self.Window._morphing or self.Window._unloading or self.Window._destroyed)) or self.ActiveSubTab == subTab or Util.IsTouchDevice() or Transition.IsOverlayBlocking(subBtn) then
			return
		end
		subHovered = true
		Tween.Play(subBtn, { BackgroundTransparency = 0.52 }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		Tween.Play(subLabel, { TextColor3 = Theme.Current.Text }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end))
	self.Maid:Give(subBtn.MouseLeave:Connect(function()
		subHovered = false
		Tween.Play(subBtn, { BackgroundTransparency = 1 }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		if self.ActiveSubTab ~= subTab then
			Tween.Play(subLabel, { TextColor3 = Theme.Current.SubText }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		end
	end))

	self.Maid:Give(subBtn.Activated:Connect(function()
		if (self.Window and (not self.Window._visible or self.Window._morphing or self.Window._unloading or self.Window._destroyed)) or Transition.IsOverlayBlocking(subBtn) then
			return
		end
		if subHovered then
			subBtn.BackgroundTransparency = 1
		end
		self:SelectSubTab(subTab)
	end))

	table.insert(self.SubTabs, subTab)
	if #self.SubTabs == 1 then
		self:SelectSubTab(subTab)
	end

	return subTab
end

function Tab:RefreshLayout(windowWidth)
	local w = windowWidth or (self.Window and self.Window:GetWidth()) or 820
	if self._flows then
		for _, flow in ipairs(self._flows) do
			if flow.RefreshLayout then
				flow.RefreshLayout(w)
			end
		end
	end
	if self._syncSubTabIndicator then
		self:_syncSubTabIndicator(true)
	end
end

function Tab:Destroy()
	self.Maid:Clean()
end

return Tab
end

__modules["Window/Window"] = function()
--[[
	Bali UI · Window/Window
	Main obsidian glassmorphic desktop/mobile window with collapsible sidebar,
	spotlight search pill, top breadcrumb & quick-action bar, popup manager,
	dialog & notification layers, and full system integration.
]]

local Assets = require("Core/Assets")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Maid = require("Core/Maid")
local Services = require("Core/Services")
local Signal = require("Core/Signal")
local Theme = require("Core/Theme")
local Transition = require("Core/Transition")
local Tween = require("Core/Tween")
local Util = require("Core/Util")

local Blur = require("Systems/Blur")
local CommandPalette = require("Systems/CommandPalette")
local Config = require("Systems/Config")
local Input = require("Systems/Input")
local KeybindList = require("Systems/KeybindList")
local Notification = require("Systems/Notification")
local Tooltip = require("Systems/Tooltip")
local Watermark = require("Systems/Watermark")

local Dialog = require("Window/Dialog")
local MobileButton = require("Window/MobileButton")
local Tab = require("Window/Tab")

local Window = {}
Window.__index = Window

local SIDEBAR_EXPANDED = 212
local SIDEBAR_COLLAPSED = 58
local TOPBAR_HEIGHT = 52
local POPUP_PAD = 8

local function getViewportSize(screenGui)
	if screenGui and screenGui:IsA("LayerCollector") and screenGui.AbsoluteSize.X > 0 and screenGui.AbsoluteSize.Y > 0 then
		return screenGui.AbsoluteSize
	end
	local cam = Services.Workspace.CurrentCamera
	local raw = cam and cam.ViewportSize or Vector2.new(1280, 720)
	local ok, inset = pcall(function()
		return Services.GuiService:GetGuiInset()
	end)
	if ok and inset then
		return Vector2.new(raw.X - inset.X, raw.Y - inset.Y)
	end
	return raw
end

local function parseSizeVector(sizeOpt, defaultVec)
	if typeof(sizeOpt) == "Vector2" then
		return sizeOpt
	elseif typeof(sizeOpt) == "UDim2" then
		return Vector2.new(sizeOpt.X.Offset, sizeOpt.Y.Offset)
	end
	return defaultVec
end

local function createActionButton(parent, iconName, tooltipText, layoutOrder, maid)
	local btn = Create.New("TextButton", {
		Name = "Action_" .. tostring(iconName),
		Size = UDim2.fromOffset(30, 30),
		Text = "",
		AutoButtonColor = false,
		ClipsDescendants = true,
		Corner = 8,
		Theme = {
			BackgroundColor3 = "Tile",
			BackgroundTransparency = "TileTransparency",
		},
		LayoutOrder = layoutOrder,
		Parent = parent,
	})
	local stroke = Create.Stroke(btn, {
		Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
	})
	local iconInst = Icons.Create(iconName, {
		Size = UDim2.fromOffset(15, 15),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = "Text",
		Parent = btn,
	})
	maid:Give(btn.MouseEnter:Connect(function()
		if iconName ~= "x" then
			Icons.SetColor(iconInst, "Accent")
		end
	end))
	maid:Give(btn.MouseLeave:Connect(function()
		if iconName ~= "x" then
			Icons.SetColor(iconInst, "Text")
		end
	end))
	maid:Give(Transition.Hover(btn, btn, "Tile", "TileHover", stroke))
	if tooltipText and tooltipText ~= "" then
		maid:Give(Tooltip.Bind(btn, tooltipText))
	end
	return btn, iconInst, stroke
end

function Window.new(screenGui, options)
	assert(typeof(screenGui) == "Instance", "[Bali] Window.new expects a ScreenGui or LayerCollector")
	if not Assets.Loaded then
		pcall(Assets.Load)
	end

	options = Util.Options(options, {
		Title = "Bali",
		Subtitle = nil,
		Version = nil,
		Icon = "bali-logo",
		WelcomeSubtitle = nil,
		ShowUser = false,
		Size = UDim2.fromOffset(820, 540),
		MinSize = Vector2.new(460, 360),
		MaxSize = Vector2.new(1280, 900),
		SidebarWidth = SIDEBAR_EXPANDED,
		SidebarCollapsed = false,
		Theme = nil,
		Accent = nil,
		Font = nil,
		ToggleKey = Enum.KeyCode.RightShift,
		Blur = nil,
		BlurIntensity = nil,
		Watermark = nil,
		KeybindList = nil,
		NotificationPosition = "BottomRight",
		MobileButton = true,
		ConfigFolder = nil,
		Folder = nil,
		AutoLoadConfig = false,
		ConfirmClose = true,
		DestroyOnClose = false,
		OwnsScreenGui = false,
		OnClose = nil,
		OnDestroy = nil,
	}, "Title")

	if options.Theme and Theme.Presets[options.Theme] then
		Theme.Set(options.Theme, false)
	end
	if typeof(options.Accent) == "Color3" then
		Theme.SetAccent(options.Accent, false)
	end
	if options.Font and Theme.Fonts[options.Font] then
		Theme.SetFont(options.Font)
	end

	local maid = Maid.new()
	local windowId = Util.RandomString(8)

	-- Root ZIndex-isolated layers
	local mainLayer = Create.New("Frame", {
		Name = "BaliMainLayer",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 1,
		Parent = screenGui,
	})
	local hudLayer = Create.New("Frame", {
		Name = "BaliHUDLayer",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 20,
		Parent = screenGui,
	})
	local popupLayer = Create.New("Frame", {
		Name = "BaliPopupLayer",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 100,
		Parent = screenGui,
	})
	local dialogLayer = Create.New("Frame", {
		Name = "BaliDialogLayer",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 200,
		Parent = screenGui,
	})
	local notificationLayer = Create.New("Frame", {
		Name = "BaliNotificationLayer",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ZIndex = 300,
		Parent = screenGui,
	})

	maid:Give(mainLayer)
	maid:Give(hudLayer)
	maid:Give(popupLayer)
	maid:Give(dialogLayer)
	maid:Give(notificationLayer)

	-- Popup click-catcher backdrop inside PopupLayer
	local popupBackdrop = Create.New("TextButton", {
		Name = "PopupBackdrop",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		AutoButtonColor = false,
		Visible = false,
		ZIndex = 1,
		Parent = popupLayer,
	})

	-- Compute initial viewport-clamped window dimensions
	local vp = getViewportSize(screenGui)
	local isMobile = (options.MobileMode ~= nil) and (options.MobileMode == true) or (Util.IsTouchDevice() or vp.X < 640)
	local desiredSize = parseSizeVector(options.Size, Vector2.new(820, 540))
	local reqMin = parseSizeVector(options.MinSize, Vector2.new(460, 360))
	local reqMax = parseSizeVector(options.MaxSize, Vector2.new(1280, 900))

	local minW = math.min(reqMin.X, math.max(300, vp.X - 16))
	local minH = math.min(reqMin.Y, math.max(260, vp.Y - 16))
	local effectiveMin = Vector2.new(minW, minH)

	local targetW = isMobile and math.min(desiredSize.X, math.max(360, math.min(540, vp.X - 24))) or desiredSize.X
	local initW = Util.Clamp(targetW, math.min(minW, vp.X - 24), math.max(minW, vp.X - 24))
	local initH = Util.Clamp(desiredSize.Y, math.min(minH, vp.Y - 24), math.max(minH, vp.Y - 24))
	local startX = math.max(8, math.floor((vp.X - initW) * 0.5))
	local startY = math.max(8, math.floor((vp.Y - initH) * 0.5))

	-- Wrapper holds Shadow + clipped Main frame so Shadow tracks Drag/Resize/Mount seamlessly
	local mainWrapper = Create.New("Frame", {
		Name = "BaliWindowWrapper",
		Position = UDim2.fromOffset(startX, startY),
		Size = UDim2.fromOffset(initW, initH),
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = mainLayer,
	})

	local shadowDesc = Assets.Shadow()
	Create.New("ImageLabel", {
		Name = "WindowShadow",
		Image = shadowDesc.Image,
		ScaleType = Enum.ScaleType.Slice,
		SliceCenter = shadowDesc.Slice,
		Position = UDim2.fromOffset(-shadowDesc.Inset, -shadowDesc.Inset + 6),
		Size = UDim2.new(1, shadowDesc.Inset * 2, 1, shadowDesc.Inset * 2),
		BackgroundTransparency = 1,
		Theme = {
			ImageColor3 = "Shadow",
			ImageTransparency = "ShadowTransparency",
		},
		ZIndex = 1,
		Parent = mainWrapper,
	})

	local main = Create.New("Frame", {
		Name = "Main",
		Size = UDim2.fromScale(1, 1),
		Theme = {
			BackgroundColor3 = "Background",
			BackgroundTransparency = "BackgroundTransparency",
		},
		Corner = 14,
		ClipsDescendants = true,
		ZIndex = 2,
		Parent = mainWrapper,
	})
	Create.GlassStroke(main, 0.04)

	-- Ambient obsidian glass radial blooms & grain (clipped cleanly to rounded corners)
	local bgClip = Create.New("CanvasGroup", {
		Name = "BackgroundClip",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Corner = 14,
		ZIndex = 1,
		Parent = main,
	})

	local glowTopLeft, glowBottomRight, noiseLayer = nil, nil, nil
	local glowAsset = Assets.Get("Glow")
	if glowAsset and Assets.Available then
		glowTopLeft = Create.New("ImageLabel", {
			Name = "GlowTopLeft",
			Image = glowAsset,
			Size = UDim2.fromOffset(420, 420),
			Position = UDim2.fromOffset(-150, -150),
			BackgroundTransparency = 1,
			Theme = {
				ImageColor3 = "Accent",
				ImageTransparency = "GlowTransparency",
			},
			ZIndex = 1,
			Parent = bgClip,
		})
		glowBottomRight = Create.New("ImageLabel", {
			Name = "GlowBottomRight",
			Image = glowAsset,
			AnchorPoint = Vector2.new(1, 1),
			Size = UDim2.fromOffset(420, 420),
			Position = UDim2.new(1, 160, 1, 160),
			BackgroundTransparency = 1,
			Theme = {
				ImageColor3 = "Accent2",
				ImageTransparency = "GlowTransparency",
			},
			ZIndex = 1,
			Parent = bgClip,
		})
	end

	local noiseAsset = Assets.Get("Noise")
	if noiseAsset and Assets.Available then
		noiseLayer = Create.New("ImageLabel", {
			Name = "Noise",
			Image = noiseAsset,
			ScaleType = Enum.ScaleType.Tile,
			TileSize = UDim2.fromOffset(128, 128),
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Corner = 14,
			Theme = { ImageTransparency = "NoiseTransparency" },
			ZIndex = 1,
			Parent = bgClip,
		})
	end

	-- ─── Left Sidebar ────────────────────────────────────────────────────────
	local expandedWidth = tonumber(options.SidebarWidth) or SIDEBAR_EXPANDED
	local isCollapsed = options.SidebarCollapsed == true or (isMobile and options.SidebarCollapsed ~= false) or (initW < 580 and options.SidebarCollapsed ~= false)
	local startSidebarW = isCollapsed and SIDEBAR_COLLAPSED or expandedWidth

	local sidebarBg = Create.New("Frame", {
		Name = "SidebarBg",
		Size = UDim2.new(0, startSidebarW, 1, 0),
		Theme = {
			BackgroundColor3 = "Sidebar",
			BackgroundTransparency = "SidebarTransparency",
		},
		ZIndex = 2,
		Parent = bgClip,
	})

	local sidebar = Create.New("Frame", {
		Name = "Sidebar",
		Size = UDim2.new(0, startSidebarW, 1, 0),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		ZIndex = 3,
		Parent = main,
	})

	Create.New("Frame", {
		Name = "RightBorder",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.fromScale(1, 0),
		Size = UDim2.new(0, 1, 1, 0),
		Theme = {
			BackgroundColor3 = "Divider",
			BackgroundTransparency = "DividerTransparency",
		},
		ZIndex = 4,
		Parent = sidebar,
	})

	local sidebarTop = Create.New("Frame", {
		Name = "SidebarTop",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Padding = { 10, 10, 8, 10 },
		ZIndex = 3,
		Parent = sidebar,
	})
	Create.List(sidebarTop, { Gap = 8 })

	-- Brand Row
	local brandRow = Create.New("Frame", {
		Name = "BrandRow",
		Size = UDim2.new(1, 0, 0, 36),
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = sidebarTop,
	})

	local customBrandIcon = options.Icon and options.Icon ~= "bali-logo" and options.Icon ~= "bali"
	local brandBadge = Create.New("TextButton", {
		Name = "BrandBadge",
		Position = UDim2.fromOffset(2, 2),
		Size = UDim2.fromOffset(32, 32),
		Text = "",
		AutoButtonColor = false,
		Corner = 8,
		BackgroundColor3 = Color3.fromRGB(37, 37, 46),
		BackgroundTransparency = 1,
		Parent = brandRow,
	})
	local brandStroke = Create.Stroke(brandBadge, {
		Theme = { Color = "Stroke" },
		Transparency = 1,
		Thickness = 1,
	})

	local brandCollapsedFlag = Create.New("Frame", {
		Name = "_BrandCollapsedFlag",
		Size = UDim2.new(),
		BackgroundTransparency = 1,
		Visible = isCollapsed,
		Parent = brandBadge,
	})
	local brandLogoIcon = Icons.Create(options.Icon or "bali-logo", {
		Name = "BrandLogoIcon",
		Size = UDim2.fromOffset(customBrandIcon and 18 or 22, customBrandIcon and 18 or 22),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = customBrandIcon and "Accent" or Color3.fromRGB(255, 255, 255),
		Visible = true,
		Parent = brandBadge,
	})
	local brandExpandIcon = Icons.Create("panel-left", {
		Name = "BrandExpandIcon",
		Size = UDim2.fromOffset(16, 16),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = "Text",
		Visible = false,
		Parent = brandBadge,
	})
	local brandBadgeHovered = false
	local function applyBrandBadgeSurface(theme, animate)
		local t = theme or Theme.Current
		local showExpand = (brandCollapsedFlag and brandCollapsedFlag.Visible == true) and brandBadgeHovered
		if brandLogoIcon then
			brandLogoIcon.Visible = not showExpand
		end
		if brandExpandIcon then
			brandExpandIcon.Visible = showExpand
		end
		local collapsedNow = showExpand
		local lightModeLogo = (t and t.Dark == false) and not customBrandIcon and not collapsedNow
		local targetBgColor = lightModeLogo and Color3.fromRGB(24, 24, 32) or ((t and t.TileHover) or Color3.fromRGB(37, 37, 46))
		local targetBgTrans = lightModeLogo and (brandBadgeHovered and 0.04 or 0.12) or (brandBadgeHovered and 0.86 or 1)
		local targetStrTrans = lightModeLogo and (brandBadgeHovered and 0.45 or 0.65) or (brandBadgeHovered and 0.62 or 1)

		if animate and not Tween.Reduced then
			Tween.Play(brandBadge, {
				BackgroundColor3 = targetBgColor,
				BackgroundTransparency = targetBgTrans,
			}, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			Tween.Play(brandStroke, { Transparency = targetStrTrans }, Tween.Fast, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		else
			Tween.Play(brandBadge, {
				BackgroundColor3 = targetBgColor,
				BackgroundTransparency = targetBgTrans,
			}, Tween.Instant)
			Tween.Play(brandStroke, { Transparency = targetStrTrans }, Tween.Instant)
			brandBadge.BackgroundColor3 = targetBgColor
			brandBadge.BackgroundTransparency = targetBgTrans
			brandStroke.Transparency = targetStrTrans
		end
	end
	applyBrandBadgeSurface(Theme.Current, false)
	maid:Give(Theme.Changed:Connect(function(theme)
		applyBrandBadgeSurface(theme, false)
	end))
	maid:Give(brandBadge.MouseEnter:Connect(function()
		brandBadgeHovered = true
		applyBrandBadgeSurface(Theme.Current, true)
	end))
	maid:Give(brandBadge.MouseLeave:Connect(function()
		brandBadgeHovered = false
		applyBrandBadgeSurface(Theme.Current, true)
	end))

	local brandText = Create.New("Frame", {
		Name = "BrandText",
		Position = UDim2.fromOffset(42, 0),
		Size = UDim2.new(1, -72, 1, 0),
		BackgroundTransparency = 1,
		Visible = not isCollapsed,
		Parent = brandRow,
	})
	Create.List(brandText, { Gap = 1, VAlign = Enum.VerticalAlignment.Center })

	local titleRow = Create.New("Frame", {
		Size = UDim2.new(1, 0, 0, 18),
		BackgroundTransparency = 1,
		LayoutOrder = 1,
		Parent = brandText,
	})
	Create.List(titleRow, {
		Direction = Enum.FillDirection.Horizontal,
		Gap = 6,
		VAlign = Enum.VerticalAlignment.Center,
	})

	local brandTitleLabel = Create.Text({
		Name = "Title",
		Text = tostring(options.Title or "Bali"),
		Font = "Bold",
		TextSize = 14,
		Color = "Text",
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		TextTruncate = Enum.TextTruncate.AtEnd,
		LayoutOrder = 1,
		Parent = titleRow,
	})

	local subtitleText = options.Subtitle or options.Version
	local brandSubLabel = Create.Text({
		Name = "Subtitle",
		Text = subtitleText and tostring(subtitleText) or "",
		Font = "Medium",
		TextSize = 10,
		Color = "Muted",
		Size = UDim2.new(1, 0, 0, 13),
		TextTruncate = Enum.TextTruncate.AtEnd,
		Visible = subtitleText ~= nil and tostring(subtitleText) ~= "",
		LayoutOrder = 2,
		Parent = brandText,
	})

	local collapseBtn = Create.New("TextButton", {
		Name = "CollapseButton",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.fromOffset(26, 26),
		Text = "",
		AutoButtonColor = false,
		Corner = 7,
		Theme = { BackgroundColor3 = "Tile" },
		BackgroundTransparency = 1,
		Visible = not isCollapsed,
		Parent = brandRow,
	})
	local collapseStroke = Create.Stroke(collapseBtn, {
		Theme = { Color = "Stroke" },
		Transparency = 1,
	})
	Icons.Create("panel-left", {
		Size = UDim2.fromOffset(14, 14),
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Color = "SubText",
		Parent = collapseBtn,
	})
	maid:Give(collapseBtn.MouseEnter:Connect(function()
		Tween.Play(collapseBtn, { BackgroundTransparency = Theme.Current.TileTransparency }, Tween.Instant)
		Tween.Play(collapseStroke, { Transparency = Theme.Current.StrokeTransparency }, Tween.Instant)
	end))
	maid:Give(collapseBtn.MouseLeave:Connect(function()
		Tween.Play(collapseBtn, { BackgroundTransparency = 1 }, Tween.Instant)
		Tween.Play(collapseStroke, { Transparency = 1 }, Tween.Instant)
	end))

	-- Optional Welcome / User block
	local welcomeCard
	local showWelcome = (options.WelcomeSubtitle ~= nil and options.WelcomeSubtitle ~= "") or options.ShowUser == true
	if showWelcome then
		local displayName = "Guest"
		pcall(function()
			local lp = Services.Players.LocalPlayer
			if lp then
				displayName = lp.DisplayName ~= "" and lp.DisplayName or lp.Name
			end
		end)
		local welcomeMainText = options.WelcomeSubtitle and tostring(options.WelcomeSubtitle)
			or ("Welcome Back, " .. displayName)

		welcomeCard = Create.New("Frame", {
			Name = "WelcomeBlock",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Corner = 9,
			Theme = {
				BackgroundColor3 = "Tile",
				BackgroundTransparency = "TileTransparency",
			},
			Padding = { 8, 9, 8, 9 },
			Visible = not isCollapsed,
			LayoutOrder = 2,
			Parent = sidebarTop,
		})
		Create.GlassStroke(welcomeCard, 0.02)
		Create.List(welcomeCard, {
			Direction = Enum.FillDirection.Horizontal,
			Gap = 8,
			VAlign = Enum.VerticalAlignment.Center,
		})

		local avatarWrap = Create.New("Frame", {
			Size = UDim2.fromOffset(26, 26),
			Corner = 999,
			Theme = { BackgroundColor3 = "Accent" },
			BackgroundTransparency = 0.85,
			ClipsDescendants = true,
			LayoutOrder = 1,
			Parent = welcomeCard,
		})
		local avatarFallback = Icons.Create("user", {
			Size = UDim2.fromOffset(14, 14),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Color = "Accent",
			Parent = avatarWrap,
		})
		task.spawn(function()
			local lp = Services.Players.LocalPlayer
			if not lp then
				return
			end
			local ok, thumb, ready = pcall(function()
				return Services.Players:GetUserThumbnailAsync(
					lp.UserId,
					Enum.ThumbnailType.HeadShot,
					Enum.ThumbnailSize.Size48x48
				)
			end)
			if ok and ready and type(thumb) == "string" and thumb ~= "" and avatarWrap.Parent then
				if avatarFallback then
					avatarFallback.Visible = false
				end
				Create.New("ImageLabel", {
					Size = UDim2.fromScale(1, 1),
					Image = thumb,
					BackgroundTransparency = 1,
					Corner = 999,
					Parent = avatarWrap,
				})
			end
		end)

		local userText = Create.New("Frame", {
			Size = UDim2.new(1, -38, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			LayoutOrder = 2,
			Parent = welcomeCard,
		})
		Create.List(userText, { Gap = 1 })
		Create.Text({
			Text = "Workspace Active",
			Font = "Medium",
			TextSize = 10,
			Color = "Muted",
			Size = UDim2.new(1, 0, 0, 12),
			TextTruncate = Enum.TextTruncate.AtEnd,
			LayoutOrder = 1,
			Parent = userText,
		})
		Create.Text({
			Text = welcomeMainText,
			Font = "SemiBold",
			TextSize = 11,
			Color = "Text",
			Size = UDim2.new(1, 0, 0, 14),
			TextWrapped = false,
			TextTruncate = Enum.TextTruncate.AtEnd,
			LayoutOrder = 2,
			Parent = userText,
		})
	end

	-- Spotlight Search Pill
	local searchPill = Create.New("TextButton", {
		Name = "SpotlightPill",
		Size = UDim2.new(1, 0, 0, 34),
		Text = "",
		AutoButtonColor = false,
		ClipsDescendants = true,
		Corner = 9,
		Theme = { BackgroundColor3 = "Field" },
		LayoutOrder = 3,
		Parent = sidebarTop,
	})
	local searchStroke = Create.Stroke(searchPill, {
		Theme = { Color = "Stroke", Transparency = "StrokeTransparency" },
	})
	maid:Give(Transition.Hover(searchPill, searchPill, "Field", "FieldHover", searchStroke))

	local searchIcon = Icons.Create("search", {
		Size = UDim2.fromOffset(14, 14),
		AnchorPoint = isCollapsed and Vector2.new(0.5, 0.5) or Vector2.new(0, 0.5),
		Position = isCollapsed and UDim2.fromScale(0.5, 0.5) or UDim2.new(0, 12, 0.5, 0),
		Color = "SubText",
		Parent = searchPill,
	})

	local searchPlaceholder = Create.Text({
		Text = "Search",
		Font = "Regular",
		TextSize = 12,
		Color = "SubText",
		TextTransparency = 0.2,
		Position = UDim2.fromOffset(32, 0),
		Size = UDim2.new(1, -84, 1, 0),
		TextTruncate = Enum.TextTruncate.AtEnd,
		Visible = not isCollapsed,
		Parent = searchPill,
	})

	local shortcutChip = Create.New("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -6, 0.5, 0),
		Size = UDim2.fromOffset(42, 18),
		Corner = 5,
		Theme = { BackgroundColor3 = "Tile", BackgroundTransparency = "TileTransparency" },
		Visible = not isCollapsed,
		Parent = searchPill,
	})
	Create.Text({
		Text = "Ctrl+K",
		Font = "SemiBold",
		TextSize = 10,
		Color = "Muted",
		Size = UDim2.fromScale(1, 1),
		TextXAlignment = Enum.TextXAlignment.Center,
		Parent = shortcutChip,
	})

	maid:Give(searchPill.Activated:Connect(function(input)
		Transition.Ripple(searchPill, input, "Accent")
		CommandPalette.Open()
	end))
	maid:Give(Tooltip.Bind(searchPill, "Search commands & elements (Ctrl+K)"))

	-- Tab Scrolling Container (dynamically positioned right beneath SidebarTop)
	local tabScroll = Create.New("ScrollingFrame", {
		Name = "TabNavigation",
		Position = UDim2.fromOffset(0, 108),
		Size = UDim2.new(1, 0, 1, -108),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(),
		ScrollBarThickness = 2,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Theme = { ScrollBarImageColor3 = "Muted" },
		Padding = { 2, 10, 12, 10 },
		ZIndex = 3,
		Parent = sidebar,
	})
	Create.List(tabScroll, { Gap = 3 })

	local function syncTabScrollBounds()
		local topH = sidebarTop.AbsoluteSize.Y
		tabScroll.Position = UDim2.fromOffset(0, topH)
		tabScroll.Size = UDim2.new(1, 0, 1, -(topH + 10))
	end
	maid:Give(sidebarTop:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncTabScrollBounds))
	task.defer(syncTabScrollBounds)

	-- ─── Right Body Area & Top Header Bar ────────────────────────────────────
	local bodyArea = Create.New("Frame", {
		Name = "BodyArea",
		Position = UDim2.new(0, startSidebarW, 0, 0),
		Size = UDim2.new(1, -startSidebarW, 1, 0),
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = main,
	})

	local topbar = Create.New("Frame", {
		Name = "Topbar",
		Size = UDim2.new(1, 0, 0, TOPBAR_HEIGHT),
		BackgroundTransparency = 1,
		ZIndex = 5,
		Parent = bodyArea,
	})

	Create.New("Frame", {
		Name = "BottomBorder",
		AnchorPoint = Vector2.new(0, 1),
		Position = UDim2.fromScale(0, 1),
