		ClipsDescendants = true,
		ScrollBarThickness = 2,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Theme = { ScrollBarImageColor3 = "Muted" },
		LayoutOrder = 3,
		Parent = pop,
	})
	Create.Padding(listScroll, { 2, 5, 2, 2 })
	local listLayout = Create.List(listScroll, { Gap = 6 })
	local function syncListHeight()
		if listScroll.Parent then
			local h = math.clamp(listLayout.AbsoluteContentSize.Y + 4, 48, 250)
			listScroll.Size = UDim2.new(1, 0, 0, h)
		end
	end
	popMaid:Give(listLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncListHeight))

	local TYPE_COLORS = {
		Info = "Info",
		Success = "Success",
		Warning = "Warning",
		Error = "Error",
		Accent = "Accent",
	}
	local TYPE_ICONS = {
		Info = "info",
		Success = "circle-check",
		Warning = "triangle-alert",
		Error = "circle-x",
		Accent = "sparkles",
	}

	local function rebuildList()
		for _, child in ipairs(listScroll:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		local history = Notification.History
		if #history == 0 then
			Create.Text({
				Text = "All caught up. No notifications yet.",
				Font = "Regular",
				TextSize = 12,
				Color = "Muted",
				Size = UDim2.new(1, 0, 0, 44),
				TextXAlignment = Enum.TextXAlignment.Center,
				Parent = listScroll,
			})
			syncListHeight()
			task.defer(syncListHeight)
			return
		end

		for index, entry in ipairs(history) do
			local item = Create.New("Frame", {
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				Corner = 8,
				Theme = { BackgroundColor3 = "Tile", BackgroundTransparency = "TileTransparency" },
				Padding = { 8, 10, 8, 10 },
				LayoutOrder = index,
				Parent = listScroll,
			})
			Create.List(item, { Gap = 4 })

			local topLine = Create.New("Frame", {
				Size = UDim2.new(1, 0, 0, 16),
				BackgroundTransparency = 1,
				LayoutOrder = 1,
				Parent = item,
			})
			Icons.Create(TYPE_ICONS[entry.Type] or "info", {
				Size = UDim2.fromOffset(13, 13),
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 0, 0.5, 0),
				Color = TYPE_COLORS[entry.Type] or "Info",
				Parent = topLine,
			})
			Create.Text({
				Text = tostring(entry.Title or "Notification"),
				Font = "SemiBold",
				TextSize = 12,
				Color = "Text",
				Position = UDim2.fromOffset(19, 0),
				Size = UDim2.new(1, -64, 1, 0),
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = topLine,
			})
			Create.Text({
				Text = tostring(entry.TimeText or ""),
				Font = "Regular",
				TextSize = 10,
				Color = "Muted",
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.fromScale(1, 0),
				Size = UDim2.new(0, 42, 1, 0),
				TextXAlignment = Enum.TextXAlignment.Right,
				Parent = topLine,
			})

			if entry.Content and entry.Content ~= "" then
				Create.Text({
					Text = tostring(entry.Content),
					Font = "Regular",
					TextSize = 11,
					Color = "SubText",
					Size = UDim2.new(1, 0, 0, 0),
					AutomaticSize = Enum.AutomaticSize.Y,
					TextWrapped = true,
					LayoutOrder = 2,
					Parent = item,
				})
			end
		end
		syncListHeight()
		task.defer(syncListHeight)
	end

	rebuildList()
	Notification.MarkAllRead()

	popMaid:Give(clearBtn.Activated:Connect(function()
		Notification.ClearHistory()
		rebuildList()
	end))

	self:OpenPopup("NotificationHistory", pop, anchorBtn, function()
		Transition.Unmount(pop, 0.95, function()
			popMaid:Clean()
		end)
	end)
	Transition.Mount(pop, 0.95)
end

-- ─── Categories & Tabs ───────────────────────────────────────────────────────

function Window:AddCategory(name)
	name = tostring(name or "General")
	self._currentCategory = name
	if self._categories[name] then
		return self._categories[name]
	end

	self._categoryCount += 1
	local slotBase = self._categoryCount * 1000
	local header = Tab.CategoryHeader(self._tabScroll, name, slotBase)
	header:SetCompact(self._sidebarCollapsed, true)

	local record = {
		Name = name,
		SlotBase = slotBase,
		Count = 0,
		Header = header,
	}
	self._categories[name] = record
	return record
end

function Window:AddTab(options)
	options = Util.Options(options, { Title = "Tab", Category = nil }, "Title")
	local categoryName = options.Category or self._currentCategory

	local layoutOrder
	if categoryName and categoryName ~= "" then
		local cat = self:AddCategory(categoryName)
		cat.Count += 1
		layoutOrder = cat.SlotBase + cat.Count
		options.Category = categoryName
	else
		self._uncategorizedOrder += 1
		layoutOrder = self._uncategorizedOrder
	end
	options.LayoutOrder = layoutOrder

	local tab = Tab.new(self, options)
	table.insert(self.Tabs, tab)
	self.Maid:Give(tab)

	if #self.Tabs == 1 then
		self:SelectTab(tab, true)
	end
	return tab
end

function Window:SelectTab(tab, instant)
	if self._destroyed or self._unloading then
		return nil
	end
	if type(tab) == "string" then
		for _, candidate in ipairs(self.Tabs) do
			if candidate.Title == tab then
				tab = candidate
				break
			end
		end
	elseif type(tab) == "number" then
		tab = self.Tabs[tab]
	end
	if type(tab) ~= "table" or not tab.Page then
		return nil
	end

	local effectiveInstant = instant == true or (not self._visible) or self._morphing
	if self.ActiveTab == tab and not effectiveInstant then
		return tab
	end

	self:ClosePopup()
	for _, candidate in ipairs(self.Tabs) do
		candidate:_setActiveVisual(candidate == tab, effectiveInstant)
	end
	self.ActiveTab = tab
	self:_updateBreadcrumb()
	return tab
end

function Window:_updateBreadcrumb()
	local parts = {}
	local tab = self.ActiveTab
	if tab then
		if tab.Category and tab.Category ~= "" then
			table.insert(parts, tab.Category)
		end
		table.insert(parts, tab.Title)
		if tab.ActiveSubTab and tab.ActiveSubTab.Title then
			table.insert(parts, tab.ActiveSubTab.Title)
		end
	else
		table.insert(parts, self.Title)
	end

	if #parts <= 1 then
		self._breadcrumbLabel.Text = parts[1] or self.Title
		return
	end

	local formatted = {}
	for index, part in ipairs(parts) do
		local safe = tostring(part):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
		if index == #parts then
			table.insert(formatted, "<b>" .. safe .. "</b>")
		else
			table.insert(formatted, safe)
		end
	end
	self._breadcrumbLabel.Text = table.concat(formatted, "  /  ")
end

-- ─── Window Controls & APIs ──────────────────────────────────────────────────

function Window:GetWidth()
	if self.MainWrapper and self.MainWrapper.AbsoluteSize.X > 0 then
		return self.MainWrapper.AbsoluteSize.X
	end
	return self.MainWrapper and self.MainWrapper.Size.X.Offset or 820
end

function Window:ToggleSidebar(collapsed)
	if collapsed == nil then
		collapsed = not self._sidebarCollapsed
	else
		collapsed = collapsed == true
	end
	if self._sidebarCollapsed == collapsed then
		return
	end
	self._sidebarCollapsed = collapsed

	local targetW = collapsed and SIDEBAR_COLLAPSED or self._sidebarExpandedWidth

	self._brandText.Visible = not collapsed
	self._collapseBtn.Visible = not collapsed
	local brandBadgeFrame = (self._brandLogoIcon and self._brandLogoIcon.Parent)
		or (self._brandExpandIcon and self._brandExpandIcon.Parent)
	local collapsedFlag = brandBadgeFrame and brandBadgeFrame:FindFirstChild("_BrandCollapsedFlag")
	if collapsedFlag then
		collapsedFlag.Visible = collapsed
	end
	if self._brandLogoIcon then
		self._brandLogoIcon.Visible = true
	end
	if self._brandExpandIcon then
		self._brandExpandIcon.Visible = false
	end
	if self._syncBrandBadge then
		task.defer(function()
			if not self._destroyed then
				self._syncBrandBadge(Theme.Current, true)
			end
		end)
	end
	if self._expandBtn then
		self._expandBtn.Visible = collapsed
	end
	if self._searchPill then
		self._searchPill.Visible = true
	end
	if self._searchIcon then
		self._searchIcon.AnchorPoint = collapsed and Vector2.new(0.5, 0.5) or Vector2.new(0, 0.5)
		self._searchIcon.Position = collapsed and UDim2.fromScale(0.5, 0.5) or UDim2.new(0, 12, 0.5, 0)
	end
	self._searchPlaceholder.Visible = not collapsed
	self._shortcutChip.Visible = not collapsed
	if self._welcomeCard then
		self._welcomeCard.Visible = not collapsed
	end
	self._breadcrumbLabel.Size = UDim2.new(1, -26, 0, 20)

	for _, cat in pairs(self._categories) do
		if cat.Header then
			cat.Header:SetCompact(collapsed, false)
		end
	end
	for _, tab in ipairs(self.Tabs) do
		tab:SetCompact(collapsed, false)
	end

	Tween.Play(self.Sidebar, { Size = UDim2.new(0, targetW, 1, 0) }, Tween.Normal)
	if self._sidebarBg then
		Tween.Play(self._sidebarBg, { Size = UDim2.new(0, targetW, 1, 0) }, Tween.Normal)
	end
	Tween.Play(self.BodyArea, {
		Position = UDim2.new(0, targetW, 0, 0),
		Size = UDim2.new(1, -targetW, 1, 0),
	}, Tween.Normal)
	if not Config.IsLoading() then
		Config.TriggerAutoSave()
	end
end

function Window:_setAmbientChromeVisible(show)
	if self._glowTopLeft then
		self._glowTopLeft.Visible = show
	end
	if self._glowBottomRight then
		self._glowBottomRight.Visible = show
	end
	if self._noiseLayer then
		self._noiseLayer.Visible = show
	end
	if self._resizeGrip then
		self._resizeGrip.Visible = show
	end
end

function Window:SetVisible(visible)
	visible = visible == true
	if self._destroyed or self._unloading or self._visible == visible then
		return
	end
	self._visible = visible
	self._visSeq = (self._visSeq or 0) + 1
	local seq = self._visSeq

	Blur.SetOpen(visible)

	local wrapper = self.MainWrapper

	if self._mobileButton then
		self._mobileButton:UpdateVisibility()
	end

	if not visible then
		self:ClosePopup()
		CommandPalette.Close()
		if self.ActiveTab then
			Transition.RestoreCascade(self.ActiveTab.Page)
			local activeScroll = self.ActiveTab.ActiveSubTab and self.ActiveTab.ActiveSubTab.Scroll or (self.ActiveTab._defaultFlow and self.ActiveTab._defaultFlow.Scroll)
			if activeScroll then
				Transition.RestoreCascade(activeScroll)
			end
		end

		if not self._morphing then
			self._restorePos = wrapper.Position
			self._restoreSize = wrapper.Size
		end

		if not Tween.Reduced then
			self._morphing = true
			local morphDur = 0.22
			local restorePos = self._restorePos or wrapper.Position
			local restoreSize = self._restoreSize or wrapper.Size
			local targetPos = UDim2.new(
				restorePos.X.Scale,
				restorePos.X.Offset,
				restorePos.Y.Scale,
				restorePos.Y.Offset + 10
			)

			wrapper.Size = restoreSize
			self.Sidebar.Visible = true
			self.BodyArea.Visible = true
			self:_setAmbientChromeVisible(true)

			Tween.Play(
				wrapper,
				{ Position = targetPos },
				morphDur,
				Enum.EasingStyle.Quint,
				Enum.EasingDirection.Out
			)
			Transition.Unmount(wrapper, 1, function()
				if self._visSeq ~= seq or self._visible or not wrapper.Parent then
					return
				end
				wrapper.Visible = false
				wrapper.ZIndex = 2
				wrapper.Position = restorePos
				wrapper.Size = restoreSize
				self.Sidebar.Visible = true
				self.BodyArea.Visible = true
				self:_setAmbientChromeVisible(true)
				self._morphing = false
			end, { NoPositionTween = true, Duration = morphDur })
			return
		end

		Transition.Unmount(wrapper, 0.95, function()
			if not self._visible and wrapper and wrapper.Parent then
				wrapper.Visible = false
			end
		end)
	else
		if not Tween.Reduced then
			self._morphing = true
			local morphDur = 0.22
			local restorePos = self._restorePos or wrapper.Position
			local restoreSize = self._restoreSize or wrapper.Size
			local startPos = UDim2.new(
				restorePos.X.Scale,
				restorePos.X.Offset,
				restorePos.Y.Scale,
				restorePos.Y.Offset + 10
			)

			wrapper.Position = startPos
			wrapper.Size = restoreSize
			self.Sidebar.Visible = true
			self.BodyArea.Visible = true
			self:_setAmbientChromeVisible(true)
			wrapper.ZIndex = 2
			wrapper.Visible = true

			local restoreTw = Tween.Play(
				wrapper,
				{ Position = restorePos },
				morphDur,
				Enum.EasingStyle.Quint,
				Enum.EasingDirection.Out
			)
			Transition.Mount(wrapper, 1, { NoPositionTween = true, Duration = morphDur })

			Tween.Then(restoreTw, function()
				if self._visSeq ~= seq or not self._visible or not wrapper.Parent then
					return
				end
				wrapper.Position = restorePos
				wrapper.Size = restoreSize
				self._morphing = false
			end)
			return
		end

		self.Sidebar.Visible = true
		self.BodyArea.Visible = true
		self:_setAmbientChromeVisible(true)
		wrapper.Visible = true
		Transition.Mount(wrapper, 0.95)
	end
end

function Window:IsVisible()
	return self._visible
end

function Window:Toggle()
	self:SetVisible(not self._visible)
end

function Window:SetToggleKey(key)
	local resolved = Util.ResolveKey(key)
	self._toggleKey = resolved
	if self._toggleKeybind then
		self._toggleKeybind.SetKey(resolved)
	end
	if not Config.IsLoading() then
		Config.TriggerAutoSave()
	end
end

function Window:GetToggleKey()
	return self._toggleKey
end

function Window:IsMobileMode()
	return self._mobileMode == true
end

function Window:SetMobileMode(enabled, silent)
	enabled = enabled == true
	if self._destroyed or self._mobileMode == enabled then
		return
	end
	self._mobileMode = enabled
	if self._mobileButton then
		self._mobileButton:UpdateVisibility()
	end

	local vp = getViewportSize(self.ScreenGui)
	local minVec = self._effectiveMin or Vector2.new(360, 320)
	local curSize = self.MainWrapper.AbsoluteSize
	if curSize.X <= 0 then
		curSize = Vector2.new(self.MainWrapper.Size.X.Offset, self.MainWrapper.Size.Y.Offset)
	end

	local targetW, targetH
	if enabled then
		self:ToggleSidebar(true)
		self:SetMobileButtonEnabled(true)
		targetW = Util.Clamp(math.min(curSize.X, math.max(360, math.min(540, vp.X - 24))), math.min(minVec.X, vp.X - 24), math.max(320, vp.X - 24))
		targetH = Util.Clamp(curSize.Y, math.min(minVec.Y, vp.Y - 24), math.max(280, vp.Y - 24))
	else
		self:ToggleSidebar(false)
		local pref = self._desktopPreferredSize or Vector2.new(820, 540)
		targetW = Util.Clamp(pref.X, math.min(minVec.X, vp.X - 24), math.max(minVec.X, vp.X - 24))
		targetH = Util.Clamp(pref.Y, math.min(minVec.Y, vp.Y - 24), math.max(minVec.Y, vp.Y - 24))
	end

	local newPosX = Util.Clamp(self.MainWrapper.Position.X.Offset, 8, math.max(8, vp.X - targetW - 8))
	local newPosY = Util.Clamp(self.MainWrapper.Position.Y.Offset, 8, math.max(8, vp.Y - targetH - 8))
	local newSizeUDim = UDim2.fromOffset(targetW, targetH)
	local newPosUDim = UDim2.fromOffset(newPosX, newPosY)
	self._restoreSize = newSizeUDim
	self._restorePos = newPosUDim

	if Tween.Reduced or silent then
		self.MainWrapper.Size = newSizeUDim
		self.MainWrapper.Position = newPosUDim
	else
		Tween.Play(self.MainWrapper, { Size = newSizeUDim, Position = newPosUDim }, Tween.Normal, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	end

	local newVec = Vector2.new(targetW, targetH)
	self._layoutChanged:Fire(newVec)
	for _, tab in ipairs(self.Tabs) do
		if type(tab.RefreshLayout) == "function" then
			tab:RefreshLayout(targetW)
		end
	end
	if self.ActiveTab and self.ActiveTab._syncSubTabIndicator then
		task.defer(function()
			if not self._destroyed and self.ActiveTab and self.ActiveTab._syncSubTabIndicator then
				self.ActiveTab:_syncSubTabIndicator(true)
			end
		end)
	end

	if not silent and not Config.IsLoading() then
		Config.TriggerAutoSave()
	end
end

function Window:LoadAutoSave()
	if self._destroyed or not Config.GetAutoSave() then
		return false
	end
	local ok, res = pcall(Config.LoadAutoSave)
	return ok and res == true
end

function Window:SetTitle(title)
	self.Title = tostring(title or "Bali")
	self._brandTitleLabel.Text = self.Title
end

function Window:SetSubtitle(subtitle)
	self.Subtitle = tostring(subtitle or "")
	self._brandSubLabel.Text = self.Subtitle
	self._brandSubLabel.Visible = self.Subtitle ~= ""
end

function Window:SetMobileButtonEnabled(enabled)
	if self._mobileButton then
		self._mobileButton:SetEnabled(enabled == true)
	end
	if not Config.IsLoading() then
		Config.TriggerAutoSave()
	end
end

function Window:Dialog(options)
	return Dialog.Show(self.DialogLayer, options)
end

function Window:Notify(options)
	return Notification.Notify(options)
end

function Window:BuildSettingsTab(options)
	local SettingsTab = require("Builders/SettingsTab")
	return SettingsTab.Build(self, options)
end

function Window:Unload()
	return self:Destroy(false)
end

function Window:Destroy(instant)
	if self._destroyed then
		return
	end
	local wrapper = self.MainWrapper
	if not instant and not self._unloading and not Tween.Reduced and self._visible and wrapper and wrapper.Parent then
		self._unloading = true
		self:ClosePopup()
		CommandPalette.Close()
		Tooltip.Hide()
		Blur.SetOpen(false)
		if self._mobileButton and self._mobileButton.Destroy then
			pcall(function()
				self._mobileButton:Destroy()
			end)
		end
		local startPos = wrapper.Position
		local exitPos = UDim2.new(
			startPos.X.Scale,
			startPos.X.Offset,
			startPos.Y.Scale,
			startPos.Y.Offset + 10
		)
		Tween.Play(wrapper, { Position = exitPos }, 0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
		Transition.Unmount(wrapper, 1, function()
			self:Destroy(true)
		end, { NoPositionTween = true, Duration = 0.22 })
		return
	end
	self._unloading = false
	self._destroyed = true

	if type(self._onDestroy) == "function" then
		Util.SafeCall(self._onDestroy)
	end

	CommandPalette.Destroy()
	KeybindList.Destroy()
	Watermark.Destroy()
	Notification.Destroy()
	Tooltip.Destroy()
	Blur.Destroy()
	Input.Destroy()

	self.Maid:Clean()
	table.clear(self.Tabs)
	table.clear(self._elements)
	table.clear(self._registry)

	if self._ownsScreenGui and self.ScreenGui and self.ScreenGui.Parent then
		self.ScreenGui:Destroy()
	end
end

return Window
end

__modules["Builders/SettingsTab"] = function()
--[[
	Bali UI · Builders/SettingsTab
	Builds a comprehensive "Settings" tab (Category "System") covering Appearance,
	Interface & HUD, Config Manager, and Session & Diagnostics.
]]

local Assets = require("Core/Assets")
local Theme = require("Core/Theme")
local Tween = require("Core/Tween")
local Util = require("Core/Util")
local Blur = require("Systems/Blur")
local Config = require("Systems/Config")
local KeybindList = require("Systems/KeybindList")
local Notification = require("Systems/Notification")
local Watermark = require("Systems/Watermark")

local SettingsTab = {}

function SettingsTab.Build(window, options)
	assert(type(window) == "table", "[Bali] SettingsTab.Build expects a Window")
	options = Util.Options(options, {
		Title = "Settings",
		Icon = "settings",
		Category = "System",
	}, "Title")

	local tab = window:AddTab({
		Title = options.Title,
		Icon = options.Icon,
		Category = options.Category,
	})
	tab._isSettingsTab = true

	-- ─── Appearance (Left) ───────────────────────────────────────────────────
	local appearance = tab:AddSection({
		Title = "Appearance",
		Subtitle = "Themes, accents, glass opacity, and motion.",
		Icon = "palette",
		Side = "Left",
	})

	local syncingTheme = false
	local themeDropdown = appearance:AddDropdown({
		Title = "Theme Preset",
		Description = "Choose a built-in obsidian or light theme.",
		Icon = "palette",
		Values = Theme.Order,
		Default = Theme.Name,
		Callback = function(value)
			if syncingTheme or not value then
				return
			end
			Theme.Set(value, true)
		end,
	})

	local accentPicker = appearance:AddColorPicker({
		Title = "Accent Color",
		Description = "Override primary highlights, active pills, and gradients.",
		Icon = "sparkles",
		Default = Theme.Current.Accent,
		Presets = {
			Color3.fromRGB(214, 64, 236),
			Color3.fromRGB(59, 130, 246),
			Color3.fromRGB(45, 212, 191),
			Color3.fromRGB(52, 211, 153),
			Color3.fromRGB(251, 113, 133),
			Color3.fromRGB(251, 191, 36),
		},
		Callback = function(color)
			if syncingTheme or typeof(color) ~= "Color3" then
				return
			end
			Theme.SetAccent(color, true)
		end,
	})

	local fontDropdown = appearance:AddDropdown({
		Title = "Font Family",
		Description = "Live typography across headers, labels, and controls.",
		Icon = "type",
		Values = Theme.FontOrder,
		Default = Theme.FontFamily,
		Callback = function(value)
			if syncingTheme or not value then
				return
			end
			Theme.SetFont(value)
		end,
	})

	local transparencySlider = appearance:AddSlider({
		Title = "Window Transparency",
		Description = "Adjust obsidian glass surface opacity.",
		Icon = "eye",
		Min = 0,
		Max = 0.45,
		Step = 0.01,
		Default = Theme.Current.BackgroundTransparency,
		Callback = function(value)
			if syncingTheme then
				return
			end
			Theme.SetValue("BackgroundTransparency", value, false)
		end,
	})

	local blurToggle = appearance:AddToggle({
		Title = "Background Blur",
		Description = "Softly blurs the 3D scene behind the window.",
		Icon = "droplet",
		Default = Blur.IsEnabled(),
		Callback = function(state)
			Blur.SetEnabled(state)
			if not syncingTheme and not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local blurSlider = appearance:AddSlider({
		Title = "Blur Intensity",
		Icon = "sliders",
		Min = 2,
		Max = 28,
		Step = 1,
		Default = Blur.GetIntensity(),
		Callback = function(value)
			Blur.SetIntensity(value)
			if not syncingTheme and not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local reduceMotionToggle = appearance:AddToggle({
		Title = "Reduce Motion",
		Description = "Use instant transitions across popups and panels.",
		Icon = "zap",
		Default = Tween.Reduced,
		Callback = function(state)
			Tween.Reduced = state == true
			if not syncingTheme and not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local speedSlider = appearance:AddSlider({
		Title = "Animation Speed",
		Icon = "gauge",
		Min = 0.25,
		Max = 2.0,
		Step = 0.05,
		Suffix = "x",
		Default = Tween.Speed,
		Callback = function(value)
			Tween.Speed = value
			if not syncingTheme and not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	tab.Maid:Give(Theme.Changed:Connect(function(theme)
		syncingTheme = true
		pcall(function()
			if themeDropdown and themeDropdown.Set then
				themeDropdown:Set(Theme.Name, true)
			end
			if accentPicker and accentPicker.Set then
				accentPicker:Set(theme.Accent, nil, true)
			end
			if fontDropdown and fontDropdown.Set then
				fontDropdown:Set(Theme.FontFamily, true)
			end
			if transparencySlider and transparencySlider.Set then
				transparencySlider:Set(theme.BackgroundTransparency, true)
			end
		end)
		syncingTheme = false
	end))

	-- ─── Interface & HUD (Right) ─────────────────────────────────────────────
	local hud = tab:AddSection({
		Title = "Interface & HUD",
		Subtitle = "Menu keybind, floating HUDs, and toast corner.",
		Icon = "monitor",
		Side = "Right",
	})

	local toggleKeybind = hud:AddKeybind({
		Title = "Toggle UI Keybind",
		Description = "Show or hide the main workspace window.",
		Icon = "keyboard",
		Default = window:GetToggleKey(),
		AllowMouse = false,
		SyncList = false,
		ChangedCallback = function(key)
			if syncingTheme then
				return
			end
			window:SetToggleKey(key)
		end,
	})

	local watermarkToggle = hud:AddToggle({
		Title = "Watermark HUD",
		Description = "Floating telemetry pill with FPS, ping, and clock.",
		Icon = "activity",
		Default = Watermark.IsVisible(),
		Callback = function(state)
			if syncingTheme then
				return
			end
			Watermark.SetVisible(state)
			if not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local keybindListToggle = hud:AddToggle({
		Title = "Keybind List HUD",
		Description = "Floating panel displaying active keybinds.",
		Icon = "list",
		Default = KeybindList.IsVisible(),
		Callback = function(state)
			if syncingTheme then
				return
			end
			KeybindList.SetVisible(state)
			if not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local keybindModeSeg = hud:AddSegmented({
		Title = "Keybind List Mode",
		Description = "Filter floating keybind overlay to active or all binds.",
		Icon = "sliders",
		Values = {
			{ Title = "Active Only", Value = "ActiveOnly" },
			{ Title = "All", Value = "All" },
		},
		Default = window._keybindListMode or "ActiveOnly",
		Callback = function(mode)
			if syncingTheme then
				return
			end
			window._keybindListMode = mode
			KeybindList.SetMode(mode)
			if not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local notifDropdown = hud:AddDropdown({
		Title = "Notification Position",
		Icon = "bell",
		Values = {
			{ Title = "Bottom Right", Value = "BottomRight" },
			{ Title = "Top Right", Value = "TopRight" },
			{ Title = "Bottom Left", Value = "BottomLeft" },
			{ Title = "Top Left", Value = "TopLeft" },
		},
		Default = window._notificationPosition or "BottomRight",
		Callback = function(pos)
			if syncingTheme then
				return
			end
			window._notificationPosition = pos
			Notification.SetPosition(pos)
			if not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local notifDurationSlider = hud:AddSlider({
		Title = "Notification Duration",
		Description = "Default toast visibility window before auto-dismiss.",
		Icon = "clock",
		Min = 1,
		Max = 15,
		Step = 0.5,
		Rounding = 1,
		Suffix = "s",
		Default = Notification.GetDefaultDuration(),
		Callback = function(val)
			if syncingTheme then
				return
			end
			Notification.SetDefaultDuration(val)
			if not Config.IsLoading() then
				Config.TriggerAutoSave()
			end
		end,
	})

	local defaultMobileBtn = true
	if window._mobileButton then
		defaultMobileBtn = window._mobileButton:IsEnabled()
	end
	local mobileBtnToggle = hud:AddToggle({
		Title = "Mobile Floating Button",
		Description = "Show draggable pill when minimized or on touch devices.",
		Icon = "layers",
		Default = defaultMobileBtn,
		Callback = function(state)
			if syncingTheme then
				return
			end
			window:SetMobileButtonEnabled(state)
		end,
	})

	local mobileModeToggle = hud:AddToggle({
		Title = "Mobile Compact Mode",
		Description = "Single-column stacked layout with compact sidebar and padding.",
		Icon = "smartphone",
		Default = window.IsMobileMode and window:IsMobileMode() or false,
		Callback = function(state)
			if syncingTheme then
				return
			end
			if window.SetMobileMode then
				window:SetMobileMode(state)
			end
		end,
	})

	-- ─── Config Manager (Right) ──────────────────────────────────────────────
	local configSection = tab:AddSection({
		Title = "Config Manager",
		Subtitle = "Save, load, and share workspace presets.",
		Icon = "folder",
		Side = "Right",
	})

	local autoSaveToggle = configSection:AddToggle({
		Title = "Auto-Save Workspace",
		Description = "Automatically save & restore all control states without creating profiles.",
		Icon = "save",
		Default = Config.GetAutoSave(),
		Callback = function(state)
			if syncingTheme then
				return
			end
			Config.SetAutoSave(state)
		end,
	})

	local folderName = window._configFolder or "Bali"
	configSection:AddLabel({
		Title = "Config Folder",
		Value = folderName,
		Icon = "folder-open",
	})

	local profileInput = configSection:AddInput({
		Title = "Profile Name",
		Icon = "pencil",
		Placeholder = "e.g. default, legit...",
		Clearable = true,
	})

	local initialProfiles = {}
	pcall(function()
		initialProfiles = Config.List() or {}
	end)

	local profileDropdown = configSection:AddDropdown({
		Title = "Saved Profiles",
		Icon = "folder",
		Values = initialProfiles,
		AllowNull = true,
	})

	local autoLoadLabel = configSection:AddLabel({
		Title = "Auto-Load Profile",
		Value = (function()
			local ok, name = pcall(Config.GetAutoLoad)
			return (ok and name and name ~= "") and tostring(name) or "None"
		end)(),
		Icon = "sparkles",
	})

	local function resolveProfileName()
		local typed = Util.Trim(profileInput:Get() or "")
		if typed ~= "" then
			return typed
		end
		local selected = profileDropdown:Get()
		if type(selected) == "string" and selected ~= "" then
			return selected
		end
		return ""
	end

	local function refreshProfiles()
		local ok, list = pcall(Config.List)
		local profiles = (ok and type(list) == "table") and list or {}
		if profileDropdown.SetValues then
			profileDropdown:SetValues(profiles)
		elseif profileDropdown.Refresh then
			profileDropdown:Refresh(profiles)
		end
		local okAuto, autoName = pcall(Config.GetAutoLoad)
		if autoLoadLabel and autoLoadLabel.SetValue then
			autoLoadLabel:SetValue((okAuto and autoName and autoName ~= "") and tostring(autoName) or "None")
		end
	end

	local function syncSettingsVisuals()
		syncingTheme = true
		pcall(function()
			themeDropdown:Set(Theme.Name, true)
			accentPicker:Set(Theme.Current.Accent, nil, true)
			fontDropdown:Set(Theme.FontFamily, true)
			transparencySlider:Set(Theme.Current.BackgroundTransparency, true)
			blurToggle:Set(Blur.IsEnabled(), true)
			blurSlider:Set(Blur.GetIntensity(), true)
			reduceMotionToggle:Set(Tween.Reduced, true)
			speedSlider:Set(Tween.Speed, true)
			toggleKeybind:Set(window:GetToggleKey(), "Toggle", true)
			watermarkToggle:Set(Watermark.IsVisible(), true)
			keybindListToggle:Set(KeybindList.IsVisible(), true)
			keybindModeSeg:Set(window._keybindListMode or "ActiveOnly", true)
			notifDropdown:Set(window._notificationPosition or "BottomRight", true)
			notifDurationSlider:Set(Notification.GetDefaultDuration(), true)
			if window._mobileButton then
				mobileBtnToggle:Set(window._mobileButton:IsEnabled(), true)
			end
			if window.IsMobileMode then
				mobileModeToggle:Set(window:IsMobileMode(), true)
			end
			autoSaveToggle:Set(Config.GetAutoSave(), true)
		end)
		syncingTheme = false
	end

	if window._configLoaded then
		tab.Maid:Give(window._configLoaded:Connect(syncSettingsVisuals))
	end

	configSection:AddButtonGroup({
		Buttons = {
			{
				Title = "Save",
				Icon = "save",
				Variant = "Primary",
				Callback = function()
					local name = resolveProfileName()
					if name == "" then
						window:Notify({ Title = "Config", Content = "Enter or select a profile name.", Type = "Warning" })
						return
					end
					local ok = Config.Save(name)
					refreshProfiles()
					profileDropdown:Set(name, true)
					window:Notify({
						Title = ok and "Config Saved" or "Save Failed",
						Content = ok and ("Saved profile '" .. name .. "'.") or "File system is unavailable.",
						Type = ok and "Success" or "Error",
					})
				end,
			},
			{
				Title = "Load",
				Icon = "upload",
				Variant = "Default",
				Callback = function()
					local name = resolveProfileName()
					if name == "" then
						window:Notify({ Title = "Config", Content = "Select a profile to load.", Type = "Warning" })
						return
					end
					local ok = Config.Load(name)
					syncSettingsVisuals()
					window:Notify({
						Title = ok and "Config Loaded" or "Load Failed",
						Content = ok and ("Loaded profile '" .. name .. "'.") or ("Could not load '" .. name .. "'."),
						Type = ok and "Success" or "Error",
					})
				end,
			},
			{
				Title = "Delete",
				Icon = "trash",
				Variant = "Danger",
				Callback = function()
					local name = resolveProfileName()
					if name == "" then
						window:Notify({ Title = "Config", Content = "Select a profile to delete.", Type = "Warning" })
						return
					end
					local ok = Config.Delete(name)
					refreshProfiles()
					window:Notify({
						Title = ok and "Config Deleted" or "Delete Failed",
						Content = ok and ("Removed profile '" .. name .. "'.") or ("Could not delete '" .. name .. "'."),
						Type = ok and "Info" or "Error",
					})
				end,
			},
		},
	})

	configSection:AddButtonGroup({
		Buttons = {
			{
				Title = "Refresh",
				Icon = "refresh",
				Variant = "Default",
				Callback = function()
					refreshProfiles()
					window:Notify({ Title = "Config", Content = "Profile list refreshed.", Type = "Info", Duration = 2.5 })
				end,
			},
			{
				Title = "Set Auto-Load",
				Icon = "badge-check",
				Variant = "Default",
				Callback = function()
					local name = resolveProfileName()
					Config.SetAutoLoad(name ~= "" and name or nil)
					refreshProfiles()
					window:Notify({
						Title = "Auto-Load Updated",
						Content = name ~= "" and ("Auto-load set to '" .. name .. "'.") or "Auto-load cleared.",
						Type = "Success",
					})
				end,
			},
		},
	})

	local jsonInput = configSection:AddInput({
		Title = "JSON Import / Export",
		Icon = "code",
		Placeholder = "Paste exported JSON payload...",
		Clearable = true,
	})

	configSection:AddButtonGroup({
		Buttons = {
			{
				Title = "Export JSON",
				Icon = "copy",
				Variant = "Default",
				Callback = function()
					local ok, payload = pcall(Config.Export, true)
					if ok and type(payload) == "string" then
						jsonInput:Set(payload, true)
						local copied = Util.SetClipboard(payload)
						window:Notify({
							Title = "Config Exported",
							Content = copied and "JSON copied to clipboard." or "JSON placed into the input field.",
							Type = "Success",
						})
					else
						window:Notify({ Title = "Export Failed", Content = "Unable to serialize config.", Type = "Error" })
					end
				end,
			},
			{
				Title = "Import JSON",
				Icon = "download",
				Variant = "Primary",
				Callback = function()
					local payload = Util.Trim(jsonInput:Get() or "")
					if payload == "" then
						window:Notify({ Title = "Import Failed", Content = "Paste JSON into the field first.", Type = "Warning" })
						return
					end
					local ok, result = pcall(Config.Import, payload)
					if ok and result then
						syncSettingsVisuals()
						window:Notify({ Title = "Config Imported", Content = "Workspace values restored.", Type = "Success" })
					else
						window:Notify({ Title = "Import Failed", Content = "Invalid or malformed JSON.", Type = "Error" })
					end
				end,
			},
		},
	})

	-- ─── Session & Diagnostics (Left) ────────────────────────────────────────
	local session = tab:AddSection({
		Title = "Session & Diagnostics",
		Subtitle = "Runtime status, asset pipeline, and cleanup.",
		Icon = "cpu",
		Side = "Left",
	})

	local versionText = "v1.0.0 (Atlas v" .. tostring(Assets.Data and Assets.Data.Version or "4") .. ")"
	local assetStatus = Assets.Available and "Custom Atlas Loaded" or "Glyph Fallback"
	local fsStatus = Util.FS.Supported() and "Supported" or "In-Memory Only"
	local deviceKind = Util.IsTouchDevice() and "Touch / Mobile" or "Desktop"

	local diagLabel = session:AddParagraph({
		Title = "Bali Runtime",
		Content = string.format(
			"Library %s  •  Assets: %s\nFile System: %s  •  Input: %s\nRegistered Elements: %d  •  Flags: %d",
			versionText,
			assetStatus,
			fsStatus,
			deviceKind,
			#window._elements,
			Util.Count(window._registry)
		),
	})

	session:AddButtonGroup({
		Buttons = {
			{
				Title = "Refresh Stats",
				Icon = "activity",
				Variant = "Default",
				Callback = function()
					if diagLabel and diagLabel.SetDesc then
						diagLabel:SetDesc(string.format(
							"Library %s  •  Assets: %s\nFile System: %s  •  Input: %s\nRegistered Elements: %d  •  Flags: %d",
							versionText,
							assetStatus,
							fsStatus,
							deviceKind,
							#window._elements,
							Util.Count(window._registry)
						))
					end
				end,
			},
			{
				Title = "Unload UI",
				Icon = "power",
				Variant = "Danger",
				Callback = function()
					window:Dialog({
						Title = "Unload Bali UI?",
						Content = "This permanently destroys all windows, keybinds, HUD elements, and lighting blur.",
						Icon = "power",
						Buttons = {
							{ Title = "Cancel", Variant = "Default" },
							{
								Title = "Unload",
								Variant = "Danger",
								Callback = function()
									window:Destroy()
								end,
							},
						},
					})
				end,
			},
		},
	})

	return tab
end

return SettingsTab
end

__modules["Bali"] = function()
--[[
	Bali UI · Entry Point
	Obsidian glassmorphic UI suite for Roblox & Luau.
]]

local Assets = require("Core/Assets")
local Create = require("Core/Create")
local Icons = require("Core/Icons")
local Maid = require("Core/Maid")
local Services = require("Core/Services")
local Signal = require("Core/Signal")
local Theme = require("Core/Theme")
local Transition = require("Core/Transition")
local Tween = require("Core/Tween")
local Util = require("Core/Util")

local Blur = require("Systems/Blur")
local CommandPalette = require("Systems/CommandPalette")
local Config = require("Systems/Config")
local Input = require("Systems/Input")
local KeybindList = require("Systems/KeybindList")
local Notification = require("Systems/Notification")
local Tooltip = require("Systems/Tooltip")
local Watermark = require("Systems/Watermark")

local Dialog = require("Window/Dialog")
local Loader = require("Window/Loader")
local Window = require("Window/Window")

-- Clean up any previously loaded Bali (or legacy Lumina) instance on script re-execution
for _, key in ipairs({ "_BaliInstance", "_LuminaInstance" }) do
	local previousInstance = Util.Global(key)
	if type(previousInstance) == "table" and type(previousInstance.Destroy) == "function" then
		pcall(function()
			previousInstance:Destroy()
		end)
	end
end

local Bali = {
	Version = "1.0.0",

	-- Core modules
	Services = Services,
	Util = Util,
	Signal = Signal,
	Maid = Maid,
	Tween = Tween,
	Transition = Transition,
	Theme = Theme,
	Create = Create,
	Assets = Assets,
	Icons = Icons,

	-- Systems
	Input = Input,
	Tooltip = Tooltip,
	Notification = Notification,
	Blur = Blur,
	Watermark = Watermark,
	KeybindList = KeybindList,
	CommandPalette = CommandPalette,
	Config = Config,

	-- Window / Modal helpers
	Dialog = Dialog,
	Loader = Loader,
	Window = Window,

	Core = {
		Services = Services,
		Util = Util,
		Signal = Signal,
		Maid = Maid,
		Tween = Tween,
		Transition = Transition,
		Theme = Theme,
		Create = Create,
		Assets = Assets,
		Icons = Icons,
	},
	Systems = {
		Input = Input,
		Tooltip = Tooltip,
		Notification = Notification,
		Blur = Blur,
		Watermark = Watermark,
		KeybindList = KeybindList,
		CommandPalette = CommandPalette,
		Config = Config,
	},

	_maid = Maid.new(),
	_windows = {},
	_loaders = {},
	_screenGui = nil,
	_ownsScreenGui = true,
	_notifyLayer = nil,
	_notifyReady = false,
	_destroyed = false,
	_destroying = false,
	StealthMode = true,
}

if type(Util.Env) == "table" then
	Util.Env._BaliInstance = Bali
end

-- ─── Error Boundary & Safe Layer Helpers ─────────────────────────────────────

local handlingError = false
local lastErrorText = nil
local lastErrorAt = 0

local function handleRuntimeError(err)
	if handlingError or Bali._destroyed then
		return
	end
	handlingError = true

	local message = tostring(err or "Unknown callback error")
	local now = os.clock()
	if message == lastErrorText and (now - lastErrorAt) < 1.2 then
		handlingError = false
		return
	end
	lastErrorText = message
	lastErrorAt = now

	pcall(function()
		Bali:Notify({
			Type = "Error",
			Title = "Callback Error",
			Content = message,
			Duration = 5,
		})
	end)

	handlingError = false
end

Util.ErrorHandler = handleRuntimeError

local function getGuiContainers()
	local containers = {}
	local seen = {}
	local function pushContainer(inst)
		local safe = Util.CloneRef(inst)
		if typeof(safe) == "Instance" and not seen[safe] then
			seen[safe] = true
			table.insert(containers, safe)
		end
	end

	if typeof(gethui) == "function" then
		local ok, hui = pcall(gethui)
		if ok then
			pushContainer(hui)
		end
	end

	local okCore, coreGui = pcall(function()
		return Services.CoreGui
	end)
	if okCore and typeof(coreGui) == "Instance" then
		pushContainer(coreGui)
	end

	local okPlayer, localPlayer = pcall(function()
		return Services.Players.LocalPlayer
	end)
	if okPlayer and localPlayer then
		local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui", 5)
		pushContainer(playerGui)
	end

	return containers
end

local function cleanupOrphanGuis(excludeGui)
	local prevStealthGui = Util.Global("_BaliScreenGui")
	if typeof(prevStealthGui) == "Instance" and prevStealthGui ~= excludeGui then
		pcall(function()
			prevStealthGui:Destroy()
		end)
		if type(Util.Env) == "table" then
			Util.Env._BaliScreenGui = nil
		end
	end

	for _, container in ipairs(getGuiContainers()) do
		pcall(function()
			for _, child in ipairs(container:GetChildren()) do
				if child ~= excludeGui and child:IsA("LayerCollector") then
					if child.Name == "BaliUI" or child.Name == "LuminaUI" then
						child:Destroy()
					end
				end
			end
		end)
	end

	local prevBlur = Util.Global("_BaliBlurEffect")
	if typeof(prevBlur) == "Instance" then
		pcall(function()
			prevBlur:Destroy()
		end)
		if type(Util.Env) == "table" then
			Util.Env._BaliBlurEffect = nil
		end
	end

	pcall(function()
		local lighting = Services.Lighting
		if lighting then
			for _, name in ipairs({ "BaliBlur", "LuminaBlur" }) do
				local fx = lighting:FindFirstChild(name)
				if fx then
					fx:Destroy()
				end
			end
		end
	end)
end

cleanupOrphanGuis(nil)

function Bali:_ensureScreenGui()
	if self._screenGui and self._screenGui.Parent then
		return self._screenGui
	end

	cleanupOrphanGuis(nil)

	local containers = getGuiContainers()
	assert(#containers > 0, "[Bali] Unable to locate gethui, CoreGui, or PlayerGui")

	local gui = Instance.new("ScreenGui")
	gui.Name = self.StealthMode and Util.RandomString(10) or "BaliUI"
	gui.IgnoreGuiInset = true
	gui.ResetOnSpawn = false
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.DisplayOrder = 100

	Util.ProtectGui(gui)

	for _, candidate in ipairs(containers) do
		local okParent = pcall(function()
			gui.Parent = candidate
		end)
		if okParent and gui.Parent then
			break
		end
	end

	assert(gui.Parent ~= nil, "[Bali] Unable to parent ScreenGui into gethui, CoreGui, or PlayerGui")

	if type(Util.Env) == "table" then
		Util.Env._BaliScreenGui = gui
	end

	self._screenGui = gui
	self._ownsScreenGui = true
	return gui
end

function Bali:_pruneLoaders()
	for index = #self._loaders, 1, -1 do
		local ctrl = self._loaders[index]
		if type(ctrl) ~= "table" or (ctrl.Frame ~= nil and not ctrl.Frame.Parent) then
			table.remove(self._loaders, index)
		end
	end
end

function Bali:_destroyNotifyLayer()
	if self._notifyLayer then
		pcall(function()
			self._notifyLayer:Destroy()
		end)
		self._notifyLayer = nil
	end
end

function Bali:_rearmState()
	self._destroyed = false
	Util.ErrorHandler = handleRuntimeError
	if type(Util.Env) == "table" then
		Util.Env._BaliInstance = self
	end
end

-- ─── Public API ──────────────────────────────────────────────────────────────

function Bali:CreateWindow(opts)
	self:_rearmState()

	local options = {}
	if type(opts) == "string" then
		options.Title = opts
	elseif type(opts) == "table" then
		for key, value in pairs(opts) do
			options[key] = value
		end
	end

	pcall(Assets.Load)
	Input.Init()

	if type(options.KeySystem) == "table" and options.KeySystem.Enabled ~= false then
		local ksOpts = {}
		for k, v in pairs(options.KeySystem) do
			ksOpts[k] = v
		end
		ksOpts.Title = ksOpts.Title or options.Title or "Bali"
		if ksOpts.Yield == nil then
			ksOpts.Yield = true
		end
		local verified = self:KeySystem(ksOpts)
		if ksOpts.Yield and not verified then
			return nil
		end
	end

	local customGui = options.ScreenGui
	local screenGui = (typeof(customGui) == "Instance" and customGui) or self:_ensureScreenGui()
	options.ScreenGui = nil
	options.OwnsScreenGui = false

	local userOnDestroy = options.OnDestroy
	local createdWindow
	options.OnDestroy = function()
		for i = #self._windows, 1, -1 do
			if self._windows[i] == createdWindow then
				table.remove(self._windows, i)
			end
		end

		if type(userOnDestroy) == "function" then
			Util.SafeCall(userOnDestroy)
		end

		if #self._windows == 0 then
			self._notifyReady = false
			self:_pruneLoaders()
			if not self._destroying and #self._loaders == 0 and self._ownsScreenGui and self._screenGui then
				pcall(function()
					self._screenGui:Destroy()
				end)
				self._screenGui = nil
			end
		else
			-- Keep error boundary active while other windows remain open
			Util.ErrorHandler = handleRuntimeError
		end
	end

	createdWindow = Window.new(screenGui, options)
	-- Clean up now-empty pre-window host after Window migrated NotificationLayer
	self:_destroyNotifyLayer()
	table.insert(self._windows, createdWindow)
	self._notifyReady = true

	-- Use Bali's debounced, recursion-safe ErrorHandler on top of the active Window
	Util.ErrorHandler = handleRuntimeError

	return createdWindow
end

function Bali:Notify(opts)
	if self._destroyed then
		return nil
	end

	if #self._windows == 0 and not self._notifyReady then
		local screenGui = self:_ensureScreenGui()
		local layer = Create.New("Frame", {
			Name = "BaliNotifyHostLayer",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			ZIndex = 300,
			Parent = screenGui,
		})
		self._notifyLayer = layer
		Notification.Init(layer)
		self._notifyReady = true
	end

	return Notification.Notify(opts)
end

function Bali:KeySystem(opts)
	self:_rearmState()
	pcall(Assets.Load)
	Input.Init()

	local screenGui = self:_ensureScreenGui()
	local r1, r2 = Loader.KeySystem(screenGui, opts)
	if type(r1) == "table" and r1.Frame then
		table.insert(self._loaders, r1)
	end
	return r1, r2
end

function Bali:LoadingScreen(opts)
	self:_rearmState()
	pcall(Assets.Load)

	local screenGui = self:_ensureScreenGui()
	local ctrl = Loader.LoadingScreen(screenGui, opts)
	if type(ctrl) == "table" and ctrl.Frame then
		table.insert(self._loaders, ctrl)
	end
	return ctrl
end

function Bali:SetTheme(name, animate)
	return Theme.Set(name, animate)
end

function Bali:AddTheme(name, tbl)
	return Theme.Add(name, tbl)
end

function Bali:SetAccent(color, animate)
	return Theme.SetAccent(color, animate)
end

function Bali:SetFont(family)
	return Theme.SetFont(family)
end

function Bali:SetOnDeviceFonts(enabled)
	return Theme.SetOnDeviceFonts(enabled)
end

function Bali:SetStealthMode(enabled)
	local state = enabled == true
	self.StealthMode = state
	Icons.StealthMode = state
	return state
end

function Bali:SetAutoSave(enabled)
	return Config.SetAutoSave(enabled)
end

function Bali:GetAutoSave()
	return Config.GetAutoSave()
end

function Bali:SetNotificationDuration(seconds)
	return Notification.SetDefaultDuration(seconds)
end

function Bali:GetNotificationDuration()
	return Notification.GetDefaultDuration()
end

function Bali:Destroy()
	if self._destroying then
		return
	end
	self._destroying = true
	self._destroyed = true

	for i = #self._loaders, 1, -1 do
		local ctrl = self._loaders[i]
		if type(ctrl) == "table" and type(ctrl.Destroy) == "function" then
			pcall(function()
				ctrl:Destroy()
			end)
		end
		self._loaders[i] = nil
	end

	local activeWindows = Util.Copy(self._windows)
	table.clear(self._windows)
	for _, win in ipairs(activeWindows) do
		if type(win) == "table" and type(win.Destroy) == "function" then
			pcall(function()
				win:Destroy(true)
			end)
		end
	end

	pcall(CommandPalette.Destroy)
	pcall(KeybindList.Destroy)
	pcall(Watermark.Destroy)
	pcall(Notification.Destroy)
	pcall(Tooltip.Destroy)
	pcall(Blur.Destroy)
	pcall(Input.Destroy)

	self:_destroyNotifyLayer()
	self._notifyReady = false

	if self._ownsScreenGui and self._screenGui then
		pcall(function()
			self._screenGui:Destroy()
		end)
	end
	self._screenGui = nil
	cleanupOrphanGuis(nil)

	self._maid:Clean()

	if Util.ErrorHandler == handleRuntimeError then
		Util.ErrorHandler = nil
	end
	if type(Util.Env) == "table" then
		if Util.Env._BaliInstance == self then
			Util.Env._BaliInstance = nil
		end
		if Util.Env._BaliScreenGui == self._screenGui then
			Util.Env._BaliScreenGui = nil
		end
	end

	self._destroying = false
end

function Bali:Unload()
	return self:Destroy()
end

return Bali
end

